"use strict";(globalThis.webpackChunkmy_tech_blog=globalThis.webpackChunkmy_tech_blog||[]).push([[71374],{35193:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"2026-11-06-domestic-market-close","metadata":{"permalink":"/blog/en/market/2026-11-06-domestic-market-close","source":"@site/market/2026-11-06-domestic-market-close/index.mdx","title":"\ucf54\uc2a4\ud53c 5,000\uc120 \ud131\uac78\uc774 \ub9c8\uac10, \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ud55c \uac80\uc740 \uae08\uc694\uc77c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-06T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":9.02,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-06-domestic-market-close","title":"\ucf54\uc2a4\ud53c 5,000\uc120 \ud131\uac78\uc774 \ub9c8\uac10, \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ud55c \uac80\uc740 \uae08\uc694\uc77c","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\ub9c8\uac10"]},"unlisted":false,"nextItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \uc774\ud6c4 5,100\uc120 \ud68c\ubcf5\uc744 \uc2dc\ub3c4\ud55c 11\uc6d4 6\uc77c \uc624\uc804\uc7a5","permalink":"/blog/en/market/2026-11-06-domestic-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \uc7a5 \ucd08\ubc18 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ud558\ub294 \ud3ed\ub77d \uc7a5\uc138 \uc18d\uc5d0 \ucf54\uc2a4\ud53c\uac00 5,000\uc120\uc744 \uac04\uc2e0\ud788 \uc9c0\ud0a4\uba70 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 324.11\ud3ec\uc778\ud2b8(6.02%) \ud558\ub77d\ud55c 5,059.69\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \ub300\ube44 34.14\ud3ec\uc778\ud2b8(5.03%) \ud558\ub77d\ud55c 644.27\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 4,911.28\uae4c\uc9c0 \ubc00\ub9ac\uba70 5,000\uc120\uc774 \ubb34\ub108\uc84c\uc73c\ub098 \uc624\ud6c4 \ub4e4\uc5b4 \ub099\ud3ed\uc744 \uc904\uc5ec 5,000\uc120\uc744 \ud68c\ubcf5\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c 5%\ub300 \uae09\ub77d\uc5d0 \uc774\uc5b4 \uc774\ud2c0 \uc5f0\uc18d 5% \ub118\ub294 \ud558\ub77d\uc774 \uc774\uc5b4\uc84c\uace0, \uc591 \uc2dc\uc7a5 \ubaa8\ub450 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uc640 \ucf54\uc2a4\ud53c 1\ub2e8\uacc4 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ud558\ub294 \ub4f1 \uc2dc\uc7a5 \uc548\uc815\uc7a5\uce58\uac00 \uac00\ub3d9\ub41c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,059.69 | -324.11 | -6.02% | 5,263.26 | 5,269.10 | 4,911.28 | 2\uc5b5 9,704\ub9cc \uc8fc | 27\uc870 4,919\uc5b5 \uc6d0 |\\n| \ucf54\uc2a4\ub2e5 | 644.27 | -34.14 | -5.03% | 654.43 | 657.95 | 629.17 | 4\uc5b5 1,755\ub9cc \uc8fc | 4\uc870 7,545\uc5b5 \uc6d0 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900\uc740 2026\ub144 11\uc6d4 6\uc77c \uc7a5 \ub9c8\uac10 \uc218\uce58\uc774\uba70, \uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \ub370\uc774\ud130 \uc5ed\uc0b0\uac12\uc73c\ub85c \uad50\ucc28 \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00 5,383.80, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00 678.41\uc774 \uc77c\ubd09 \ub370\uc774\ud130\uc640 \uc77c\uce58\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c200\uc740 783.23\uc73c\ub85c 6.51% \ud558\ub77d\ud588\uace0, \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 1,356.50\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.07% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd9c\ucc98: [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI), [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc624\ub298 \ud558\ub77d\uc758 \uadfc\ubcf8 \ucd09\ub9e4\ub294 \ubbf8\uad6d\ubc1c AI \ud22c\uc790 \ud68c\uc758\ub860\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc2b9\ub9ac\ud55c \uc9c1\ud6c4, \ubbf8\uad6d \uc77c\ubd80 \uc8fc\uc5d0\uc11c \uc2e0\uaddc \ub370\uc774\ud130\uc13c\ud130 \uac1c\ubc1c \uc911\ub2e8\uacfc \uc138\uc81c \ud61c\ud0dd \ucd95\uc18c\ub97c \ucd94\uc9c4\ud558\ub294 \uc6c0\uc9c1\uc784\uc774 \ub098\ud0c0\ub0ac\uace0, ING\uac00 5\uc5b5 \ub2ec\ub7ec \uaddc\ubaa8\uc758 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828 \ub300\ucd9c\uc744 \ub9e4\ubb3c\ub85c \ub0b4\ub193\uc558\ub2e4\ub294 \uc18c\uc2dd\uc774 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uac74\uc124\uc744 \ub4b7\ubc1b\uce68\ud558\ub358 \uc790\uae08 \uc870\ub2ec \uad6c\uc870 \uc790\uccb4\uc5d0 \uade0\uc5f4\uc774 \uc0dd\uacbc\ub2e4\ub294 \uc2e0\ud638\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc84c\uace0, \uc774\ub294 AI \uc778\ud504\ub77c \ud22c\uc790 \uc0ac\uc774\ud074\uc758 \uc9c0\uc18d \uac00\ub2a5\uc131\uc5d0 \ub300\ud55c \uc758\uad6c\uc2ec\uc73c\ub85c \ubc88\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ubbf8\uad6d \uc99d\uc2dc\uc5d0\uc11c \ub098\uc2a4\ub2e5\uc774 5.52%, \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\uac00 12.25% \uae09\ub77d\ud55c \uac83\uc774 \uad6d\ub0b4 \uc7a5 \ucd08\ubc18 \ud22c\ub9e4\uc758 \uc9c1\uc811\uc801\uc778 \ubc29\uc544\uc1e0\uac00 \ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc99d\uc2dc\ub294 \ubc18\ub3c4\uccb4 \ube44\uc911\uc774 \ub192\uc740 \uad6c\uc870\ub77c, \ubbf8\uad6d \ubc18\ub3c4\uccb4\uc8fc\uc758 \uae09\ub77d\uc774 \ucf54\uc2a4\ud53c200 \uc120\ubb3c -6.49%\uae4c\uc9c0 \uc774\uc5b4\uc9c0\uba70 \uc9c0\uc218 \ud558\ub77d\uc744 \uc99d\ud3ed\uc2dc\ucf30\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uae09 \uad6c\ub3c4\ub294 \uc678\uad6d\uc778\uc758 \uc77c\ubc29\uc801\uc778 \ub9e4\ub3c4\uc640 \uac1c\uc778\xb7\uae30\uad00\uc758 \ubc1b\uce68\uc73c\ub85c \uc694\uc57d\ub429\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c \uc678\uad6d\uc778\uc740 2\uc870 7,686\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uace0, \uac1c\uc778\uc774 6,045\uc5b5 \uc6d0, \uae30\uad00\uc774 1\uc870 7,000\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\uc218\ud558\uba70 \ubb3c\ub7c9\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc758 \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uac1c\uc778\uacfc \uae30\uad00\uc758 \ud569\uc744 \uc6c3\ub3cc\uc558\uace0, \ud2b9\ud788 \uae08\uc735\ud22c\uc790 \uc911\uc2ec\uc758 \uae30\uad00 \ub9e4\uc218\uac00 \uc7a5\uc911 \uc800\uc810 \ubd80\uadfc\uc5d0\uc11c \uc720\uc785\ub418\uba70 \ub099\ud3ed\uc744 \uc77c\ubd80 \ub9cc\ud68c\ud558\ub294 \ub370 \uae30\uc5ec\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uae30\uad00\uc758 \ub9e4\uc218\uac00 \ucd94\uc138 \uc804\ud658\uc744 \uc758\ubbf8\ud55c\ub2e4\uace0 \ubcf4\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\ud22c\uc2e0\uacfc \uc0ac\ubaa8\ub294 \uc624\ud788\ub824 \uc21c\ub9e4\ub3c4\ub97c \uae30\ub85d\ud588\uace0, \uc5f0\uae30\uae08\uc758 \uc21c\ub9e4\uc218 2,885\uc5b5 \uc6d0\uc740 \ud558\ub77d\uc7a5\uc5d0\uc11c\uc758 \uae30\uacc4\uc801\uc778 \ube44\uc911 \uc870\uc808 \uc131\uaca9\uc774 \uac15\ud569\ub2c8\ub2e4.<br/>\\n\uac1c\uc778 \ud22c\uc790\uc790\uc758 \uc21c\ub9e4\uc218\ub3c4 \uc800\uac00 \ub9e4\uc218\ub77c\uae30\ubcf4\ub2e4, \ud55c \ub2ec\uac04 KODEX \ub808\ubc84\ub9ac\uc9c0 \uc0c1\ud488\uc5d0 \uc57d 1\uc870 2,199\uc5b5 \uc6d0\uc774 \uc21c\uc720\uc785\ub41c \ud750\ub984\uc758 \uc5f0\uc7a5\uc120\uc73c\ub85c \ud574\uc11d\ub429\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \ucd94\uac00\ub85c \ubc00\ub9b4 \uacbd\uc6b0 \uc2e0\uc6a9\uc735\uc790 \ubc18\ub300\ub9e4\ub9e4\uac00 \uc5f0\uc1c4\uc801\uc73c\ub85c \ub098\uc62c \uc218 \uc788\ub294 \uad6c\uc870\ub77c, \uac1c\uc778\uc758 \ub9e4\uc218 \uc5ec\ub825\uc740 \uc81c\ud55c\uc801\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud658\uc728\uc740 1,356.50\uc6d0\uc73c\ub85c \ube44\uad50\uc801 \uc548\uc815\uc801\uc774\uc5c8\uc73c\ub098, \uc774\ub294 \uc6d0\ud654 \uac15\uc138\uac00 \uc544\ub2c8\ub77c \ub2ec\ub7ec \uac15\uc138 \uc18d\uc5d0\uc11c\ub3c4 \uc678\uad6d\uc778 \ub9e4\ub3c4 \uc790\uae08\uc758 \uc774\ud0c8\uc774 \ud658\uc728\uc5d0 \uace0\uc2a4\ub780\ud788 \ubc18\uc601\ub418\uc9c0 \uc54a\uc558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\ud658\uc728\uc774 \uae09\ub4f1\ud558\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc740 \uc774\ubc88 \ud558\ub77d\uc774 \uc678\ud658 \uc704\uae30\ud615\uc774 \uc544\ub2c8\ub77c \uc8fc\uc2dd \uc2dc\uc7a5 \ub0b4\ubd80\uc758 \ubc38\ub958\uc5d0\uc774\uc158 \uc7ac\ud3c9\uac00 \uc131\uaca9\uc774 \uac15\ud558\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### 1. \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uc774\ud6c4 AI \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824 \ud655\uc0b0\\n\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc2b9\ub9ac\ud55c \uc9c1\ud6c4, \uc2a4\ud0c0\uac8c\uc774\ud2b8 \ud504\ub85c\uc81d\ud2b8\uac00 \ucd94\uc9c4\ub418\ub294 \ubbf8\uc2dc\uac04\uacfc \ub274\uba55\uc2dc\ucf54\uc5d0\uc11c \uc2e0\uaddc \ub370\uc774\ud130\uc13c\ud130 \uac1c\ubc1c \uc911\ub2e8\uacfc \uc138\uc81c \ud61c\ud0dd \ucd95\uc18c\ub97c \ucd94\uc9c4\ud558\ub294 \uc6c0\uc9c1\uc784\uc774 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\nING\uac00 5\uc5b5 \ub2ec\ub7ec \uaddc\ubaa8\uc758 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828 \ub300\ucd9c\uc744 \ub9e4\ubb3c\ub85c \ub0b4\ub193\uc558\ub2e4\ub294 \uc18c\uc2dd\ub3c4 \uac19\uc740 \ub0a0 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\nAI \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \ubd90\uc744 \ub5a0\ubc1b\uce58\ub358 \uc790\uae08 \uc870\ub2ec\uacfc \uc815\ucc45 \uc9c0\uc6d0\uc774\ub77c\ub294 \ub450 \ucd95\uc774 \ub3d9\uc2dc\uc5d0 \ud754\ub4e4\ub9b0\ub2e4\ub294 \uc810\uc774 \uc2dc\uc7a5\uc758 \uc2ec\ub9ac\ub97c \uac00\uc7a5 \ud06c\uac8c \uac74\ub4dc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub3d9\uc548 AI \uc778\ud504\ub77c \ud22c\uc790\ub294 \uc218\uc694\uac00 \uc544\ub2c8\ub77c \uc790\uae08 \uc870\ub2ec \ub2a5\ub825\uc5d0 \uc758\ud574 \uc9c0\ud0f1\ub41c\ub2e4\ub294 \uc758\ubb38\uc774 \uc81c\uae30\ub3fc \uc654\ub294\ub370, \ub300\ud615 \uc740\ud589\uc758 \ub300\ucd9c \ub9e4\uac01\uc740 \uadf8 \uc758\ubb38\uc5d0 \ud604\uc2e4\uc131\uc744 \ubd80\uc5ec\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc99d\uc2dc\ub294 \ubc18\ub3c4\uccb4\ub97c \uc911\uc2ec\uc73c\ub85c AI \ubc38\ub958\uccb4\uc778\uc5d0 \ub300\ud55c \ub178\ucd9c\uc774 \ud06c\uae30 \ub54c\ubb38\uc5d0, \ubbf8\uad6d\ubc1c \uaddc\uc81c \uc6b0\ub824\ub294 \uace7\ubc14\ub85c \uad6d\ub0b4 \ubc18\ub3c4\uccb4\uc8fc\uc640 \uad00\ub828 \ubc38\ub958\uccb4\uc778\uc758 \ub3d9\ubc18 \ud558\ub77d\uc73c\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### 2. \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uc640 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74 \ubc1c\ub3d9, \uc7a5\uc911 4,911\uc120 \uc774\ud0c8\\n\\n\ucf54\uc2a4\ud53c\ub294 4,923.47\ub85c 8.55% \ud558\ub77d \ucd9c\ubc1c\ud55c \ub4a4 \uc624\uc804 9\uc2dc 3\ubd84 34\ucd08\uc5d0 1\ub2e8\uacc4 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ud574 20\ubd84\uac04 \ub9e4\ub9e4\uac00 \uc911\ub2e8\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\ub9e4 \uc7ac\uac1c \uc774\ud6c4\uc5d0\ub3c4 \ub099\ud3ed\uc774 \uc774\uc5b4\uc838 \uc624\uc804 9\uc2dc 34\ubd84\uacbd \ucf54\uc2a4\ud53c \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud588\uace0, \ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub3c4 \uc624\uc804 9\uc2dc 6\ubd84\uacbd \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ucf54\uc2a4\ud53c\ub294 4,911.28\uae4c\uc9c0 \ubc00\ub824 5,000\uc120\uc744 \uc774\ud0c8\ud588\uace0, \ucf54\uc2a4\ub2e5\ub3c4 629.17\uae4c\uc9c0 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc11c\ud0b7\ube0c\ub808\uc774\ucee4\ub294 10\uc6d4 15\uc77c \uc774\ud6c4 \ud55c \ub2ec\uc774 \ucc44 \ub418\uc9c0 \uc54a\uc544 \ub2e4\uc2dc \ubc1c\ub3d9\ud55c \uac83\uc73c\ub85c, \ucd5c\uadfc \ud55c \ub2ec \uc0ac\uc774 \uc2dc\uc7a5 \uc548\uc815\uc7a5\uce58\uac00 \ub450 \ucc28\ub840\ub098 \uac00\ub3d9\ub410\ub2e4\ub294 \uc810\uc5d0\uc11c \ubcc0\ub3d9\uc131\uc758 \uac15\ub3c4\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc624\ud6c4 \ub4e4\uc5b4 \ub099\ud3ed\uc774 \uc904\uba70 \ucf54\uc2a4\ud53c\uac00 5,000\uc120\uc744 \ud68c\ubcf5\ud588\uc9c0\ub9cc, \uc774\ub294 \ucd94\uc138 \ubc18\uc804\uc774 \uc544\ub2c8\ub77c \uc7a5\uc911 \uacfc\ub9e4\ub3c4\uc5d0 \ub530\ub978 \uae30\uc220\uc801 \ub418\ub3cc\ub9bc\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\ub9e4 \uc911\ub2e8\uacfc \uc0ac\uc774\ub4dc\uce74 \ubc1c\ub3d9\uc740 \ud22c\uc790 \uc2ec\ub9ac\uac00 \uacf5\ud3ec \uad6c\uac04\uc5d0 \uc9c4\uc785\ud588\uc74c\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc9c0\ud45c\uc774\uba70, \ub2f9\ubd84\uac04 \ubcc0\ub3d9\uc131\uc774 \uc27d\uac8c \uac00\ub77c\uc549\uc9c0 \uc54a\uc744 \uac83\uc784\uc744 \uc2dc\uc0ac\ud569\ub2c8\ub2e4.<br/>\\n\\n### 3. \ubbf8\uad6d 10\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c \ubc1c\ud45c \uc784\ubc15\\n\\n\ubbf8\uad6d \ub178\ub3d9\ubd80\ub294 \ud55c\uad6d \uc2dc\uac04 \uc624\ub298 \ubc24 22\uc2dc 30\ubd84\uc5d0 10\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c\ub97c \ubc1c\ud45c\ud569\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\ubcf4\uace0\uc11c\ub294 \ubbf8\uad6d \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc758 \uae08\ub9ac \uacbd\ub85c\ub97c \uac00\ub2a0\ud558\ub294 \ud575\uc2ec \uc9c0\ud45c\uc774\uba70, \uc774\ubc88 \ubc1c\ud45c\ub294 \uc911\uac04\uc120\uac70 \uc774\ud6c4 \ubd88\uac70\uc9c4 \uc815\ucc45 \ubd88\ud655\uc2e4\uc131\uacfc \ub9de\ubb3c\ub824 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\uc774 \uc608\uc0c1\ubcf4\ub2e4 \uc57d\ud558\uba74 \uacbd\uae30 \ub454\ud654 \uc6b0\ub824\uac00 \ucee4\uc9c0\uace0, \uc608\uc0c1\ubcf4\ub2e4 \uac15\ud558\uba74 \uae08\ub9ac \uc778\ud558 \uae30\ub300\uac00 \uc57d\ud574\uc9c0\ub294 \ub4f1 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c\ub4e0 \uc2dc\uc7a5\uc744 \uc790\uadf9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uad6d\ub0b4 \uc7a5\uc758 \uae09\ub77d\uc774 \ubbf8\uad6d\ubc1c \uc694\uc778\uc5d0\uc11c \uc2dc\uc791\ub41c \ub9cc\ud07c, \uace0\uc6a9\ubcf4\uace0\uc11c \uacb0\uacfc\uc5d0 \ub530\ub77c \ub2e4\uc74c \uac70\ub798\uc77c \uad6d\ub0b4 \uc99d\uc2dc\uc758 \ubc29\ud5a5\uc774 \uac08\ub9b4 \uac00\ub2a5\uc131\uc774 \ud07d\ub2c8\ub2e4.<br/>\\n\ubc1c\ud45c \uc804\uae4c\uc9c0\ub294 \ud3ec\uc9c0\uc158\uc744 \uc0c8\ub85c \uc7a1\uae30\ubcf4\ub2e4 \uad00\ub9dd\ud558\ub294 \uc790\uae08\uc774 \ub298\uc5b4\ub0a0 \uc218 \uc788\uc5b4, \uc7a5 \ub9c8\uac10 \uc774\ud6c4 \uc2dc\uac04\uc678 \ud750\ub984\uae4c\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc139\ud130\xb7\ud14c\ub9c8 \uc601\ud5a5 \uccb4\uc778\\n\\n\uc624\ub298 \ud558\ub77d\uc758 \uc911\uc2ec\uc5d0\ub294 \ubc18\ub3c4\uccb4\uc640 AI \ubc38\ub958\uccb4\uc778\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\uc758 \uc804\uc77c 12.25% \uae09\ub77d\uc774 \uad6d\ub0b4 \ubc18\ub3c4\uccb4\uc8fc\uc758 \ud22c\uc790 \uc2ec\ub9ac\ub97c \uc9c1\uc811\uc801\uc73c\ub85c \uc555\ubc15\ud588\uace0, \uc774\ub294 \ucf54\uc2a4\ud53c200\uc774 \ucf54\uc2a4\ud53c\ubcf4\ub2e4 \ub354 \ud06c\uac8c \ud558\ub77d\ud55c 6.51%\uc5d0\uc11c \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uacbd\ub85c\uc5d0 \ub300\ud55c \ubd88\ud655\uc2e4\uc131\ub3c4 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ubd80\ub2f4\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\ub294 \ub2e8\uc21c\ud788 \ubc18\ub3c4\uccb4 \uc218\uc694 \uac10\uc18c\ub97c \ub118\uc5b4, AI \uc778\ud504\ub77c \ud22c\uc790 \uc790\uccb4\uc758 \uc790\uae08 \uc870\ub2ec \ube44\uc6a9 \uc0c1\uc2b9\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\uae08 \uc870\ub2ec \ube44\uc6a9\uc774 \uc624\ub974\uba74 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uc18d\ub3c4\uac00 \ub290\ub824\uc9c0\uace0, \uc774\ub294 \ub2e4\uc2dc \ubc18\ub3c4\uccb4\uc640 \uc804\ub825 \uc124\ube44, \uac74\uc124 \uc790\uc7ac \ub4f1 \ud558\uc704 \ubc38\ub958\uccb4\uc778 \uc804\ubc18\uc758 \uc218\uc694 \ub454\ud654\ub85c \uc5f0\uacb0\ub418\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc77c\ubd80 \ubc29\uc5b4\uc801 \uc131\uaca9\uc758 \ud14c\ub9c8\ub294 \uc0c1\ub300\uc801\uc778 \uac15\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\nKIS MTS \ud14c\ub9c8 \ub370\uc774\ud130\uc5d0\uc11c \ud1b5\uc2e0\uc0ac\uac00 2.79% \uc0c1\uc2b9\ud588\uace0, \ub514\uc9c0\ud138\ubc29\uc1a1\uc774 3.03%, \uc911\uace0\ucc28 \ubc0f \ub80c\ud130\uce74\uac00 1.19% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ub9c8 \uad00\ub828\uc8fc\uac00 14.12% \uc0c1\uc2b9\ud588\uc73c\ub098, \uc774\ub294 \uc885\ubaa9 \uc218\uac00 2\uac1c\uc5d0 \ubd88\uacfc\ud55c \uc18c\uaddc\ubaa8 \ud14c\ub9c8\ub77c \uc2dc\uc7a5 \uc804\uccb4\uc758 \ud750\ub984\uc744 \ub300\ud45c\ud55c\ub2e4\uace0 \ubcf4\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\ud1b5\uc2e0\uc0ac\ucc98\ub7fc \ud604\uae08 \ud750\ub984\uc774 \uc548\uc815\uc801\uc778 \uc139\ud130\uac00 \ud558\ub77d\uc7a5\uc5d0\uc11c \uc0c1\ub300\uc801\uc73c\ub85c \uc120\ubc29\ud55c \uac83\uc740, \uc790\uae08\uc774 \uc131\uc7a5\uc8fc\uc5d0\uc11c \ubc29\uc5b4\uc8fc\ub85c \uc774\ub3d9\ud558\ub294 \uc804\ud615\uc801\uc778 \uc704\ud5d8 \ud68c\ud53c \ud750\ub984\uc73c\ub85c \ud574\uc11d\ub429\ub2c8\ub2e4.<br/>\\n\uc804\ub825\xb7\ud1b5\uc2e0 \uc778\ud504\ub77c \uad00\ub828 \ud14c\ub9c8\uac00 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uc640 \uc9c1\uc811 \uc5f0\uacb0\ub418\ub294 \ub9cc\ud07c, \uaddc\uc81c\uc758 \uad6c\uccb4\uc801\uc778 \ubc94\uc704\uac00 \ud655\uc778\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \uad00\ub828 \ud14c\ub9c8\uc758 \ubcc0\ub3d9\uc131\ub3c4 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c \uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | 198,130 |\\n| 2026-11-03 | 5,715.19 | 5,735.92 | 5,615.80 | 5,648.79 | 207,371 |\\n| 2026-11-04 | 5,786.13 | 5,828.13 | 5,421.72 | 5,683.80 | 276,889 |\\n| 2026-11-05 | 5,580.09 | 5,586.46 | 5,336.88 | 5,383.80 | 277,253 |\\n| 2026-11-06 | 5,263.26 | 5,269.10 | 4,911.28 | 5,059.69 | 297,036 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c \uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | 355,750 |\\n| 2026-11-03 | 723.92 | 723.92 | 702.34 | 704.39 | 430,571 |\\n| 2026-11-04 | 715.74 | 718.34 | 683.66 | 714.95 | 539,758 |\\n| 2026-11-05 | 713.49 | 717.06 | 673.38 | 678.41 | 434,307 |\\n| 2026-11-06 | 654.43 | 657.95 | 629.17 | 644.27 | 417,550 |\\n\\n5\uac70\ub798\uc77c \uae30\uc900\uc73c\ub85c \ucf54\uc2a4\ud53c\ub294 5,859.08\uc5d0\uc11c 5,059.69\ub85c 13.65% \ud558\ub77d\ud588\uace0, \ucf54\uc2a4\ub2e5\uc740 734.36\uc5d0\uc11c 644.27\ub85c 12.27% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud2b9\ud788 11\uc6d4 4\uc77c \uc7a5\uc911 \uc800\uc810 5,421.72\uc5d0\uc11c \ud55c \ucc28\ub840 \ubc18\ub4f1\ud55c \ub4a4 \ub2e4\uc2dc \ud558\ub77d\ud558\ub294 \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\uace0 \uc788\uc5b4, \ub2e8\uae30 \uc800\uc810\uc744 \ud655\uc778\ud558\ub294 \uacfc\uc815\uc774 \ubc18\ubcf5\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uc7a5\uc911 \uc800\uc810 4,911.28\uc740 \ucd5c\uadfc 5\uac70\ub798\uc77c \uc911 \uac00\uc7a5 \ub0ae\uc740 \uc218\uc900\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub2f9\uc77c \uc218\uae09\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 2\uc870 7,686\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uace0, \uac1c\uc778\uc774 6,045\uc5b5 \uc6d0, \uae30\uad00\uc774 1\uc870 7,000\uc5b5 \uc6d0, \uae30\ud0c0\ubc95\uc778\uc774 4,641\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc758 \ub9e4\ub3c4\ub294 \uc804\uc77c 3\uc870 3,733\uc5b5 \uc6d0 \uc21c\ub9e4\ub3c4\uc5d0 \uc774\uc5b4 \uc774\ud2c0 \uc5f0\uc18d \ub300\uaddc\ubaa8\ub85c \uc774\uc5b4\uc84c\uace0, \uc774\ub294 \ub2e8\uc21c\ud55c \ucc28\uc775 \uc2e4\ud604\uc774 \uc544\ub2c8\ub77c AI \ud22c\uc790 \ud68c\uc758\ub860\uc5d0 \ub530\ub978 \ud3ec\uc9c0\uc158 \ucd95\uc18c\ub85c \ubcf4\uc785\ub2c8\ub2e4.<br/>\\n\uae30\uad00 \uc21c\ub9e4\uc218 1\uc870 7,000\uc5b5 \uc6d0\uc758 \ub300\ubd80\ubd84\uc740 \uae08\uc735\ud22c\uc790 1\uc870 6,146\uc5b5 \uc6d0\uacfc \uc5f0\uae30\uae08 2,885\uc5b5 \uc6d0\uc5d0\uc11c \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\uc735\ud22c\uc790\uc758 \ub9e4\uc218\ub294 \uc99d\uad8c\uc0ac \uc790\uae30\ub9e4\ub9e4 \uc131\uaca9\uc774 \uac15\ud574 \ucd94\uc138\uc801\uc778 \ub9e4\uc218\ub77c\uae30\ubcf4\ub2e4 \uc7a5\uc911 \ubcc0\ub3d9\uc131\uc5d0 \ub300\uc751\ud55c \ubb3c\ub7c9 \uc870\uc808\ub85c \ud574\uc11d\ud558\ub294 \uac83\uc774 \uc801\uc808\ud569\ub2c8\ub2e4.<br/>\\n\ud22c\uc2e0\uacfc \uc0ac\ubaa8\uac00 \uac01\uac01 1,886\uc5b5 \uc6d0, 849\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud55c \uc810\ub3c4 \uae30\uad00 \ub0b4\ubd80\uc758 \uc628\ub3c4 \ucc28\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 999\uc5b5 \uc6d0, \uac1c\uc778\uc774 1,104\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uace0, \uae30\uad00\uc774 2,055\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uc640 \ub2ec\ub9ac \ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uac1c\uc778\ub3c4 \uc21c\ub9e4\ub3c4\ub97c \uae30\ub85d\ud588\ub294\ub370, \uc774\ub294 \uc911\uc18c\ud615\uc8fc \uc911\uc2ec\uc758 \ucf54\uc2a4\ub2e5\uc5d0\uc11c \uac1c\uc778\uc758 \uc800\uac00 \ub9e4\uc218 \uc5ec\ub825\uc774 \uc18c\uc9c4\ub418\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uc758 \ucf54\uc2a4\ub2e5 \uc21c\ub9e4\uc218 \uc5ed\uc2dc \uae08\uc735\ud22c\uc790 3,423\uc5b5 \uc6d0\uc5d0 \uc9d1\uc911\ub410\uace0, \ud22c\uc2e0\uc740 972\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uae09 \uc218\uce58 \uc911 \uc678\uad6d\uc778\xb7\uae30\uad00\xb7\uac1c\uc778\uc758 \ud569\uc774 0\uc5d0 \uac00\uae5d\uac8c \ub9de\uc544\ub5a8\uc5b4\uc9c0\ub294 \uac83\uc73c\ub85c \ubcf4\uc544 \ub9c8\uac10 \uc9c1\ud6c4 \uc7a0\uc815\uce58\uc774\uc9c0\ub9cc \uad6c\uc870\ub294 \uc548\uc815\uc801\uc73c\ub85c \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\ucd5c\uc885 \ud655\uc815\uce58\ub294 \ucd94\ud6c4 \ub124\uc774\ubc84 \uc2dc\uc7a5\ub3d9\ud5a5 \ucd5c\uc885\uac12\uc73c\ub85c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984\\n\\n\ud558\ub77d\uc7a5 \uc18d\uc5d0\uc11c\ub3c4 \uc77c\ubd80 \ud14c\ub9c8\ub294 \uc0c1\uc2b9 \ud750\ub984\uc744 \uc720\uc9c0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nKIS MTS \ud14c\ub9c8 \uae30\uc900 \ub300\ub9c8 \uad00\ub828\uc8fc\uac00 14.12% \uc0c1\uc2b9\ud588\uace0, \ub514\uc9c0\ud138\ubc29\uc1a1\uc774 3.03%, \ud1b5\uc2e0\uc0ac\uac00 2.79% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud1b5\uc2e0\uc0ac\ub294 \uad6c\uc131 \uc885\ubaa9 3\uac1c\uac00 \ubaa8\ub450 \uc0c1\uc2b9\ud558\uba70 \ud14c\ub9c8 \ub0b4 \ud655\uc0b0\uc774 \ud655\uc778\ub410\uace0, \uc774\ub294 \ubc29\uc5b4\uc8fc \uc120\ud638 \ud750\ub984\uacfc \ub9de\ub2ff\uc544 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\ubcc4 \uc885\ubaa9 \uae30\uc900\uc73c\ub85c\ub294 \ud30c\uc774\uc628\uc5d1\uc2a4\uac00 29.89% \uc0c1\uc2b9\ud558\uba70 KIS MTS \uc2e4\uc2dc\uac04 \ub7ad\ud0b9 \uc0c1\uc704\uc5d0 \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc624\ub298\uc758 \ud14c\ub9c8 \uac15\uc138\ub294 \ub300\ubd80\ubd84 \uc18c\uaddc\ubaa8 \ud14c\ub9c8\ub098 \uac1c\ubcc4 \uc885\ubaa9\uc758 \uc6c0\uc9c1\uc784\uc5d0 \ubd88\uacfc\ud569\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5 \uc804\uccb4\uac00 5% \ub118\uac8c \ud558\ub77d\ud55c \ub0a0\uc758 \ud14c\ub9c8 \uc0c1\uc2b9\uc740 \uc8fc\ub3c4\uc8fc\uc758 \uc804\ud658\uc774\ub77c\uae30\ubcf4\ub2e4 \ud558\ub77d\uc7a5\uc5d0\uc11c\uc758 \uc77c\uc2dc\uc801\uc778 \uc790\uae08 \ud53c\ub09c\ucc98 \uc131\uaca9\uc774 \uac15\ud569\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uac00 \uad6c\uccb4\ud654\ub418\ub294 \uacfc\uc815\uc5d0\uc11c \uc804\ub825\xb7\ud1b5\uc2e0 \uc778\ud504\ub77c \uad00\ub828 \ud14c\ub9c8\ub294 \uc218\ud61c\uc640 \ud0c0\uaca9\uc774 \uc5c7\uac08\ub9b4 \uc218 \uc788\uc5b4, \ud14c\ub9c8\ubcc4 \ud750\ub984\uc744 \ub2e8\uc815\uc801\uc73c\ub85c \ud574\uc11d\ud558\uae30\ubcf4\ub2e4 \uaddc\uc81c \ub0b4\uc6a9 \ud655\uc778\uc744 \uc6b0\uc120\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \ub0b4\uc77c \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ub2e8\uae30\uc801\uc73c\ub85c\ub294 \ubbf8\uad6d 10\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c \uacb0\uacfc\uac00 \uac00\uc7a5 \uc911\uc694\ud55c \ubcc0\uc218\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \ubc24 22\uc2dc 30\ubd84 \ubc1c\ud45c\ub418\ub294 \uace0\uc6a9\ubcf4\uace0\uc11c\uac00 \uc608\uc0c1\uce58\ub97c \ud06c\uac8c \ubc97\uc5b4\ub098\uba74, \ub2e4\uc74c \uac70\ub798\uc77c \uad6d\ub0b4 \uc99d\uc2dc\ub294 \uc624\ub298\uc758 \ub418\ub3cc\ub9bc\uc774 \uc774\uc5b4\uc9c8\uc9c0 \uc544\ub2c8\uba74 \uc7ac\ucc28 \ud558\ub77d\ud560\uc9c0\uac00 \uac08\ub9bd\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\uc774 \ub454\ud654\ub418\uba74 \uacbd\uae30 \uce68\uccb4 \uc6b0\ub824\uac00 \ucee4\uc9c0\uace0, \uace0\uc6a9\uc774 \uac15\ud558\uba74 \uae08\ub9ac \uc778\ud558 \uae30\ub300\uac00 \ud6c4\ud1f4\ud558\ub294 \ub9cc\ud07c, \uc5b4\ub290 \ucabd \uacb0\uacfc\ub4e0 \ubcc0\ub3d9\uc131\uc740 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ud560 \uac00\uaca9 \ub808\ubca8\uc740 \ucf54\uc2a4\ud53c 5,000\uc120\uacfc \uc7a5\uc911 \uc800\uc810 4,911.28\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uac70\ub798\uc77c \uc2dc\ucd08\uc5d0 5,000\uc120\uc744 \ub2e4\uc2dc \ub0b4\uc900\ub2e4\uba74 \uc800\uc810 \ud655\uc778 \uacfc\uc815\uc774 \uae38\uc5b4\uc9c8 \uc218 \uc788\uace0, 5,000\uc120\uc744 \uc9c0\ud0a4\uba70 \ubc18\ub4f1\ud55c\ub2e4\uba74 \uc624\ub298\uc758 \ub418\ub3cc\ub9bc\uc774 \ub2e8\uae30 \ubc14\ub2e5 \uc2e0\ud638\ub85c \uc791\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 629.17\uc758 \uc7a5\uc911 \uc800\uc810\uacfc 650\uc120 \uc548\ucc29 \uc5ec\ubd80\uac00 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 \ubbf8\uad6d \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \ub17c\uc758\uc758 \uad6c\uccb4\uc801\uc778 \ubc94\uc704\uac00 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uc2dc\uac04\xb7\ub274\uba55\uc2dc\ucf54 \ub4f1 \uac1c\ubcc4 \uc8fc \ub2e8\uc704\uc758 \uc6c0\uc9c1\uc784\uc774 \uc5f0\ubc29 \ucc28\uc6d0\uc758 \uc815\ucc45\uc73c\ub85c \ud655\uc0b0\ub418\ub294\uc9c0, ING\uc758 \ub300\ucd9c \ub9e4\uac01\uc774 \uc77c\ud68c\uc131\uc778\uc9c0 \ub2e4\ub978 \uae08\uc735\uae30\uad00\uc73c\ub85c \ubc88\uc9c0\ub294\uc9c0\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \ub9e4\ub3c4\uc758 \uc9c4\uc815 \uc5ec\ubd80\ub3c4 \ud568\uaed8 \ubd10\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc774 \uc774\ud2c0 \uc5f0\uc18d 3\uc870 \uc6d0 \uc548\ud30e\uc744 \uc21c\ub9e4\ub3c4\ud55c \uc0c1\ud669\uc5d0\uc11c, \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc904\uc5b4\ub4e4\uc9c0 \uc54a\uc73c\uba74 \uc9c0\uc218 \ud558\ubc29 \uc555\ub825\uc740 \uc27d\uac8c \ud574\uc18c\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc678\uad6d\uc778 \ub9e4\ub3c4\uac00 \ub454\ud654\ub418\uace0 \uae30\uad00\uc758 \ub9e4\uc218\uac00 \uc9c0\uc18d\ub41c\ub2e4\uba74, 5,000\uc120 \ubd80\uadfc\uc5d0\uc11c \uc800\uc810\uc744 \ub2e4\uc9c0\ub294 \ud750\ub984\uc774 \ub098\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e0\uc6a9\uc735\uc790 \ubc18\ub300\ub9e4\ub9e4 \ub9ac\uc2a4\ud06c\ub3c4 \ub2e8\uae30 \ubcc0\uc218\uc758 \ud558\ub098\uc785\ub2c8\ub2e4.<br/>\\n\uac1c\uc778 \ud22c\uc790\uc790\uc758 \ub808\ubc84\ub9ac\uc9c0 \uc0c1\ud488 \uc21c\ub9e4\uc218\uac00 \ud55c \ub2ec\uac04 1\uc870 \uc6d0\uc744 \ub118\uae34 \uc0c1\ud669\uc5d0\uc11c \uc9c0\uc218\uac00 \ucd94\uac00\ub85c \ud558\ub77d\ud558\uba74 \ubc18\ub300\ub9e4\ub9e4\uac00 \ub9e4\ubb3c\uc744 \ud0a4\uc6b0\ub294 \uc545\uc21c\ud658\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc9c0\uc218\uac00 5,000\uc120\uc744 \ud68c\ubcf5\ud558\uba70 \uc548\uc815\ub41c\ub2e4\uba74 \ubc18\ub300\ub9e4\ub9e4 \uc555\ub825\uc740 \ube60\ub974\uac8c \uc904\uc5b4\ub4ed\ub2c8\ub2e4.<br/>\\n\ub0b4\uc77c \ud655\uc778\ud560 \uc774\ubca4\ud2b8\ub294 \ubbf8\uad6d \uace0\uc6a9\ubcf4\uace0\uc11c \uacb0\uacfc, \ubbf8\uad6d \uc99d\uc2dc\uc758 \ub9c8\uac10 \ud750\ub984, \uc678\uad6d\uc778 \uc120\ubb3c \ud3ec\uc9c0\uc158 \ubcc0\ud654\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc911 \uc5b4\ub290 \ud558\ub098\ub77c\ub3c4 \uae0d\uc815\uc801\uc73c\ub85c \ud655\uc778\ub418\uba74 \ub2e8\uae30 \ubc18\ub4f1\uc758 \uadfc\uac70\uac00 \ub418\uc9c0\ub9cc, \uc138 \uac00\uc9c0\uac00 \ubaa8\ub450 \ubd80\uc815\uc801\uc774\uba74 4,911\uc120 \uc7ac\ud655\uc778 \ud750\ub984\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc624\ub298 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ud558\ub294 \ud3ed\ub77d \uc18d\uc5d0\uc11c\ub3c4 5,000\uc120\uc744 \uac04\uc2e0\ud788 \uc9c0\ud0a4\uba70 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc774\ub294 \ubc18\ub4f1\uc758 \uc2dc\uc791\uc774\ub77c\uae30\ubcf4\ub2e4 \uacfc\ub9e4\ub3c4 \uc774\ud6c4\uc758 \ub418\ub3cc\ub9bc\uc5d0 \uac00\uae5d\uace0, \uc9c4\uc815\ud55c \ubc29\ud5a5\uc740 \uc624\ub298 \ubc24 \ubc1c\ud45c\ub418\ub294 \ubbf8\uad6d \uace0\uc6a9\ubcf4\uace0\uc11c\uc640 \ubbf8\uad6d\ubc1c AI \uaddc\uc81c \ub17c\uc758\uc758 \ud5a5\ubc29\uc774 \uc815\ud560 \uac83\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub410\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-06-domestic-market-midday","metadata":{"permalink":"/blog/en/market/2026-11-06-domestic-market-midday","source":"@site/market/2026-11-06-domestic-market-midday/index.mdx","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \uc774\ud6c4 5,100\uc120 \ud68c\ubcf5\uc744 \uc2dc\ub3c4\ud55c 11\uc6d4 6\uc77c \uc624\uc804\uc7a5","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-06T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":8.96,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-06-domestic-market-midday","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \uc774\ud6c4 5,100\uc120 \ud68c\ubcf5\uc744 \uc2dc\ub3c4\ud55c 11\uc6d4 6\uc77c \uc624\uc804\uc7a5","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"\ucf54\uc2a4\ud53c 5,000\uc120 \ud131\uac78\uc774 \ub9c8\uac10, \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ud55c \uac80\uc740 \uae08\uc694\uc77c","permalink":"/blog/en/market/2026-11-06-domestic-market-close"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c 8%\ub300 \uae09\ub77d\uacfc \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \ubc1c\ub3d9\uc73c\ub85c \ucd9c\ubc1c\ud55c 11\uc6d4 6\uc77c \uc7a5 \ucd08\ubc18","permalink":"/blog/en/market/2026-11-06-domestic-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 6\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc624\uc804\uc7a5 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uc7a5 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 2.24% \ub0b4\ub9b0 5,263.26\uc5d0 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc9c1\ud6c4 \ub099\ud3ed\uc774 \ube60\ub974\uac8c \ud655\ub300\ub418\uba70 \uc624\uc804 9\uc2dc 3\ubd84 \uae30\uc900 4,911.91\uae4c\uc9c0 \ub0b4\ub824\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uac00 \uc7a5\uc911 5,000\uc120 \uc544\ub798\ub85c \ub0b4\ub824\uac04 \uac83\uc740 \uc9c0\ub09c 2\uc6d4 6\uc77c \uc774\ud6c4 \uc57d 9\uac1c\uc6d4 \ub9cc\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \uc804\uc77c \ub300\ube44 8% \uc774\uc0c1 \ud558\ub77d\ud55c \uc0c1\ud0dc\uac00 1\ubd84\uac04 \uc9c0\uc18d\ub418\uba74\uc11c \ud55c\uad6d\uac70\ub798\uc18c\ub294 \uc624\uc804 9\uc2dc 3\ubd84 34\ucd08\ubd80\ud130 1\ub2e8\uacc4 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\ub97c \ubc1c\ub3d9\ud574 \uc720\uac00\uc99d\uad8c\uc2dc\uc7a5 \uc804\uccb4 \ub9e4\ub9e4\uac70\ub798\ub97c 20\ubd84\uac04 \uc911\ub2e8\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc624\uc804 9\uc2dc 6\ubd84 2\ucd08 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\ub9e4 \uc7ac\uac1c \uc774\ud6c4 \uc9c0\uc218\ub294 \uc800\uc810 \ub300\ube44 \ud68c\ubcf5 \ud750\ub984\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \ucf54\uc2a4\ud53c\ub294 5,124.31\ub85c \ub2f9\uc77c \uc800\uc810 4,911.28 \ub300\ube44 4.34% \ubc18\ub4f1\ud55c \uc218\uc900\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 \ub2f9\uc77c \uc800\uc810 629.17\uc5d0\uc11c 652.06\uae4c\uc9c0 3.64% \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ub450 \uc9c0\uc218 \ubaa8\ub450 \uc5ec\uc804\ud788 4% \uc548\ud30e\uc758 \ud558\ub77d\ub960\uc744 \uae30\ub85d\ud558\uace0 \uc788\uc5b4 \uc624\uc804\uc7a5 \uc804\uccb4\ub85c\ub294 \uae09\ub77d \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,124.31 | -259.49 | -4.82% | 5,263.26 | 5,269.10 | 4,911.28 | 177,873\ucc9c\uc8fc | 15\uc870 9,880\uc5b5\uc6d0 | 2026-11-06 12:29 KST |\\n| \ucf54\uc2a4\ub2e5 | 652.06 | -26.35 | -3.88% | 654.43 | 657.95 | 629.17 | 295,989\ucc9c\uc8fc | 3\uc870 786\uc5b5\uc6d0 | 2026-11-06 12:29 KST |\\n\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,383.80, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 678.41\uc785\ub2c8\ub2e4.<br/>\\n\uad50\ucc28 \uac80\uc99d\uc740 \ud604\uc7ac\uac00\ub97c \ub4f1\ub77d\ub960\ub85c \ub098\ub208 \uc5ed\uc0b0\uac12\uc73c\ub85c \uc218\ud589\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\uac12\uc740 \ucf54\uc2a4\ud53c \uc57d 5,383.8, \ucf54\uc2a4\ub2e5 \uc57d 678.4\ub85c \uc77c\ubd09 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc624\ub298 \uae09\ub77d\uc758 \uadfc\ubcf8 \ucd09\ub9e4\ub294 \ubbf8\uad6d \uc815\uce58 \uc9c0\ud615 \ubcc0\ud654\uac00 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \uc0ac\uc774\ud074\uc5d0 \ub358\uc9c4 \uaddc\uc81c \ubd88\ud655\uc2e4\uc131\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uc9c1\ud6c4\uc5d0\ub294 \uc815\uce58 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c\ub85c \ub274\uc695 \uc99d\uc2dc\uac00 \uc62c\ub790\uc9c0\ub9cc, \ud558\ub8e8 \ub9cc\uc5d0 \ud574\uc11d\uc774 \uc815\ubc18\ub300\ub85c \ubc14\ub00c\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9\uc774 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124\uc5d0 \ub300\ud55c \uaddc\uc81c\ub97c \uac15\ud654\ud560 \uc218 \uc788\ub2e4\ub294 \uc804\ub9dd\uc774 \ubd80\uac01\ub418\uba74\uc11c \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud655\uc7a5\uc774 \ub2a6\uc5b4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc6b0\ub824\uac00 \ud655\uc0b0\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\ube44\uc5d0\uc2a4 \uc804\ub7b5\uac00\ub4e4\uc740 2028\ub144 \uacc4\ud68d\ub41c \ub370\uc774\ud130\uc13c\ud130 \uc99d\uc124 \uc6a9\ub7c9\uc758 \uc57d 30%\uac00 \uc9c0\uc5f0\ub418\uac70\ub098 \ucc28\uc9c8\uc744 \ube5a\uc744 \uc218 \uc788\ub2e4\uace0 \uacbd\uace0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc6b0\ub824\ub294 \uae30\uc874\uc5d0 \uc313\uc5ec \uc788\ub358 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ud68c\uc218\uc5d0 \ub300\ud55c \uc758\uad6c\uc2ec\uacfc \ub9de\ubb3c\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ube45\ud14c\ud06c \uae30\uc5c5\ub4e4\uc740 \ub370\uc774\ud130\uc13c\ud130\uc640 \uce69, \uc778\ud504\ub77c\uc5d0 \uc218\ucc9c\uc5b5 \ub2ec\ub7ec\ub97c \uc3df\uc544\ubd93\uace0 \uc788\uc9c0\ub9cc, \uadf8 \ud22c\uc790\uac00 \uc5b8\uc81c \uc774\uc775\uc73c\ub85c \ub3cc\uc544\uc62c\uc9c0\uc5d0 \ub300\ud55c \uc758\ubb38\uc740 \ud574\uc18c\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\ub09c\ub2ec \uc54c\ud30c\ubcb3\uacfc \uba54\ud0c0\uc758 \uc2e4\uc801\ub3c4 \uc778\uacf5\uc9c0\ub2a5 \uc9c0\ucd9c\uc758 \uc218\uc775\uc131\uc5d0 \ub300\ud55c \uc2dc\uc7a5\uc758 \uc6b0\ub824\ub97c \uac00\ub77c\uc549\ud788\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc560\ud50c\uc774 \uc57d 70\uc5b5 \ub2ec\ub7ec \uaddc\ubaa8\uc758 \ud68c\uc0ac\ucc44 \ubc1c\ud589\uc744 \ucd94\uc9c4\ud558\ub294 \ub4f1 \ube45\ud14c\ud06c\uc758 \ucc28\uc785 \ud655\ub300\ub3c4 \ubd80\ub2f4\uc73c\ub85c \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\uac00 \uc5ec\uc804\ud788 \ub192\uc740 \uc218\uc900\uc5d0 \uba38\ubb34\ub294 \uac00\uc6b4\ub370 \ucc28\uc785\uc5d0 \uc758\uc874\ud55c \uc124\ube44\ud22c\uc790 \ud655\ub300\ub294 \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc744 \ud0a4\uc6b0\ub294 \uc694\uc778\uc785\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 \uc62c\ud574 \ub4e4\uc5b4 \uac00\uc7a5 \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 24,315.00\uc73c\ub85c \uc804\uc77c \ub300\ube44 5.52% \ud558\ub77d\ud588\uace0, \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 12.25% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,353.73\uc73c\ub85c 4.36% \ud558\ub77d\ud588\uace0, \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 51,523.06\uc73c\ub85c 3.44% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc774 \ucda9\uaca9\uc774 \ubc18\ub3c4\uccb4 \uc911\uc2ec\uc758 \uc9c0\uc218 \uad6c\uc870\ub97c \ud1b5\ud574 \uadf8\ub300\ub85c \uc804\ub2ec\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c200\uc740 792.67\ub85c 5.38% \ud558\ub77d\ud588\uace0, \ucf54\uc2a4\ud53c \uc120\ubb3c\uc740 792.65\ub85c 5.33% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc218\uae09 \uad6c\ub3c4\ub294 \uc678\uad6d\uc778\uc758 \uc77c\ubc29\uc801\uc778 \ub9e4\ub3c4\uc640 \uac1c\uc778\xb7\uae30\uad00\uc758 \ubc1b\uae30\uac00 \ub9de\uc120 \ud615\ud0dc\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc2dc\uc7a5\ub3d9\ud5a5 API \ucd5c\uc885\uac12 \uae30\uc900 \uc804\uc77c \ucf54\uc2a4\ud53c \uc218\uae09\uc740 \uc678\uad6d\uc778 3\uc870 3,733\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4, \uac1c\uc778 2\uc870 2,087\uc5b5\uc6d0 \uc21c\ub9e4\uc218, \uae30\uad00 8,819\uc5b5\uc6d0 \uc21c\ub9e4\uc218\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00 \ub0b4\ubd80\uc5d0\uc11c\ub3c4 \ubc29\ud5a5\uc740 \uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\uc735\ud22c\uc790\ub294 1\uc870 1,443\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud558\uba70 \ubc1b\uae30\ub97c \uc8fc\ub3c4\ud588\uc9c0\ub9cc, \ud22c\uc2e0\uc740 3,078\uc5b5\uc6d0, \uc0ac\ubaa8\ub294 1,545\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc774 \ud314\uace0 \uac1c\uc778\uacfc \uae30\uad00\uc774 \ubc1b\uc558\uc73c\ub098 \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc555\ub3c4\uc801\uc774\uc5b4\uc11c \uc9c0\uc218 \ubc29\uc5b4\ub85c \uc774\uc5b4\uc9c0\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uc7a5\uc911\uc5d0\ub3c4 \uc678\uad6d\uc778\uc758 \uc21c\ub9e4\ub3c4 \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\ub294 \uac83\uc73c\ub85c \uc9d1\uacc4\ub429\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc2dc\uc7a5\ub3d9\ud5a5 API \uae30\uc900 12\uc2dc 29\ubd84 \uc7a5\uc911 \ub204\uc801 \uc7a0\uc815\uce58(\ucf54\uc2a4\ud53c\xb7\ucf54\uc2a4\ub2e5 \ud569\uacc4)\ub294 \uc678\uad6d\uc778 1\uc870 3,357\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4, \uae30\uad00 9,905\uc5b5\uc6d0 \uc21c\ub9e4\uc218, \uac1c\uc778 786\uc5b5\uc6d0 \uc21c\ub9e4\uc218\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ub204\uc801\uce58\ub294 \ud655\uc815\uce58\uac00 \uc544\ub2c8\uba70, \ucd5c\uc885 \uc218\uae09\uc740 \ub9c8\uac10 \uc774\ud6c4 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc740 1,360.90\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 5.40\uc6d0, 0.40% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \ub9e4\ub3c4\uc5d0\ub3c4 \ud658\uc728 \uae09\ub4f1\uc740 \uc81c\ud55c\uc801\uc774\uc5b4\uc11c \ud658\uc728 \uc790\uccb4\ub294 \uc774\ub0a0 \uae09\ub77d\uc758 \uc9c1\uc811\uc801\uc778 \ucd09\ub9e4\uac00 \ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\uc870\uc801\uc778 \ubd80\ub2f4 \uc694\uc778\ub3c4 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc778\uc740 10\uc6d4 6\uc77c\ubd80\ud130 11\uc6d4 5\uc77c\uae4c\uc9c0 \ud55c \ub2ec\uac04 KODEX \ub808\ubc84\ub9ac\uc9c0 \uc57d 1\uc870 2,199\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae09\ub77d\uc774 \uc774\uc5b4\uc9c0\uba74 \ub808\ubc84\ub9ac\uc9c0 \uc0c1\ud488\uc758 \ubc18\ub300\ub9e4\ub9e4\uac00 \ubcc0\ub3d9\uc131\uc744 \ud0a4\uc6b8 \uc218 \uc788\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n\uccab\uc9f8, \ucf54\uc2a4\ud53c 5,000\uc120 \ubd95\uad34\uc640 1\ub2e8\uacc4 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \ubc1c\ub3d9\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uac1c\uc7a5 \uc9c1\ud6c4 4,911.91\uae4c\uc9c0 \ub0b4\ub824\uac00\uba70 5,000\uc120\uc744 \ubc11\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 9\uc2dc 3\ubd84 34\ucd08 1\ub2e8\uacc4 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ub3fc \uc720\uac00\uc99d\uad8c\uc2dc\uc7a5 \uc804\uccb4 \ub9e4\ub9e4\uac00 20\ubd84\uac04 \uc911\ub2e8\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc624\uc804 9\uc2dc 6\ubd84 2\ucd08 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc11c\ud0b7\ube0c\ub808\uc774\ucee4\ub294 \uc9c0\uc218 \uae09\ub77d \uc2dc \ub9e4\ub9e4\ub97c \uc77c\uc2dc \uc911\ub2e8\ud574 \ud22c\uc790\uc790\uc5d0\uac8c \ub0c9\uac01 \uc2dc\uac04\uc744 \uc8fc\ub294 \uc7a5\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ubc1c\ub3d9 \uc790\uccb4\uac00 \uc2dc\uc7a5\uc758 \uacf5\ud3ec \uc2ec\ub9ac\uac00 \uadf9\ub2e8\uc801\uc778 \uc218\uc900\uc5d0 \ub3c4\ub2ec\ud588\uc74c\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc2e0\ud638\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\ub9e4 \uc7ac\uac1c \uc774\ud6c4 \uc9c0\uc218\uac00 \uc800\uc810 \ub300\ube44 4% \uc774\uc0c1 \ubc18\ub4f1\ud55c \uc810\uc740 \uc911\ub2e8\uc774 \ub2e8\uae30\uc801\uc778 \uc9c4\uc815 \ud6a8\uacfc\ub97c \ub0c8\uc74c\uc744 \uc2dc\uc0ac\ud569\ub2c8\ub2e4.<br/>\\n\\n\ub458\uc9f8, \uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\uc758 \uae09\ub77d\uacfc \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 5.52% \ud558\ub77d\ud588\uace0, \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 12.25% \ud558\ub77d\ud574 \uc0ac\uc0c1 \ub450 \ubc88\uc9f8\ub85c \ud070 \ub099\ud3ed\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 10\uc6d4 6\uc77c \uc0ac\uc0c1 \ucd5c\uace0 \uc885\uac00 27,599.89 \ub300\ube44 10% \uc774\uc0c1 \ud558\ub77d\ud574 \uc870\uc815 \uad6d\uba74\uc5d0 \uc9c4\uc785\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc911\uac04\uc120\uac70 \uacb0\uacfc\uc5d0 \ub300\ud55c \ud574\uc11d\uc774 \ud558\ub8e8 \ub9cc\uc5d0 \ub4a4\uc9d1\ud78c \uc810\uc774 \ucda9\uaca9\uc758 \ud06c\uae30 \ud0a4\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\uc815\uce58 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c\ub85c \uc62c\ub790\ub358 \uc2dc\uc7a5\uc774 \uaddc\uc81c \uac15\ud654 \uc804\ub9dd\uc5d0 \ub2e4\uc2dc \uae09\ub77d\ud558\uba74\uc11c, \ud22c\uc790 \uc2ec\ub9ac\ub294 \ubc29\ud5a5\uc131 \uc790\uccb4\ub97c \uc783\uc740 \uc0c1\ud0dc\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc740 \uad6d\ub0b4 \ubc18\ub3c4\uccb4 \uc911\uc2ec \uc9c0\uc218\uc5d0 \uc9c1\uc811\uc801\uc778 \ud558\ubc29 \uc555\ub825\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\uc14b\uc9f8, \uc815\ubd80\uc758 \uae34\uae09 \ub300\uc751\uacfc \uc2e0\uc6a9\uc735\uc790 \ub2f4\ubcf4\ube44\uc728 \uc720\uc9c0\uc758\ubb34 \uba74\uc81c\uc785\ub2c8\ub2e4.<br/>\\n\uc815\ubd80\ub294 \ubd80\ucd1d\ub9ac \uc8fc\uc7ac \uae34\uae09 \uc2dc\uc7a5\uc0c1\ud669\uc810\uac80\ud68c\uc758\ub97c \uc5f4\uace0 \uc8fc\uac00 \uae09\ub77d\uc5d0 \ub300\uc751\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc99d\uad8c\uc0ac\uc758 \uc2e0\uc6a9\uc735\uc790 \ub2f4\ubcf4\ube44\uc728 140% \uc720\uc9c0\uc758\ubb34\ub97c \uc624\ub294 9\uc77c\ubd80\ud130 3\uac1c\uc6d4\uac04 \uba74\uc81c\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae09\ub77d\uc5d0 \ub530\ub978 \uacfc\ub3c4\ud55c \ubc18\ub300\ub9e4\ub9e4\ub85c \uc2dc\uc7a5 \ubcc0\ub3d9\uc131\uc774 \uc99d\ud3ed\ub418\ub294 \uc0c1\ud669\uc744 \ub9c9\ub294 \uac83\uc774 \ubaa9\uc801\uc785\ub2c8\ub2e4.<br/>\\n\uc815\ubd80\ub294 \uacfc\ub3c4\ud55c \ubd88\uc548 \uc2ec\ub9ac\uc640 \uc218\uae09 \uc3e0\ub9bc \ud604\uc0c1\uc744 \uc608\uc758\uc8fc\uc2dc\ud558\uba74\uc11c \ubcc0\ub3d9\uc131\uc774 \ucd94\uac00\ub85c \ud655\ub300\ub420 \uacbd\uc6b0 \uc2dc\uc7a5 \uc548\uc815\uc744 \uc704\ud55c \ucd94\uac00 \uc870\uce58\ub3c4 \uc900\ube44\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc870\uce58\ub294 \uae09\ub77d\uc758 \uc6d0\uc778\uc744 \ud574\uc18c\ud558\ub294 \ub300\ucc45\uc774 \uc544\ub2c8\ub77c \ubc18\ub300\ub9e4\ub9e4 \uc5f0\uc1c4\ub97c \ucc28\ub2e8\ud558\ub294 \uc9c4\uc815\ucc45\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uc131\uaca9\uc774 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\ub300\ucc45 \ubc1c\ud45c \uc774\ud6c4 \uc9c0\uc218\uac00 \uc800\uc810 \ub300\ube44 \ud68c\ubcf5 \ud750\ub984\uc744 \ubcf4\uc600\uc73c\ub098, \ub300\ucc45 \ud6a8\uacfc\uc640 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \uae30\uc220\uc801 \ubc18\ub4f1\uc744 \uad6c\ubd84\ud558\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc139\ud130\xb7\ud14c\ub9c8 \uc601\ud5a5 \uccb4\uc778\\n\\n\uac00\uc7a5 \uc9c1\uc811\uc801\uc778 \ud0c0\uaca9\uc740 \ubc18\ub3c4\uccb4\uc640 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ubc38\ub958\uccb4\uc778\uc5d0 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d\uc758 \uc911\uad6d \uc7a5\ube44 \uc218\ucd9c \uaddc\uc81c\uc640 \uc778\uacf5\uc9c0\ub2a5 \uc218\uc694 \ubd88\ud655\uc2e4\uc131\uc774 \ud558\ub77d \uc555\ub825\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4\uc5d0\uc11c\ub294 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc \uc911\uc2ec\uc758 \ub9e4\ub3c4\uac00 \ucf54\uc2a4\ud53c200\uacfc \uc120\ubb3c \ub3d9\ubc18 \ud558\ub77d\uc73c\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c200\uc774 5.38% \ud558\ub77d\ud55c \uc810\uc740 \uc9c0\uc218 \uc804\uccb4\uac00 \ubc18\ub3c4\uccb4 \ucda9\uaca9\uc744 \uace0\uc2a4\ub780\ud788 \ubc18\uc601\ud588\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uacbd\ub85c\ub294 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc744 \ud1b5\ud574 \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\uac00 \ub192\uc740 \uc218\uc900\uc5d0 \uba38\ubb34\ub294 \uac00\uc6b4\ub370 \ube45\ud14c\ud06c\uc758 \ucc28\uc785 \ud655\ub300\uac00 \ubd80\uac01\ub418\uba74\uc11c \uc778\uacf5\uc9c0\ub2a5 \uc124\ube44\ud22c\uc790\uc758 \uc218\uc775\uc131 \uc758\ubb38\uc774 \ucee4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uc99d\uc124 \uc9c0\uc5f0 \uc6b0\ub824\ub294 \uce69\uacfc \uc7a5\ube44, \uc18c\uc7ac\ub85c \uc774\uc5b4\uc9c0\ub294 \ubc38\ub958\uccb4\uc778 \uc804\uccb4\uc758 \ud22c\uc790 \uc2ec\ub9ac\ub97c \uc555\ubc15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \uc139\ud130 \ub0b4\ubd80\uc5d0\uc11c\ub294 \ucc28\ubcc4\ud654\ub3c4 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS 12\uc2dc \uc2dc\uc7a5 \ube0c\ub9ac\ud551 \uae30\uc900 D\ub7a8\uacfc HBM, \ubc18\ub3c4\uccb4 \uc139\ud130 \uac70\ub798\ub300\uae08\uc740 1\uc870 1,000\uc5b5\uc6d0 \uaddc\ubaa8\ub85c \uc139\ud130 1\uc704\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\ub3c4 \uc555\ub825\uc774 \uc720\uc9c0\ub418\ub294 \uac00\uc6b4\ub370\uc11c\ub3c4 \uc7a5\ube44\uc640 \uc18c\uc7ac \uc77c\ubd80 \uc885\ubaa9\uc740 \uc0c1\uc2b9\ud558\uba70 \uc628\ub3c4 \ucc28\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud0dc\uc131\uc740 3.28% \uc0c1\uc2b9\ud588\uace0 \uba5c\ucf58\uc740 0.44% \uc0c1\uc2b9\ud55c \ubc18\uba74, \ud55c\ubbf8\ubc18\ub3c4\uccb4\ub294 5.14%, \uc0d8\uc528\uc5d4\uc5d0\uc2a4\ub294 3.73% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\uc7a5 \uc18d \uc790\uae08 \uc774\ub3d9\ub3c4 \ud655\uc778\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ube0c\ub9ac\ud551 \uae30\uc900 \ub85c\ubd07\uacfc \uc9c0\ubc30\uad6c\uc870 \uc774\uc288\ub85c \uc21c\ud658\ub9e4\uac00 \ub098\ud0c0\ub0ac\uace0, \ubc14\uc774\uc624 \uc77c\ubd80 \uc885\ubaa9\ub3c4 \uac15\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uba74\uc801\uc778 \ud22c\ub9e4\uac00 \uc544\ub2c8\ub77c \ud14c\ub9c8 \uac04 \uc790\uae08 \uc774\ub3d9\uc774 \ubcd1\ud589\ub418\uace0 \uc788\ub2e4\ub294 \uc810\uc740 \uc624\ud6c4 \ud750\ub984\uc744 \uac00\ub974\ub294 \ub2e8\uc11c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09 \ud45c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 \ub4f1\ub77d\ub960 | \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | -3.49% | 228,294\ucc9c\uc8fc |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | +2.24% | 198,130\ucc9c\uc8fc |\\n| 2026-11-03 | 5,715.19 | 5,735.92 | 5,615.80 | 5,648.79 | -3.59% | 207,371\ucc9c\uc8fc |\\n| 2026-11-04 | 5,786.13 | 5,828.13 | 5,421.72 | 5,683.80 | +0.62% | 276,889\ucc9c\uc8fc |\\n| 2026-11-05 | 5,580.09 | 5,586.46 | 5,336.88 | 5,383.80 | -5.28% | 277,253\ucc9c\uc8fc |\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 \ub4f1\ub77d\ub960 | \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | -3.83% | 470,174\ucc9c\uc8fc |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | +1.38% | 355,750\ucc9c\uc8fc |\\n| 2026-11-03 | 723.92 | 723.92 | 702.34 | 704.39 | -4.08% | 430,571\ucc9c\uc8fc |\\n| 2026-11-04 | 715.74 | 718.34 | 683.66 | 714.95 | +1.50% | 539,758\ucc9c\uc8fc |\\n| 2026-11-05 | 713.49 | 717.06 | 673.38 | 678.41 | -5.11% | 434,307\ucc9c\uc8fc |\\n\\n\uc704 \ud45c\ub294 \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5 \uc21c\uc11c\uc785\ub2c8\ub2e4.<br/>\\n11\uc6d4 4\uc77c \uc885\uac00 \ub300\ube44 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \ucf54\uc2a4\ud53c\ub294 9.84% \ub0ae\uc740 \uc218\uc900\uc774\uba70, \ucf54\uc2a4\ub2e5\uc740 8.80% \ub0ae\uc740 \uc218\uc900\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ud2c0 \uc5f0\uc18d \uae09\ub77d\uc774 \uc774\uc5b4\uc9c4 \ub4a4 \uc624\uc804\uc7a5\uc5d0 \uae30\uc220\uc801 \ubc18\ub4f1\uc774 \ub098\ud0c0\ub09c \uad6c\ub3c4\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984 \ubcc0\ud654\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS 12\uc2dc \uc2dc\uc7a5 \ube0c\ub9ac\ud551\uc740 \ubc18\ub3c4\uccb4 \ub9e4\ub3c4 \uc555\ub825 \uc720\uc9c0, \ub85c\ubd07\uacfc \uc9c0\ubc30\uad6c\uc870 \uc774\uc288\ub85c \uc21c\ud658\ub9e4, \ubc14\uc774\uc624 \uc77c\ubd80 \uc885\ubaa9 \uac15\uc138\ub85c \uc624\uc804\uc7a5\uc744 \uc694\uc57d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nD\ub7a8\uacfc HBM, \ubc18\ub3c4\uccb4 \uc139\ud130\ub294 \uac70\ub798\ub300\uae08 1\uc870 1,000\uc5b5\uc6d0 \uaddc\ubaa8\ub85c \uc139\ud130 1\uc704\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc774 \uc624\uc804\uc7a5\uc758 \uac00\uc7a5 \ud070 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,263.26\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 4,911.28\uae4c\uc9c0 \ub0b4\ub824\uac14\ub2e4\uac00 5,124.31\uae4c\uc9c0 \ud68c\ubcf5\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 \uc2dc\uac00 654.43\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 629.17\uae4c\uc9c0 \ub0b4\ub824\uac14\ub2e4\uac00 652.06\uae4c\uc9c0 \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00 \ub300\ube44\ub85c\ub294 \uc5ec\uc804\ud788 \uc57d\uc138\uc774\uc9c0\ub9cc, \uc7a5\uc911 \uc800\uc810 \ub300\ube44\ub85c\ub294 \ub69c\ub837\ud55c \ud68c\ubcf5 \ud750\ub984\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud14c\ub9c8\ubcc4\ub85c\ub294 \ubc18\ub3c4\uccb4 \ub9e4\ub3c4 \uc555\ub825\uc774 \uc720\uc9c0\ub418\ub294 \uac00\uc6b4\ub370 \ub85c\ubd07\uacfc \uc9c0\ubc30\uad6c\uc870, \ubc14\uc774\uc624 \ucabd\uc73c\ub85c \uc790\uae08\uc774 \uc774\ub3d9\ud558\ub294 \uc21c\ud658\ub9e4\uac00 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \uc139\ud130 \ub0b4\ubd80\uc5d0\uc11c\ub3c4 \uc7a5\ube44\uc640 \uc18c\uc7ac \uc77c\ubd80 \uc885\ubaa9\uc774 \uc0c1\uc2b9\ud558\uba70 \ub300\ud615\uc8fc \ub9e4\ub3c4\uc640 \ub2e4\ub978 \uc6c0\uc9c1\uc784\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \ud750\ub984\uc774 \uc624\ud6c4\uc5d0\ub3c4 \uc774\uc5b4\uc9c8\uc9c0\ub294 \uc678\uad6d\uc778 \ub9e4\ub3c4 \uc9c4\uc815 \uc5ec\ubd80\uc640 \ubbf8\uad6d \uace0\uc6a9\ubcf4\uace0\uc11c \ub300\uae30 \uc2ec\ub9ac\uc5d0 \ub2ec\ub824 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ud6c4 \uc804\ub9dd\uacfc \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\uc624\uc804 \ud750\ub984\uc740 \uc77c\uc2dc\uc801 \uacf5\ud3ec\uc5d0 \ub530\ub978 \uae09\ub77d\uacfc \uc800\uc810 \ub9e4\uc218\uc138 \uc720\uc785\uc774 \uad50\ucc28\ud55c \ud615\ud0dc\uc785\ub2c8\ub2e4.<br/>\\n\uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \ubc1c\ub3d9 \uc774\ud6c4 \uc800\uc810 \ub300\ube44 4% \uc774\uc0c1 \ubc18\ub4f1\ud55c \uc810\uc740 \ub2e8\uae30 \ub099\ud3ed \uacfc\ub300\uc5d0 \ub300\ud55c \ub418\ub3cc\ub9bc\uc774 \uc791\ub3d9\ud588\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ubc18\ub4f1\uc774 \ucd94\uc138 \uc804\ud658\uc778\uc9c0 \uc77c\uc2dc\uc801 \ub418\ub3cc\ub9bc\uc778\uc9c0\ub294 \uc624\ud6c4 \uc218\uae09\uc73c\ub85c \uac00\ub824\uc9c8 \uc804\ub9dd\uc785\ub2c8\ub2e4.<br/>\\n\uccab \ubc88\uc9f8\ub85c \ud655\uc778\ud560 \uc218\uce58\ub294 \uc624\ud6c4 \uc678\uad6d\uc778 \ub9e4\ub3c4 \uaddc\ubaa8\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ucf54\uc2a4\ud53c 3\uc870 3,733\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4\uc5d0 \uc774\uc5b4 \uc7a5\uc911\uc5d0\ub3c4 \ucf54\uc2a4\ud53c\xb7\ucf54\uc2a4\ub2e5 \ud569\uacc4 1\uc870 3,000\uc5b5\uc6d0\ub300 \uc21c\ub9e4\ub3c4\uac00 \uc774\uc5b4\uc9c0\uace0 \uc788\uc5b4 \ub9e4\ub3c4 \uc9c4\uc815 \uc5ec\ubd80\uac00 \uc624\ud6c4 \ubc29\ud5a5\uc744 \uac00\ub985\ub2c8\ub2e4.<br/>\\n\ub450 \ubc88\uc9f8\ub85c \ud655\uc778\ud560 \uad6c\uac04\uc740 \ucf54\uc2a4\ud53c 5,000\uc120\uacfc \ub2f9\uc77c \uc800\uac00 4,911.28\uc758 \uc9c0\uc9c0 \uc5ec\ubd80\uc785\ub2c8\ub2e4.<br/>\\n5,000\uc120\uc774 \ub2e4\uc2dc \uc704\ud611\ubc1b\uc73c\uba74 \uc624\uc804\uc758 \uacf5\ud3ec\uac00 \uc7ac\uc810\ud654\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \ud68c\ubcf5 \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\uba74 \ub2f9\uc77c \uace0\uac00 5,269.10\uc774 1\ucc28 \uc800\ud56d \uad6c\uac04\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 630\uc120 \uc548\ucc29 \uc5ec\ubd80\uc640 654.43\uc778 \uc2dc\uac00 \ud68c\ubcf5 \uc5ec\ubd80\uac00 \uad00\uc804 \ud3ec\uc778\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\uc138 \ubc88\uc9f8\ub85c \ud655\uc778\ud560 \uc774\ubca4\ud2b8\ub294 \uc624\ub298 \ubc24 10\uc2dc 30\ubd84 \ubc1c\ud45c\ub418\ub294 \ubbf8\uad6d 10\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\ubc1c\ud45c\ub97c \uc55e\ub450\uace0 \uc624\ud6c4\uc5d0\ub294 \uad00\ub9dd \uc2ec\ub9ac\uac00 \uac15\ud574\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\uc9c0\ud45c \uacb0\uacfc\uc5d0 \ub530\ub77c \ubbf8\uad6d \uae08\ub9ac \uacbd\ub85c \uae30\ub300\uac00 \ub2ec\ub77c\uc9c0\uba74 \uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\ub3c4 \ub2e4\uc74c \uac70\ub798\uc77c \ubc29\ud5a5\uc131\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124 \ubc88\uc9f8\ub85c \ud655\uc778\ud560 \ubcc0\uc218\ub294 \uc815\ubd80 \ub300\ucc45\uc758 \uccb4\uac10 \ud6a8\uacfc\uc785\ub2c8\ub2e4.<br/>\\n\uc2e0\uc6a9\uc735\uc790 \ub2f4\ubcf4\ube44\uc728 \uc720\uc9c0\uc758\ubb34 \uba74\uc81c\ub294 9\uc77c \uc2dc\ud589 \uc608\uc815\uc73c\ub85c, \ub2f9\uc7a5 \uc624\ud6c4 \uc7a5\uc5d0 \uc9c1\uc811 \uc791\uc6a9\ud558\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ubc18\ub300\ub9e4\ub9e4 \uc6b0\ub824\uac00 \uc644\ud654\ub41c\ub2e4\ub294 \uc2e0\ud638\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc9c0\uba74 \uc624\ud6c4 \uc2ec\ub9ac\uc5d0 \uc644\ucda9 \uc791\uc6a9\uc744 \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ud6c4\uc5d0\ub294 \uc9c0\uc218 \ub808\ubca8\ubcf4\ub2e4 \uc678\uad6d\uc778 \ub9e4\ub3c4 \uc9c4\uc815 \uc5ec\ubd80\uc640 5,000\uc120 \uc9c0\uc9c0 \uc5ec\ubd80\ub97c \uc6b0\uc120 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc624\ub298 \uc624\uc804\uc7a5\uc740 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \ubc1c\ub3d9\uc774\ub77c\ub294 \uadf9\ub2e8\uc801\uc778 \uc7a5\uba74\uc73c\ub85c \uc2dc\uc791\ud588\uc9c0\ub9cc, \uc800\uc810 \ub300\ube44 \ud68c\ubcf5 \ud750\ub984\uc774 \ub098\ud0c0\ub098\uba70 \uc624\ud6c4\ub97c \uac00\ub974\ub294 \ubd84\uae30\uc810\uc5d0 \uc11c \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uc2dc\uc7a5 \ud574\uc124 \ubaa9\uc801\uc774\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc815\uc815(2026\ub144 11\uc6d4 6\uc77c \uc624\ud6c4): \ucd08\ud310\uc758 \uc804\uc77c\xb7\uc7a5\uc911 \uc218\uae09 \uc218\uce58\ub294 \ucf54\uc2a4\ud53c\xb7\ucf54\uc2a4\ub2e5 \ud569\uacc4 \uae30\uc900\uc73c\ub85c \uc4f4 \uac83\uc744 \ucf54\uc2a4\ud53c \uc218\uce58\ub85c \uc798\ubabb \ud45c\uae30\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ucf54\uc2a4\ud53c \uc218\uae09 \ucd5c\uc885\uac12\uc740 \uc678\uad6d\uc778 -3\uc870 3,733\uc5b5\uc6d0, \uac1c\uc778 +2\uc870 2,087\uc5b5\uc6d0, \uae30\uad00 +8,819\uc5b5\uc6d0\uc774\uba70, \uc7a5\uc911 \ub204\uc801 \uc7a0\uc815\uce58\ub294 \ucf54\uc2a4\ud53c\xb7\ucf54\uc2a4\ub2e5 \ud569\uacc4 \uae30\uc900\uc73c\ub85c \ubc14\ub85c\uc7a1\uc558\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-06-domestic-market-open","metadata":{"permalink":"/blog/en/market/2026-11-06-domestic-market-open","source":"@site/market/2026-11-06-domestic-market-open/index.mdx","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c 8%\ub300 \uae09\ub77d\uacfc \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \ubc1c\ub3d9\uc73c\ub85c \ucd9c\ubc1c\ud55c 11\uc6d4 6\uc77c \uc7a5 \ucd08\ubc18","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-06T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":10.25,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-06-domestic-market-open","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c 8%\ub300 \uae09\ub77d\uacfc \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \ubc1c\ub3d9\uc73c\ub85c \ucd9c\ubc1c\ud55c 11\uc6d4 6\uc77c \uc7a5 \ucd08\ubc18","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \uc774\ud6c4 5,100\uc120 \ud68c\ubcf5\uc744 \uc2dc\ub3c4\ud55c 11\uc6d4 6\uc77c \uc624\uc804\uc7a5","permalink":"/blog/en/market/2026-11-06-domestic-market-midday"},"nextItem":{"title":"2026\ub144 11\uc6d4 6\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-06-nasdaq-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 6\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ubc30\uacbd\\n\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 \uc62c\ud574 \ub4e4\uc5b4 \uac00\uc7a5 \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 24,315.00\uc73c\ub85c \uc804\uc77c \ub300\ube44 1,421.51\ud3ec\uc778\ud2b8, 5.52% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,353.73\uc73c\ub85c \uc804\uc77c \ub300\ube44 334.89\ud3ec\uc778\ud2b8, 4.36% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 51,523.06\uc73c\ub85c 3.44% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 10\uc6d4 6\uc77c \uc0ac\uc0c1 \ucd5c\uace0 \uc885\uac00 27,599.89 \ub300\ube44 10% \uc774\uc0c1 \ud558\ub77d\ud574 \uc870\uc815 \uad6d\uba74\uc5d0 \uc9c4\uc785\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 12.2% \ud558\ub77d\ud574 \uc0ac\uc0c1 \ub450 \ubc88\uc9f8\ub85c \ud070 \ub099\ud3ed\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c\uc778 2026\ub144 11\uc6d4 5\uc77c \uad6d\ub0b4 \uc99d\uc2dc\ub3c4 \uc774\ubbf8 5% \ub118\uac8c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 5,383.80\uc73c\ub85c \uc804\uc77c \ub300\ube44 5.28% \ud558\ub77d\ud588\uace0, \ucf54\uc2a4\ub2e5\uc740 678.41\ub85c \uc804\uc77c \ub300\ube44 5.11% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ud2c0 \uc5f0\uc18d \uae09\ub77d\uc774 \uc774\uc5b4\uc9c0\uba74\uc11c \ucf54\uc2a4\ud53c\ub294 11\uc6d4 4\uc77c \uc885\uac00 5,683.80 \ub300\ube44 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \uae30\uc900 13.4% \ub0ae\uc740 \uc218\uc900\uae4c\uc9c0 \ub0b4\ub824\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 \uac19\uc740 \uae30\uac04 714.95\uc5d0\uc11c 632.91\uae4c\uc9c0 11.5% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 4,923.47 | -460.33 | -8.55% | 5,263.26 | 5,269.10 | 4,911.28 | 16,390\ucc9c\uc8fc | 1\uc870 2,568\uc5b5\uc6d0 | 2026-11-06 09:30 KST |\\n| \ucf54\uc2a4\ub2e5 | 632.91 | -45.50 | -6.71% | 654.43 | 654.43 | 629.17 | 97,971\ucc9c\uc8fc | 8,188\uc5b5\uc6d0 | 2026-11-06 09:30 KST |\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc740 \ubaa8\ub450 \ud3ed\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 2.24% \ub0b4\ub9b0 5,263.26\uc5d0 \ucd9c\ubc1c\ud588\uc9c0\ub9cc \uac1c\uc7a5 \uc9c1\ud6c4 \ub099\ud3ed\uc774 \ube60\ub974\uac8c \ud655\ub300\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc624\uc804 9\uc2dc 3\ubd84 \uae30\uc900 4,911.91\uae4c\uc9c0 \ub0b4\ub824\uac00\uba70 \uc804\uc77c \ub300\ube44 8.76% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uac00 \uc7a5\uc911 5,000\uc120 \uc544\ub798\ub85c \ub0b4\ub824\uac04 \uac83\uc740 \uc9c0\ub09c 2\uc6d4 6\uc77c \uc774\ud6c4 \uc57d 9\uac1c\uc6d4 \ub9cc\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \uc804\uc77c \ub300\ube44 8% \uc774\uc0c1 \ud558\ub77d\ud55c \uc0c1\ud0dc\uac00 1\ubd84\uac04 \uc9c0\uc18d\ub418\uba74\uc11c \ud55c\uad6d\uac70\ub798\uc18c\ub294 \uc624\uc804 9\uc2dc 3\ubd84 34\ucd08\ubd80\ud130 1\ub2e8\uacc4 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\ub97c \ubc1c\ub3d9\ud574 \uc720\uac00\uc99d\uad8c\uc2dc\uc7a5 \uc804\uccb4 \ub9e4\ub9e4\uac70\ub798\ub97c 20\ubd84\uac04 \uc911\ub2e8\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc624\uc804 9\uc2dc 6\ubd84 2\ucd08 \ucf54\uc2a4\ub2e5150 \uc120\ubb3c\uac00\uaca9\uacfc \ud604\ubb3c\uc9c0\uc218\uac00 \ub3d9\ubc18 \uae09\ub77d\ud558\uc790 \ud504\ub85c\uadf8\ub7a8\ub9e4\ub9e4 \ub9e4\ub3c4\ud638\uac00\uc758 \ud6a8\ub825\uc744 5\ubd84\uac04 \uc815\uc9c0\ud558\ub294 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \ucf54\uc2a4\ud53c\ub294 4,923.47\ub85c \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \ubc1c\ub3d9 \ub2f9\uc2dc \uc218\uc900\uc5d0\uc11c \ud06c\uac8c \ubc97\uc5b4\ub098\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,383.80, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 678.41\uc785\ub2c8\ub2e4.<br/>\\n\uad50\ucc28 \uac80\uc99d\uc740 \ud604\uc7ac\uac00\ub97c \ub4f1\ub77d\ub960\ub85c \ub098\ub208 \uc5ed\uc0b0\uac12\uc73c\ub85c \uc218\ud589\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\uac12\uc740 \ucf54\uc2a4\ud53c \uc57d 5,383.8, \ucf54\uc2a4\ub2e5 \uc57d 678.4\ub85c \uc77c\ubd09 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc740 1,356.30\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.06% \uc0c1\uc2b9\uc5d0 \uadf8\uccd0 \ud658\uc728 \uc790\uccb4\ub294 \uc774\ub0a0 \uae09\ub77d\uc758 \uc9c1\uc811\uc801\uc778 \ucd09\ub9e4\uac00 \ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc624\ub298 \uae09\ub77d \ucd9c\ubc1c\uc758 \uadfc\ubcf8 \ucd09\ub9e4\ub294 \ubbf8\uad6d \uc815\uce58 \uc9c0\ud615 \ubcc0\ud654\uac00 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \uc0ac\uc774\ud074\uc5d0 \ub358\uc9c4 \uaddc\uc81c \ubd88\ud655\uc2e4\uc131\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uc9c1\ud6c4\uc5d0\ub294 \uc815\uce58 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c\ub85c \ub274\uc695 \uc99d\uc2dc\uac00 \uc62c\ub790\uc9c0\ub9cc, \ud558\ub8e8 \ub9cc\uc5d0 \ud574\uc11d\uc774 \uc815\ubc18\ub300\ub85c \ubc14\ub00c\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9\uc774 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124\uc5d0 \ub300\ud55c \uaddc\uc81c\ub97c \uac15\ud654\ud560 \uc218 \uc788\ub2e4\ub294 \uc804\ub9dd\uc774 \ubd80\uac01\ub418\uba74\uc11c \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud655\uc7a5\uc774 \ub2a6\uc5b4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc6b0\ub824\uac00 \ud655\uc0b0\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\ube44\uc5d0\uc2a4 \uc804\ub7b5\uac00\ub4e4\uc740 2028\ub144 \uacc4\ud68d\ub41c \ub370\uc774\ud130\uc13c\ud130 \uc99d\uc124 \uc6a9\ub7c9\uc758 \uc57d 30%\uac00 \uc9c0\uc5f0\ub418\uac70\ub098 \ucc28\uc9c8\uc744 \ube5a\uc744 \uc218 \uc788\ub2e4\uace0 \uacbd\uace0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc6b0\ub824\ub294 \uae30\uc874\uc5d0 \uc313\uc5ec \uc788\ub358 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ud68c\uc218\uc5d0 \ub300\ud55c \uc758\uad6c\uc2ec\uacfc \ub9de\ubb3c\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ube45\ud14c\ud06c \uae30\uc5c5\ub4e4\uc740 \ub370\uc774\ud130\uc13c\ud130\uc640 \uce69, \uc778\ud504\ub77c\uc5d0 \uc218\ucc9c\uc5b5 \ub2ec\ub7ec\ub97c \uc3df\uc544\ubd93\uace0 \uc788\uc9c0\ub9cc, \uadf8 \ud22c\uc790\uac00 \uc5b8\uc81c \uc774\uc775\uc73c\ub85c \ub3cc\uc544\uc62c\uc9c0\uc5d0 \ub300\ud55c \uc758\ubb38\uc740 \ud574\uc18c\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\ub09c\ub2ec \uc54c\ud30c\ubcb3\uacfc \uba54\ud0c0\uc758 \uc2e4\uc801\ub3c4 \uc778\uacf5\uc9c0\ub2a5 \uc9c0\ucd9c\uc758 \uc218\uc775\uc131\uc5d0 \ub300\ud55c \uc2dc\uc7a5\uc758 \uc6b0\ub824\ub97c \uac00\ub77c\uc549\ud788\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc560\ud50c\uc774 \uc57d 70\uc5b5 \ub2ec\ub7ec \uaddc\ubaa8\uc758 \ud68c\uc0ac\ucc44 \ubc1c\ud589\uc744 \ucd94\uc9c4\ud558\ub294 \ub4f1 \ube45\ud14c\ud06c\uc758 \ucc28\uc785 \ud655\ub300\ub3c4 \ubd80\ub2f4\uc73c\ub85c \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\uac00 \uc5ec\uc804\ud788 \ub192\uc740 \uc218\uc900\uc5d0 \uba38\ubb34\ub294 \uac00\uc6b4\ub370 \ucc28\uc785\uc5d0 \uc758\uc874\ud55c \uc124\ube44\ud22c\uc790 \ud655\ub300\ub294 \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc744 \ud0a4\uc6b0\ub294 \uc694\uc778\uc785\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc774 \ucda9\uaca9\uc774 \ubc18\ub3c4\uccb4 \uc911\uc2ec\uc758 \uc9c0\uc218 \uad6c\uc870\ub97c \ud1b5\ud574 \uadf8\ub300\ub85c \uc804\ub2ec\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c200\uc740 761.38\ub85c 9.12% \ud558\ub77d\ud588\uace0, \ucf54\uc2a4\ud53c \uc120\ubb3c\ub3c4 8.00% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc218\uae09 \uad6c\ub3c4\ub3c4 \uc624\ub298 \uae09\ub77d\uc758 \ubc30\uacbd\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ucf54\uc2a4\ud53c\uc5d0\uc11c \uc678\uad6d\uc778\uc740 3\uc870 3,733\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uace0, \uac1c\uc778\uc774 2\uc870 2,087\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud558\uba70 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uc740 8,819\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc9c0\ub9cc \uc678\uad6d\uc778 \ub9e4\ub3c4 \uaddc\ubaa8\ub97c \uba54\uc6b0\uae30\uc5d0\ub294 \ubd80\uc871\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc758 \ub300\uaddc\ubaa8 \ub9e4\ub3c4\uac00 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370 \uac1c\uc778\uc774 \ubb3c\ub7c9\uc744 \ub5a0\uc548\ub294 \uad6c\ub3c4\ub294 \ud558\ub77d\uc774 \uae4a\uc5b4\uc9c8\uc218\ub85d \uac1c\uc778\uc758 \uc190\uc2e4 \ubd80\ub2f4\uc774 \ucee4\uc9c0\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\uc62c\ud574 1\uc6d4 2\uc77c\ubd80\ud130 11\uc6d4 5\uc77c\uae4c\uc9c0 \ucf54\uc2a4\ud53c \uc2dc\uc7a5\uc5d0\uc11c \uc678\uad6d\uc778\uc758 \ub204\uc801 \uc21c\ub9e4\uc218 \uaddc\ubaa8\ub294 215\uc870 4,370\uc5b5\uc6d0\uc5d0 \ub2ec\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \ub204\uc801 \ub9e4\uc218 \ubb3c\ub7c9\uc774 \ub418\ub3cc\ub9bc \uad6d\uba74\uc5d0\uc11c \ub9e4\ub3c4 \uc555\ub825\uc73c\ub85c \uc804\ud658\ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc2dc\uc7a5\uc758 \ubd88\uc548 \uc694\uc778\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n\uccab \ubc88\uc9f8 \uc0ac\uac74\uc740 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ubbfc\uc8fc\ub2f9 \uc591\uc6d0 \uc11d\uad8c \uc774\ud6c4 \uc778\uacf5\uc9c0\ub2a5 \uaddc\uc81c \uc6b0\ub824\uac00 \ubcf8\uaca9\ud654\ub41c \uc810\uc785\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9 \uc2b9\ub9ac \uc9c1\ud6c4 \ub274\uc695 \uc99d\uc2dc\ub294 \uc62c\ub790\uc9c0\ub9cc, \ub2e4\uc74c \ub0a0 \uc2dc\uc7a5\uc740 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uaddc\uc81c \uac15\ud654 \uac00\ub2a5\uc131\uc744 \ub2e4\uc2dc \ud3c9\uac00\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud14d\uc0ac\uc2a4\uc640 \uc870\uc9c0\uc544 \ub4f1 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \ubc18\ub300 \ubaa9\uc18c\ub9ac\uac00 \ud070 \uc9c0\uc5ed\uc5d0\uc11c \uaddc\uc81c \uc9c0\uc9c0 \ud6c4\ubcf4\ub4e4\uc774 \uc2b9\ub9ac\ud55c \uc810\ub3c4 \uc6b0\ub824\ub97c \ud0a4\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc0ac\uc774\ud074\uc758 \uc804\uc81c\uac00 \ud754\ub4e4\ub838\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uc99d\uc124\uc774 \ub2a6\uc5b4\uc9c0\uba74 \uce69\uacfc \uc7a5\ube44, \uc804\ub825 \uc778\ud504\ub77c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc218\uc694 \uc804\ub9dd \uc790\uccb4\uac00 \ub0ae\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc774 \uc131\uc7a5 \uc804\ub9dd\uc744 \uac00\uaca9\uc5d0 \ubc18\uc601\ud574 \uc628 \ub9cc\ud07c, \uc804\ub9dd \ud558\ud5a5\uc740 \ubc38\ub958\uc5d0\uc774\uc158 \uc870\uc815\uc73c\ub85c \uc9c1\uacb0\ub429\ub2c8\ub2e4.<br/>\\n\\n\ub450 \ubc88\uc9f8 \uc0ac\uac74\uc740 \uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\uc758 \ud3ed\ub77d \uc790\uccb4\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 5.52% \ud558\ub77d\ud574 \uc62c\ud574 \ub4e4\uc5b4 \uac00\uc7a5 \ud070 \ub099\ud3ed\uc744 \uae30\ub85d\ud588\uace0, 10\uc6d4 6\uc77c \uc0ac\uc0c1 \ucd5c\uace0 \uc885\uac00 \ub300\ube44 10% \uc774\uc0c1 \ud558\ub77d\ud558\uba70 \uc870\uc815 \uad6d\uba74\uc5d0 \uc9c4\uc785\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 4.36% \ud558\ub77d\ud588\uace0, 11\uac1c \uc5c5\uc885\uc774 \ubaa8\ub450 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc220 \uc5c5\uc885\uc740 7.3% \ud558\ub77d\ud588\uace0, \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 12.2% \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5d4\ube44\ub514\uc544\ub294 9.26%, AMD\ub294 17.26%, \uc0cc\ub514\uc2a4\ud06c\ub294 22% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud004\ucef4\uc740 4\ubd84\uae30 \uc2a4\ub9c8\ud2b8\ud3f0\uc6a9 \uce69 \ub9e4\ucd9c \uc804\ub9dd\uc774 \uc2dc\uc7a5 \uae30\ub300\uc5d0 \ubabb \ubbf8\uce58\uba74\uc11c \uc57d\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc2dc\uac00\ucd1d\uc561\uc740 \ud558\ub8e8 \ub9cc\uc5d0 \uc57d 2\uc870 \ub2ec\ub7ec\uac00 \uc99d\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n10\uc6d4 \ud55c \ub2ec \ub3d9\uc548\uc5d0\ub9cc \ub098\uc2a4\ub2e5 \uc2dc\uac00\ucd1d\uc561\uc774 2\uc870 5,000\uc5b5 \ub2ec\ub7ec \uc774\uc0c1 \uc904\uc5c8\ub358 \ud750\ub984\uc774 \uc774\uc5b4\uc9c4 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc740 \uad6d\ub0b4 \uc2dc\uc7a5 \uac1c\uc7a5 \uc804\ubd80\ud130 \ud22c\uc790 \uc2ec\ub9ac\ub97c \uc5bc\uc5b4\ubd99\uac8c \ub9cc\ub4e4\uc5c8\uace0, \uc7a5 \ucd08\ubc18 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \ubc1c\ub3d9\uc73c\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\uc138 \ubc88\uc9f8 \uc0ac\uac74\uc740 \uc601\uad6d \uc911\uc559\uc740\ud589\uc758 \uae08\ub9ac \uc778\uc0c1\uacfc \ubbf8\uad6d \uae08\ub9ac \uacbd\ub85c\uc5d0 \ub300\ud55c \uc804\ub9dd \ubcc0\ud654\uc785\ub2c8\ub2e4.<br/>\\n\uc601\uad6d \uc911\uc559\uc740\ud589\uc740 2023\ub144 \uc774\ud6c4 \ucc98\uc74c\uc73c\ub85c \uae08\ub9ac\ub97c \uc778\uc0c1\ud588\uace0, \ucd94\uac00 \uc778\uc0c1 \uac00\ub2a5\uc131\uc774 \ud06c\ub2e4\uace0 \uacbd\uace0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d\uc5d0\uc11c\ub294 \uae08\ub9ac \uc120\ubb3c \uc2dc\uc7a5\uc774 \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc758 \ub2e4\uc74c \uc778\uc0c1 \uc2dc\uae30\ub97c 3\uc6d4\ub85c \ubbf8\ub8e8\ub294 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9 \uc591\uc6d0 \uc7a5\uc545 \uc774\ud6c4 \ubd80\ucc44\ud55c\ub3c4 \ub300\uce58 \uc704\ud5d8\ub3c4 \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc0ac\uc774\ud074\uc774 \ub192\uc740 \ucc28\uc785 \ube44\uc6a9\uc5d0 \ubbfc\uac10\ud558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\uac00 \ub192\uc740 \uc218\uc900\uc5d0 \uc624\ub798 \uba38\ubb3c\uc218\ub85d \ucc28\uc785\uc5d0 \uc758\uc874\ud55c \ub370\uc774\ud130\uc13c\ud130 \ud22c\uc790\uc758 \uc218\uc775\uc131\uc740 \ub0ae\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\uc778\ud50c\ub808\uc774\uc158 \uc6b0\ub824\uac00 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370 \uc911\uc559\uc740\ud589\ub4e4\uc758 \uae34\ucd95 \uae30\uc870\uac00 \ud655\uc778\ub418\uba74\uc11c, \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ub300\ud55c \ud560\uc778\uc728 \ubd80\ub2f4\ub3c4 \ucee4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc139\ud130\xb7\ud14c\ub9c8 \uc601\ud5a5 \uccb4\uc778\\n\\n\uc774\ubc88 \uae09\ub77d\uc758 \uc601\ud5a5\uc740 \ubc18\ub3c4\uccb4\uc640 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ubc38\ub958\uccb4\uc778\uc744 \uc911\uc2ec\uc73c\ub85c \ud37c\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uaddc\uc81c \uc6b0\ub824\ub294 \uce69 \uc218\uc694 \uc804\ub9dd\uc744 \uc9c1\uc811 \ub0ae\ucd94\ub294 \uc694\uc778\uc785\ub2c8\ub2e4.<br/>\\n\uce69 \uc218\uc694\uac00 \uc904\uba74 \ubc18\ub3c4\uccb4 \uc7a5\ube44\uc640 \uc18c\uc7ac, \uc804\ub825 \uc778\ud504\ub77c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc218\uc694\ub3c4 \ud568\uaed8 \uc704\ucd95\ub429\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc2dc\uc7a5\uc5d0\uc11c \ubc18\ub3c4\uccb4\uc9c0\uc218\uac00 12.2% \uae09\ub77d\ud55c \uac83\uc740 \uc774 \uc5f0\uacb0\uace0\ub9ac\uac00 \uc2dc\uc7a5 \uc804\uccb4\ub85c \ud655\uc0b0\ub410\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\uc11c\ub3c4 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\uc758 \ud558\ub77d\uc774 \uc9c0\uc218 \ud558\ub77d\uc744 \uc8fc\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uc0bc\uc131\uc804\uc790 \uc8fc\uac00\ub294 20\ub9cc\uc6d0\uc120 \uc544\ub798\ub85c, SK\ud558\uc774\ub2c9\uc2a4 \uc8fc\uac00\ub294 120\ub9cc\uc6d0\uc120 \uc544\ub798\ub85c \uac01\uac01 \ub0b4\ub824\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\uac00 \ucc28\uc9c0\ud558\ub294 \ube44\uc911\uc774 \ud070 \ub9cc\ud07c, \ubc18\ub3c4\uccb4 \uc57d\uc138\ub294 \uc9c0\uc218 \uc804\uccb4\uc758 \ud558\ub77d\uc73c\ub85c \uace7\ubc14\ub85c \uc5f0\uacb0\ub429\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uc131\uc7a5\uc8fc\uc640 \uc911\uc18c\ud615 \uae30\uc220\uc8fc\uc758 \ub099\ud3ed\uc774 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 6.71% \ud558\ub77d\ud55c \uac83\uc740 \uae08\ub9ac\uc640 \uc131\uc7a5 \uc804\ub9dd\uc5d0 \ubbfc\uac10\ud55c \uc911\uc18c\ud615 \uc131\uc7a5\uc8fc\uac00 \ubc38\ub958\uc5d0\uc774\uc158 \uc870\uc815\uc744 \ub354 \ud06c\uac8c \ubc1b\uc558\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ud14c\ub9c8\ubcc4\ub85c\ub294 \uc0c1\uc2b9\ud55c \ud14c\ub9c8\uac00 \uc0ac\uc2e4\uc0c1 \uc5c6\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uc778\ubc84\uc2a4 2\ubc30 \uc0c1\uc7a5\uc9c0\uc218\uc99d\uad8c\uc740 59% \uc548\ud30e \uae09\ub4f1\ud574 \ud558\ub77d\uc5d0 \ubca0\ud305\ud558\uac70\ub098 \ud558\ub77d\uc744 \ud5e4\uc9c0\ud558\ub824\ub294 \uc218\uc694\uac00 \ubab0\ub838\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \ubd80\ub2f4\uc774 \ucee4\uc9c0\uba74\uc11c \uc131\uc7a5\uc8fc \uc804\ubc18\uc758 \ubc38\ub958\uc5d0\uc774\uc158 \ud560\uc778 \uc555\ub825\uc774 \ub192\uc544\uc84c\uace0, \uc774\ub294 \ubc18\ub3c4\uccb4\ub97c \ub118\uc5b4 \uc778\uacf5\uc9c0\ub2a5 \uad00\ub828 \ubc38\ub958\uccb4\uc778 \uc804\uccb4\ub85c \ud37c\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4\ub97c \uc81c\uc678\ud55c \uc5c5\uc885\ub3c4 \uc2dc\uc7a5 \uc804\uccb4\uc758 \uc704\ud5d8 \ud68c\ud53c \uc2ec\ub9ac\uc5d0 \ud729\uc4f8\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218 11\uac1c \uc5c5\uc885\uc774 \ubaa8\ub450 \ud558\ub77d\ud55c \uac83\ucc98\ub7fc, \uc774\ub0a0 \ud558\ub77d\uc740 \ud2b9\uc815 \uc5c5\uc885\uc758 \ubb38\uc81c\uac00 \uc544\ub2c8\ub77c \uc2dc\uc7a5 \uc804\ubc18\uc758 \uc704\ud5d8 \ud68c\ud53c \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ud658\uc728\uc774 \uc548\uc815\uc801\uc73c\ub85c \uc720\uc9c0\ub41c \uc810\uc740 \uc6d0\ud654 \uc790\uc0b0 \uc804\ubc18\uc5d0 \ub300\ud55c \uc2e0\ub8b0\uac00 \ubb34\ub108\uc9c0\uc9c0\ub294 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc774 1,356.30\uc6d0\uc73c\ub85c 0.06% \uc0c1\uc2b9\uc5d0 \uadf8\uce5c \uac83\uc740 \uc678\uad6d\uc778 \ub9e4\ub3c4\uac00 \ud658\uc728 \uae09\ub4f1\uacfc \ub9de\ubb3c\ub9b0 \uc790\uae08 \uc774\ud0c8 \uad6d\uba74\uc73c\ub85c \ubc88\uc9c0\uc9c0 \uc54a\uc558\uc74c\uc744 \uc2dc\uc0ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n\ucf54\uc2a4\ud53c \uc77c\ubd09\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | 198,130\ucc9c\uc8fc |\\n| 2026-11-03 | 5,715.19 | 5,735.92 | 5,615.80 | 5,648.79 | 207,371\ucc9c\uc8fc |\\n| 2026-11-04 | 5,786.13 | 5,828.13 | 5,421.72 | 5,683.80 | 276,889\ucc9c\uc8fc |\\n| 2026-11-05 | 5,580.09 | 5,586.46 | 5,336.88 | 5,383.80 | 277,253\ucc9c\uc8fc |\\n| 2026-11-06 (\ud615\uc131 \uc911) | 5,263.26 | 5,269.10 | 4,911.28 | 4,923.47 | 16,390\ucc9c\uc8fc |\\n\\n\ucf54\uc2a4\ub2e5 \uc77c\ubd09\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | 355,750\ucc9c\uc8fc |\\n| 2026-11-03 | 723.92 | 723.92 | 702.34 | 704.39 | 430,571\ucc9c\uc8fc |\\n| 2026-11-04 | 715.74 | 718.34 | 683.66 | 714.95 | 539,758\ucc9c\uc8fc |\\n| 2026-11-05 | 713.49 | 717.06 | 673.38 | 678.41 | 434,307\ucc9c\uc8fc |\\n| 2026-11-06 (\ud615\uc131 \uc911) | 654.43 | 654.43 | 629.17 | 632.91 | 97,971\ucc9c\uc8fc |\\n\\n\ucf54\uc2a4\ud53c\ub294 11\uc6d4 2\uc77c 5,859.08\uae4c\uc9c0 \uc62c\ub790\ub358 \ud750\ub984\uc774 \uc0ac\ud758 \ub9cc\uc5d0 4,923.47\uae4c\uc9c0 \ubb34\ub108\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 4\uc77c \uc7a5\uc911 \uace0\uac00 5,828.13\uc5d0\uc11c \uc800\uac00 5,421.72\uae4c\uc9c0 400\ud3ec\uc778\ud2b8 \ub118\uac8c \ud754\ub4e4\ub838\ub358 \ubcc0\ub3d9\uc131\uc774 \uc774\ud2c0 \uc5f0\uc18d \uae09\ub77d\uc73c\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 11\uc6d4 2\uc77c 734.36\uc5d0\uc11c 632.91\uae4c\uc9c0 \ub098\ud758 \ub9cc\uc5d0 100\ud3ec\uc778\ud2b8 \ub118\uac8c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac70\ub798\ub7c9\uc740 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\ub85c \ub9e4\ub9e4\uac00 \uc911\ub2e8\ub41c \uc601\ud5a5\uc73c\ub85c \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \uae30\uc900 \ucf54\uc2a4\ud53c 16,390\ucc9c\uc8fc\uc5d0 \uadf8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\uac70\ub798 \uc7ac\uac1c \uc774\ud6c4 \uac70\ub798\ub7c9\uc774 \uc5bc\ub9c8\ub098 \ub298\uc5b4\ub098\ub294\uc9c0\uac00 \uc7a5\uc911 \ub9e4\ub3c4 \uc555\ub825\uc758 \uac15\ub3c4\ub97c \uac00\ub2a0\ud558\ub294 \uc9c0\ud45c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n## \uc804\uc77c \uc218\uae09\\n\\n\uc804\uc77c\uc778 2026\ub144 11\uc6d4 5\uc77c \ucf54\uc2a4\ud53c \uc218\uae09\uc740 \uc678\uad6d\uc778\uc758 \ub300\uaddc\ubaa8 \ub9e4\ub3c4\ub97c \uac1c\uc778\uacfc \uae30\uad00\uc774 \ubc1b\uc544\ub0b4\ub294 \uad6c\ub3c4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc740 3\uc870 3,733\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc778\uc740 2\uc870 2,087\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uace0, \uae30\uad00\uc740 8,819\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00 \uc21c\ub9e4\uc218 \uc548\uc5d0\uc11c\ub294 \uae08\uc735\ud22c\uc790\uac00 1\uc870 1,443\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud55c \ubc18\uba74 \ud22c\uc2e0\uc740 3,078\uc5b5\uc6d0, \uc0ac\ubaa8\ud380\ub4dc\ub294 1,545\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5f0\uae30\uae08\uc740 1,602\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\ud0c0\ubc95\uc778\uc740 2,827\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uac1c\uc778\uacfc \uae30\uad00\uc758 \ub9e4\uc218\ub97c \ud569\uce5c \uaddc\ubaa8\ub97c \uc6c3\ub3cc\uc558\uace0, \uc9c0\uc218\ub294 5.28% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc774 \ud30c\ub294 \ubb3c\ub7c9\uc744 \uac1c\uc778\uc774 \ub5a0\uc548\ub294 \uad6c\ub3c4\uac00 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370, \uac1c\uc778\uc758 \ub9e4\uc218 \uc5ec\ub825\uc740 \ud558\ub77d\uc774 \uae4a\uc5b4\uc9c8\uc218\ub85d \ubd80\ub2f4\uc774 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uc804\uc77c \uc218\uae09\uc740 \ucf54\uc2a4\ud53c\uc640 \ub2e4\ub978 \uc591\uc0c1\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc740 584\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uace0, \uac1c\uc778\uc740 1,568\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uc740 1,026\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00 \uc548\uc5d0\uc11c\ub294 \uae08\uc735\ud22c\uc790\uac00 1,442\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud55c \ubc18\uba74 \ud22c\uc2e0\uc740 1,140\uc5b5\uc6d0, \uc5f0\uae30\uae08\uc740 784\uc5b5\uc6d0, \uc0ac\ubaa8\ud380\ub4dc\ub294 385\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \ud568\uaed8 \uc21c\ub9e4\ub3c4\ud588\uace0 \uac1c\uc778\ub9cc \uc21c\ub9e4\uc218\ud55c \uad6c\ub3c4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc2dc\uc7a5 \ubaa8\ub450 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218 \uc8fc\uccb4\ub85c \ub098\uc130\uc9c0\ub9cc, \uc9c0\uc218\ub294 \uac01\uac01 5% \ub118\uac8c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uac1c\uc778 \ub9e4\uc218\uac00 \ud558\ub77d\uc744 \ub9c9\uc544\ub0b4\ub294 \ud798\uc774 \uc544\ub2c8\ub77c \ud558\ub77d \uacfc\uc815\uc5d0\uc11c \ubb3c\ub7c9\uc744 \ub5a0\uc548\ub294 \ud750\ub984\uc5d0 \uac00\uae5d\ub2e4\ub294 \ud574\uc11d\uc744 \uac00\ub2a5\ud558\uac8c \ud569\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\uc778 11\uc6d4 6\uc77c \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ucf54\uc2a4\ud53c \uc218\uae09\uc740 \uc678\uad6d\uc778 1,337\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4, \uae30\uad00 865\uc5b5\uc6d0 \uc21c\ub9e4\uc218, \uac1c\uc778 426\uc5b5\uc6d0 \uc21c\ub9e4\uc218\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc678\uad6d\uc778 492\uc5b5\uc6d0 \uc21c\ub9e4\uc218, \uae30\uad00 3\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4, \uac1c\uc778 496\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc7a5 \ucd08\ubc18 \uc218\uae09\uc740 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uc640 \uc0ac\uc774\ub4dc\uce74 \ubc1c\ub3d9\uc73c\ub85c \ub9e4\ub9e4\uac00 \uc911\ub2e8\ub41c \uc601\ud5a5\uc774 \uc788\uc5b4, \ub9c8\uac10 \uae30\uc900\uc73c\ub85c \ub2e4\uc2dc \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ub2e8\uae30\uc801\uc73c\ub85c\ub294 \ubcc0\ub3d9\uc131 \ud655\ub300 \uad6d\uba74\uc774 \uc774\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \ud07d\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 \uc870\uc815 \uad6d\uba74\uc5d0 \uc9c4\uc785\ud588\uace0, \ucf54\uc2a4\ud53c\ub294 \uc774\ud2c0 \ub9cc\uc5d0 13% \ub118\uac8c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc220\uc801\uc73c\ub85c \uacfc\ub9e4\ub3c4 \uad6c\uac04\uc5d0 \ub4e4\uc5b4\uc130\ub2e4\uace0 \ubcfc \uc218 \uc788\uc9c0\ub9cc, \uc2dc\uc7a5\uc774 \ubc14\ub2e5\uc744 \ud655\uc778\ud558\uae30 \uc804\uc5d0\ub294 \ubc18\ub4f1\uc744 \ub2e8\uc815\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ud560 \uccab \ubc88\uc9f8 \uac00\uaca9 \ub808\ubca8\uc740 \ucf54\uc2a4\ud53c 5,000\uc120\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18 \ubb34\ub108\uc9c4 5,000\uc120\uc744 \uc885\uac00 \uae30\uc900\uc73c\ub85c \ud68c\ubcf5\ud558\ub294\uc9c0\uac00 \ub2e8\uae30 \uc2ec\ub9ac\uc758 \ubd84\uae30\uc810\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc7a5\uc911 \uc800\uc810 4,911.28\uacfc \uc804\uc77c \uc800\uc810 5,336.88 \uc0ac\uc774\uc758 \uad6c\uac04\ub3c4 \uc9c0\uc9c0 \uc5ec\ubd80\ub97c \ud655\uc778\ud560 \uad6c\uac04\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 630\uc120 \ubd80\uadfc\uc758 \uc9c0\uc9c0 \uc5ec\ubd80\uc640 700\uc120 \ud68c\ubcf5 \uc5ec\ubd80\uac00 \ud655\uc778\ud560 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \ucf54\uc2a4\ub2e5 \uc800\uc810\uc740 629.17\uc785\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 \uc778\uacf5\uc9c0\ub2a5 \uaddc\uc81c \ub17c\uc758\uc758 \uc804\uac1c\uac00 \ud575\uc2ec \ubcc0\uc218\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc758\ud68c\uc5d0\uc11c \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \ub17c\uc758\uac00 \uc2e4\uc81c\ub85c \uc785\ubc95\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0, \uc720\ube44\uc5d0\uc2a4 \uc804\ub9dd\ucc98\ub7fc 2028\ub144 \uc99d\uc124 \uc6a9\ub7c9\uc758 30%\uac00 \uc9c0\uc5f0\ub418\ub294\uc9c0\uac00 \ud655\uc778\ub3fc\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uc6b0\ub824\uac00 \uad6c\uccb4\ud654\ub418\uc9c0 \uc54a\uace0 \uc758\uad6c\uc2ec \uc218\uc900\uc5d0 \uba38\ubb34\ub978\ub2e4\uba74 \uc2dc\uc7a5\uc740 \uacfc\ub3c4\ud55c \ub099\ud3ed\uc744 \ub418\ub3cc\ub9b4 \uc5ec\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uaddc\uc81c\uac00 \uad6c\uccb4\ud654\ub418\uba74 \uc778\uacf5\uc9c0\ub2a5 \ubc38\ub958\uccb4\uc778 \uc804\ubc18\uc758 \uc774\uc775 \uc804\ub9dd\uc774 \ud558\ud5a5 \uc870\uc815\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uacbd\ub85c\ub3c4 \uc911\uae30 \ubcc0\uc218\uc785\ub2c8\ub2e4.<br/>\\n\uc601\uad6d \uc911\uc559\uc740\ud589\uc758 \uae08\ub9ac \uc778\uc0c1\uacfc \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4 \uc778\uc0c1 \uc2dc\uae30 \uc804\ub9dd\uc774 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \uc8fc\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \uc218\uae09\ub3c4 \ud655\uc778\ud560 \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\uc62c\ud574 \ub204\uc801 \uc21c\ub9e4\uc218\uac00 \ud070 \ub9cc\ud07c, \uc678\uad6d\uc778\uc758 \ub9e4\ub3c4\uac00 \uc77c\uc2dc\uc801\uc778 \ucc28\uc775 \uc2e4\ud604\uc778\uc9c0 \ucd94\uc138 \uc804\ud658\uc778\uc9c0\uac00 \ub2e8\uae30 \ubc29\ud5a5\uc744 \uac00\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9ac\uc2a4\ud06c \uad00\ub9ac \uad00\uc810\uc5d0\uc11c\ub294 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \ubc1c\ub3d9 \uc774\ud6c4 \uac70\ub798 \uc7ac\uac1c \uc9c1\ud6c4\uc758 \ubcc0\ub3d9\uc131\uc5d0 \uc8fc\uc758\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ub9e4\ub9e4 \uc911\ub2e8 \uc774\ud6c4\uc5d0\ub294 \uc313\uc778 \uc8fc\ubb38\uc774 \ud55c\uaebc\ubc88\uc5d0 \uccb4\uacb0\ub418\uba74\uc11c \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \uc2dc\uc7a5 \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub410\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \ubc1c\ub3d9 \uc774\ud6c4 \uac70\ub798 \uc7ac\uac1c \uc9c1\ud6c4 \ucf54\uc2a4\ud53c\uac00 5,000\uc120\uc744 \ud68c\ubcf5\ud558\ub294\uc9c0 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74 \uc774\ud6c4 \ud504\ub85c\uadf8\ub7a8\ub9e4\ub9e4 \ub9e4\ub3c4 \ubb3c\ub7c9\uc774 \uc5bc\ub9c8\ub098 \ub098\uc624\ub294\uc9c0\ub3c4 \ud655\uc778\ud560 \uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc758 \uc7a5\uc911 \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc804\uc77c \uc218\uc900\uc744 \uc774\uc5b4\uac00\ub294\uc9c0, \uac1c\uc778\uc758 \ub9e4\uc218\uc138\uac00 \uc720\uc9c0\ub418\ub294\uc9c0\ub3c4 \ud655\uc778\ud560 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc774 1,350\uc6d0\ub300 \ud6c4\ubc18\uc5d0\uc11c \uc548\uc815\ub418\ub294\uc9c0\ub3c4 \ud655\uc778\ud560 \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\ud658\uc728\uc774 \uae09\ub4f1\ud558\uba74 \uc678\uad6d\uc778 \uc790\uae08 \uc774\ud0c8 \uc6b0\ub824\uac00 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc120\ubb3c \uc2dc\uc7a5\uacfc \uc544\uc2dc\uc544 \uc99d\uc2dc\uc758 \uc7a5\uc911 \ud750\ub984\ub3c4 \uc624\ud6c4 \uc7a5 \ubc29\ud5a5\uc744 \uac00\ub2a0\ud558\ub294 \ub2e8\uc11c\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n2026\ub144 11\uc6d4 6\uc77c \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ubbf8\uad6d \uc778\uacf5\uc9c0\ub2a5 \uaddc\uc81c \uc6b0\ub824\uc640 \uac04\ubc24 \ub274\uc695 \uc99d\uc2dc \ud3ed\ub77d\uc758 \uc5ec\ud30c\ub85c \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ub418\ub294 \ud3ed\ub77d \ucd9c\ubc1c\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n5,000\uc120 \ud68c\ubcf5 \uc5ec\ubd80\uc640 \uc678\uad6d\uc778 \uc218\uae09, \ubbf8\uad6d \uaddc\uc81c \ub17c\uc758 \uc804\uac1c\ub97c \ud655\uc778\ud558\uba74\uc11c \uc7a5\uc911 \ud750\ub984\uc744 \uc9c0\ucf1c\ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-06-nasdaq-market-close","metadata":{"permalink":"/blog/en/market/2026-11-06-nasdaq-market-close","source":"@site/market/2026-11-06-nasdaq-market-close/index.mdx","title":"2026\ub144 11\uc6d4 6\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-06T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":7.66,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-06-nasdaq-market-close","title":"2026\ub144 11\uc6d4 6\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c 8%\ub300 \uae09\ub77d\uacfc \uc11c\ud0b7\ube0c\ub808\uc774\ucee4 \ubc1c\ub3d9\uc73c\ub85c \ucd9c\ubc1c\ud55c 11\uc6d4 6\uc77c \uc7a5 \ucd08\ubc18","permalink":"/blog/en/market/2026-11-06-domestic-market-open"},"nextItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911 1.15% \uc0c1\uc2b9, \uace0\uc6a9\xb7\uc18c\ube44\uc2ec\ub9ac \ud638\uc870\uc5d0\ub3c4 \ubc18\ub3c4\uccb4 \ub418\ub3cc\ub9bc\uc5d0 \uc0c1\uc2b9\ud3ed \ucd95\uc18c","permalink":"/blog/en/market/2026-11-06-nasdaq-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 6\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc804\uc77c \ub300\ube44 1.09% \uc0c1\uc2b9\ud574 24,579.43\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9 \ud3ed\uc740 264.43\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c \ud558\ub77d \ud3ed 1,421.51\uc758 18.6%\ub97c \ub418\ub3cc\ub9b0 \uc218\uc900\uc73c\ub85c, \uae09\ub77d \ud558\ub8e8 \ub9cc\uc758 \uae30\uc220\uc801 \ubc18\ub4f1\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 \uc9c0\ub09c 10\uc6d4 6\uc77c \uae30\ub85d\ud55c \uc0ac\uc0c1 \ucd5c\uace0 \uc885\uac00 27,599.89 \ub300\ube44 10.94% \ub0ae\uc544\uc838 \uc870\uc815 \uad6c\uac04\uc5d0 \uba38\ubb3c\ub800\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\uc740 0.31% \uc0c1\uc2b9\ud574 7,376.86\uc73c\ub85c \ub9c8\uac10\ud588\uace0, \ub2e4\uc6b0\uc9c0\uc218\ub294 0.46% \ud558\ub77d\ud574 51,285.73\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138 \uc9c0\uc218\uac00 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\uc740 \ud63c\uc870 \uc7a5\uc138\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00 24,825.55\uae4c\uc9c0 \uc62c\ub790\ub358 \ub098\uc2a4\ub2e5\uc740 \ub9c8\uac10 \ubb34\ub835 \uc0c1\uc2b9 \ud3ed\uc744 \uc0c1\ub2f9 \ubd80\ubd84 \ubc18\ub0a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \ub2f9\uc77c \uace0\uac00 | \ub2f9\uc77c \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 24,579.43 | +264.43 | +1.09% | 24,315.00 | 24,825.55 | 24,507.63 |\\n| S&P500 | 7,376.86 | +23.13 | +0.31% | 7,353.73 | 7,444.20 | 7,369.55 |\\n| \ub2e4\uc6b0\uc9c0\uc218 | 51,285.73 | -237.33 | -0.46% | 51,523.06 | 51,662.26 | 50,992.61 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 11\uc6d4 6\uc77c 16\uc2dc 20\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 11\uc6d4 7\uc77c 06\uc2dc 20\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569 \uc218\uce58\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 curl \uc9c1\uc811 \uc870\ud68c\ub85c\ub294 \uc2dc\uc138 \ub370\uc774\ud130\uac00 \ud655\uc778\ub418\uc9c0 \uc54a\uc544 \ube0c\ub77c\uc6b0\uc800\ub85c \uc9c1\uc811 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\ub294 \ubbf8\uad6d 11\uc6d4 6\uc77c 16\uc2dc 20\ubd84 \uc7a5\ub9c8\uac10 \uae30\uc900\uc73c\ub85c \uc885\uac00 24,579.43, \uc804\uc77c \ub300\ube44 264.43, \ub4f1\ub77d\ub960 1.09%\uac00 \ud45c\uc2dc\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \ub2f9\uc77c \uc2dc\uac00\ub294 24,602.48, 52\uc8fc \ubc94\uc704\ub294 20,690.25\uc5d0\uc11c 27,722.75\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc758 \ub098\uc2a4\ub2e5 \uc885\ud569 \uac12\ub3c4 \uc885\uac00 24,579.43, \uc804\uc77c \ub300\ube44 264.43, \ub4f1\ub77d\ub960 1.09%\ub85c \ub124\uc774\ubc84 \uac12\uacfc \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\nS&P500 \uc218\uce58\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \uc885\uac00\uc5d0\uc11c \uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc744 \ube7c\ub294 \ubc29\uc2dd\uc73c\ub85c \uc5ed\uc0b0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 \ub098\uc2a4\ub2e5 24,315.00, S&P500 7,353.73, \ub2e4\uc6b0\uc9c0\uc218 51,523.06\uc774\uba70, \uc138 \uac12 \ubaa8\ub450 \uc804 \uac70\ub798\uc77c \ub9c8\uac10 \uae00\uc758 \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uacfc \ub2e4\uc6b0\uc9c0\uc218\uc758 \ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 Yahoo Finance \uc77c\ubd09 \uae30\uc900\uc785\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc77c\ubd09\uc758 \ub098\uc2a4\ub2e5 \uc218\uce58\uac00 \ub124\uc774\ubc84 \ub9c8\uac10 \uc218\uce58\uc640 \uc2dc\uac00\uc640 \uace0\uac00\uc640 \uc800\uac00\uc640 \uc885\uac00\uae4c\uc9c0 \uc77c\uce58\ud574 \uc77c\ubd09 \uae30\uc900\uc758 \uc815\ud569\uc131\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uae30\uc900 1,361.00\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 5.50\uc6d0, 0.41% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc640 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub9c8\uac10 \uc6d0\uc778\uc740 \ubcf8\ubb38\uc5d0 \uc4f0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc774\ub0a0 \ubc18\ub4f1\uc758 \ud45c\uba74\uc801 \uc774\uc720\ub294 \uc804\uc77c \ud3ed\ub77d\uc5d0 \ub300\ud55c \uc800\uac00 \ub9e4\uc218\uc138\uc785\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c \ub098\uc2a4\ub2e5\uc740 5.52% \ud558\ub77d\ud574 2025\ub144 4\uc6d4 \uc774\ud6c4 \uac00\uc7a5 \ud070 \ub099\ud3ed\uc744 \uae30\ub85d\ud588\uace0, \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 12.25% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub099\ud3ed\uc774 \ucef8\ub358 \ub9cc\ud07c \ub2e8\uae30 \ub418\ub3cc\ub9bc \ub9e4\uc218\uac00 \ub4e4\uc5b4\uc624\ub294 \uac83\uc740 \uc790\uc5f0\uc2a4\ub7ec\uc6b4 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\uadfc\ubcf8 \ucd09\ub9e4\ub294 10\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n10\uc6d4 \ube44\ub18d\uc5c5 \ubd80\ubb38 \uc2e0\uaddc \uace0\uc6a9\uc740 16\ub9cc 5\ucc9c \uba85 \uc99d\uac00\ud574 \uc2dc\uc7a5 \uc608\uc0c1\uce58 5\ub9cc 9\ucc9c \uba85\uc744 3\ubc30 \uac00\uae4c\uc774 \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9 \ud638\uc870\ub294 \uacbd\uae30 \ub454\ud654 \uc6b0\ub824\ub97c \ub35c\uc5b4\uc8fc\ub294 \uc7ac\ub8cc\uc600\uc9c0\ub9cc, \ub3d9\uc2dc\uc5d0 12\uc6d4 \uae30\uc900\uae08\ub9ac \uc778\uc0c1 \ud655\ub960\uc744 66%\uc5d0\uc11c 76%\ub85c \ub04c\uc5b4\uc62c\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d 2\ub144\ubb3c \uad6d\ucc44\uae08\ub9ac\ub294 5bp \uc62c\ub790\uace0, 10\ub144\ubb3c \uad6d\ucc44\uae08\ub9ac\ub294 4.868%\ub85c \uc804 \uac70\ub798\uc77c \uc885\uac00 4.84%\ubcf4\ub2e4 \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uc778\uc0c1 \uae30\ub300\uac00 \ucee4\uc9c0\uc790 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc774 \ub2e4\uc2dc \ubd80\uac01\ub410\uace0, \ub098\uc2a4\ub2e5\uc740 \uc7a5\uc911 \uace0\uac00\uc5d0\uc11c \ubc00\ub824 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5f0\uc900 \uc778\uc0ac\ub4e4\uc758 \ubc1c\uc5b8\ub3c4 \uac19\uc740 \ubc29\ud5a5\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uba54\ub9ac \ub370\uc77c\ub9ac \uc0cc\ud504\ub780\uc2dc\uc2a4\ucf54 \uc5f0\uc740 \ucd1d\uc7ac\ub294 \ucd94\uac00 \uae08\ub9ac \uc778\uc0c1\uc774 \ud544\uc694\ud558\ub2e4\uace0 \ubc1d\ud614\uace0, \ud1a0\uba38\uc2a4 \ubc14\ud0a8 \ub9ac\uce58\uba3c\ub4dc \uc5f0\uc740 \ucd1d\uc7ac\ub3c4 11\uc6d4 5\uc77c \ucd94\uac00 \uc778\uc0c1 \ud544\uc694\uc131\uc744 \uc5b8\uae09\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \ucd1d\uc7ac \ubaa8\ub450 \uc810\uc9c4\uc801\uc778 \ubc29\uc2dd\uc744 \uc120\ud638\ud55c\ub2e4\uace0 \ubc1d\ud614\uc9c0\ub9cc, \uc778\uc0c1 \uc790\uccb4\ub97c \uc2dc\uc0ac\ud55c \uc810\uc774 \uc2dc\uc7a5\uc5d0 \ub9e4\ud30c \uc2e0\ud638\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\ub77c\ub294 \uc804 \uac70\ub798\uc77c\uc758 \ud558\ub77d \uc6d0\uc778\uc740 \ud574\uc18c\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\ub35c\ub780\ub4dc \ub300\ud615 \uc740\ud589 ING\uac00 \uc57d 5\uc5b5 \ub2ec\ub7ec \uaddc\ubaa8\uc758 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828 \ub300\ucd9c\ucc44\uad8c \ub9e4\uac01\uc744 \ucd94\uc9c4\ud55c\ub2e4\ub294 \ubcf4\ub3c4\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uc6b0\ub824\uac00 \uc2e4\ubb3c \uc2e0\uc6a9\uc2dc\uc7a5\uc73c\ub85c \ubc88\uc9c0\uace0 \uc788\ub2e4\ub294 \uc2e0\ud638\ub85c, \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ub17c\uc7c1\uc774 \ub2e8\uc21c\ud55c \uc8fc\uac00 \uc870\uc815\uc744 \ub118\uc5b4 \uc2e0\uc6a9\uc704\ud5d8 \ub17c\uc758\ub85c \ud655\uc0b0\ub418\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc774 0.41% \uc624\ub974\uba70 \ub2ec\ub7ec \uac15\uc138\uac00 \uc774\uc5b4\uc9c4 \uc810\ub3c4 \uc704\ud5d8\uc790\uc0b0 \ud68c\ud53c \uc2ec\ub9ac\uac00 \uc644\uc804\ud788 \uac00\uc2dc\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uac04 \ubc29\ud5a5 \ucc28\uc774\ub294 \ubc18\ub4f1\uc758 \uc131\uaca9\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c \ub099\ud3ed\uc774 \uac00\uc7a5 \ucef8\ub358 \ub098\uc2a4\ub2e5\uc774 1.09% \uc624\ub974\uba70 \ubc18\ub4f1\uc744 \uc8fc\ub3c4\ud588\uace0, \uc6b0\ub7c9\uc8fc\uc640 \uac00\uce58\uc8fc \ube44\uc911\uc774 \ub192\uc740 \ub2e4\uc6b0\uc9c0\uc218\ub294 0.46% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc790\uae08\uc774 \uc804 \uac70\ub798\uc77c \uae09\ub77d\uc8fc\ub97c \ub418\uc0ac\ub294 \ucabd\uc73c\ub85c \uc6c0\uc9c1\uc600\uace0, \uc2dc\uc7a5 \uc804\ubc18\uc758 \uc704\ud5d8 \uc120\ud638\uac00 \ud68c\ubcf5\ub41c \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n\uccab\uc9f8, 10\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c\uac00 \uc608\uc0c1\uc744 \ud06c\uac8c \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8 \ub178\ub3d9\ubd80\uc5d0 \ub530\ub974\uba74 10\uc6d4 \ube44\ub18d\uc5c5 \ubd80\ubb38 \uc2e0\uaddc \uace0\uc6a9\uc740 16\ub9cc 5\ucc9c \uba85 \uc99d\uac00\ud588\uace0, \uc2dc\uc7a5 \uc608\uc0c1\uce58 5\ub9cc 9\ucc9c \uba85\uc744 \ud06c\uac8c \uc0c1\ud68c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\ubb38 \uc11c\ube44\uc2a4 \ubd80\ubb38\uc5d0\uc11c \uc77c\uc790\ub9ac\uac00 7\ub9cc \uac1c \ub298\uc5b4 \ucd5c\uadfc 12\uac1c\uc6d4 \ud3c9\uade0 1\ub9cc 5\ucc9c \uac1c\ub97c \ub300\ud3ed \uc6c3\ub3cc\uc558\uace0, \uac74\uc124 \ubd80\ubb38\uc5d0\uc11c\ub294 \uace0\uc6a9\uc774 3\ucc9c \uba85 \uac10\uc18c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9 \ud638\uc870\uc5d0 12\uc6d4 \uae08\ub9ac \uc778\uc0c1 \ud655\ub960\uc740 66%\uc5d0\uc11c 76%\ub85c \uc62c\ub790\uace0, 2\ub144\ubb3c \uad6d\ucc44\uae08\ub9ac\ub294 5bp \uae09\ub4f1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\uc774 \uac15\ud558\ub2e4\ub294 \uc18c\uc2dd\uc740 \uacbd\uae30\uc5d0\ub294 \uae0d\uc815\uc801\uc774\uc9c0\ub9cc \uae08\ub9ac \uacbd\ub85c\uc5d0\ub294 \ubd80\ub2f4\uc774 \ub418\ub294 \uc591\uba74\uc131\uc744 \uc9c0\ub154\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uace0\uac00\uc5d0\uc11c \ubc00\ub824 \ub9c8\uac10\ud55c \ubc30\uacbd\uc5d0\ub294 \uc774 \uc591\uba74\uc131\uc774 \uc790\ub9ac\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\ub458\uc9f8, \uc778\uacf5\uc9c0\ub2a5\uc8fc\uc640 \ubc18\ub3c4\uccb4\uc8fc\uc5d0 \uc800\uac00 \ub9e4\uc218\uc138\uac00 \uc720\uc785\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 6% \ub118\uac8c \uc62c\ub77c 9,586.08\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c \uc885\uac00 9,011.14 \ub300\ube44 6.38% \uc624\ub978 \uc218\uc900\uc73c\ub85c, \uc804 \uac70\ub798\uc77c \ud558\ub77d \ud3ed\uc758 \uc808\ubc18 \uac00\uae4c\uc774\ub97c \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 11\uc6d4 4\uc77c \uc885\uac00 10,268.65 \ub300\ube44\ub85c\ub294 \uc5ec\uc804\ud788 6.65% \ub0ae\uc740 \uc218\uc900\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\ub3c4 \uc804 \uac70\ub798\uc77c \ud558\ub77d \ud3ed\uc758 18.6%\ub9cc \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc774 \uc2dc\uc791\ub410\uc9c0\ub9cc \ud558\ub77d \uc774\uc804 \uc218\uc900 \ud68c\ubcf5\uae4c\uc9c0\ub294 \uac70\ub9ac\uac00 \uba40\uace0, \ub418\ub3cc\ub9bc\uc758 \uc131\uaca9\uc774 \uac15\ud558\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\\n\uc14b\uc9f8, \uae09\ub77d\uc758 \uc5ec\ud30c\uac00 \uae00\ub85c\ubc8c \uc2dc\uc7a5\uacfc \uc2e0\uc6a9\uc2dc\uc7a5\uc73c\ub85c \ud655\uc0b0\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d \ucf54\uc2a4\ud53c\ub294 11\uc6d4 6\uc77c \uac1c\uc7a5 \uc9c1\ud6c4 8% \ub118\uac8c \uae09\ub77d\ud574 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ud588\uace0, \uc7a5\uc911 5,000\uc120 \uc544\ub798\ub85c \ub5a8\uc5b4\uc84c\ub2e4\uac00 5,059.69\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc740 \uc774\ub0a0 \uc57d 2\uc870 8\ucc9c\uc5b5 \uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uac00 \uba54\ubaa8\ub9ac \ubc18\ub3c4\uccb4 \uc218\uc694 \ub454\ud654 \uc6b0\ub824\ub85c \uc774\uc5b4\uc9c0\uba70 \ud55c\uad6d \ubc18\ub3c4\uccb4\uc8fc\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0bc\uc131\uc804\uc790\ub294 \uc774\ud2c0 \ub9cc\uc5d0 12.69%, SK\ud558\uc774\ub2c9\uc2a4\ub294 17.18% \ud558\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\nING\uc758 \ub370\uc774\ud130\uc13c\ud130 \ub300\ucd9c \ub9e4\uac01 \ucd94\uc9c4 \ubcf4\ub3c4\uc640 \ub9de\ubb3c\ub824, \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ub17c\uc7c1\uc774 \uc8fc\uac00\ubfd0 \uc544\ub2c8\ub77c \uc2e0\uc6a9\uacfc \uae00\ub85c\ubc8c \uc218\uae09\uc73c\ub85c \ubc88\uc9c0\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\ub098\uc2a4\ub2e5\uc758 \uc0c1\uc2b9\ub960\uc774 \uac00\uc7a5 \ucef8\ub358 \uac83\uc740 \uc804 \uac70\ub798\uc77c \ub099\ud3ed\uc774 \uac00\uc7a5 \ucef8\ub358 \uae30\uc220\uc8fc\uc640 \ubc18\ub3c4\uccb4\uc8fc\uc758 \ub418\ub3cc\ub9bc\uc774 \uc9d1\uc911\ub410\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\uac00 6.38% \uc624\ub974\uba70 \ubc18\ub4f1\uc744 \uc8fc\ub3c4\ud588\uace0, \uc774\ub294 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790\uc5d0 \ub300\ud55c \uc7ac\ud3c9\uac00\uac00 \uc77c\ub2e8 \uc9c4\uc815\ub418\ub294 \ucabd\uc73c\ub85c \uc6c0\uc9c1\uc600\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ubc18\ub3c4\uccb4\uc9c0\uc218\uac00 11\uc6d4 4\uc77c \uc218\uc900\uc744 \ud68c\ubcf5\ud558\uc9c0 \ubabb\ud55c \uc810\uc740 \uc7ac\ud3c9\uac00\uac00 \ub05d\ub0ac\ub2e4\uace0 \ubcf4\uae30 \uc5b4\ub835\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\nS&P500\uc740 \uae30\uc220\uc8fc \ube44\uc911\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub0ae\uace0, \uae08\ub9ac \uc778\uc0c1 \uae30\ub300\uc5d0 \ubbfc\uac10\ud55c \uc131\uc7a5\uc8fc\uc640 \ubc29\uc5b4\uc8fc\uac00 \uc11e\uc5ec \uc788\uc5b4 \uc0c1\uc2b9\ub960\uc774 0.31%\uc5d0 \uadf8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc0b0\uc5c5\uc7ac\uc640 \uac00\uce58\uc8fc\uc640 \uc6b0\ub7c9\uc8fc \ube44\uc911\uc774 \ub192\uc544 \uc804 \uac70\ub798\uc77c \ub099\ud3ed\uc774 \uac00\uc7a5 \uc791\uc558\uc9c0\ub9cc, \uc774\ub0a0\uc740 0.46% \ud558\ub77d\ud558\uba70 \ubc18\ub4f1\uc5d0\uc11c \uc18c\uc678\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ubc18\ub4f1 \uc790\uae08\uc774 \uc804 \uac70\ub798\uc77c \uae09\ub77d\uc8fc\uc5d0 \uc9d1\uc911\ub410\uace0, \uc6b0\ub7c9\uc8fc \ucabd\uc73c\ub85c\ub294 \uc21c\ud658\ub418\uc9c0 \uc54a\uc558\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\uc5d0\ub108\uc9c0 \uc139\ud130\ub294 \uc720\uac00 \ud750\ub984\uacfc \ubcc4\uac1c\ub85c \uc6c0\uc9c1\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0 \uc6d0\uc720\ub294 \uc7a5\uc911 \ubc30\ub7f4\ub2f9 91\ub2ec\ub7ec\ub300 \uc911\ubc18\uae4c\uc9c0 \uc62c\ub790\uace0, \ube0c\ub80c\ud2b8\uc720\ub294 \uc7a5\uc911 \ubc30\ub7f4\ub2f9 100\ub2ec\ub7ec\ub97c \ub2e4\uc2dc \ub118\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc911\ub3d9 \uc720\uc870\uc120 \uacf5\uaca9 \uc18c\uc2dd\uc5d0 \ub530\ub978 \uacf5\uae09 \ucc28\uc9c8 \uc6b0\ub824\uac00 \uc720\uac00\ub97c \ub04c\uc5b4\uc62c\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ub450 \uc720\uc885 \ubaa8\ub450 \uc8fc\uac04 \uae30\uc900\uc73c\ub85c\ub294 12% \uc548\ud30e\uc758 \ud558\ub77d\uc774 \uc608\uc0c1\ub3fc, \uc720\uac00 \ubc18\ub4f1\uc740 \uc8fc\uac04 \uae09\ub77d \uc18d \ub418\ub3cc\ub9bc\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5f0\uacb0\uace0\ub9ac\ub294 \uace0\uc6a9\uc5d0\uc11c \uc2dc\uc791\ud574 \uae08\ub9ac\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9 \ud638\uc870\ub294 \uae08\ub9ac \uc778\uc0c1 \uae30\ub300\ub97c \ub192\uc774\uace0, \uae08\ub9ac \uc0c1\uc2b9\uc740 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc73c\ub85c \uc774\uc5b4\uc9c0\uba70, \uc774\ub294 \ub098\uc2a4\ub2e5\uc758 \uc7a5\uc911 \ub418\ubc00\ub9bc\uc73c\ub85c \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\uc815\ub9ac\ud558\uba74 \uc774\ub0a0\uc740 \uc778\uacf5\uc9c0\ub2a5 \uaddc\uc81c \uc6b0\ub824\uac00 \uac00\uc2e0 \ub0a0\uc774 \uc544\ub2c8\ub77c, \uae09\ub77d \uc774\ud6c4 \ub418\ub3cc\ub9bc\uacfc \uae08\ub9ac \ubd80\ub2f4\uc774 \ub9de\ubd80\ub52a\ud78c \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7S&P500 \ub9c8\uac10 \ud750\ub984\\n\\nS&P500\uc740 7,376.86\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 23.13, \ub4f1\ub77d\ub960\uc740 0.31%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,353.73\uc785\ub2c8\ub2e4.<br/>\\nYahoo Finance \uc77c\ubd09 \uae30\uc900 S&P500 \ub2f9\uc77c \uc2dc\uac00\ub294 7,377.65, \uace0\uac00\ub294 7,444.20, \uc800\uac00\ub294 7,369.55\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 51,285.73\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 -237.33, \ub4f1\ub77d\ub960\uc740 -0.46%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\nYahoo Finance \uc77c\ubd09 \uae30\uc900 \ub2e4\uc6b0\uc9c0\uc218 \ub2f9\uc77c \uc2dc\uac00\ub294 51,078.85, \uace0\uac00\ub294 51,662.26, \uc800\uac00\ub294 50,992.61\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c\uacfc \ube44\uad50\ud558\uba74 \ud798\uc758 \ubc30\uce58\uac00 \ubc14\ub00c\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c\uc5d0\ub294 \ub2e4\uc6b0\uc9c0\uc218\uac00 3.44% \ud558\ub77d\uc73c\ub85c \ub099\ud3ed\uc774 \uac00\uc7a5 \uc791\uc558\uc9c0\ub9cc, \uc774\ub0a0\uc740 \uc138 \uc9c0\uc218 \uc911 \uc720\uc77c\ud558\uac8c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\uc740 \uc804 \uac70\ub798\uc77c 334.89 \ud558\ub77d\ud588\ub358 \uac83\uc758 6.9%\ub9cc \ub418\ub3cc\ub838\uace0, \ub098\uc2a4\ub2e5\uc740 \uc804 \uac70\ub798\uc77c 1,421.51 \ud558\ub77d\ud588\ub358 \uac83\uc758 18.6%\ub97c \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc774 \ub098\uc2a4\ub2e5\uc5d0 \uc9d1\uc911\ub410\uace0, \uadf8 \ud3ed\ub3c4 \uc804 \uac70\ub798\uc77c \ud558\ub77d\uc758 \uc77c\ubd80\uc5d0 \uadf8\ucce4\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \ub2e4\uc74c \uac70\ub798\uc77c \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ud750\ub984 \uc9c0\uc18d\uacfc \uc77c\uc2dc\uc801 \ubc18\ub4f1\uc744 \uad6c\ubd84\ud558\ub294 \uae30\uc900\uc740 \uc138 \uac00\uc9c0\uc785\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uc800\uac00 24,507.63 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uac04\uc774 \ubb34\ub108\uc9c0\uba74 \ubc18\ub4f1\uc774 \uaebe\uc774\uace0 \uc870\uc815 \uad6c\uac04\uc5d0\uc11c\uc758 \ud558\ub77d\uc774 \uc774\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uace0\uac00 24,825.55\uc640 25,000 \uad6c\uac04\uc744 \ud68c\ubcf5\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uac04\uc744 \ud68c\ubcf5\ud558\uc9c0 \ubabb\ud558\uace0 \ub418\ubc00\ub9ac\uba74 \ubc18\ub4f1 \ub3d9\ub825\uc774 \uc57d\ud558\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ubc18\ub3c4\uccb4\uc8fc\uc758 \ubc18\ub4f1\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\uac00 9,500 \uad6c\uac04\uc744 \uc9c0\ud0a4\uace0 10,000 \uad6c\uac04\uc744 \ud5a5\ud574 \uc624\ub974\ub294\uc9c0, \uc544\ub2c8\uba74 \ub418\ubc00\ub9ac\ub294\uc9c0\uac00 \uc9c0\uc218 \uc804\ubc18\uc758 \ubc29\ud5a5\uc744 \uac00\ub97c \uac83\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uac70\ub798\uc77c \uc774\ud6c4 \ud655\uc778\ud560 \uc774\ubca4\ud2b8\ub85c\ub294 \uc5f0\uc900 \uad00\uacc4\uc790 \ubc1c\uc5b8\uacfc \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \ub17c\uc758\uc758 \uad6c\uccb4\ud654 \uc5ec\ubd80\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \ubc29\ud5a5\uc774 \uad6c\uccb4\ud654\ub418\uae30 \uc804\uc5d0\ub294 \ud558\ub8e8\uc758 \ubc18\ub4f1\ub9cc\uc73c\ub85c \ucd94\uc138 \uc804\ud658\uc744 \ub2e8\uc815\ud558\uc9c0 \uc54a\uace0, \uc800\uac00 \uc9c0\uc9c0 \uc5ec\ubd80\uc640 \uc139\ud130 \ud655\uc0b0 \uc5ec\ubd80\ub97c \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n12\uc6d4 \uae08\ub9ac \uc778\uc0c1 \ud655\ub960\uc774 76%\uae4c\uc9c0 \uc624\ub978 \ub9cc\ud07c, \uc5f0\uc900 \uc778\uc0ac\ub4e4\uc758 \ubc1c\uc5b8 \ud558\ub098\ud558\ub098\uac00 \uae08\ub9ac \uacbd\ub85c\uc5d0 \ub300\ud55c \uac00\uc815\uc744 \ubc14\uafc0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc120\ubb3c\uc740 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uae30\uc900 27,116.75\ub85c \uc804\uc77c \ub300\ube44 1.36% \uc0c1\uc2b9\ud55c \uc0c1\ud0dc\uc774\uba70, \uc120\ubb3c \uc2dc\uc7a5\uc758 \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0\ub3c4 \ud655\uc778\ud560 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \ub17c\uc758\uc640 \ubc18\ub3c4\uccb4 \uc218\uc694 \uc804\ub9dd, \uadf8\ub9ac\uace0 12\uc6d4 \uc5f0\ubc29\uacf5\uac1c\uc2dc\uc7a5\uc704\uc6d0\ud68c\ub97c \uc55e\ub454 \uae08\ub9ac \uacbd\ub85c\uac00 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0\uc740 \uc804 \uac70\ub798\uc77c \ud3ed\ub77d \uc774\ud6c4 \uc800\uac00 \ub9e4\uc218\uc138\uac00 \ub4e4\uc5b4\uc654\uc9c0\ub9cc, \uace0\uc6a9 \ud638\uc870\uc5d0 \ub530\ub978 \uae08\ub9ac \uc778\uc0c1 \uae30\ub300\uac00 \ubc18\ub4f1\uc758 \uc0c1\ub2e8\uc744 \ub204\ub978 \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0, \ub2e4\uc2dc \ubc00\ub9ac\ub294\uc9c0\ub294 \ub2f9\uc77c \uace0\uc800 \uad6c\uac04\uacfc \ubc18\ub3c4\uccb4\uc8fc\uc758 \ud750\ub984\uc5d0\uc11c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc21c\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-06-nasdaq-market-midday","metadata":{"permalink":"/blog/en/market/2026-11-06-nasdaq-market-midday","source":"@site/market/2026-11-06-nasdaq-market-midday/index.mdx","title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911 1.15% \uc0c1\uc2b9, \uace0\uc6a9\xb7\uc18c\ube44\uc2ec\ub9ac \ud638\uc870\uc5d0\ub3c4 \ubc18\ub3c4\uccb4 \ub418\ub3cc\ub9bc\uc5d0 \uc0c1\uc2b9\ud3ed \ucd95\uc18c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-06T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":11.3,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-06-nasdaq-market-midday","title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911 1.15% \uc0c1\uc2b9, \uace0\uc6a9\xb7\uc18c\ube44\uc2ec\ub9ac \ud638\uc870\uc5d0\ub3c4 \ubc18\ub3c4\uccb4 \ub418\ub3cc\ub9bc\uc5d0 \uc0c1\uc2b9\ud3ed \ucd95\uc18c","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 11\uc6d4 6\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-06-nasdaq-market-close"},"nextItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \uace0\uc6a9 \uc11c\ud504\ub77c\uc774\uc988\uc640 \ubc18\ub3c4\uccb4 \ubc18\ub4f1\uc5d0 1.72% \uc0c1\uc2b9 \ucd9c\ubc1c","permalink":"/blog/en/market/2026-11-06-nasdaq-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 6\uc77c \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 \uc7a5\uc911 \ub098\uc2a4\ub2e5 \ud750\ub984\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5\uc911 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc9c0\uc218\ub294 \uc7a5\uc911 1.15% \uc0c1\uc2b9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 12\uc2dc 59\ubd84 \uae30\uc900 24,594.03\uc73c\ub85c, \uc804\uc77c \uc885\uac00 \ub300\ube44 279.03\ud3ec\uc778\ud2b8 \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c 5.52% \uae09\ub77d\ud55c \ub4a4 \ubc18\ub4f1 \ud750\ub984\uc744 \uc774\uc5b4\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc7a5 \ucd08\ubc18 2.10%\uae4c\uc9c0 \uc62c\ub790\ub358 \uc0c1\uc2b9\ud3ed\uc740 \uc7a5\uc911 \ub4e4\uc5b4 \uc808\ubc18 \uac00\uae4c\uc774 \uc904\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n10\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c\uc640 11\uc6d4 \ubbf8\uc2dc\uac04\ub300 \uc18c\ube44\uc2ec\ub9ac\uac00 \uc608\uc0c1\uc744 \uc6c3\ub3cc\uba70 \ubc18\ub4f1\uc758 \uc7ac\ub8cc\uac00 \ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \ubc18\ub3c4\uccb4\uc8fc\uc758 \ub418\ub3cc\ub9bc\uacfc \uae08\ub9ac \uc778\uc0c1 \uc804\ub9dd\uc774 \uc0c1\uc2b9\ud3ed\uc744 \uc81c\ud55c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 24,594.03 | +279.03 | +1.15% | 24,315.00 | 24,825.55 | 24,507.63 |\\n| S&P500 | 7,396.50 | +42.77 | +0.58% | 7,353.73 | 7,444.20 | 7,369.55 |\\n| \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218 | 51,454.38 | -68.68 | -0.13% | 51,523.06 | 51,662.26 | 50,992.61 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 11\uc6d4 6\uc77c 12\uc2dc 59\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 11\uc6d4 7\uc77c 2\uc2dc 59\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc218\uce58\uc640 \ub2e4\uc6b0\uc874\uc2a4 \uc218\uce58\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uacfc [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569 \uac00\uaca9](https://stock.naver.com/worldstock/index/.IXIC/price), [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub2e4\uc6b0\uc874\uc2a4 \uac00\uaca9](https://stock.naver.com/worldstock/index/.DJI/price)\uc5d0\uc11c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uacfc\ub3c4 \uad50\ucc28 \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 24,545.93\uc73c\ub85c \uc804\uc77c \ub300\ube44 230.93\ud3ec\uc778\ud2b8, 0.95% \uc0c1\uc2b9\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,384.18\ub85c 0.41% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uac12\uacfc \ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac12\uc758 \ucc28\uc774\ub294 \uc870\ud68c \uc2dc\uc810 \ucc28\uc774 \ubc94\uc704 \uc548\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8\uc640 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uc73c\ub85c \uad50\ucc28 \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \uac12\uc73c\ub85c, \ub9c8\uac10 \uc804\uae4c\uc9c0 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc7a5\uc911 \uac70\ub798\ub7c9\uc740 722,386\ucc9c\uc8fc\ub85c \uc9d1\uacc4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc7a5\uc911 \uac70\ub798\ub7c9\uc740 262,207\ucc9c\uc8fc\ub85c \uc9d1\uacc4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc774\ubc88 \uc7a5\uc911 \ubc18\ub4f1\uc758 \uccab \ubc88\uc9f8 \ucd09\ub9e4\ub294 \uace0\uc6a9\uc785\ub2c8\ub2e4.<br/>\\n10\uc6d4 \ube44\ub18d\uc5c5 \ucde8\uc5c5\uc790 \uc218\uac00 16\ub9cc 5\ucc9c \uba85 \ub298\uba70 \uc608\uc0c1\uce58 6\ub9cc 5\ucc9c \uba85\uc744 2\ubc30 \uc774\uc0c1 \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc5c5\ub960\uc740 4.1%\ub85c \uc608\uc0c1\uce58 4.2%\ubcf4\ub2e4 \ub0ae\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\uc774 \uac15\ud558\ub2e4\ub294 \uc2e0\ud638\ub294 \uacbd\uae30\uac00 \uc544\uc9c1 \uacac\uc870\ud558\ub2e4\ub294 \ud655\uc778\uc73c\ub85c \uc77d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\uc911\uac04\uc120\uac70 \uc774\ud6c4 \ubd88\ud655\uc2e4\uc131\uc774 \ucee4\uc9c4 \uc0c1\ud669\uc5d0\uc11c, \uc2e4\ubb3c \uacbd\uae30\uc758 \ud68c\ubcf5\ub825\uc774 \ubc18\ub4f1\uc758 \uadfc\uac70\uac00 \ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \ubc88\uc9f8 \ucd09\ub9e4\ub294 \uc18c\ube44\uc2ec\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n11\uc6d4 \ubbf8\uc2dc\uac04\ub300 \uc18c\ube44\uc790\uc2ec\ub9ac\uc9c0\uc218 \uc608\ube44\uce58\uac00 51.0\uc73c\ub85c, 10\uc6d4 \ucd5c\uc885\uce58 48.0\uacfc \uc608\uc0c1\uce58 48.0\uc744 \ubaa8\ub450 \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\uc5d0 \uc774\uc5b4 \uc18c\ube44\uc2ec\ub9ac\uae4c\uc9c0 \uc608\uc0c1\uc744 \uc6c3\ub3cc\uba74\uc11c, \uacbd\uae30 \ub454\ud654 \uc6b0\ub824\uac00 \uc7a5\uc911\uc5d0\ub294 \ub418\ub3cc\ub824\uc9c0\ub294 \ubaa8\uc2b5\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ub450 \uc9c0\ud45c\uac00 \ubaa8\ub450 \uae08\ub9ac\uc5d0\ub294 \ubd80\ub2f4\uc785\ub2c8\ub2e4.<br/>\\n\uac15\ud55c \uace0\uc6a9\uc740 \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc758 \uae08\ub9ac \uc778\uc0c1 \uc5ec\uc9c0\ub97c \ud0a4\uc6b0\ub294 \uc7ac\ub8cc\uc785\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 CME \ud398\ub4dc\uc6cc\uce58 \uae30\uc900 12\uc6d4 \uc5f0\ubc29\uacf5\uac1c\uc2dc\uc7a5\uc704\uc6d0\ud68c\uc5d0\uc11c\uc758 25bp \uae08\ub9ac \uc778\uc0c1 \ud655\ub960\uc740 72.8%\ub85c \uc9d1\uacc4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d 10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc740 4.84% \uc218\uc900\uc73c\ub85c, \uc804\uc77c \uc885\uac00 4.837%\uc640 \uac70\uc758 \uac19\uc740 \uc218\uc900\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00 4.903%\uae4c\uc9c0 \uc62c\ub790\ub358 \uae08\ub9ac\uac00 \ub418\ub3cc\ub824\uc84c\ub2e4\ub294 \uc810\uc740, \uae08\ub9ac \ubd80\ub2f4\uc774 \uc7a5\uc911\uc5d0\ub294 \ub2e4\uc18c \uc644\ud654\ub41c \uc2e0\ud638\uc785\ub2c8\ub2e4.<br/>\\n\uadf8\ub7fc\uc5d0\ub3c4 \ub098\uc2a4\ub2e5 \uc0c1\uc2b9\ud3ed\uc774 \uc7a5\uc911 \uc808\ubc18 \uac00\uae4c\uc774 \uc904\uc5c8\ub2e4\ub294 \uc810\uc740, \uae08\ub9ac \ubd80\ub2f4\uc774 \uc644\uc804\ud788 \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec\uc9c0\uc218\ub294 102.234\ub85c \uc804\uc77c \ub300\ube44 0.68% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc740 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uae30\uc900 1,361.60\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.45% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uac15\uc138\uac00 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370\uc11c\ub3c4 \uae30\uc220\uc8fc\uac00 \uc62c\ub790\ub2e4\ub294 \uc810\uc740, \uc774\ub0a0 \ub9e4\uc218\uc138\uac00 \ud658\uc728\ubcf4\ub2e4\ub294 \uace0\uc6a9\uacfc \ubc18\ub3c4\uccb4 \uc7ac\ub8cc\uc5d0 \ubc18\uc751\ud588\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uad6d\uc81c\uc720\uac00\ub294 \uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0\uc6d0\uc720\uac00 89.93\ub2ec\ub7ec\ub85c \uc804\uc77c \ub300\ube44 0.65% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc740 \uc778\ud50c\ub808\uc774\uc158 \uc555\ub825\uc744 \ub0ae\ucd94\ub294 \uc694\uc778\uc778 \ub3d9\uc2dc\uc5d0, \uc704\ud5d8\uc790\uc0b0 \uc2ec\ub9ac\uac00 \uc644\uc804\ud788 \ud68c\ubcf5\ub418\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc2e0\ud638\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4.<br/>\\n\uacf5\ud3ec\uc9c0\uc218\ub294 25.34\ub85c \uc804\uc77c \uc885\uac00 28.18\ubcf4\ub2e4 10.08% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc800\uac00 23.47\uae4c\uc9c0 \ub0b4\ub824\uac14\ub2e4\uac00 \ub418\ub3cc\ub824\uc84c\uace0, \ud22c\uc790 \uc2ec\ub9ac\ub294 \uc804\uc77c\ubcf4\ub2e4 \uc644\ud654\ub410\uc9c0\ub9cc \uc5ec\uc804\ud788 \ub192\uc740 \uc218\uc900\uc785\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\ub77c\ub294 \uc804\uc77c\uc758 \ud558\ub77d \uc6d0\uc778\uc740 \uc544\uc9c1 \ud574\uc18c\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uc6b0\ub824\uac00 \uc2e4\uc81c \ubc95\uc548\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc5ec\ubd80\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6b0\ub824\uac00 \uc2ec\ub9ac\uc5d0 \uadf8\uce58\uba74 \ubc18\ub4f1\uc774 \uc774\uc5b4\uc9c8 \uc5ec\uc9c0\uac00 \uc788\uace0, \uc815\ucc45\uc73c\ub85c \uad73\uc5b4\uc9c0\uba74 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \ub17c\uc7c1\uc740 \uc911\uae30 \uc7ac\ub8cc\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\uc804\uc77c 3\ub300 \uc9c0\uc218\uac00 \ub098\ub780\ud788 2025\ub144 4\uc6d4 \uc774\ud6c4 \ucd5c\uc545\uc758 \ud558\ub8e8\ub97c \uae30\ub85d\ud55c \ub4a4\uc758 \ubc18\ub4f1\uc774\ub77c\ub294 \uc810\ub3c4 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 5.52%, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\uac00 4.36%, \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\uac00 3.44% \ub0b4\ub838\ub358 \ub9cc\ud07c, \uc774\ub0a0 \uc0c1\uc2b9\uc740 \ub099\ud3ed \ub418\ub3cc\ub9bc\uc758 \uc131\uaca9\uc774 \uac15\ud569\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uc804\uc77c \ud558\ub8e8 \ub3d9\uc548 \uae30\uc220\uc8fc \uc2dc\uac00\ucd1d\uc561 2\uc870 3\ucc9c\uc5b5 \ub2ec\ub7ec\uac00 \uc99d\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uac04 \ubc29\ud5a5 \ucc28\uc774\ub3c4 \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 1.15% \uc624\ub978 \ubc18\uba74 \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 0.13% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc774 \uc2dc\uc7a5 \uc804\ubc18\uc774 \uc544\ub2c8\ub77c \uc804\uc77c \uac00\uc7a5 \ub9ce\uc774 \ube60\uc9c4 \uae30\uc220\uc8fc\uc640 \ubc18\ub3c4\uccb4\uc5d0 \uc9d1\uc911\ub418\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub2e4\uc6b0\uac00 \uc138 \uc9c0\uc218 \uac00\uc6b4\ub370 \ub099\ud3ed\uc774 \uac00\uc7a5 \uc791\uc558\ub358 \uac83\uacfc \ub300\ube44\ub418\ub294, \uae30\uc220\uc8fc \uc911\uc2ec\uc758 \ub418\ub3cc\ub9bc\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### 1. 10\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c \uc11c\ud504\ub77c\uc774\uc988\uc785\ub2c8\ub2e4\\n\\n\ubbf8\uad6d 10\uc6d4 \ube44\ub18d\uc5c5 \ucde8\uc5c5\uc790 \uc218\ub294 16\ub9cc 5\ucc9c \uba85 \uc99d\uac00\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub85c\uc774\ud130 \uc9d1\uacc4 \uc608\uc0c1\uce58 6\ub9cc 5\ucc9c \uba85\uc744 2\ubc30 \uc774\uc0c1 \uc6c3\ub3cc\uc558\uace0, \uc9c0\ub09c 12\uac1c\uc6d4 \uc6d4\ud3c9\uade0 \uc99d\uac00 \ud3ed 4\ub9cc 8\ucc9c \uba85\uc758 3\ubc30\ub97c \ub118\uacbc\uc2b5\ub2c8\ub2e4.<br/>\\n\uc99d\uac00\ub294 \uc804\ubb38\xb7\uc0ac\uc5c5 \uc11c\ube44\uc2a4 7\ub9cc \uba85, \uc758\ub8cc 4\ub9cc 2\ucc9c \uba85, \uc6b4\uc1a1\xb7\ucc3d\uace0 2\ub9cc 5\ucc9c \uba85, \uc81c\uc870\uc5c5 1\ub9cc 9\ucc9c \uba85\uc73c\ub85c \uc5c5\uc885 \uc804\ubc18\uc5d0 \ud37c\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc5c5\ub960\uc740 4.1%\ub85c \ub0ae\uc544\uc84c\uace0, \uacbd\uc81c\ud65c\ub3d9\ucc38\uac00\uc728\uc740 61.9%\ub85c 3\uc6d4 \uc774\ud6c4 \uac00\uc7a5 \ub192\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n9\uc6d4 \ucde8\uc5c5\uc790 \uc218 \uc99d\uac00 \ud3ed\uc740 2\ub9cc 9\ucc9c \uba85\uc5d0\uc11c 6\ub9cc \uba85\uc73c\ub85c, 8\uc6d4\uc740 13\ub9cc 3\ucc9c \uba85\uc5d0\uc11c 18\ub9cc 6\ucc9c \uba85\uc73c\ub85c \uac01\uac01 \uc0c1\ud5a5 \uc218\uc815\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac04\ub2f9 \ud3c9\uade0 \uc784\uae08\uc740 \uc804\uc6d4 \ub300\ube44 0.4% \uc62c\ub77c 38.00\ub2ec\ub7ec\ub97c \uae30\ub85d\ud588\uace0, \uc804\ub144 \ub300\ube44\ub85c\ub294 3.1% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uace0\uc6a9\uc774 \uacbd\uae30 \ub454\ud654 \uc6b0\ub824\ub97c \ub418\ub3cc\ub9ac\ub294 \uac00\uc7a5 \uc9c1\uc811\uc801\uc778 \uc99d\uac70\uc774\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc911\uac04\uc120\uac70 \uc774\ud6c4 \ubd88\ud655\uc2e4\uc131\uc774 \ucee4\uc9c4 \uc0c1\ud669\uc5d0\uc11c, \uace0\uc6a9 \uc9c0\ud45c\ub294 \uc2e4\ubb3c \uacbd\uae30\uac00 \uc544\uc9c1 \uacac\uc870\ud558\ub2e4\ub294 \uc2e0\ud638\ub97c \uc92c\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uac15\ud55c \uace0\uc6a9\uc740 \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc758 \uae08\ub9ac \uc778\uc0c1 \uac00\ub2a5\uc131\uc744 \ub192\uc785\ub2c8\ub2e4.<br/>\\n\ubc1c\ud45c \uc9c1\ud6c4 10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc774 \uc62c\ub790\uace0, 12\uc6d4 \uae08\ub9ac \uc778\uc0c1 \ud655\ub960\uc774 70%\ub97c \ub118\uacbc\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9 \ud638\uc7ac\uac00 \uae08\ub9ac \ubd80\ub2f4\uc744 \uc774\uae30\ub294\uc9c0, \uc544\ub2c8\uba74 \uc7a5 \ud6c4\ubc18\uc5d0 \uae08\ub9ac \ubd80\ub2f4\uc774 \ub418\ub3cc\ub9bc\uc744 \ubd80\ub974\ub294\uc9c0\uac00 \uc624\ub298 \uc7a5\uc758 \uad00\uc804 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\\n### 2. \ubbf8\uc2dc\uac04\ub300 \uc18c\ube44\uc2ec\ub9ac \uc608\ube44\uce58 \uc608\uc0c1 \uc0c1\ud68c\uc785\ub2c8\ub2e4\\n\\n\ubbf8\uc2dc\uac04\ub300 \uc18c\ube44\uc790\uc2ec\ub9ac\uc9c0\uc218 11\uc6d4 \uc608\ube44\uce58\ub294 51.0\uc73c\ub85c \ubc1c\ud45c\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n10\uc6d4 \ucd5c\uc885\uce58 48.0\ubcf4\ub2e4 3.0\ud3ec\uc778\ud2b8 \uc62c\ub790\uace0, \uc608\uc0c1\uce58 48.0\ub3c4 \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n3\uac1c\uc6d4 \ub9cc\uc5d0 \uac00\uc7a5 \ub192\uc740 \uc218\uc900\uc774\uc9c0\ub9cc, \uc5ec\uc804\ud788 \uc5ed\uc0ac\uc801 \uc800\uc810 \ubd80\uadfc\uc5d0 \uba38\ubb3c\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\ub300 \ucd5c\uc800\uce58\ub294 \uc9c0\ub09c 5\uc6d4 \uae30\ub85d\ud55c 44.8\uc785\ub2c8\ub2e4.<br/>\\n\ud604\uc7ac \uc5ec\uac74 \uc9c0\uc218\ub294 51.0\uc73c\ub85c 10\uc6d4 46.7\uc5d0\uc11c \uc62c\ub790\uace0, \uae30\ub300 \uc9c0\uc218\ub294 50.9\ub85c 10\uc6d4 48.8\uc5d0\uc11c \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ud5a5\ud6c4 1\ub144 \uae30\ub300 \uc778\ud50c\ub808\uc774\uc158\uc740 4.3%\ub85c 10\uc6d4 4.7%\uc5d0\uc11c \ub0b4\ub824\uc654\uace0, 5\ub144 \uae30\ub300 \uc778\ud50c\ub808\uc774\uc158\uc740 3.4%\ub85c 10\uc6d4 3.5%\uc5d0\uc11c \ub0b4\ub824\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uc18c\ube44\uc2ec\ub9ac\uac00 \uace0\uc6a9\uacfc \uac19\uc740 \ubc29\ud5a5\uc758 \ud655\uc778 \uc2e0\ud638\ub97c \uc92c\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uac00\uacc4\uc758 \uccb4\uac10 \uacbd\uae30\uac00 \ubc14\ub2e5\uad8c\uc5d0\uc11c \uc18c\ud3ed \uac1c\uc120\ub410\ub2e4\ub294 \uc810\uc740, \uacbd\uae30 \ub454\ud654 \uc6b0\ub824\ub97c \ucd94\uac00\ub85c \ub418\ub3cc\ub9ac\ub294 \uc7ac\ub8cc\uc785\ub2c8\ub2e4.<br/>\\n\uae30\ub300 \uc778\ud50c\ub808\uc774\uc158\uc774 \ud568\uaed8 \ub0b4\ub824\uc654\ub2e4\ub294 \uc810\ub3c4 \uae08\ub9ac \ubd80\ub2f4\uc744 \ub35c\uc5b4\uc8fc\ub294 \ubc29\ud5a5\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc870\uc0ac \uae30\uac04\uc774 10\uc6d4 20\uc77c\ubd80\ud130 11\uc6d4 2\uc77c\uae4c\uc9c0\ub85c, \uc911\uac04\uc120\uac70 \uacb0\uacfc\uac00 \ub098\uc624\uae30 \uc804\uc5d0 \ub05d\ub0ac\ub2e4\ub294 \uc810\uc5d0 \uc720\uc758\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uc774\ud6c4\uc758 \uc2ec\ub9ac\ub294 \uc774\ub2ec \ub9d0 \ubc1c\ud45c\ub418\ub294 \ucd5c\uc885\uce58\uc5d0\uc11c \ud655\uc778\ud560 \uc0ac\uc548\uc785\ub2c8\ub2e4.<br/>\\n\uc608\ube44\uce58\ub77c\ub294 \uc810\uc5d0\uc11c\ub3c4, \uc218\uce58\uac00 \ud655\uc815\uce58\uac00 \uc544\ub2c8\ub77c \ucd94\ud6c4 \uc218\uc815\ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \ud568\uaed8 \ubd10\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n### 3. \ubc18\ub3c4\uccb4 \ubc18\ub4f1 \ud6c4 \ub418\ub3cc\ub9bc\uc785\ub2c8\ub2e4\\n\\n\ub7a8 \ub9ac\uc11c\uce58\ub294 \uc804\uc77c \uc7a5 \ub9c8\uac10 \ud6c4 250\uc5b5 \ub2ec\ub7ec \uaddc\ubaa8\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785 \uc2b9\uc778\uacfc \ubd84\uae30 \ubc30\ub2f9\uae08 0.33\ub2ec\ub7ec\ub97c \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804 \uc8fc\uac00\ub294 10% \ub118\uac8c \uc62c\ub790\uace0, \uc7a5 \ucd08\ubc18\uc5d0\ub294 \uc804\uc77c \uc885\uac00 \ub300\ube44 10.86%\uae4c\uc9c0 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ud604\uc7ac \ub7a8 \ub9ac\uc11c\uce58\ub294 198.69\ub2ec\ub7ec\ub85c \uc804\uc77c \ub300\ube44 7.29% \uc0c1\uc2b9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00 209.18\ub2ec\ub7ec\uc640 \ube44\uad50\ud558\uba74 \uc0c1\uc2b9\ud3ed\uc774 \uc808\ubc18 \uac00\uae4c\uc774 \uc904\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\nAMD\ub294 435.75\ub2ec\ub7ec\ub85c \uc804\uc77c \ub300\ube44 7.75% \uc62c\ub790\uace0, \uc7a5\uc911 \uace0\uac00\ub294 459.78\ub2ec\ub7ec\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9c8\uc774\ud06c\ub860\uc740 681.70\ub2ec\ub7ec\ub85c 3.86% \uc62c\ub790\uace0, \uc7a5\uc911 \uace0\uac00\ub294 724.80\ub2ec\ub7ec\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5d4\ube44\ub514\uc544\ub294 185.995\ub2ec\ub7ec\ub85c 2.42% \uc62c\ub790\uace0, \uc7a5\uc911 \uace0\uac00\ub294 194.895\ub2ec\ub7ec\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ube0c\ub85c\ub4dc\ucef4\uc740 291.36\ub2ec\ub7ec\ub85c \uc804\uc77c \ub300\ube44 0.06% \ub0b4\ub9ac\uba70 \uc7a5 \ucd08\ubc18 \uc0c1\uc2b9\ubd84\uc744 \ubaa8\ub450 \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 9,307.61\ub85c \uc804\uc77c \ub300\ube44 3.29% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00 9,627.26\uacfc \ube44\uad50\ud558\uba74 6.84%\uae4c\uc9c0 \uc62c\ub790\ub358 \uc0c1\uc2b9\ud3ed\uc774 \uc808\ubc18 \uc218\uc900\uc73c\ub85c \uc904\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uc804\uc77c \ubc18\ub3c4\uccb4 \ud3ed\ub77d\uc758 \uc131\uaca9\uacfc \ub9de\ub2ff\uc544 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 12.25% \ud3ed\ub77d\ud588\uace0, \ub098\uc2a4\ub2e5 100 \uc9c0\uc218\ub294 2020\ub144 3\uc6d4 \uc774\ud6c4 \ucd5c\uc545\uc758 \ud558\ub8e8\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud3ed\ub77d\uc758 \uc6d0\uc778\uc774 \uc2e4\uc801\uc774 \uc544\ub2c8\ub77c \uaddc\uc81c \uc6b0\ub824\ub77c\ub294 \uc2ec\ub9ac \uc7ac\ub8cc\uc600\ub358 \ub9cc\ud07c, \uc790\uc0ac\uc8fc \ub9e4\uc785 \uac19\uc740 \uad6c\uccb4\uc801\uc778 \uc7ac\ub8cc\uac00 \uc800\uac00 \ub9e4\uc218\ub97c \ubd80\ub974\ub294 \uacc4\uae30\uac00 \ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc7a5\uc911 \ub418\ub3cc\ub9bc\uc740 \uc800\uac00 \ub9e4\uc218\uac00 \ucc28\uc775 \uc2e4\ud604\uacfc \ub9de\ubd80\ub52a\ud788\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc790\uc0ac\uc8fc \ub9e4\uc785 \uc2b9\uc778\uc740 \ub9e4\uc785 \uc758\ubb34\uac00 \uc544\ub2c8\ub77c \uc0c1\ud55c\uc120\uc774\ub77c\ub294 \uc810\uc5d0\ub3c4 \uc720\uc758\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc81c \ub9e4\uc785 \uaddc\ubaa8\ub294 \ud5a5\ud6c4 \uacf5\uc2dc\ub85c \ud655\uc778\ud560 \uc0ac\uc548\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4\uc758 \ub418\ub3cc\ub9bc\uc774 \ub098\uc2a4\ub2e5 \uc804\uccb4\uc758 \uc0c1\uc2b9\ud3ed \ucd95\uc18c\ub85c \uc9c1\uacb0\ub410\ub2e4\ub294 \uc810\uc5d0\uc11c, \uc774 \uc139\ud130\uc758 \uc7a5 \ud6c4\ubc18 \uc6c0\uc9c1\uc784\uc774 \ub9c8\uac10 \ubc29\ud5a5\uc744 \uac00\ub985\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\ub098\uc2a4\ub2e5\uc774 1.15% \uc624\ub978 \ubc18\uba74 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 0.58%, \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 0.13% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc220\uc8fc \ube44\uc911\uc774 \ub192\uc740 \ub098\uc2a4\ub2e5\uc758 \uc0c1\uc2b9\ud3ed\uc774 \uac00\uc7a5 \ud06c\ub2e4\ub294 \uc810\uc774 \uc774\ubc88 \ubc18\ub4f1\uc758 \uc131\uaca9\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc774 \uc804\uc77c \uac00\uc7a5 \ub9ce\uc774 \ube60\uc9c4 \uae30\uc220\uc8fc\uc640 \ubc18\ub3c4\uccb4\uc5d0 \uc9d1\uc911\ub418\uace0 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uae30\uc220\xb7\ubc18\ub3c4\uccb4 \uc139\ud130\ub294 \ubc18\ub4f1\uc758 \uc911\uc2ec\uc774\uc790 \ub418\ub3cc\ub9bc\uc758 \uc9c4\uc6d0\uc9c0\uc785\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\ub294 \ubc18\ub3c4\uccb4 \uc218\uc694 \uc804\ub9dd\uc744 \ub0ae\ucd94\ub294 \uc7ac\ub8cc\uc600\uace0, \uc774\ub0a0\uc740 \ub7a8 \ub9ac\uc11c\uce58\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785 \uc7ac\ub8cc\uc640 \uc800\uac00 \ub9e4\uc218\uac00 \uac19\uc740 \uc5f0\uacb0\uace0\ub9ac\ub97c \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ubc18\ub3c4\uccb4 \uc0c1\uc2b9\ud3ed\uc774 \uc808\ubc18\uc73c\ub85c \uc904\uba74\uc11c \ub098\uc2a4\ub2e5 \uc0c1\uc2b9\ud3ed\ub3c4 \ud568\uaed8 \uc904\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\uc5d0\uc11c \uae08\ub9ac\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub3c4 \ud568\uaed8 \uc791\ub3d9\ud569\ub2c8\ub2e4.<br/>\\n\uac15\ud55c \uace0\uc6a9\uc740 \uacbd\uae30 \ud68c\ubcf5\ub825\uc744 \ud655\uc778\uc2dc\ucf1c\uc8fc\uc9c0\ub9cc, \ub3d9\uc2dc\uc5d0 \uae08\ub9ac \uc778\uc0c1 \uac00\ub2a5\uc131\uc744 \ub192\uc785\ub2c8\ub2e4.<br/>\\n10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc774 4.84% \uc218\uc900\uc5d0\uc11c \ud6a1\ubcf4\ud558\uace0 \uc788\ub2e4\ub294 \uc810\uc740, \ub450 \ud798\uc774 \uc7a5\uc911 \ud33d\ud33d\ud558\uac8c \ub9de\uc11c\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\uac00 \ub2e4\uc2dc 4.90% \uc704\ub85c \uc624\ub974\uba74 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec\uc5d0\uc11c \uc790\uae08 \ud750\ub984\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub3c4 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec\uc9c0\uc218\ub294 102.234\ub85c \uc804\uc77c \ub300\ube44 0.68% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uac15\uc138\uac00 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370 \uae30\uc220\uc8fc\uac00 \ubc18\ub4f1\ud588\ub2e4\ub294 \uc810\uc740, \uc774\ub0a0 \ub9e4\uc218\uc138\uac00 \ud658\uc728\ubcf4\ub2e4\ub294 \uac1c\ubcc4 \uc7ac\ub8cc\uc5d0 \ubc18\uc751\ud588\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc548\uc804\uc790\uc0b0\uc5d0\uc11c\ub294 \ubc18\ub300 \ud750\ub984\uc774 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08 \uc120\ubb3c\uc740 4,065.20\ub2ec\ub7ec\ub85c \uc804\uc77c \ub300\ube44 1.17% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc704\ud5d8 \uc120\ud638\uac00 \ub418\ub3cc\uc544\uc624\uba74\uc11c \uc548\uc804\uc790\uc0b0 \uc120\ud638\uac00 \uc644\ud654\ub41c \ubaa8\uc2b5\uc785\ub2c8\ub2e4.<br/>\\n\uc5d0\ub108\uc9c0\ub294 \uc720\uac00 \ud558\ub77d\uc758 \uc601\ud5a5\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0\uc6d0\uc720\ub294 89.93\ub2ec\ub7ec\ub85c \uc804\uc77c \ub300\ube44 0.65% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc740 \uc778\ud50c\ub808\uc774\uc158 \uc555\ub825\uc744 \ub0ae\ucd94\ub294 \uc694\uc778\uc778 \ub3d9\uc2dc\uc5d0, \uacbd\uae30 \ub454\ud654 \uc6b0\ub824\uc640 \uc804\uc7c1 \ud504\ub9ac\ubbf8\uc5c4 \uc18c\uba78\uc774 \uacb9\uce5c \uc2e0\ud638\ub85c\ub3c4 \uc77d\ud799\ub2c8\ub2e4.<br/>\\n\uae08\uc735 \uc139\ud130 \ub4f1 \ub2e4\ub978 \uc139\ud130\uc758 \ub2f9\uc77c \ud750\ub984\uc740 \ud655\uc778\ub41c \uc218\uce58\uac00 \uc5c6\uc5b4 \ub2e8\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\ud61c\uc640 \ud0c0\uaca9\uc744 \ub2e8\uc21c\ud788 \ub098\ub204\uae30\ubcf4\ub2e4, \uac19\uc740 \uace0\uc6a9 \uc9c0\ud45c\uac00 \uacbd\uae30 \ud655\uc778\uacfc \uae08\ub9ac \ubd80\ub2f4\uc774\ub77c\ub294 \ub450 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud55c\ub2e4\ub294 \uc810\uc774 \uc774\ubc88 \uc7a5\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911\uc5d0\ub294 \uacbd\uae30 \ud655\uc778 \ucabd \ud574\uc11d\uc774 \uc6b0\uc704\ub97c \uc810\ud558\uace0 \uc788\uc9c0\ub9cc, \uc0c1\uc2b9\ud3ed \ucd95\uc18c\ub294 \uae08\ub9ac \ubd80\ub2f4 \ucabd\uc774 \ub2e4\uc2dc \uace0\uac1c\ub97c \ub4e4\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \ud750\ub984\\n\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 11\uc6d4 5\uc77c 7,353.73\uc73c\ub85c 4.36% \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 6\uc77c \uc7a5 \uc624\ud508 \ubb34\ub835\uc5d0\ub294 7,420.82\ub85c 0.91% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ud604\uc7ac\ub294 7,396.50\uc73c\ub85c 0.58% \uc0c1\uc2b9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc0c1\uc2b9\ub960 1.15%\uc758 \uc808\ubc18 \uc218\uc900\uc73c\ub85c, \uc0c1\uc2b9 \ud3ed\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \uc791\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ubc18\ub4f1\uc774 \uae30\uc220\uc8fc\uc5d0 \uc9d1\uc911\ub418\uace0, \uc2dc\uc7a5 \uc804\ubc18\uc73c\ub85c \uace0\ub974\uac8c \ud655\uc0b0\ub418\uc9c0\ub294 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 11\uc6d4 5\uc77c 51,523.06\uc73c\ub85c 3.44% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138 \uc9c0\uc218 \uac00\uc6b4\ub370 \ub099\ud3ed\uc774 \uac00\uc7a5 \uc791\uc558\uace0, \uc804\uc77c\uc5d0\ub294 \uac00\uce58\uc8fc\uc640 \uc0b0\uc5c5\uc8fc\uac00 \uc0c1\ub300\uc801\uc73c\ub85c \uc120\ubc29\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 6\uc77c \uc7a5 \uc624\ud508 \ubb34\ub835 \ub2e4\uc6b0\ub294 51,436.37\ub85c 0.17% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc800\uac00 50,992.61\uae4c\uc9c0 \ubc00\ub838\ub2e4\uac00 \ud604\uc7ac\ub294 51,454.38\ub85c 0.13% \ud558\ub77d\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc120\ubb3c\uc740 \uc0c1\uc2b9\ud588\uc9c0\ub9cc \ub2e4\uc6b0 \uc120\ubb3c\uc740 \uac1c\uc7a5 \uc804 478\ud3ec\uc778\ud2b8 \ub0b4\ub838\ub358 \ud750\ub984\uc774 \uc7a5 \ucd08\ubc18\uc5d0\ub3c4 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc7a5\uc911 \ub4e4\uc5b4 \ub2e4\uc6b0\ub294 \uc800\uac00\uc5d0\uc11c \ub418\ub3cc\ub824\uc9c0\uba70 \ub099\ud3ed\uc744 \uc904\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uac00\uc7a5 \uc801\uac8c \ube60\uc84c\ub358 \ub2e4\uc6b0\uac00 \ub2f9\uc77c\uc5d0\ub294 \uc720\uc77c\ud558\uac8c \ub0b4\ub9ac\uace0 \uc788\ub2e4\ub294 \uc810\uc774 \ub208\uc5d0 \ub755\ub2c8\ub2e4.<br/>\\n\uae30\uc220\uc8fc\uc5d0\uc11c \ube60\uc838\ub098\uc628 \uc790\uae08\uc774 \uac00\uce58\uc8fc\ub85c \uc62e\uaca8\uac14\ub358 \uc804\uc77c\uc758 \uc21c\ud658\ub9e4\uac00 \ub418\ub3cc\ub824\uc9c0\ub294 \ud750\ub984\uc73c\ub85c \uc77d\ud799\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uac00 \uc7a5 \ud6c4\ubc18\uc5d0 \ub098\uc2a4\ub2e5\uc758 \ubc18\ub4f1\uc5d0 \ub3d9\ucc38\ud558\ub294\uc9c0\uac00 \ud655\uc778\ud560 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uacfc \uc624\ud6c4 \ud750\ub984 \ubcc0\ud654\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc7a5 \uc624\ud508 \ubb34\ub835 24,732.82\ub85c 1.72% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00 24,825.55\uae4c\uc9c0 \uc624\ub974\uba70 \uc0c1\uc2b9\ub960\uc774 2.10%\uae4c\uc9c0 \ud655\ub300\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ud604\uc7ac\ub294 24,594.03\uc73c\ub85c \uc0c1\uc2b9\ub960\uc774 1.15%\uae4c\uc9c0 \uc904\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud604\uc7ac\uac00\ub294 \uc2dc\uac00 24,602.48\ubcf4\ub2e4\ub3c4 8.45\ud3ec\uc778\ud2b8 \uc544\ub798\uc785\ub2c8\ub2e4.<br/>\\n\uc624\uc804\uc758 \uc0c1\uc2b9 \ud655\ub300 \ud750\ub984\uc774 \uc624\ud6c4 \ub4e4\uc5b4 \uc0c1\uc2b9\ud3ed \ucd95\uc18c\ub85c \ubc14\ub010 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc804\uc77c \uc885\uac00 24,315.00\ubcf4\ub2e4\ub294 \uc5ec\uc804\ud788 279.03\ud3ec\uc778\ud2b8 \uc704\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub3c4 \uac19\uc740 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5 \uc624\ud508 \ubb34\ub835 7,420.82\ub85c 0.91% \uc62c\ub790\uace0, \uc7a5\uc911 \uace0\uac00 7,444.20\uae4c\uc9c0 \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ud604\uc7ac\ub294 7,396.50\uc73c\ub85c \uc0c1\uc2b9\ub960\uc774 0.58%\uae4c\uc9c0 \uc904\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc2dc\uac00 7,377.65\ubcf4\ub2e4\ub294 \uc704\uc5d0 \uba38\ubb3c\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \uc624\ud508 \ubb34\ub835 51,436.37\ub85c 0.17% \ub0b4\ub838\uace0, \uc7a5\uc911 \uc800\uac00 50,992.61\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ud604\uc7ac\ub294 51,454.38\ub85c \ub099\ud3ed\uc774 0.13%\uae4c\uc9c0 \uc904\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00 51,078.85\ubcf4\ub2e4 \uc704\uc5d0 \uc788\uace0, \uc800\uac00\uc5d0\uc11c 461.77\ud3ec\uc778\ud2b8 \ub418\ub3cc\ub824\uc9c4 \uc0c1\ud0dc\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 \uace0\uc810\uc5d0\uc11c \ubc00\ub9ac\ub294 \ub3d9\uc548 \ub2e4\uc6b0\ub294 \uc800\uc810\uc5d0\uc11c \ub418\ub3cc\ub824\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub3c4 \uc7a5\uc911 \uace0\uac00 9,627.26\uc5d0\uc11c 9,307.61\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uacf5\ud3ec\uc9c0\uc218\ub294 \uc804\uc77c \uc885\uac00 28.18\uc5d0\uc11c \uc7a5\uc911 25.34\uae4c\uc9c0 \ub0b4\ub824\uc654\uace0, \uc7a5\uc911 \uc800\uac00\ub294 23.47\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804\uc758 \uac15\ud55c \ubc18\ub4f1\uc774 \uc624\ud6c4 \ub4e4\uc5b4 \ucc28\uc775 \uc2e4\ud604\uacfc \ub9de\ubd80\ub52a\ud788\uba70 \uc0c1\uc2b9\ud3ed\uc774 \uc904\uace0 \uc788\ub294 \ubaa8\uc2b5\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10\uae4c\uc9c0 \uc804\ub9dd\uacfc \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ud750\ub984 \uc9c0\uc18d\uacfc \uc77c\uc2dc\uc801 \ub178\uc774\uc988\ub97c \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc774 \uc774\uc5b4\uc9c0\ub824\uba74 \ubc18\ub3c4\uccb4\uc758 \ub418\ub3cc\ub9bc\uc774 \uc7a5 \ud6c4\ubc18\uc5d0 \uba48\ucdb0\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uae08\ub9ac \ubd80\ub2f4\uc774 \uc6b0\uc704\ub97c \uc810\ud558\uba74, \uc7a5 \ucd08\ubc18 \uc0c1\uc2b9 \ud3ed\uc774 \ub354 \ub418\ub3cc\ub824\uc9c8 \uc5ec\uc9c0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ud6c4\ubc18\uc5d0 \ud655\uc778\ud560 \uccab \ubc88\uc9f8 \uc218\uce58\ub294 \uc7a5\uc911 \uc800\uac00\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc800\uac00\ub294 24,507.63\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc218\uc900\uc744 \uc9c0\ucf1c\ub0b4\ub294\uc9c0, \uc544\ub2c8\uba74 \uc804\uc77c \uc885\uac00 24,315.00\uae4c\uc9c0 \ubc00\ub9ac\ub294\uc9c0\uac00 \ub2e8\uae30 \ubc29\ud5a5\uc744 \uac00\ub985\ub2c8\ub2e4.<br/>\\n\uc800\ud56d\uc120\uc73c\ub85c\ub294 \uc7a5\uc911 \uace0\uac00 24,825.55\uc640 25,000\uc120, \uc804\uc804\uc77c \uc885\uac00 25,736.51\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub418\ub3cc\ub9bc\uc774 \uc774\uc5b4\uc9c4\ub2e4\uba74 25,000\uc120 \ud68c\ubcf5 \uc5ec\ubd80\uac00 \uccab \ubc88\uc9f8 \ud655\uc778 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc139\ud130 \ub2e8\uc704\uc5d0\uc11c\ub294 \ubc18\ub3c4\uccb4\uc9c0\uc218\uc758 \uc6c0\uc9c1\uc784\uc774 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c 12.25% \ud3ed\ub77d\ud55c \ubc18\ub3c4\uccb4\uac00 \ub2f9\uc77c \uc0c1\uc2b9 \ud3ed\uc744 \uc720\uc9c0\ud558\ub294\uc9c0, \uc544\ub2c8\uba74 \ub418\ub3cc\ub9bc\uc5d0 \uadf8\uce58\ub294\uc9c0\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \ud750\ub984\ub3c4 \ud568\uaed8 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc774 \uc7a5\uc911 \uace0\uac00 4.903%\ub97c \ub2e4\uc2dc \ub118\ub294\uc9c0, \uc544\ub2c8\uba74 4.84% \uc218\uc900\uc5d0\uc11c \uba38\ubb34\ub294\uc9c0\uac00 \uc131\uc7a5\uc8fc \ubc29\ud5a5\uc744 \uac00\ub985\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec\uc9c0\uc218\uac00 102.234\uc5d0\uc11c \ub354 \uc624\ub974\ub294\uc9c0\ub3c4 \ud655\uc778\ud560 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uac15\uc138\uac00 \uc774\uc5b4\uc9c0\uba74 \uc678\uad6d\uc778 \uc790\uae08 \uc774\ud0c8 \uc555\ub825\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \uc7a5 \ub9c8\uac10\uae4c\uc9c0 \uc608\uc815\ub41c \uc8fc\uc694 \ubbf8\uad6d \uacbd\uc81c\uc9c0\ud45c\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \ud655\uc778\ud560 \uc77c\uc815\uc740 \ud654\uc694\uc77c\uc5d0 \ubc1c\ud45c\ub418\ub294 10\uc6d4 \uc18c\ube44\uc790\ubb3c\uac00\uc9c0\uc218\uc785\ub2c8\ub2e4.<br/>\\n12\uc6d4 9\uc77c \uc5f0\ubc29\uacf5\uac1c\uc2dc\uc7a5\uc704\uc6d0\ud68c\ub97c \uc55e\ub450\uace0 12\uc6d4 4\uc77c \ubc1c\ud45c\ub418\ub294 11\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c\ub3c4 \ud655\uc778\ud560 \uc77c\uc815\uc785\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 \ubbfc\uc8fc\ub2f9\uc758 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uad00\ub828 \uc785\ubc95 \uc6c0\uc9c1\uc784\uacfc \ube45\ud14c\ud06c\uc758 \uc790\ubcf8\uc9c0\ucd9c \uacc4\ud68d\uc744 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc81c \ubc95\uc548\uc774\ub098 \uac00\uc774\ub358\uc2a4 \ubcc0\uacbd\uc774 \ud655\uc778\ub418\uae30 \uc804\uc5d0\ub294, \uaddc\uc81c \uc6b0\ub824\ub97c \ud655\uc815\uc801\uc778 \uc815\ucc45 \ubcc0\ud654\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uac00\uc9c0 \uc2dc\ub098\ub9ac\uc624\ub97c \uc815\ub9ac\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\uccab \ubc88\uc9f8\ub294 \ubc18\ub4f1 \uc720\uc9c0 \uc2dc\ub098\ub9ac\uc624\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uc800\uac00 24,507.63\uc744 \uc9c0\ud0a4\uace0 \ubc18\ub3c4\uccb4\uac00 \uc0c1\uc2b9 \ud3ed\uc744 \uc720\uc9c0\ud558\uba74, \ubc18\ub4f1 \ud750\ub984\uc774 \ub9c8\uac10\uae4c\uc9c0 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \ubc88\uc9f8\ub294 \ub418\ub3cc\ub9bc \ud655\ub300 \uc2dc\ub098\ub9ac\uc624\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \ub418\ub3cc\ub9bc\uc774 \uc774\uc5b4\uc9c0\uace0 \uae08\ub9ac\uac00 \ub2e4\uc2dc \uc624\ub974\uba74, \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \uc885\uac00 24,315.00\uc744 \ub2e4\uc2dc \uc2dc\ud5d8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5b4\ub290 \ucabd\uc774\ub4e0 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc73c\uba70, \uc9c0\uc218\uc640 \uc139\ud130 \ub2e8\uc704\uc758 \ud750\ub984\uc744 \ud655\uc778\ud558\ub294 \uad00\uc810\uc73c\ub85c \ubd10\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n11\uc6d4 6\uc77c \ub098\uc2a4\ub2e5\uc740 \uace0\uc6a9\uacfc \uc18c\ube44\uc2ec\ub9ac \ud638\uc870\uc5d0 \ud798\uc785\uc5b4 \ubc18\ub4f1\uc744 \uc774\uc5b4\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ubc18\ub3c4\uccb4 \ub418\ub3cc\ub9bc\uc73c\ub85c \uc0c1\uc2b9\ud3ed\uc774 \uc904\uace0 \uc788\uc5b4, \ub9c8\uac10\uae4c\uc9c0 \uc7a5\uc911 \uc800\uac00\uc640 \uae08\ub9ac \ud750\ub984\uc744 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-06-nasdaq-market-open","metadata":{"permalink":"/blog/en/market/2026-11-06-nasdaq-market-open","source":"@site/market/2026-11-06-nasdaq-market-open/index.mdx","title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \uace0\uc6a9 \uc11c\ud504\ub77c\uc774\uc988\uc640 \ubc18\ub3c4\uccb4 \ubc18\ub4f1\uc5d0 1.72% \uc0c1\uc2b9 \ucd9c\ubc1c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-06T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":9.27,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-06-nasdaq-market-open","title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \uace0\uc6a9 \uc11c\ud504\ub77c\uc774\uc988\uc640 \ubc18\ub3c4\uccb4 \ubc18\ub4f1\uc5d0 1.72% \uc0c1\uc2b9 \ucd9c\ubc1c","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911 1.15% \uc0c1\uc2b9, \uace0\uc6a9\xb7\uc18c\ube44\uc2ec\ub9ac \ud638\uc870\uc5d0\ub3c4 \ubc18\ub3c4\uccb4 \ub418\ub3cc\ub9bc\uc5d0 \uc0c1\uc2b9\ud3ed \ucd95\uc18c","permalink":"/blog/en/market/2026-11-06-nasdaq-market-midday"},"nextItem":{"title":"2026\ub144 11\uc6d4 5\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 - \ube14\ub8e8\uc6e8\uc774\ube0c \ucda9\uaca9\uc5d0 \uc591 \uc2dc\uc7a5 5%\ub300 \uae09\ub77d","permalink":"/blog/en/market/2026-11-05-domestic-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 6\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uac1c\uc7a5 \ubc30\uacbd\\n\\n\uc804\uc77c \ubbf8\uad6d \uc99d\uc2dc\ub294 2025\ub144 4\uc6d4 \uc774\ud6c4 \ucd5c\uc545\uc758 \ud558\ub8e8\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 5\uc77c \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 24,315.00\uc73c\ub85c \uc804\uc77c \ub300\ube44 5.52% \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,353.73\uc73c\ub85c 4.36% \ub0b4\ub838\uace0, \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 51,523.06\uc73c\ub85c 3.44% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 12.25% \ud3ed\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0\uc778\uc740 \ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc555\uc2b9\ud55c \uc774\ud6c4 \ubd88\uac70\uc9c4 \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \ud558\ub8e8 \ub3d9\uc548 \uae30\uc220\uc8fc \uc2dc\uac00\ucd1d\uc561 2\uc870 3\ucc9c\uc5b5 \ub2ec\ub7ec\uac00 \uc99d\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucda9\uaca9\uc740 \uc544\uc2dc\uc544\ub85c\ub3c4 \ubc88\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 6\uc77c \ucf54\uc2a4\ud53c\ub294 \uac1c\uc7a5 \uc9c1\ud6c4 8.55% \uae09\ub77d\ud574 \uc624\uc804 9\uc2dc 3\ubd84 34\ucd08\uc5d0 1\ub2e8\uacc4 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ud588\uace0, \ucf54\uc2a4\ub2e5\uc5d0\ub294 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc774\ub0a0 6%\ub300 \uae09\ub77d\uc5d0\ub3c4 5,000\uc120\uc744 \uac00\uae4c\uc2a4\ub85c \uc9c0\ucf30\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \ubbf8\uad6d \uc7a5 \uc624\ud508 \ubb34\ub835\uc5d0\ub294 \ubd84\uc704\uae30\uac00 \ub2ec\ub77c\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804 \ubc1c\ud45c\ub41c 10\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c\uac00 \uc608\uc0c1\uc744 \ud06c\uac8c \uc6c3\ub3cc\uc558\uace0, \ubc18\ub3c4\uccb4\uc8fc\uac00 \ub3d9\ubc18 \ubc18\ub4f1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 1.72% \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub3c4 0.91% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 0.17% \ub0b4\ub9ac\uba70 \uc5c7\uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 24,732.82 | +417.82 | +1.72% | 24,315.00 | 24,825.55 | 24,561.11 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-06 10:02, \ud55c\uad6d\uc2dc\uac04 2026-11-07 00:02 |\\n| \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 | 7,420.82 | +67.09 | +0.91% | 7,353.73 | 7,444.20 | 7,369.55 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-06 10:02, \ud55c\uad6d\uc2dc\uac04 2026-11-07 00:02 |\\n| \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218 | 51,436.37 | -86.69 | -0.17% | 51,523.06 | 51,506.97 | 50,992.61 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-06 10:01, \ud55c\uad6d\uc2dc\uac04 2026-11-07 00:01 |\\n\\n\ub2f9\uc77c \uc218\uce58\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc758 \uc2dc\uac00\ub294 24,602.48\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\uc640 \ube44\uad50\ud558\uba74 \uc2dc\uac00 \uae30\uc900\uc73c\ub85c\ub294 1.18% \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uace0, \uc774\ud6c4 \uc0c1\uc2b9 \ud3ed\uc774 1.72%\uae4c\uc9c0 \ud655\ub300\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\uc758 \uc2dc\uac00\ub294 7,377.65\ub85c \uc804\uc77c \ub300\ube44 0.33% \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\uc758 \uc2dc\uac00\ub294 51,078.85\ub85c \uc804\uc77c \ub300\ube44 0.86% \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uac12\uc740 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uacfc [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569 \uac00\uaca9](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uacfc \uad50\ucc28 \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 24,743.12\ub85c \uc804\uc77c \ub300\ube44 428.12\ud3ec\uc778\ud2b8, 1.76% \uc0c1\uc2b9\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,426.17\ub85c 0.99% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uac12\uacfc \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uac12\uc758 \ucc28\uc774\ub294 \uc870\ud68c \uc2dc\uc810 \ucc28\uc774 \ubc94\uc704 \uc548\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8\uc640 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uac12\uc73c\ub85c \uad50\ucc28 \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\ud45c\uba74\uc801\uc73c\ub85c\ub294 \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \ub300\ube44 1.72% \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uccab \ubc88\uc9f8 \ucd09\ub9e4\ub294 10\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \ub178\ub3d9\ubd80\uac00 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 \uc624\uc804 8\uc2dc 30\ubd84\uc5d0 \ubc1c\ud45c\ud55c 10\uc6d4 \ube44\ub18d\uc5c5 \ucde8\uc5c5\uc790 \uc218\ub294 16\ub9cc 5\ucc9c \uba85 \uc99d\uac00\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub85c\uc774\ud130 \uc9d1\uacc4 \uc608\uc0c1\uce58 6\ub9cc 5\ucc9c \uba85\uc744 2\ubc30 \uc774\uc0c1 \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc5c5\ub960\uc740 4.1%\ub85c \uc608\uc0c1\uce58 4.2%\ubcf4\ub2e4 \ub0ae\uc558\uace0, \uc804\uc6d4 4.2%\uc5d0\uc11c\ub3c4 \ub0b4\ub824\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n9\uc6d4 \ucde8\uc5c5\uc790 \uc218 \uc99d\uac00 \ud3ed\uc740 2\ub9cc 9\ucc9c \uba85\uc5d0\uc11c 6\ub9cc \uba85\uc73c\ub85c, 8\uc6d4\uc740 13\ub9cc 3\ucc9c \uba85\uc5d0\uc11c 18\ub9cc 6\ucc9c \uba85\uc73c\ub85c \uac01\uac01 \uc0c1\ud5a5 \uc218\uc815\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac04\ub2f9 \ud3c9\uade0 \uc784\uae08\uc740 \uc804\uc6d4 \ub300\ube44 0.4% \uc62c\ub77c 38.00\ub2ec\ub7ec\ub97c \uae30\ub85d\ud588\uace0, \uc804\ub144 \ub300\ube44\ub85c\ub294 3.1% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\uc774 \uac15\ud558\ub2e4\ub294 \uc2e0\ud638\ub294 \uacbd\uae30 \ud68c\ubcf5\ub825\uc5d0 \ub300\ud55c \ud655\uc778\uc73c\ub85c \uc77d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uac15\ud55c \uace0\uc6a9\uc740 \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc758 \uae08\ub9ac \uc778\uc0c1 \uc5ec\uc9c0\ub97c \ud0a4\uc6b0\ub294 \uc7ac\ub8cc\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4.<br/>\\n\ubc1c\ud45c \uc9c1\ud6c4 \ubbf8\uad6d 10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc740 4.87% \uc218\uc900\uc73c\ub85c \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 CME \ud398\ub4dc\uc6cc\uce58 \uae30\uc900 12\uc6d4 \uc5f0\ubc29\uacf5\uac1c\uc2dc\uc7a5\uc704\uc6d0\ud68c\uc5d0\uc11c\uc758 25bp \uae08\ub9ac \uc778\uc0c1 \ud655\ub960\uc740 72.8%\ub85c \uc9d1\uacc4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uc0c1\uc2b9\uc740 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ubd80\ub2f4\uc774 \ub418\ub294 \uc694\uc778\uc785\ub2c8\ub2e4.<br/>\\n\uadf8\ub7fc\uc5d0\ub3c4 \ub098\uc2a4\ub2e5\uc774 \uc624\ub978 \uac83\uc740, \uc774\ub0a0\uc740 \uace0\uc6a9\uc758 \uacbd\uae30 \ud655\uc778 \ud6a8\uacfc\uac00 \uae08\ub9ac \ubd80\ub2f4\ubcf4\ub2e4 \uba3c\uc800 \ubc18\uc601\ub410\uae30 \ub54c\ubb38\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4.<br/>\\n\ub450 \ubc88\uc9f8 \ucd09\ub9e4\ub294 \ubc18\ub3c4\uccb4\uc8fc\uc758 \ubc18\ub4f1\uc785\ub2c8\ub2e4.<br/>\\n\ub7a8 \ub9ac\uc11c\uce58\ub294 \uc804\uc77c \uc7a5 \ub9c8\uac10 \ud6c4 250\uc5b5 \ub2ec\ub7ec \uaddc\ubaa8\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785 \uc2b9\uc778\uacfc \ubd84\uae30 \ubc30\ub2f9\uae08 0.33\ub2ec\ub7ec\ub97c \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804 \uc8fc\uac00\ub294 10% \ub118\uac8c \uc62c\ub790\uace0, \ub9c8\uc774\ud06c\ub860\uacfc AMD, \uc5d4\ube44\ub514\uc544, \ube0c\ub85c\ub4dc\ucef4\ub3c4 \ub3d9\ubc18 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub099\ud3ed\uc758 30~40%\ub97c \ub418\ub3cc\ub9ac\ub294 \uc218\uc900\uc758 \ubc18\ub4f1\uc774\ub77c\ub294 \ubd84\uc11d\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uae09\ub77d\uc774 \uaddc\uc81c \uc6b0\ub824\ub77c\ub294 \uc2ec\ub9ac \uc7ac\ub8cc\uc5d0 \uae30\ub304 \ub9cc\ud07c, \uac1c\ubcc4 \uae30\uc5c5\uc758 \uc8fc\uc8fc \ud658\uc6d0 \uc7ac\ub8cc\uac00 \uc800\uac00 \ub9e4\uc218\uc758 \uacc4\uae30\uac00 \ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uad50\ucc28 \uc790\uc0b0 \ud750\ub984\ub3c4 \uc704\ud5d8 \uc120\ud638 \ud68c\ubcf5 \ucabd\uc744 \uac00\ub9ac\ud0b5\ub2c8\ub2e4.<br/>\\n\uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc740 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 1,362.90\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.55% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uac15\uc138\uac00 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370\uc11c\ub3c4 \uae30\uc220\uc8fc\uac00 \ubc18\ub4f1\ud588\ub2e4\ub294 \uc810\uc740, \uc774\ub0a0 \ub9e4\uc218\uc138\uac00 \ud658\uc728\ubcf4\ub2e4\ub294 \ubc18\ub3c4\uccb4 \uc7ac\ub8cc\uc640 \uace0\uc6a9 \uc9c0\ud45c\uc5d0 \ubc18\uc751\ud588\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uad6d\uc81c\uc720\uac00\uc758 \ub2f9\uc77c \uc218\uce58\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc73c\ubbc0\ub85c, \uc720\uac00 \uacbd\ub85c\uc5d0 \ub300\ud55c \ud310\ub2e8\uc740 \ud655\uc778 \ud544\uc694\ub85c \ub0a8\uaca8\ub461\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uac04 \ubc29\ud5a5 \ucc28\uc774\ub3c4 \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 1.72% \uc624\ub978 \ubc18\uba74 \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 0.17% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ubc18\ub4f1\uc774 \uc2dc\uc7a5 \uc804\ubc18\uc774 \uc544\ub2c8\ub77c \uc804\uc77c \uac00\uc7a5 \ub9ce\uc774 \ube60\uc9c4 \uae30\uc220\uc8fc\uc640 \ubc18\ub3c4\uccb4\uc5d0 \uc9d1\uc911\ub418\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub2e4\uc6b0\uac00 \uc138 \uc9c0\uc218 \uac00\uc6b4\ub370 \ub099\ud3ed\uc774 \uac00\uc7a5 \uc791\uc558\ub358 \uac83\uacfc \ub300\ube44\ub418\ub294, \uae30\uc220\uc8fc \uc911\uc2ec\uc758 \ub418\ub3cc\ub9bc\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ud558\ub8e8\uc758 \ubc18\ub4f1\ub9cc\uc73c\ub85c \ucd94\uc138 \uc804\ud658\uc744 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9 \uc9c0\ud45c\uc758 \ud638\uc7ac\uc640 \uaddc\uc81c \uc6b0\ub824\uc758 \uc545\uc7ac\uac00 \ub3d9\uc2dc\uc5d0 \uc791\uc6a9\ud558\ub294 \uad6c\uac04\uc5d0\uc11c\ub294, \ubc18\ub4f1\uc758 \uc9c0\uc18d \uc5ec\ubd80\ub97c \uc7a5\uc911 \ud750\ub984\uc73c\ub85c \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### \uccab\uc9f8, 10\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c \uc11c\ud504\ub77c\uc774\uc988\uc785\ub2c8\ub2e4\\n\\n\ubbf8\uad6d 10\uc6d4 \ube44\ub18d\uc5c5 \ucde8\uc5c5\uc790 \uc218\ub294 16\ub9cc 5\ucc9c \uba85 \uc99d\uac00\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc608\uc0c1\uce58\ub97c 10\ub9cc \uba85 \ub118\uac8c \uc6c3\ub3cc\uc558\uace0, \uc9c0\ub09c 12\uac1c\uc6d4 \uc6d4\ud3c9\uade0 \uc99d\uac00 \ud3ed 4\ub9cc 8\ucc9c \uba85\uc758 3\ubc30\ub97c \ub118\uacbc\uc2b5\ub2c8\ub2e4.<br/>\\n\uc99d\uac00\ub294 \uc804\ubb38\xb7\uc0ac\uc5c5 \uc11c\ube44\uc2a4 7\ub9cc \uba85, \uc758\ub8cc 4\ub9cc 2\ucc9c \uba85, \uc6b4\uc1a1\xb7\ucc3d\uace0 2\ub9cc 5\ucc9c \uba85, \uc81c\uc870\uc5c5 1\ub9cc 9\ucc9c \uba85\uc73c\ub85c \uc5c5\uc885 \uc804\ubc18\uc5d0 \ud37c\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc5c5\ub960\uc740 4.1%\ub85c \ub0ae\uc544\uc84c\uace0, \uacbd\uc81c\ud65c\ub3d9\ucc38\uac00\uc728\uc740 61.9%\ub85c 3\uc6d4 \uc774\ud6c4 \uac00\uc7a5 \ub192\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uace0\uc6a9\uc774 \uacbd\uae30 \ub454\ud654 \uc6b0\ub824\ub97c \ub418\ub3cc\ub9ac\ub294 \uac00\uc7a5 \uc9c1\uc811\uc801\uc778 \uc99d\uac70\uc774\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc911\uac04\uc120\uac70 \uc774\ud6c4 \ubd88\ud655\uc2e4\uc131\uc774 \ucee4\uc9c4 \uc0c1\ud669\uc5d0\uc11c, \uace0\uc6a9 \uc9c0\ud45c\ub294 \uc2e4\ubb3c \uacbd\uae30\uac00 \uc544\uc9c1 \uacac\uc870\ud558\ub2e4\ub294 \uc2e0\ud638\ub97c \uc92c\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uac15\ud55c \uace0\uc6a9\uc740 \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc758 \uae08\ub9ac \uc778\uc0c1 \uac00\ub2a5\uc131\uc744 \ub192\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc774 \uc624\ub978 \uac83\uc774 \uadf8 \ubc18\uc601\uc785\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9 \ud638\uc7ac\uac00 \uae08\ub9ac \ubd80\ub2f4\uc744 \uc774\uae30\ub294\uc9c0, \uc544\ub2c8\uba74 \uc7a5 \ud6c4\ubc18\uc5d0 \uae08\ub9ac \ubd80\ub2f4\uc774 \ub418\ub3cc\ub9bc\uc744 \ubd80\ub974\ub294\uc9c0\uac00 \uc624\ub298 \uc7a5\uc758 \uad00\uc804 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ub458\uc9f8, \ub7a8 \ub9ac\uc11c\uce58\uc758 250\uc5b5 \ub2ec\ub7ec \uc790\uc0ac\uc8fc \ub9e4\uc785\uacfc \ubc18\ub3c4\uccb4 \ubc18\ub4f1\uc785\ub2c8\ub2e4\\n\\n\ub7a8 \ub9ac\uc11c\uce58\ub294 \uc774\uc0ac\ud68c\uac00 250\uc5b5 \ub2ec\ub7ec \uaddc\ubaa8\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785\uc744 \uc2b9\uc778\ud588\ub2e4\uace0 \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubd84\uae30 \ubc30\ub2f9\uae08 0.33\ub2ec\ub7ec\ub3c4 \ud568\uaed8 \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc1c\ud45c\ub294 \uc804\uc77c \uc7a5 \ub9c8\uac10 \ud6c4\uc778 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 \uc624\ud6c4 4\uc2dc 5\ubd84\uc5d0 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804 \uc8fc\uac00\ub294 10% \ub118\uac8c \uc62c\ub790\uace0, \uc7a5 \uc624\ud508 \ubb34\ub835\uc5d0\ub294 \uc804\uc77c \uc885\uac00 \ub300\ube44 10.86% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9c8\uc774\ud06c\ub860\uc740 \uac1c\uc7a5 \uc804 8% \uc548\ud30e, AMD\ub294 7% \uc548\ud30e, \uc5d4\ube44\ub514\uc544\ub294 3~4% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uc804\uc77c \ubc18\ub3c4\uccb4 \ud3ed\ub77d\uc758 \uc131\uaca9\uacfc \ub9de\ub2ff\uc544 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 12.25% \ud3ed\ub77d\ud588\uace0, \ub098\uc2a4\ub2e5 100 \uc9c0\uc218\ub294 2020\ub144 3\uc6d4 \uc774\ud6c4 \ucd5c\uc545\uc758 \ud558\ub8e8\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud3ed\ub77d\uc758 \uc6d0\uc778\uc774 \uc2e4\uc801\uc774 \uc544\ub2c8\ub77c \uaddc\uc81c \uc6b0\ub824\ub77c\ub294 \uc2ec\ub9ac \uc7ac\ub8cc\uc600\ub358 \ub9cc\ud07c, \uc790\uc0ac\uc8fc \ub9e4\uc785 \uac19\uc740 \uad6c\uccb4\uc801\uc778 \uc7ac\ub8cc\uac00 \uc800\uac00 \ub9e4\uc218\ub97c \ubd80\ub974\ub294 \uacc4\uae30\uac00 \ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc790\uc0ac\uc8fc \ub9e4\uc785 \uc2b9\uc778\uc740 \ub9e4\uc785 \uc758\ubb34\uac00 \uc544\ub2c8\ub77c \uc0c1\ud55c\uc120\uc774\ub77c\ub294 \uc810\uc5d0 \uc720\uc758\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc81c \ub9e4\uc785 \uaddc\ubaa8\ub294 \ud5a5\ud6c4 \uacf5\uc2dc\ub85c \ud655\uc778\ud560 \uc0ac\uc548\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uc14b\uc9f8, \uc804\uc77c \ud3ed\ub77d\uc758 \ucda9\uaca9\uacfc \uc544\uc2dc\uc544 \uc99d\uc2dc\ub85c\uc758 \uc804\uc774\uc785\ub2c8\ub2e4\\n\\n\uc804\uc77c \ub098\uc2a4\ub2e5\uc740 5.52% \uae09\ub77d\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 4.36%, \ub2e4\uc6b0\ub294 3.44% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138 \uc9c0\uc218\ub294 \ub098\ub780\ud788 2025\ub144 4\uc6d4 \uc774\ud6c4 \ucd5c\uc545\uc758 \ud558\ub8e8\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \ud558\ub8e8 \ub3d9\uc548 \uae30\uc220\uc8fc \uc2dc\uac00\ucd1d\uc561 2\uc870 3\ucc9c\uc5b5 \ub2ec\ub7ec\uac00 \uc99d\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0\uc778\uc740 \ubbfc\uc8fc\ub2f9\uc758 \uc911\uac04\uc120\uac70 \uc555\uc2b9 \uc774\ud6c4 \ubd88\uac70\uc9c4 \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ucda9\uaca9\uc740 \uc544\uc2dc\uc544 \uc99d\uc2dc\ub85c \ubc88\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 6\uc77c \ucf54\uc2a4\ud53c\ub294 \uac1c\uc7a5 \uc9c1\ud6c4 8.55% \uae09\ub77d\ud558\uba70 \uc11c\ud0b7\ube0c\ub808\uc774\ucee4\uac00 \ubc1c\ub3d9\ud588\uace0, \ucf54\uc2a4\ub2e5\uc5d0\ub3c4 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc774\ub0a0 6%\ub300 \uae09\ub77d\uc5d0\ub3c4 5,000\uc120\uc744 \uac00\uae4c\uc2a4\ub85c \uc9c0\ucf30\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uc624\ub298\uc758 \ubc18\ub4f1\uc774 \uae30\uc220\uc801 \ub418\ub3cc\ub9bc\uc778\uc9c0, \ucd94\uc138 \uc804\ud658\uc778\uc9c0 \uac00\ub974\ub294 \uae30\uc900\uc774 \ub418\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uc6b0\ub824\uac00 \uc2e4\uc81c \ubc95\uc548\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \uc5ec\ubd80\ub294 \uc544\uc9c1 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6b0\ub824\uac00 \uc2ec\ub9ac\uc5d0 \uadf8\uce58\uba74 \ubc18\ub4f1\uc774 \uc774\uc5b4\uc9c8 \uc5ec\uc9c0\uac00 \uc788\uace0, \uc815\ucc45\uc73c\ub85c \uad73\uc5b4\uc9c0\uba74 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \ub17c\uc7c1\uc740 \uc911\uae30 \uc7ac\ub8cc\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\uace0\uc6a9\uc5d0\uc11c \uae08\ub9ac\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\uac00 \uba3c\uc800 \uc791\ub3d9\ud569\ub2c8\ub2e4.<br/>\\n\uac15\ud55c \uace0\uc6a9\uc740 \uacbd\uae30 \ud68c\ubcf5\ub825\uc744 \ud655\uc778\uc2dc\ucf1c\uc8fc\uc9c0\ub9cc, \ub3d9\uc2dc\uc5d0 \uae08\ub9ac \uc778\uc0c1 \uac00\ub2a5\uc131\uc744 \ub192\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc774 4.87% \uc218\uc900\uc73c\ub85c \uc624\ub978 \uac83\uc774 \uadf8 \ubc18\uc601\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uc0c1\uc2b9\uc740 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ubd80\ub2f4\uc774\uc9c0\ub9cc, \uc774\ub0a0\uc740 \uace0\uc6a9\uc758 \uacbd\uae30 \ud655\uc778 \ud6a8\uacfc\uac00 \uba3c\uc800 \ubc18\uc601\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ud6c4\ubc18\uc5d0 \uae08\ub9ac \ubd80\ub2f4\uc774 \uc6b0\uc704\ub97c \uc810\ud558\ub294\uc9c0\ub294 \ud655\uc778\ud560 \uc0ac\uc548\uc785\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uc6b0\ub824\uc5d0\uc11c \ubc18\ub3c4\uccb4\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub294 \ub418\ub3cc\ub9bc \uad6d\uba74\uc5d0 \ub4e4\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\ub294 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud655\uc7a5\uc758 \uc18d\ub3c4\ub97c \ub2a6\ucd9c \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \ubc18\ub3c4\uccb4\uc640 \uba54\ubaa8\ub9ac \uc218\uc694 \uc804\ub9dd\uc5d0 \ubd80\ub2f4\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\uac00 12.25% \ud3ed\ub77d\ud55c \uac83\uc774 \uadf8 \ubc18\uc601\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0\uc740 \ub7a8 \ub9ac\uc11c\uce58\uc758 \uc790\uc0ac\uc8fc \ub9e4\uc785 \uc7ac\ub8cc\uc640 \uc800\uac00 \ub9e4\uc218\uac00 \uac19\uc740 \uc5f0\uacb0\uace0\ub9ac\ub97c \ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4\uc5d0\uc11c \ud558\ub4dc\uc6e8\uc5b4\uc640 \uc804\ub825\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub3c4 \ud568\uaed8 \uc6c0\uc9c1\uc785\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uc18d\ub3c4\uc5d0 \ub300\ud55c \uc758\uad6c\uc2ec\uc740 \ub0c9\uac01\uacfc \uc804\ub825\uae30\uae30, \uc11c\ubc84\uc6a9 \ubd80\ud488 \uc218\uc694\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ubc18\ub3c4\uccb4 \ubc18\ub4f1\uc774 \uc774\ub4e4 \uc5f0\uad00 \uc139\ud130\ub85c \ud655\uc0b0\ub418\ub294\uc9c0\uac00 \ud655\uc778\ud560 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804 \ub9e4\uadf8\ub2c8\ud53c\uc13c\ud2b8 7 \uc885\ubaa9\uc758 \uc6c0\uc9c1\uc784\uc740 \uc5c7\uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uac1c\uc7a5 \uc804 \uc5d4\ube44\ub514\uc544\ub294 4% \uc548\ud30e, \ud14c\uc2ac\ub77c\ub294 1.7% \uc62c\ub790\uace0, \uc560\ud50c\uc740 1.2%, \uc544\ub9c8\uc874\uc740 0.8%, \ub9c8\uc774\ud06c\ub85c\uc18c\ud504\ud2b8\ub294 0.7% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c\uc640 \uc9c1\uc811 \uc5f0\uacb0\ub41c \uc885\ubaa9\uc774 \uc624\ub974\uace0, \uadf8 \uc678 \ub300\ud615 \uae30\uc220\uc8fc\ub294 \uc57d\uc138\ub97c \ubcf4\uc778 \uac83\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ubc18\ub4f1\uc774 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c\ub77c\ub294 \uc881\uc740 \ucd95\uc5d0 \uc9d1\uc911\ub418\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec\uc5d0\uc11c \uc790\uae08 \ud750\ub984\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub3c4 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc740 1,362.90\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.55% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uac15\uc138\uac00 \uc774\uc5b4\uc9c0\ub294 \uac00\uc6b4\ub370 \uae30\uc220\uc8fc\uac00 \ubc18\ub4f1\ud588\ub2e4\ub294 \uc810\uc740, \uc774\ub0a0 \ub9e4\uc218\uc138\uac00 \ud658\uc728\ubcf4\ub2e4\ub294 \uac1c\ubcc4 \uc7ac\ub8cc\uc5d0 \ubc18\uc751\ud588\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc218\ud61c\uc640 \ud0c0\uaca9\uc744 \ub2e8\uc21c\ud788 \ub098\ub204\uae30\ubcf4\ub2e4, \uac19\uc740 \uace0\uc6a9 \uc9c0\ud45c\uac00 \uacbd\uae30 \ud655\uc778\uacfc \uae08\ub9ac \ubd80\ub2f4\uc774\ub77c\ub294 \ub450 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud55c\ub2e4\ub294 \uc810\uc774 \uc774\ubc88 \uc7a5\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\uc5d0\ub294 \uacbd\uae30 \ud655\uc778 \ucabd \ud574\uc11d\uc774 \uc6b0\uc704\ub97c \uc810\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \ud750\ub984\\n\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 11\uc6d4 5\uc77c 7,353.73\uc73c\ub85c 4.36% \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 6\uc77c \uc7a5 \uc624\ud508 \ubb34\ub835\uc5d0\ub294 7,420.82\ub85c 0.91% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc0c1\uc2b9\ub960 1.72%\uc758 \uc808\ubc18 \uc218\uc900\uc73c\ub85c, \uc0c1\uc2b9 \ud3ed\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \uc791\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ubc18\ub4f1\uc774 \uae30\uc220\uc8fc\uc5d0 \uc9d1\uc911\ub418\uace0, \uc2dc\uc7a5 \uc804\ubc18\uc73c\ub85c \uace0\ub974\uac8c \ud655\uc0b0\ub418\uc9c0\ub294 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 11\uc6d4 5\uc77c 51,523.06\uc73c\ub85c 3.44% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138 \uc9c0\uc218 \uac00\uc6b4\ub370 \ub099\ud3ed\uc774 \uac00\uc7a5 \uc791\uc558\uace0, \uc804\uc77c\uc5d0\ub294 \uac00\uce58\uc8fc\uc640 \uc0b0\uc5c5\uc8fc\uac00 \uc0c1\ub300\uc801\uc73c\ub85c \uc120\ubc29\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 6\uc77c \uc7a5 \uc624\ud508 \ubb34\ub835 \ub2e4\uc6b0\ub294 51,436.37\ub85c 0.17% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc120\ubb3c\uc740 \uc0c1\uc2b9\ud588\uc9c0\ub9cc \ub2e4\uc6b0 \uc120\ubb3c\uc740 \uac1c\uc7a5 \uc804 478\ud3ec\uc778\ud2b8 \ub0b4\ub838\ub358 \ud750\ub984\uc774 \uc7a5 \ucd08\ubc18\uc5d0\ub3c4 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uac00\uc7a5 \uc801\uac8c \ube60\uc84c\ub358 \ub2e4\uc6b0\uac00 \ub2f9\uc77c\uc5d0\ub294 \uc720\uc77c\ud558\uac8c \ub0b4\ub9ac\uace0 \uc788\ub2e4\ub294 \uc810\uc774 \ub208\uc5d0 \ub755\ub2c8\ub2e4.<br/>\\n\uae30\uc220\uc8fc\uc5d0\uc11c \ube60\uc838\ub098\uc628 \uc790\uae08\uc774 \uac00\uce58\uc8fc\ub85c \uc62e\uaca8\uac14\ub358 \uc804\uc77c\uc758 \uc21c\ud658\ub9e4\uac00 \ub418\ub3cc\ub824\uc9c0\ub294 \ud750\ub984\uc73c\ub85c \uc77d\ud799\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uac00 \uc7a5 \ud6c4\ubc18\uc5d0 \ub098\uc2a4\ub2e5\uc758 \ubc18\ub4f1\uc5d0 \ub3d9\ucc38\ud558\ub294\uc9c0\uac00 \ud655\uc778\ud560 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ud750\ub984 \uc9c0\uc18d\uacfc \uc77c\uc2dc\uc801 \ub178\uc774\uc988\ub97c \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc774 \uc774\uc5b4\uc9c0\ub824\uba74 \ubc18\ub3c4\uccb4\uc758 \ub418\ub3cc\ub9bc\uc774 \uc7a5 \ud6c4\ubc18\uae4c\uc9c0 \uc720\uc9c0\ub3fc\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uae08\ub9ac \ubd80\ub2f4\uc774 \uc6b0\uc704\ub97c \uc810\ud558\uba74, \uc7a5 \ucd08\ubc18 \uc0c1\uc2b9 \ud3ed\uc774 \ub418\ub3cc\ub824\uc9c8 \uc5ec\uc9c0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\uc5d0 \ud655\uc778\ud560 \uc218\uce58\ub294 \uc804\uc77c \uc885\uac00\uc640 \uc7a5\uc911 \uc800\uac00\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 \uc804\uc77c \uc885\uac00 24,315.00\uc744 \uc774\ubbf8 \uc6c3\ub3cc\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc800\uac00 24,561.11\uc744 \uc9c0\ucf1c\ub0b4\ub294\uc9c0, \uc544\ub2c8\uba74 \uc2dc\uac00 24,602.48 \uc544\ub798\ub85c \ubc00\ub9ac\ub294\uc9c0\uac00 \ub2e8\uae30 \ubc29\ud5a5\uc744 \uac00\ub985\ub2c8\ub2e4.<br/>\\n\uc800\ud56d\uc120\uc73c\ub85c\ub294 \uc804\uc77c \uc7a5\uc911 \uace0\uac00 25,559.03\uacfc \uc804\uc804\uc77c \uc885\uac00 25,736.51\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub418\ub3cc\ub9bc\uc774 \uc774\uc5b4\uc9c4\ub2e4\uba74 25,000\uc120 \ud68c\ubcf5 \uc5ec\ubd80\uac00 \uccab \ubc88\uc9f8 \ud655\uc778 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc139\ud130 \ub2e8\uc704\uc5d0\uc11c\ub294 \ubc18\ub3c4\uccb4\uc9c0\uc218\uc758 \uc6c0\uc9c1\uc784\uc774 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c 12.25% \ud3ed\ub77d\ud55c \ubc18\ub3c4\uccb4\uac00 \ub2f9\uc77c \uc0c1\uc2b9 \ud3ed\uc744 \uc720\uc9c0\ud558\ub294\uc9c0, \uc544\ub2c8\uba74 \ub418\ub3cc\ub9bc\uc5d0 \uadf8\uce58\ub294\uc9c0\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 \uc624\uc804 10\uc2dc\uc5d0 \ubc1c\ud45c\ub418\ub294 11\uc6d4 \ubbf8\uc2dc\uac04\ub300 \uc18c\ube44\uc790\uc2ec\ub9ac\uc9c0\uc218 \uc608\ube44\uce58\ub3c4 \ud655\uc778\ud560 \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00 \uc791\uc131 \uc2dc\uc810\uc5d0\ub294 \ud574\ub2f9 \uc218\uce58\uac00 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec\uc640 \uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc758 \uc6c0\uc9c1\uc784\ub3c4 \ud568\uaed8 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uac15\uc138\uac00 \uc774\uc5b4\uc9c0\uba74 \uc678\uad6d\uc778 \uc790\uae08 \uc774\ud0c8 \uc555\ub825\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 \ubbfc\uc8fc\ub2f9\uc758 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uad00\ub828 \uc785\ubc95 \uc6c0\uc9c1\uc784\uacfc \ube45\ud14c\ud06c\uc758 \uc790\ubcf8\uc9c0\ucd9c \uacc4\ud68d\uc744 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n12\uc6d4 9\uc77c \uc5f0\ubc29\uacf5\uac1c\uc2dc\uc7a5\uc704\uc6d0\ud68c\ub97c \uc55e\ub450\uace0 12\uc6d4 4\uc77c \ubc1c\ud45c\ub418\ub294 11\uc6d4 \uace0\uc6a9\ubcf4\uace0\uc11c\ub3c4 \ud655\uc778\ud560 \uc77c\uc815\uc785\ub2c8\ub2e4.<br/>\\n\uc2e4\uc81c \ubc95\uc548\uc774\ub098 \uac00\uc774\ub358\uc2a4 \ubcc0\uacbd\uc774 \ud655\uc778\ub418\uae30 \uc804\uc5d0\ub294, \uaddc\uc81c \uc6b0\ub824\ub97c \ud655\uc815\uc801\uc778 \uc815\ucc45 \ubcc0\ud654\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n11\uc6d4 6\uc77c \ub098\uc2a4\ub2e5\uc740 \uace0\uc6a9 \uc11c\ud504\ub77c\uc774\uc988\uc640 \ubc18\ub3c4\uccb4 \ubc18\ub4f1\uc5d0 \ud798\uc785\uc5b4 1.72% \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\uc5d0\ub294 \ubc18\ub3c4\uccb4\uc758 \uc0c1\uc2b9 \uc9c0\uc18d \uc5ec\ubd80\uc640 \uae08\ub9ac \ubd80\ub2f4\uc758 \ub418\ub3cc\ub9bc \uc5ec\ubd80\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-05-domestic-market-close","metadata":{"permalink":"/blog/en/market/2026-11-05-domestic-market-close","source":"@site/market/2026-11-05-domestic-market-close/index.mdx","title":"2026\ub144 11\uc6d4 5\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 - \ube14\ub8e8\uc6e8\uc774\ube0c \ucda9\uaca9\uc5d0 \uc591 \uc2dc\uc7a5 5%\ub300 \uae09\ub77d","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-05T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":8.77,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-05-domestic-market-close","title":"2026\ub144 11\uc6d4 5\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 - \ube14\ub8e8\uc6e8\uc774\ube0c \ucda9\uaca9\uc5d0 \uc591 \uc2dc\uc7a5 5%\ub300 \uae09\ub77d","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \uace0\uc6a9 \uc11c\ud504\ub77c\uc774\uc988\uc640 \ubc18\ub3c4\uccb4 \ubc18\ub4f1\uc5d0 1.72% \uc0c1\uc2b9 \ucd9c\ubc1c","permalink":"/blog/en/market/2026-11-06-nasdaq-market-open"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ube14\ub8e8 \uc6e8\uc774\ube0c\ubc1c \ubc18\ub3c4\uccb4 \uc1fc\ud06c\uc5d0 \ucf54\uc2a4\ud53c \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud55c 11\uc6d4 5\uc77c \uc624\uc804\uc7a5","permalink":"/blog/en/market/2026-11-05-domestic-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 5\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc774 \ubaa8\ub450 5% \ub118\uac8c \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 5.28% \ub0b4\ub9b0 5,383.80\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \ub300\ube44 5.11% \ub0b4\ub9b0 678.41\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc7a5\uc911 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 5,400\uc120\uc744 \ub0b4\uc92c\uace0, \ucf54\uc2a4\ub2e5\uc740 700\uc120\uc744 \ub0b4\uc92c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc7a5\uc911 \uae09\ub77d \ub4a4 \uc0c1\uc2b9 \ub9c8\uac10\ud588\ub358 \ud750\ub984\uc740 \ud558\ub8e8 \ub9cc\uc5d0 \ub2e4\uc2dc \uae09\ub77d\uc73c\ub85c \ub3cc\uc544\uc130\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 10\uc6d4 29\uc77c \uc885\uac00 5,937.66 \ub300\ube44 9.33% \ub0b4\ub824\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 \uac19\uc740 \uae30\uac04 753.23\uc5d0\uc11c 678.41\ub85c 9.93% \ub0b4\ub824\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc77c\uc8fc\uc77c \uc0ac\uc774 \uc9c0\uc218 \ub808\ubca8 \uc790\uccb4\uac00 \ud55c \ub2e8\uacc4 \ub0ae\uc544\uc9c4 \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,383.80 | -300.00 | -5.28% | 5,580.09 | 5,586.46 | 5,336.88 | 256,819\ucc9c\uc8fc | 22\uc870 6,176\uc5b5\uc6d0 |\\n| \ucf54\uc2a4\ub2e5 | 678.41 | -36.54 | -5.11% | 713.49 | 717.06 | 673.38 | 408,677\ucc9c\uc8fc | 4\uc870 9,124\uc5b5\uc6d0 |\\n\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,683.80, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 714.95\uc785\ub2c8\ub2e4.<br/>\\n\uad50\ucc28 \uac80\uc99d\uc740 \ud604\uc7ac\uac00\ub97c \ub4f1\ub77d\ub960\ub85c \ub098\ub208 \uc5ed\uc0b0\uac12\uc73c\ub85c \uc218\ud589\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7\uc740 2026\ub144 11\uc6d4 5\uc77c 16\uc2dc \uc7a5 \ub9c8\uac10 \uae30\uc900\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc624\ub298 \uae09\ub77d\uc758 \uc9c1\uc811 \ucd09\ub9e4\ub294 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uacb0\uacfc\uc758 \ud574\uc11d\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud558\ub294 \ube14\ub8e8\uc6e8\uc774\ube0c\uac00 \ud655\uc815\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc99d\uc2dc\ub294 \uac19\uc740 \uacb0\uacfc\ub97c \ubd88\ud655\uc2e4\uc131 \uc644\ud654\ub85c \ubc1b\uc544\ub4e4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 4\uc77c \ubbf8\uad6d \ub2e4\uc6b0\uc874\uc2a4 \uc9c0\uc218\ub294 3.03%, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 1.58%, \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 1.44% \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \ud55c\uad6d \uc2dc\uc7a5\uc740 \uac19\uc740 \uacb0\uacfc\ub97c \uc804\ud600 \ub2e4\ub974\uac8c \ud574\uc11d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9\uc758 \uc758\ud68c \uc7a5\uc545 \uc774\ud6c4 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uaddc\uc81c \uac15\ud654 \uac00\ub2a5\uc131\uc774 \ubd80\uac01\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\uacbd\uc774\ucf54\ub178\ubbf8 \ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uc774 \uc6b0\ub824\uac00 \ubc18\ub3c4\uccb4\uc8fc \uc57d\uc138\ub85c \uc9c1\uacb0\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc120\uac70 \uacb0\uacfc\uac00 \ubbf8\uad6d\uc5d0\uc11c\ub294 \uc0c1\uc2b9 \uc7ac\ub8cc, \ud55c\uad6d\uc5d0\uc11c\ub294 \ud558\ub77d \uc7ac\ub8cc\ub85c \uc791\uc6a9\ud55c \uc148\uc785\ub2c8\ub2e4.<br/>\\n\ucc28\uc774\ub294 \uc9c0\uc218 \uad6c\uc131\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c \ubc18\ub3c4\uccb4 \ubc38\ub958\uccb4\uc778\uc774 \ucc28\uc9c0\ud558\ub294 \ube44\uc911\uc774 \ud06c\uae30 \ub54c\ubb38\uc5d0, \ubc18\ub3c4\uccb4 \uc57d\uc138\ub294 \uace7 \uc9c0\uc218 \uc57d\uc138\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c200 \uc9c0\uc218\ub294 5.79% \ub0b4\ub838\uace0, \ucf54\uc2a4\ud53c \uc120\ubb3c\uc740 5.91% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ud604\ubb3c\ubcf4\ub2e4 \uc120\ubb3c \ub099\ud3ed\uc774 \ucef8\ub2e4\ub294 \uc810\uc740 \ub2e8\uae30 \ub9e4\ub3c4 \uc2ec\ub9ac\uac00 \uac15\ud588\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc218\uae09 \uad6c\ub3c4\ub3c4 \uac19\uc740 \ubc29\ud5a5\uc744 \uac00\ub9ac\ud0b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c \uc678\uad6d\uc778\uc740 3\uc870 3,934\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \ub9e4\ub3c4\ub294 11\uc6d4 \ub4e4\uc5b4 \uacc4\uc18d \ucee4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 2\uc77c 3,845\uc5b5\uc6d0, 11\uc6d4 3\uc77c 1\uc870 5,086\uc5b5\uc6d0, 11\uc6d4 4\uc77c 2\uc870 4,528\uc5b5\uc6d0\uc5d0 \uc774\uc5b4 \uc624\ub298 3\uc870 3,934\uc5b5\uc6d0\uc73c\ub85c \ub298\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\ud758 \uc5f0\uc18d \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \ucee4\uc9c0\ub294 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\uac1c\uc778\uacfc \uae30\uad00\uc774 \ub9e4\uc218\uc5d0 \ub098\uc130\uc9c0\ub9cc \ubb3c\ub7c9\uc744 \uc18c\ud654\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c \uac1c\uc778\uc740 2\uc870 2,768\uc5b5\uc6d0, \uae30\uad00\uc740 8,417\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc774 \ud310 \ubb3c\ub7c9\uc758 \ub300\ubd80\ubd84\uc744 \uad6d\ub0b4 \ud22c\uc790\uc790\uac00 \ubc1b\uc558\uc9c0\ub9cc, \uc9c0\uc218\ub294 5% \ub118\uac8c \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc1b\ub294 \ucabd\uc758 \ub9e4\uc218\uc138\uac00 \uc57d\ud588\ub2e4\uae30\ubcf4\ub2e4, \ud30c\ub294 \ucabd\uc758 \ubb3c\ub7c9\uacfc \uc18d\ub3c4\uac00 \uc555\ub3c4\ud588\ub2e4\ub294 \ud574\uc11d\uc774 \ub9de\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 1,341.00\uc6d0\uc73c\ub85c \ubcf4\ud569 \uc218\uc900\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud658\uc728 \uae09\ub4f1\uc774 \uc7a5\uc138\ub97c \uc9c1\uc811 \ucd09\ub9e4\ud588\ub2e4\uace0 \ubcfc \uadfc\uac70\ub294 \uc774\ub0a0 \uc218\uce58\uc5d0\uc11c\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00\ub3c4 \uc7a5\uc138\uc758 \ud55c \ucd95\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0 \uc6d0\uc720 \uc120\ubb3c\uc740 \uc804\uc77c \ub300\ube44 8.29% \uae09\ub77d\ud574 \ubc30\ub7f4\ub2f9 88.12\ub2ec\ub7ec\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub780 \uc885\uc804 \uae30\ub300\uac00 \uc720\uac00\ub97c \ub04c\uc5b4\ub0b4\ub838\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \uae09\ub77d\uc740 \ud56d\uacf5\ucc98\ub7fc \uc5f0\ub8cc\ube44 \ubd80\ub2f4\uc774 \ud070 \ucabd\uc5d0\ub294 \uc6b0\ud638\uc801\uc774\uc9c0\ub9cc, \uc5d0\ub108\uc9c0\uc640 \ud654\ud559 \ubc38\ub958\uccb4\uc778\uc5d0\ub294 \uc218\uc694 \ub454\ud654 \uc2e0\ud638\ub85c \uc77d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\uacb0\uad6d \uc624\ub298 \uc7a5\uc138\ub294 \ub2e8\uc77c \uc545\uc7ac\uac00 \uc544\ub2c8\ub77c, \uc120\uac70 \uacb0\uacfc \ud574\uc11d\uacfc \ubc18\ub3c4\uccb4 \uaddc\uc81c \uc6b0\ub824, \uc678\uad6d\uc778 \ub9e4\ub3c4 \uac00\uc18d\uc774 \uacb9\uce5c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### 1. \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ube14\ub8e8\uc6e8\uc774\ube0c \ud655\uc815\uacfc \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\\n\\n\ubbfc\uc8fc\ub2f9\uc774 \ubbf8\uad6d \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc99d\uc2dc\ub294 \uc774\ub97c \uc815\uce58\uc801 \ubd88\ud655\uc2e4\uc131 \uc644\ud654\ub85c \ubc1b\uc544\ub4e4\uc5ec 11\uc6d4 4\uc77c 3\ub300 \uc9c0\uc218\uac00 \uc77c\uc81c\ud788 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uaddc\uc81c \uac15\ud654 \uac00\ub2a5\uc131\uc774 \ud568\uaed8 \ubd80\uac01\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\uacbd\uc774\ucf54\ub178\ubbf8 \ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uc774 \uc6b0\ub824\uac00 \ubc18\ub3c4\uccb4\uc8fc \uc57d\uc138\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc0bc\uc131\uc804\uc790 7.5%, SK\ud558\uc774\ub2c9\uc2a4 9.3% \ud558\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \uc120\uac70 \uacb0\uacfc\uac00 \ubbf8\uad6d \ubcf8\ud1a0\uc5d0\uc11c\ub294 \uc0c1\uc2b9 \uc7ac\ub8cc, \ud55c\uad6d\uc5d0\uc11c\ub294 \ud558\ub77d \uc7ac\ub8cc\uac00 \ub41c \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc815\ucc45 \ubcc0\ud654\uc758 \ubc29\ud5a5\uc774 \uc544\uc9c1 \ud655\uc815\ub418\uc9c0 \uc54a\uc740 \ub9cc\ud07c, \uaddc\uc81c \uad00\ub828 \ud6c4\uc18d \ubc1c\uc5b8\uc774 \ub098\uc62c \ub54c\ub9c8\ub2e4 \ubc18\ub3c4\uccb4 \ubc38\ub958\uccb4\uc778 \uc2ec\ub9ac\uac00 \ud754\ub4e4\ub9b4 \uc218 \uc788\ub294 \uad6d\uba74\uc785\ub2c8\ub2e4.<br/>\\n\\n### 2. \uc591 \uc2dc\uc7a5 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74 \ubc1c\ub3d9\\n\\n\uc624\ud6c4 \ub4e4\uc5b4 \ucf54\uc2a4\ud53c\uc5d0 \uc774\uc5b4 \ucf54\uc2a4\ub2e5\uc5d0\ub3c4 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 14\uc2dc 37\ubd84 \uae30\uc900 \uc804\uc77c \ub300\ube44 5.39% \ub0b4\ub9b0 5,377.56\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 \uac19\uc740 \uc624\ud6c4 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\ub294 \uc120\ubb3c \uac00\uaca9\uc774 \uae09\ub77d\ud560 \ub54c \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub3c4 \ud638\uac00\uc758 \ud6a8\ub825\uc744 \uc77c\uc2dc \uc815\uc9c0\ud558\ub294 \uc81c\ub3c4\uc785\ub2c8\ub2e4.<br/>\\n\ubc1c\ub3d9 \uc790\uccb4\uac00 \ucd94\uc138\ub97c \ubc14\uafb8\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \uc2dc\uc7a5\uc758 \ub9e4\ub3c4 \uc555\ub825\uc774 \uc81c\ub3c4 \uac1c\uc785 \uc218\uc900\uc5d0 \ub3c4\ub2ec\ud588\uc74c\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc2e0\ud638\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c200 \uc9c0\uc218\uac00 5.79% \ub0b4\ub838\ub2e4\ub294 \uc810\uc740, \ub300\ud615\uc8fc \uc911\uc2ec\uc758 \ub9e4\ub3c4\uac00 \uc9c0\uc218 \uc804\ubc18\uc744 \ub04c\uc5b4\ub0b4\ub838\uc74c\uc744 \ud655\uc778\ud574 \uc90d\ub2c8\ub2e4.<br/>\\n\\n### 3. 2\ucc28\uc804\uc9c0 \uc2e4\uc801 \uc1fc\ud06c\\n\\n\uc5d0\ucf54\ud504\ub85c\uc758 3\ubd84\uae30 \uc601\uc5c5\uc774\uc775\uc774 \uc804\ub144 \ub300\ube44 90% \uc774\uc0c1 \uac10\uc18c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub525\uc11c\uce58 \ud2b8\ub80c\ub529 \ud1a0\ud53d\uc5d0\uc11c\ub3c4 \ub2f9\uc77c \uacbd\uc81c \ubd84\uc57c 3\uc704 \uc774\uc288\ub85c \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\nLG\ud654\ud559\ub3c4 3\ubd84\uae30 \uc601\uc5c5\uc774\uc775 5,612\uc5b5\uc6d0\uc744 \uae30\ub85d\ud574 \uc804\ub144 \ub300\ube44 17% \uac10\uc18c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n2\ucc28\uc804\uc9c0\uc640 \ud654\ud559 \ubc38\ub958\uccb4\uc778\uc5d0 \uc2e4\uc801 \ubd80\ub2f4\uc774 \uacb9\uce5c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \uc57d\uc138\uc640 \ubcc4\uac1c\ub85c, \uc2e4\uc801\uc774 \ud655\uc778\ub41c \ucabd\uc5d0\uc11c\ub3c4 \ub9e4\ub3c4 \uba85\ubd84\uc774 \uc313\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801 \uc2dc\uc98c\uc5d0 \ud655\uc778\ub41c \uc218\uce58\uac00 \uae30\ub300\uc5d0 \ubabb \ubbf8\uce58\uba74, \uc9c0\uc218 \ud558\ub77d \uad6d\uba74\uc5d0\uc11c\ub294 \ub099\ud3ed\uc774 \ub354 \ucee4\uc9c0\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc139\ud130\xb7\ud14c\ub9c8 \uc601\ud5a5 \uccb4\uc778\\n\\n\ubc18\ub3c4\uccb4 \ubc38\ub958\uccb4\uc778\uc774 \uc9c1\uc811 \ud0c0\uaca9\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\ub294 \uba54\ubaa8\ub9ac \uc218\uc694 \uc804\ub9dd\uacfc \uc9c1\uacb0\ub429\ub2c8\ub2e4.<br/>\\n\uc218\uc694 \uc804\ub9dd\uc774 \ud754\ub4e4\ub9ac\uba74 \uba54\ubaa8\ub9ac\uc640 \uc7a5\ube44, \uc18c\ubd80\uc7a5\uae4c\uc9c0 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \uc6c0\uc9c1\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc5f0\uacb0\uace0\ub9ac\uac00 \ucf54\uc2a4\ud53c \ub099\ud3ed\uc744 5%\ub300\ub85c \ud0a4\uc6b4 \ud575\uc2ec \uacbd\ub85c\uc785\ub2c8\ub2e4.<br/>\\n2\ucc28\uc804\uc9c0 \ubc38\ub958\uccb4\uc778\ub3c4 \uc57d\uc138 \uc555\ub825\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5d0\ucf54\ud504\ub85c \uc2e4\uc801 \uc1fc\ud06c\uac00 \ud655\uc778\ub41c \ub370\ub2e4, \uc720\uac00 \uae09\ub77d\uc774 \uc218\uc694 \ub454\ud654 \uc2e0\ud638\ub85c \uc77d\ud788\uba74\uc11c \ud22c\uc790 \uc2ec\ub9ac\uac00 \uc704\ucd95\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uac15\ud588\ub358 \ucabd\uc740 \ubd84\uba85\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud56d\uacf5 \ud14c\ub9c8\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 4.60% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \uae09\ub77d\uc774 \uc5f0\ub8cc\ube44 \ubd80\ub2f4 \uc644\ud654 \uae30\ub300\ub85c \uc5f0\uacb0\ub41c \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\uc790\ub3d9\ucc28 \uad00\ub828\uc8fc\ub3c4 \uac15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS AI \uc694\uc57d\uc5d0 \ub530\ub974\uba74 \uae30\uc544 4.49%, \ud604\ub300\ucc28 3.00%, \ud604\ub300\ubaa8\ube44\uc2a4 2.25% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uae30\ucc28 \uc0dd\uc0b0 \uc138\uc561\uacf5\uc81c \ub3c4\uc785 \uac80\ud1a0\uac00 \uc7ac\ub8cc\ub85c \uc9c0\ubaa9\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc14\uc774\uc624\ub3c4 \uc120\ubcc4 \uac15\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc140\ud2b8\ub9ac\uc628\uc740 6.50% \uc62c\ub790\uace0, \ud504\ub85c\ud2f0\ub098\ub294 24.21% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ud574\uc678 \uc9c4\ucd9c \uc131\uacfc\uc640 \uc790\uae08 \uc870\ub2ec \uc18c\uc2dd\uc774 \ubc30\uacbd\uc73c\ub85c \uaf3d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\ubaa9\uc7ac \ud14c\ub9c8\ub294 5.54% \uc62c\ub790\uace0, \ud0c0\uc774\uc5b4 4.50%, \uc8fc\ub958\ud310\ub9e4 4.07%, \uc704\ud0c1\uc0dd\uc0b0 3.20%, \uc5d4\ud130\ud14c\uc778\uba3c\ud2b8 3.10%, \ud1b5\uc2e0\uc0ac 2.78%\ub3c4 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc774\ub4e4 \ud14c\ub9c8\uc758 \uc0c1\uc2b9\uc740 \uc9c0\uc218 \ud558\ub77d\uc744 \uc0c1\uc1c4\ud560 \uaddc\ubaa8\uac00 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ud558\ub77d \uad6d\uba74\uc5d0\uc11c \uc18c\uc218 \ud14c\ub9c8\ub9cc \uc624\ub974\ub294 \uad6c\uc870\ub294, \uc790\uae08\uc774 \ubc29\uc5b4\ucc98\ub97c \ucc3e\uc544 \uc6c0\uc9c1\uc600\ub2e4\ub294 \ud574\uc11d\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \ub4f1\ub77d\ub960 | \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | -3.48% | 228,294\ucc9c\uc8fc |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | +2.24% | 198,130\ucc9c\uc8fc |\\n| 2026-11-03 | 5,715.19 | 5,735.92 | 5,615.80 | 5,648.79 | -3.59% | 207,371\ucc9c\uc8fc |\\n| 2026-11-04 | 5,786.13 | 5,828.13 | 5,421.72 | 5,683.80 | +0.62% | 276,889\ucc9c\uc8fc |\\n| 2026-11-05 | 5,580.09 | 5,586.46 | 5,336.88 | 5,383.80 | -5.28% | 256,819\ucc9c\uc8fc |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \ub4f1\ub77d\ub960 | \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | -3.83% | 470,174\ucc9c\uc8fc |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | +1.38% | 355,750\ucc9c\uc8fc |\\n| 2026-11-03 | 723.92 | 723.92 | 702.34 | 704.39 | -4.08% | 430,571\ucc9c\uc8fc |\\n| 2026-11-04 | 715.74 | 718.34 | 683.66 | 714.95 | +1.50% | 539,758\ucc9c\uc8fc |\\n| 2026-11-05 | 713.49 | 717.06 | 673.38 | 678.41 | -5.11% | 408,677\ucc9c\uc8fc |\\n\\n\ucd5c\uadfc 5\uac70\ub798\uc77c \ub3d9\uc548 \ucf54\uc2a4\ud53c\ub294 \uc138 \ubc88 \ud558\ub77d\ud558\uace0 \ub450 \ubc88 \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ud558\ub77d\uc77c\uc758 \ub099\ud3ed\uc774 \uc0c1\uc2b9\uc77c\uc758 \uc0c1\uc2b9\ud3ed\ubcf4\ub2e4 \ud6e8\uc52c \ud07d\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uc800\uac00 5,336.88\uc740 \uc804\uc77c \uc7a5\uc911 \uc800\uac00 5,421.72\ub97c \ubc11\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00 \uae30\uc900\uc73c\ub85c \uc624\ub298 \uace0\uac00\ub294 1.71% \ub0ae\uc558\uace0, \uc800\uac00\ub294 6.10% \ub0ae\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\ubd80\ud130 \uc804\uc77c \uc885\uac00\ub97c \ud68c\ubcf5\ud558\uc9c0 \ubabb\ud55c \ucc44 \ubc00\ub9b0 \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2f9\uc77c \uc218\uae09\\n\\n\ucf54\uc2a4\ud53c \uc218\uae09\uc740 \uc678\uad6d\uc778\uc758 \ub300\uaddc\ubaa8 \ub9e4\ub3c4\uac00 \uc911\uc2ec\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc740 3\uc870 3,934\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc911 \uc678\uad6d\uc778(9000)\uc774 3\uc870 4,248\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uace0, \uae30\ud0c0\uc678\uad6d\uc778(9001)\uc740 314\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc778\uc740 2\uc870 2,768\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uace0, \uae30\uad00\uc740 8,417\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00 \ub9e4\uc218\ub294 \uae08\uc735\ud22c\uc790 1\uc870 1,088\uc5b5\uc6d0\uacfc \uc5f0\uae30\uae08 1,607\uc5b5\uc6d0\uc774 \uc774\ub04c\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud22c\uc2e0\uc740 3,131\uc5b5\uc6d0, \uc0ac\ubaa8\ub294 1,545\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud574 \uae30\uad00 \ub0b4\ubd80\uc5d0\uc11c\ub3c4 \ubc29\ud5a5\uc774 \uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\ud0c0\ubc95\uc778\uc740 2,749\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\ub3c4\ub97c \ud55c \ubb38\uc7a5\uc73c\ub85c \uc815\ub9ac\ud558\uba74, \uc678\uad6d\uc778\uc774 \ub358\uc9c4 \ubb3c\ub7c9\uc744 \uac1c\uc778\uacfc \uae08\uc735\ud22c\uc790 \uc911\uc2ec\uc758 \uae30\uad00\uc774 \ubc1b\uc558\uc9c0\ub9cc \uc9c0\uc218 \ud558\ub77d\uc744 \ub9c9\uc9c0 \ubabb\ud55c \ud558\ub8e8\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uc218\uae09\uc740 \ucf54\uc2a4\ud53c\uc640 \uacb0\uc774 \ub2ec\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc740 731\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uace0, \uae30\uad00\ub3c4 1,029\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc778\uc740 1,721\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00 \ub0b4\ubd80\uc5d0\uc11c\ub294 \uae08\uc735\ud22c\uc790\uac00 1,438\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc9c0\ub9cc, \ud22c\uc2e0 1,140\uc5b5\uc6d0\uacfc \uc5f0\uae30\uae08 784\uc5b5\uc6d0\uc758 \uc21c\ub9e4\ub3c4\uac00 \uc774\ub97c \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uac1c\uc778 \ud640\ub85c \ub9e4\uc218\uc5d0 \ub098\uc120 \uad6c\ub3c4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc120\ubb3c \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 1\uc870 257\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uace0, \uae30\uad00\uc774 1\uc870 1,538\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc774 \ud604\ubb3c\uc740 \ud314\uace0 \uc120\ubb3c\uc740 \uc0b0 \ubaa8\uc2b5\uc774\uc9c0\ub9cc, \ud604\ubb3c \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \ud6e8\uc52c \ucee4 \uc804\uccb4 \ubc29\ud5a5\uc740 \ub9e4\ub3c4 \uc6b0\uc704\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uae09\ub9cc\uc73c\ub85c \ub0b4\uc77c \ud750\ub984\uc744 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc678\uad6d\uc778 \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \ub098\ud758 \uc5f0\uc18d \ucee4\uc9c0\uace0 \uc788\ub2e4\ub294 \uc810\uc740 \ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub3c4 \ud655\uc778\ud560 \uccab \ubc88\uc9f8 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984\\n\\n\uc9c0\uc218 \uae09\ub77d \uc18d\uc5d0\uc11c\ub3c4 \uc624\ub978 \ud14c\ub9c8\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ubaa9\uc7ac \ud14c\ub9c8\ub294 5.54% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ud56d\uacf5 \ud14c\ub9c8\ub294 4.60%, \ud0c0\uc774\uc5b4 \ud14c\ub9c8\ub294 4.50% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc8fc\ub958\ud310\ub9e4 4.07%, P2E 3.73%, \uc120\ud06c\ub9bc 3.41%, \uc704\ud0c1\uc0dd\uc0b0 3.20%, \uc5d4\ud130\ud14c\uc778\uba3c\ud2b8 3.10%, \ud1b5\uc2e0\uc0ac 2.78%\ub3c4 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc790\ub3d9\ucc28\uc640 \ubc14\uc774\uc624 \uad00\ub828\uc8fc\ub3c4 \uc9c0\uc218 \ud558\ub77d\uacfc \ub2e4\ub978 \ubc29\ud5a5\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc544\uc640 \ud604\ub300\ucc28, \ud604\ub300\ubaa8\ube44\uc2a4\uac00 \uc62c\ub790\uace0 \uc140\ud2b8\ub9ac\uc628\uacfc \ud504\ub85c\ud2f0\ub098\ub3c4 \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub4e4 \uc885\ubaa9\uc758 \uac15\uc138\uc5d0\ub294 \uac01\uac01\uc758 \uc7ac\ub8cc\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uae30\ucc28 \uc138\uc561\uacf5\uc81c \uac80\ud1a0, \ud574\uc678 \uc9c4\ucd9c \uc131\uacfc \uac19\uc740 \uac1c\ubcc4 \uc7ac\ub8cc\uac00 \uc9c0\uc218 \ud558\ub77d\uacfc \ubd84\ub9ac\ub3fc \uc791\uc6a9\ud55c \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ud14c\ub9c8 \uc0c1\uc2b9\uc774 \uc9c0\uc218 \ud558\ub77d \uad6d\uba74\uc758 \ubc29\uc5b4 \ud750\ub984\uc778\uc9c0, \uc7ac\ub8cc\uc5d0 \ub530\ub978 \uc120\ubcc4 \ub9e4\uc218\uc778\uc9c0 \uad6c\ubd84\ud558\uae30\ub294 \uc544\uc9c1 \uc774\ub985\ub2c8\ub2e4.<br/>\\n\ub0b4\uc77c\ub3c4 \uac19\uc740 \ud14c\ub9c8\uac00 \uac15\uc138\ub97c \uc774\uc5b4\uac00\ub294\uc9c0\uac00 \ud655\uc778 \ud3ec\uc778\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \ub0b4\uc77c \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ub2e8\uae30\uc801\uc73c\ub85c\ub294 \ud558\ub77d \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0, \ub418\ub3cc\ub9bc\uc774 \ub098\uc624\ub294\uc9c0\uac00 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 5,400\uc120\uc744 \ub0b4\uc900 \ucc44 5,383.80\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc800\uac00 5,336.88\uc774 1\ucc28 \uc9c0\uc9c0 \uad6c\uac04\uc73c\ub85c \uc791\uc6a9\ud558\ub294\uc9c0\uac00 \uccab \ubc88\uc9f8 \ud655\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n5,336.88\uc744 \ubc11\ub3cc\uba74 \uc804\uc77c \uc7a5\uc911 \uc800\uac00 5,421.72 \ud68c\ubcf5\uc740 \ub354 \uba40\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc800\uac00\ub97c \uc9c0\ud0a4\uace0 \uc678\uad6d\uc778 \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc904\uc5b4\ub4e4\uba74 \ub2e8\uae30 \ub418\ub3cc\ub9bc \uc5ec\uc9c0\uac00 \uc0dd\uae41\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \ud604\ubb3c \uc21c\ub9e4\ub3c4 \uaddc\ubaa8\ub294 \ubc18\ub4dc\uc2dc \ud655\uc778\ud560 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298 3\uc870 3,934\uc5b5\uc6d0\uc744 \uae30\ub85d\ud588\uace0, \ub098\ud758 \uc5f0\uc18d \uaddc\ubaa8\uac00 \ucee4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub0b4\uc77c \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc904\uc5b4\ub4dc\ub294\uc9c0, 3\uc870\uc6d0\ub300\uac00 \uc774\uc5b4\uc9c0\ub294\uc9c0\uac00 \ud750\ub984 \uc9c0\uc18d \uc5ec\ubd80\ub97c \uac00\ub974\ub294 \uae30\uc900\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc2dc\uac04\uc678\uc640 \uc120\ubb3c \uc2dc\uc7a5\uc5d0\uc11c \ubc18\ub3c4\uccb4\uc8fc \ud750\ub984\ub3c4 \ud655\uc778\ud560 \ub300\uc0c1\uc785\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uad00\ub828 \ud6c4\uc18d \ubc1c\uc5b8\uc774 \ub098\uc624\ub294\uc9c0\uac00 \ubc18\ub3c4\uccb4 \ubc38\ub958\uccb4\uc778 \uc2ec\ub9ac\ub97c \uc88c\uc6b0\ud569\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\ub3c4 \ud655\uc778\ud560 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298 1,341.00\uc6d0\uc73c\ub85c \ubcf4\ud569\uc774\uc5c8\uc9c0\ub9cc, \ud658\uc728\uc774 \ub2e4\uc2dc \uc624\ub974\uba74 \uc678\uad6d\uc778 \ub9e4\ub3c4 \uc555\ub825\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 \uc870\uc815 \uad6d\uba74\uc758 \uae4a\uc774\ub97c \uac00\ub2a0\ud558\ub294 \ub2e8\uacc4\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 10\uc6d4 29\uc77c \uc885\uac00 5,937.66\uc5d0\uc11c 553.86\ud3ec\uc778\ud2b8, 9.33% \ub0b4\ub824\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uac19\uc740 \uae30\uac04 74.82\ud3ec\uc778\ud2b8, 9.93% \ub0b4\ub824\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e8\uae30 \ub099\ud3ed\uc774 \ucee4\uc9c4 \ub9cc\ud07c \uae30\uc220\uc801 \ub418\ub3cc\ub9bc\uc774 \ub098\uc62c \uc218 \uc788\ub294 \uad6c\uac04\uc774\uc9c0\ub9cc, \ucd09\ub9e4\uac00 \ub41c \uc815\ucc45 \ubd88\ud655\uc2e4\uc131\uc774 \ud574\uc18c\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub418\ub3cc\ub9bc\uc774 \ucd94\uc138 \uc804\ud658\uc778\uc9c0, \ud558\ub77d \uacfc\uc815\uc758 \uc77c\uc2dc\uc801 \ubc18\ub4f1\uc778\uc9c0 \uad6c\ubd84\ud558\ub824\uba74 \uc678\uad6d\uc778 \uc218\uae09\uacfc \uaddc\uc81c \uad00\ub828 \ud6c4\uc18d \uc18c\uc2dd\uc744 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc2dc\ub098\ub9ac\uc624\ub97c \uc815\ub9ac\ud558\uba74 \uc138 \uac00\uc9c0\uc785\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \uc678\uad6d\uc778 \ub9e4\ub3c4\uac00 \uc904\uace0 \ubc18\ub3c4\uccb4 \uaddc\uc81c \uc6b0\ub824\uac00 \uc644\ud654\ub418\uba74 \uc9c0\uc218\uac00 \uc800\uac00\ub97c \uc9c0\ud0a4\uba70 \ub418\ub3cc\ub9bc\uc744 \uc2dc\ub3c4\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc678\uad6d\uc778 \ub9e4\ub3c4\uac00 \uc774\uc5b4\uc9c0\uace0 \uaddc\uc81c \uc6b0\ub824\uac00 \ucee4\uc9c0\uba74 5,336.88 \uc800\uac00\ub97c \ub2e4\uc2dc \uc2dc\ud5d8\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ubbf8\uad6d \uc99d\uc2dc\uc640 \uad6d\ub0b4 \uc99d\uc2dc\uc758 \ud574\uc11d \ucc28\uc774\uac00 \uc881\ud600\uc9c0\uc9c0 \uc54a\uc73c\uba74 \ubcc0\ub3d9\uc131\uc774 \ud070 \ubc15\uc2a4 \ud750\ub984\uc774 \uc774\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc5b4\ub290 \uc2dc\ub098\ub9ac\uc624\uac00 \ub9de\ub294\uc9c0\ub294 \ub0b4\uc77c \uc218\uce58\ub85c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc624\ub298\uc740 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uacb0\uacfc\ub77c\ub294 \uac19\uc740 \uc7ac\ub8cc\uac00 \ubbf8\uad6d\uacfc \ud55c\uad6d\uc5d0\uc11c \uc815\ubc18\ub300 \ud574\uc11d\uc744 \ubc1b\uc740 \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub0b4\uc77c\uc740 \uc678\uad6d\uc778 \ub9e4\ub3c4 \uaddc\ubaa8\uc640 \ubc18\ub3c4\uccb4 \uaddc\uc81c \uad00\ub828 \ud6c4\uc18d \uc18c\uc2dd, \uadf8\ub9ac\uace0 \ucf54\uc2a4\ud53c 5,336.88 \uc800\uac00 \ubc29\uc5b4 \uc5ec\ubd80\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uc2dc\uc7a5 \ud574\uc124\uc744 \uc704\ud55c \uad50\uc721 \ubaa9\uc801\uc758 \uc815\ub9ac\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-05-domestic-market-midday","metadata":{"permalink":"/blog/en/market/2026-11-05-domestic-market-midday","source":"@site/market/2026-11-05-domestic-market-midday/index.mdx","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ube14\ub8e8 \uc6e8\uc774\ube0c\ubc1c \ubc18\ub3c4\uccb4 \uc1fc\ud06c\uc5d0 \ucf54\uc2a4\ud53c \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud55c 11\uc6d4 5\uc77c \uc624\uc804\uc7a5","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-05T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":8.54,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-05-domestic-market-midday","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ube14\ub8e8 \uc6e8\uc774\ube0c\ubc1c \ubc18\ub3c4\uccb4 \uc1fc\ud06c\uc5d0 \ucf54\uc2a4\ud53c \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud55c 11\uc6d4 5\uc77c \uc624\uc804\uc7a5","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 11\uc6d4 5\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 - \ube14\ub8e8\uc6e8\uc774\ube0c \ucda9\uaca9\uc5d0 \uc591 \uc2dc\uc7a5 5%\ub300 \uae09\ub77d","permalink":"/blog/en/market/2026-11-05-domestic-market-close"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ubbf8\uad6d \uc0c1\uc2b9\uc5d0\ub3c4 \ubc18\ub3c4\uccb4 \uaddc\uc81c \uc6b0\ub824\uc5d0 \uae09\ub77d \ucd9c\ubc1c\ud55c \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5","permalink":"/blog/en/market/2026-11-05-domestic-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 5\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uc7a5 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc740 \uc7a5 \uc624\ud508\ubd80\ud130 \uae09\ub77d\ud55c \ub4a4 \uc7a5\uc911 \ub099\ud3ed\uc744 \ub354 \ud0a4\uc6e0\uace0, \uc774\ud6c4 \uc77c\ubd80 \ud68c\ubcf5\ud558\ub294 \ud750\ub984\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,580.09\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 \uc800\uc810 5,386.29\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc800\uc810 \uae30\uc900 \uc804\uc77c \uc885\uac00 \ub300\ube44 \ub099\ud3ed\uc740 5.24%\uc5d0 \ub2ec\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 713.49\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 \uc800\uc810 679.97\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc800\uc810 \uae30\uc900 \uc804\uc77c \uc885\uac00 \ub300\ube44 \ub099\ud3ed\uc740 4.89%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub099\ud3ed \ud655\ub300 \uacfc\uc815\uc5d0\uc11c \ucf54\uc2a4\ud53c \uc2dc\uc7a5\uc5d0 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uac70\ub798 \uc911\ub2e8 \uc870\uce58 \uc5c6\uc774 \uac70\ub798\ub97c \uc774\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc2dc\uc7a5\uc758 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74 \ubc1c\ub3d9\uc740 10\uc6d4 30\uc77c \uc774\ud6c4 \uc57d 1\uc8fc\uc77c \ub9cc\uc785\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc2dc\uc810\uc5d0\ub294 \uc800\uc810 \ub300\ube44 \ubc18\ub4f1\uc774 \ub098\ud0c0\ub098\uba70 \ub099\ud3ed\uc774 \ub2e4\uc18c \ucd95\uc18c\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00\uc640 \uc804\uc77c \uc885\uac00\ub97c \ud06c\uac8c \ubc11\ub3c4\ub294 \uc218\uc900\uc5d0 \uba38\ubb3c\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,456.84 | -226.96 | -3.99% | 5,580.09 | 5,586.46 | 5,386.29 | 152,197\ucc9c\uc8fc | 12\uc870 1,904\uc5b5\uc6d0 | 2026-11-05 12:28 KST |\\n| \ucf54\uc2a4\ub2e5 | 688.18 | -26.77 | -3.74% | 713.49 | 717.06 | 679.97 | 269,749\ucc9c\uc8fc | 3\uc870 1,033\uc5b5\uc6d0 | 2026-11-05 12:28 KST |\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,456.84\ub85c, \uc804\uc77c \uc885\uac00 5,683.80 \ub300\ube44 226.96\ud3ec\uc778\ud2b8, 3.99% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 688.18\ub85c, \uc804\uc77c \uc885\uac00 714.95 \ub300\ube44 26.77\ud3ec\uc778\ud2b8, 3.74% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc7a5 \uc624\ud508 \uc9c1\ud6c4 700\uc120\uc744 \ubc11\ub3cc\uc558\uace0, \uc2a4\ub0c5\uc0f7 \uc2dc\uc810\uc5d0\ub3c4 700\uc120\uc744 \ud68c\ubcf5\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad50\ucc28 \uac80\uc99d\uc740 \ud604\uc7ac\uac00\ub97c \ub4f1\ub77d\ub960\ub85c \ub098\ub208 \uc5ed\uc0b0\uac12\uc73c\ub85c \uc218\ud589\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\uac12\uc740 \ucf54\uc2a4\ud53c \uc57d 5,683.7, \ucf54\uc2a4\ub2e5 \uc57d 714.9\ub85c \uc77c\ubd09 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc624\ub298 \uc624\uc804\uc7a5 \uae09\ub77d\uc758 \uadfc\ubcf8 \ucd09\ub9e4\ub294 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uacb0\uacfc\uc5d0\uc11c \ube44\ub86f\ub41c \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \uaddc\uc81c \ubd88\ud655\uc2e4\uc131\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud558\ub294 \ube14\ub8e8 \uc6e8\uc774\ube0c\uac00 \ud604\uc2e4\ud654\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc815\uce58\uc801 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c\ub77c\ub294 \ud574\uc11d\uc5d0 \uac04\ubc24 \ub274\uc695 \uc99d\uc2dc 3\ub300 \uc9c0\uc218\ub294 \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,736.51\ub85c \uc804\uc77c \ub300\ube44 1.44% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7f0\ub370 \uac19\uc740 \uacb0\uacfc\ub294 \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124\uc5d0 \ub300\ud55c \uaddc\uc81c \uac15\ud654 \uac00\ub2a5\uc131\uc73c\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc2dc\uc7a5\uc5d0\uc11c\ub3c4 \ubc18\ub3c4\uccb4\uc640 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828\uc8fc\ub294 \uc9c0\uc218 \uc0c1\uc2b9\uacfc \ub530\ub85c \uc57d\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uadf8 \uc57d\uc138\uac00 \uc7a5 \uc624\ud508 \uc9c1\ud6c4 \ub300\ud615 \ubc18\ub3c4\uccb4\uc8fc\ub97c \uc911\uc2ec\uc73c\ub85c \ud655\ub300\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uc0bc\uc131\uc804\uc790\ub294 4% \ub118\uac8c \ud558\ub77d\ud588\uace0, SK\ud558\uc774\ub2c9\uc2a4\ub294 7% \ub118\uac8c \ud558\ub77d\ud574 130\ub9cc\uc6d0 \uc120 \uc544\ub798\ub85c \ub0b4\ub824\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uc758 \ubb34\uac8c \uc911\uc2ec\uc774 \ubc18\ub3c4\uccb4\uc5d0 \uc3e0\ub824 \uc788\ub294 \uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc774 \ub9e4\ub3c4\ub9cc\uc73c\ub85c\ub3c4 \uc9c0\uc218 \uc804\uccb4\uac00 \ud06c\uac8c \ud754\ub4e4\ub9bd\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ucf54\uc2a4\ud53c200\uc740 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 851.68\ub85c \uc804\uc77c \ub300\ube44 4.22% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc120\ubb3c\ub3c4 4.30% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615\uc8fc \uc911\uc2ec\uc758 \ud558\ub77d\uc774\ub77c\ub294 \uc810\uc774 \uc218\uce58\ub85c \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 1,343.80\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.21% \uc0c1\uc2b9\uc5d0 \uadf8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ud658\uc728 \uae09\ubcc0\ub3d9\uc774 \uc624\ub298 \ud558\ub77d\uc744 \uc8fc\ub3c4\ud55c \ud754\uc801\uc740 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810\uc5d0\uc11c\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \ubbf8\uad6d 10\ub144\ubb3c \uad6d\ucc44 \uae08\ub9ac\ub294 \uc911\uac04\uc120\uac70 \uacb0\uacfc \ubc18\uc601 \uacfc\uc815\uc5d0\uc11c 8bp\uc5d0\uc11c 9bp \uc218\uc900 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \ud558\ub77d\uc740 \ud1b5\uc0c1 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \uc6b0\ud638\uc801\uc785\ub2c8\ub2e4.<br/>\\n\uadf8\ub7fc\uc5d0\ub3c4 \ubc18\ub3c4\uccb4 \uaddc\uc81c \uc6b0\ub824\uac00 \ubc38\ub958\uc5d0\uc774\uc158 \ud638\uc7ac\ub97c \uc555\ub3c4\ud55c \uac83\uc774 \uc624\ub298 \uc624\uc804\uc7a5\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc218\uae09 \uad6c\ub3c4\ub3c4 \uc624\ub298 \ud558\ub77d\uc758 \ubc30\uacbd\uc744 \uc124\uba85\ud569\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc2dc\uc7a5\ub3d9\ud5a5 API \uae30\uc900 \uc804\uc77c\uc778 11\uc6d4 4\uc77c \ucf54\uc2a4\ud53c\uc5d0\uc11c \uc678\uad6d\uc778\uc740 24,528\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub0a0 \uac1c\uc778\uc740 9,629\uc5b5\uc6d0 \uc21c\ub9e4\uc218, \uae30\uad00\uc740 11,334\uc5b5\uc6d0 \uc21c\ub9e4\uc218\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9 \ub9c8\uac10\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \ub9e4\ub3c4 \uc8fc\uccb4\uac00 \uc678\uad6d\uc778\uc774\uc5c8\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uac1c\uc778\uacfc \uae30\uad00\uc774 \ubb3c\ub7c9\uc744 \ubc1b\uc544\ub0c8\uc9c0\ub9cc, \uc218\uae09\uc758 \ubc29\ud5a5\uc740 \ub9e4\ub3c4 \ucabd\uc5d0 \ubb34\uac8c\uac00 \uc2e4\ub824 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uc624\uc804\uc7a5 \ud558\ub77d\uc740 \ubbf8\uad6d \uc99d\uc2dc \uc0c1\uc2b9\uc774\ub77c\ub294 \ud45c\uba74\uc801 \ud638\uc7ac\ubcf4\ub2e4, \ubc18\ub3c4\uccb4 \uaddc\uc81c \uc6b0\ub824\uc640 \uc678\uad6d\uc778 \ub9e4\ub3c4 \ud750\ub984\uc774 \ub354 \uac15\ud558\uac8c \uc791\uc6a9\ud55c \uacb0\uacfc\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc218\uae09 \ud655\uc815\uce58\ub294 \uc544\uc9c1 \ub098\uc624\uc9c0 \uc54a\uc73c\ubbc0\ub85c, \ub2f9\uc77c \uc7a5\uc911 \uc218\uae09\uc740 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### 1. \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ube14\ub8e8 \uc6e8\uc774\ube0c\uc640 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\\n\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc815\uce58\uc801 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c\uc5d0 \ub274\uc695 \uc99d\uc2dc\ub294 \uc0c1\uc2b9\ud588\uc9c0\ub9cc, \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uaddc\uc81c \uac15\ud654 \uac00\ub2a5\uc131\uc774 \ud568\uaed8 \ubd80\uac01\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uac15\ud654\ub294 \ub370\uc774\ud130\uc13c\ud130 \ud22c\uc790 \uc18d\ub3c4\uc640 \ubc18\ub3c4\uccb4 \uc218\uc694 \uc804\ub9dd\uc5d0 \uc9c1\uc811\uc801\uc778 \ud558\ubc29 \uc694\uc778\uc73c\ub85c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc774 \uc6b0\ub824\uac00 \uc7a5 \uc624\ud508 \uc9c1\ud6c4 \ubc18\ub3c4\uccb4\uc8fc\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \ub9e4\ub3c4\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub099\ud3ed \ud655\ub300 \uacfc\uc815\uc5d0\uc11c \ucf54\uc2a4\ud53c \uc2dc\uc7a5\uc5d0 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uac70\ub798 \uc911\ub2e8 \uc870\uce58 \uc5c6\uc774 \uac70\ub798\ub97c \uc774\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0ac\uc774\ub4dc\uce74\ub294 \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub9e4 \ud638\uac00\ub97c \uc77c\uc2dc\uc801\uc73c\ub85c \uc81c\ud55c\ud558\ub294 \uc7a5\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ubc1c\ub3d9 \uc790\uccb4\uac00 \ub099\ud3ed\uc758 \uc18d\ub3c4\uc640 \uac15\ub3c4\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc2e0\ud638\ub85c \ud574\uc11d\ub429\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc2dc\uc7a5\uc758 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74 \ubc1c\ub3d9\uc740 10\uc6d4 30\uc77c \uc774\ud6c4 \uc57d 1\uc8fc\uc77c \ub9cc\uc785\ub2c8\ub2e4.<br/>\\n\\n### 2. \uc7a5\uc911 5%\ub300 \ub099\ud3ed \uc774\ud6c4 \ubd80\ubd84 \ud68c\ubcf5\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 \uc800\uc810 5,386.29\uc5d0\uc11c \uc804\uc77c \ub300\ube44 5.24%\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc7a5\uc911 \uc800\uc810 679.97\uc5d0\uc11c \uc804\uc77c \ub300\ube44 4.89%\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ud6c4 \uc800\uc810 \ub9e4\uc218\uc138 \uc720\uc785\uc73c\ub85c \ub450 \uc9c0\uc218 \ubaa8\ub450 \ub099\ud3ed\uc744 \uc77c\ubd80 \ucd95\uc18c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \ucf54\uc2a4\ud53c\ub294 \uc624\uc804 11\uc2dc 20\ubd84 \uae30\uc900 5,500\uc120 \uc7ac\uc9c4\uc785\uc744 \ub178\ub9ac\ub294 \ud750\ub984\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \ucf54\uc2a4\ud53c 5,456.84\ub294 \uc800\uc810 \ub300\ube44 \uc57d 70\ud3ec\uc778\ud2b8 \ubc18\ub4f1\ud55c \uc218\uc900\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc774 \ub098\ud0c0\ub0ac\ub2e4\ub294 \uc0ac\uc2e4\uacfc \ud558\ub77d \ucd94\uc138\uac00 \ub05d\ub0ac\ub2e4\ub294 \uc0ac\uc2e4\uc740 \ub2e4\ub985\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00 5,580.09\uc640 5,500\uc120\uc744 \ub3d9\uc2dc\uc5d0 \ud68c\ubcf5\ud558\uc9c0 \ubabb\ud55c \uc0c1\ud0dc\uc5d0\uc11c\ub294 \ubc18\ub4f1\uc758 \uc9c0\uc18d \uc5ec\ubd80\ub97c \ub2e8\uc815\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc740 \uc624\uc804\uc7a5\uc758 \ubcc0\ub3d9\uc131\uc774 \ub2e8\uc21c\ud55c \uc870\uc815\uc774 \uc544\ub2c8\ub77c, \ub9e4\ub3c4 \uc18d\ub3c4\uac00 \ube68\ub790\ub358 \ucda9\uaca9 \uc7a5\uc138\uc600\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n### 3. 9\uc6d4 \uacbd\uc0c1\uc218\uc9c0 614\uc5b5\ub2ec\ub7ec, \uc0ac\uc0c1 \uccab 600\uc5b5\ub2ec\ub7ec \ub3cc\ud30c\\n\\n9\uc6d4 \uacbd\uc0c1\uc218\uc9c0\ub294 614\uc5b5\ub2ec\ub7ec \ud751\uc790\ub85c \uc0ac\uc0c1 \uccab 600\uc5b5\ub2ec\ub7ec \ub3cc\ud30c\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\ucd9c \ud638\uc870\uc5d0 \ud798\uc785\uc740 \uacbd\uc0c1\uc218\uc9c0 \ud751\uc790\ub294 \ub300\uc678 \uac74\uc804\uc131\uc758 \ubc84\ud300\ubaa9\uc73c\ub85c \ud3c9\uac00\ub429\ub2c8\ub2e4.<br/>\\n\uc774 \uc18c\uc2dd\uc740 \uc7a5\uc911 \ud558\ub77d\uc744 \ub9c9\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac70\uc2dc \uac74\uc804\uc131 \uc9c0\ud45c\uc640 \ubc18\ub3c4\uccb4 \uaddc\uc81c \ucda9\uaca9\uc740 \uc11c\ub85c \ub2e4\ub978 \uc2dc\uac04\ucd95\uc5d0\uc11c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uacbd\uc0c1\uc218\uc9c0 \ud751\uc790\ub294 \uad6c\uc870\uc801 \uc9c0\uc9c0 \uc694\uc778\uc774\uace0, \uaddc\uc81c \uc6b0\ub824\ub294 \ub2f9\uc7a5\uc758 \uac00\uaca9 \ucda9\uaca9 \uc694\uc778\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uc624\uc804\uc7a5\uc740 \ub2e8\uae30 \ucda9\uaca9\uc774 \uad6c\uc870\uc801 \uc9c0\uc9c0 \uc694\uc778\ubcf4\ub2e4 \uba3c\uc800 \uac00\uaca9\uc5d0 \ubc18\uc601\ub41c \uc0ac\ub840\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uacbd\uc0c1\uc218\uc9c0 \ud751\uc790 \uaddc\ubaa8 \uc790\uccb4\uac00 \ud6fc\uc190\ub41c \uac83\uc740 \uc544\ub2c8\ubbc0\ub85c, \uc624\ud6c4 \uc774\ud6c4 \uc2dc\uc7a5\uc758 \ud574\uc11d\uc774 \ub2ec\ub77c\uc9c8 \uc5ec\uc9c0\ub294 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc758 \uc758\ubbf8\ub97c \ub2e8\uc815\ud558\uc9c0 \uc54a\uace0, \uc624\ud6c4 \ud750\ub984\uc5d0\uc11c \ud655\uc778\ud560 \uc7ac\ub8cc\ub85c \ub0a8\uaca8\ub461\ub2c8\ub2e4.<br/>\\n\\n## \uc139\ud130\xb7\ud14c\ub9c8 \uc601\ud5a5 \uccb4\uc778\\n\\n\ubc18\ub3c4\uccb4 \ucda9\uaca9\uc740 \uc9c0\uc218 \uc804\uccb4\ub85c \ud655\uc0b0\ub418\ub294 \uc5f0\uacb0\uace0\ub9ac\ub97c \uac00\uc9d1\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\uac00 \uc9c0\uc218\uc5d0\uc11c \ucc28\uc9c0\ud558\ub294 \ube44\uc911\uc774 \ud06c\uae30 \ub54c\ubb38\uc5d0, \ubc18\ub3c4\uccb4 \ub9e4\ub3c4\ub294 \ucf54\uc2a4\ud53c200\uacfc \uc120\ubb3c\uc744 \ud568\uaed8 \ub04c\uc5b4\ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c200\uc774 4.22% \ud558\ub77d\ud55c \uc810\uc740 \ud558\ub77d\uc774 \uc77c\ubd80 \uc885\ubaa9\uc5d0 \uad6d\ud55c\ub418\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n2\ucc28\uc804\uc9c0 \uccb4\uc778\uc5d0\ub294 \ubcc4\ub3c4\uc758 \uc2e4\uc801 \uc545\uc7ac\uac00 \uacb9\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5d0\ucf54\ud504\ub85c\ube44\uc5e0\uc758 3\ubd84\uae30 \uc601\uc5c5\uc774\uc775\uc740 120\uc5b5\uc6d0\uc73c\ub85c \uc804\ub144 \ub300\ube44 76.2% \uac10\uc18c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801 \uc545\ud654\ub294 \ubc30\ud130\ub9ac \uc18c\uc7ac \uccb4\uc778\uc758 \ud22c\uc790 \uc2ec\ub9ac\ub97c \ucd94\uac00\ub85c \uc704\ucd95\uc2dc\ud0a4\ub294 \uc694\uc778\uc785\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc740 \ubc18\ub300 \ubc29\ud5a5\uc758 \uc5f0\uacb0\uace0\ub9ac\ub97c \ub9cc\ub4ed\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uc9c0\uc815\ud559\uc801 \ub9ac\uc2a4\ud06c \ucd95\uc18c \uae30\ub300\uc5d0 \uad6d\uc81c\uc720\uac00\ub294 8%\ub300 \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc740 \ud56d\uacf5\uacfc \uc6b4\uc1a1\uc758 \uc5f0\ub8cc\ube44 \ubd80\ub2f4\uc744 \ub0ae\ucd94\ub294 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud14c\ub9c8 \uae30\uc900 \ud56d\uacf5 \ud14c\ub9c8\ub294 \uc7a5\uc911 4.16% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\uc138 \uc644\ud654 \uae30\ub300\ub294 \ub610 \ub2e4\ub978 \uc5f0\uacb0\uace0\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n\uc77c\ubd80 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \ud2b8\ub7fc\ud504 \uc601\ud5a5\ub825 \uc57d\ud654\uc5d0 \ub530\ub978 \uad00\uc138 \uc644\ud654 \uae30\ub300\uc5d0 \uc790\ub3d9\ucc28\uc8fc\uac00 \uc0c1\ub300\uc801\uc73c\ub85c \uc120\uc804\ud588\ub2e4\uace0 \uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \ubc29\uc0b0 \uad00\ub828\uc8fc\uac00 \uc57d\uc138\ub97c \ubcf4\uc600\ub2e4\uace0 \uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \ud558\ub77d\uc740 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \uc6b0\ud638\uc801\uc774\uc9c0\ub9cc, \uc624\ub298\uc740 \uaddc\uc81c \uc6b0\ub824\uac00 \uadf8 \ud6a8\uacfc\ub97c \ub36e\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uacb0\uad6d \uc624\ub298 \uc624\uc804\uc7a5\uc758 \uc601\ud5a5 \uccb4\uc778\uc740 \ubc18\ub3c4\uccb4 \uaddc\uc81c \uc6b0\ub824\uac00 \uc911\uc2ec\uc774\uace0, \uc720\uac00 \ud558\ub77d\uacfc \uad00\uc138 \uae30\ub300\uac00 \ubd80\ubd84\uc801\uc778 \uc0c1\uc1c4 \uc694\uc778\uc73c\ub85c \uc791\uc6a9\ud55c \uad6c\ub3c4\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09 \ud45c\\n\\n\ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\uc740 \uc624\ub298 \uae09\ub77d\uc774 \ub2e8\uae30 \uc870\uc815 \ubc94\uc704\ub97c \ubc97\uc5b4\ub0ac\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 11\uc6d4 4\uc77c \uc885\uac00 5,683.80\uc5d0\uc11c \uc624\ub298 \uc7a5\uc911 \uc800\uc810 5,386.29\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 11\uc6d4 4\uc77c \uc885\uac00 714.95\uc5d0\uc11c \uc624\ub298 \uc7a5\uc911 \uc800\uc810 679.97\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \ub0a0\uc9dc | \ucf54\uc2a4\ud53c \uc2dc\uac00 | \ucf54\uc2a4\ud53c \uace0\uac00 | \ucf54\uc2a4\ud53c \uc800\uac00 | \ucf54\uc2a4\ud53c \uc885\uac00 | \ucf54\uc2a4\ud53c \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495\ucc9c\uc8fc |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 228,294\ucc9c\uc8fc |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | 198,130\ucc9c\uc8fc |\\n| 2026-11-03 | 5,715.19 | 5,735.92 | 5,615.80 | 5,648.79 | 207,371\ucc9c\uc8fc |\\n| 2026-11-04 | 5,786.13 | 5,828.13 | 5,421.72 | 5,683.80 | 276,889\ucc9c\uc8fc |\\n\\n| \ub0a0\uc9dc | \ucf54\uc2a4\ub2e5 \uc2dc\uac00 | \ucf54\uc2a4\ub2e5 \uace0\uac00 | \ucf54\uc2a4\ub2e5 \uc800\uac00 | \ucf54\uc2a4\ub2e5 \uc885\uac00 | \ucf54\uc2a4\ub2e5 \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052\ucc9c\uc8fc |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 470,174\ucc9c\uc8fc |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | 355,750\ucc9c\uc8fc |\\n| 2026-11-03 | 723.92 | 723.92 | 702.34 | 704.39 | 430,571\ucc9c\uc8fc |\\n| 2026-11-04 | 715.74 | 718.34 | 683.66 | 714.95 | 539,758\ucc9c\uc8fc |\\n\\n## \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984 \ubcc0\ud654\\n\\n\uc9c0\uc218 \uae09\ub77d \uc18d\uc5d0\uc11c\ub3c4 \uc77c\ubd80 \ud14c\ub9c8\ub294 \uc0c1\uc2b9 \ud750\ub984\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud14c\ub9c8 \uae30\uc900 \uc7a5\uc911 \uc0c1\uc2b9 \ud14c\ub9c8\ub294 \ubaa9\uc7ac 5.96%, \uc8fc\ub958\ud310\ub9e4 5.25%, \ud0c0\uc774\uc5b4 4.79%, P2E 4.76%, \ud56d\uacf5 4.16%, \uc704\ud0c1\uc0dd\uc0b0 3.94%, \uc5d4\ud130\ud14c\uc778\uba3c\ud2b8 3.49%, \ube44\ub9cc\uce58\ub8cc\uc81c 3.14% \uc21c\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \ud14c\ub9c8\ub4e4\uc740 \uad6c\uc131 \uc885\ubaa9 \uc218\uac00 \uc801\uc740 \uc18c\uaddc\ubaa8 \ud14c\ub9c8\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ud558\ub77d \uad6d\uba74\uc5d0\uc11c\ub294 \ubc29\uc5b4\uc801 \uc131\uaca9\uc758 \uc18c\uaddc\ubaa8 \ud14c\ub9c8\ub85c \uc790\uae08\uc774 \uc774\ub3d9\ud558\ub294 \ud750\ub984\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud0c0\uc774\uc5b4 \uc0c1\uc2b9\uc740 \uad00\uc138 \uc644\ud654 \uae30\ub300\uc640 \uc5f0\uacb0\ub418\ub294 \ud750\ub984\uc73c\ub85c \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud56d\uacf5 \uc0c1\uc2b9\uc740 \uc720\uac00 \ud558\ub77d\uc5d0 \ub530\ub978 \ube44\uc6a9 \ubd80\ub2f4 \uc644\ud654 \uae30\ub300\uc640 \uc5f0\uacb0\ub429\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ud14c\ub9c8 \uc0c1\uc2b9\uc774 \uc9c0\uc218 \ud558\ub77d\uc744 \uc0c1\uc1c4\ud558\ub294 \uaddc\ubaa8\ub294 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658 \uc5ec\ubd80\ub97c \ubcf4\uba74, \ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00 \ub300\ube44 \ud558\ub77d \ubc29\ud5a5\uc744 \uc720\uc9c0\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,580.09\uc5d0\uc11c \uc800\uc810 5,386.29\uae4c\uc9c0 \ubc00\ub9b0 \ub4a4 5,456.84\uae4c\uc9c0 \ubc18\ub4f1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 713.49\uc5d0\uc11c \uc800\uc810 679.97\uae4c\uc9c0 \ubc00\ub9b0 \ub4a4 688.18\uae4c\uc9c0 \ubc18\ub4f1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc800\uc810 \ub300\ube44 \ubc18\ub4f1\uc740 \ud655\uc778\ub418\uc9c0\ub9cc, \uc2dc\uac00 \ud68c\ubcf5\uc5d0\ub294 \uc774\ub974\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804\uc7a5\uc758 \ud750\ub984 \ubcc0\ud654\ub294 \uae09\ub77d \ud6c4 \ubd80\ubd84 \ubc18\ub4f1\uc774\uc9c0, \ubc29\ud5a5 \uc804\ud658\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ud6c4 \uc804\ub9dd\uacfc \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\uc624\ud6c4\uc5d0\ub294 \uc624\uc804 \uae09\ub77d\uc774 \uc77c\uc2dc\uc801 \ucda9\uaca9\uc774\uc5c8\ub294\uc9c0, \ud558\ub77d \ucd94\uc138\uc758 \uc2dc\uc791\uc778\uc9c0\ub97c \uad6c\ubd84\ud558\ub294 \uad6c\uac04\uc785\ub2c8\ub2e4.<br/>\\n\uccab \ubc88\uc9f8\ub85c \ud655\uc778\ud560 \uc218\uce58\ub294 \ucf54\uc2a4\ud53c 5,500\uc120 \uc7ac\uc9c4\uc785 \uc5ec\ubd80\uc785\ub2c8\ub2e4.<br/>\\n5,500\uc120\uc744 \ud68c\ubcf5\ud558\uace0 \uc720\uc9c0\ud558\uba74 \ubc18\ub4f1\uc774 \uc774\uc5b4\uc9c8 \uc5ec\uc9c0\uac00 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n5,500\uc120 \uc544\ub798\uc5d0 \uba38\ubb3c\uba74 \uc624\ud6c4\uc5d0\ub3c4 \ub9e4\ub3c4 \uc6b0\uc704 \ud750\ub984\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \ubc88\uc9f8\ub85c \ud655\uc778\ud560 \uad6c\uac04\uc740 \ub2f9\uc77c \uc800\uc810\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc800\uc810 5,386.29\uc640 \ucf54\uc2a4\ub2e5 \uc800\uc810 679.97\uc774 \uc9c0\uc9c0\ub418\ub294\uc9c0\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc800\uc810\uc744 \ub2e4\uc2dc \ubc11\ub3cc\uba74 \uc624\uc804 \ubc18\ub4f1\uc774 \uc2e4\ud328\ud55c \uac83\uc73c\ub85c \ud574\uc11d\ub429\ub2c8\ub2e4.<br/>\\n\uc138 \ubc88\uc9f8\ub85c \ud655\uc778\ud560 \uc218\uce58\ub294 \ucf54\uc2a4\ub2e5 700\uc120 \ud68c\ubcf5 \uc5ec\ubd80\uc785\ub2c8\ub2e4.<br/>\\n700\uc120\uc740 \uc2ec\ub9ac\uc801 \uae30\uc900\uc120\uc73c\ub85c, \ud68c\ubcf5 \uc5ec\ubd80\uac00 \ud22c\uc790 \uc2ec\ub9ac \ud310\ub2e8\uc5d0 \ucc38\uace0\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\ub124 \ubc88\uc9f8\ub85c \ud655\uc778\ud560 \uc7ac\ub8cc\ub294 \ubc18\ub3c4\uccb4 \uad00\ub828 \ucd94\uac00 \uc18c\uc2dd\uc785\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \ub17c\uc758\uc758 \uad6c\uccb4\uc801\uc778 \ub0b4\uc6a9\uacfc \ubbf8\uad6d \ubc18\ub3c4\uccb4\uc8fc \uc57c\uac04 \ud750\ub984\uc774 \uc624\ud6c4 \uc2ec\ub9ac\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc12f \ubc88\uc9f8\ub85c \ud655\uc778\ud560 \uc7ac\ub8cc\ub294 \uc678\uad6d\uc778 \uc218\uae09\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc218\uae09 \ud655\uc815\uce58\ub294 \uc544\uc9c1 \ub098\uc624\uc9c0 \uc54a\uc73c\ubbc0\ub85c, \ub9c8\uac10 \uc218\uae09\uc5d0\uc11c \uc678\uad6d\uc778 \ub9e4\ub3c4 \uc9c0\uc18d \uc5ec\ubd80\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc704 \uc2dc\ub098\ub9ac\uc624\ub294 \uc9c0\uc218\uc640 \uc139\ud130 \ub2e8\uc704\uc758 \uad00\ucc30 \uae30\uc900\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\ub294 \ub0b4\uc6a9\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc624\ub298 \uc624\uc804\uc7a5\uc740 \ubbf8\uad6d \uc815\uce58 \uc9c0\ud615 \ubcc0\ud654\uac00 \ubc18\ub3c4\uccb4 \uaddc\uc81c \uc6b0\ub824\ub85c \uc774\uc5b4\uc9c0\uba70 \ucf54\uc2a4\ud53c \uc2dc\uc7a5\uc5d0 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud55c \ucda9\uaca9 \uc7a5\uc138\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ud6c4\uc5d0\ub294 5,500\uc120\uacfc \ub2f9\uc77c \uc800\uc810 \ub4f1 \uad6c\uccb4\uc801\uc778 \uac00\uaca9 \ub808\ubca8\uc744 \uae30\uc900\uc73c\ub85c \ubc18\ub4f1 \uc9c0\uc18d \uc5ec\ubd80\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\ud669 \uc815\ub9ac\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc815\uc815(2026\ub144 11\uc6d4 5\uc77c \uc624\ud6c4): \ucd08\ud310\uc5d0\uc11c \ucf54\uc2a4\ub2e5\uc5d0\ub3c4 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud588\ub2e4\uace0 \uc37c\uc73c\ub098, \ub2f9\uc77c \ubc1c\ub3d9\ub41c \uac83\uc740 \ucf54\uc2a4\ud53c \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\ubfd0\uc774\uba70 \ucf54\uc2a4\ub2e5\uc740 \uac70\ub798 \uc911\ub2e8 \uc870\uce58 \uc5c6\uc774 \uac70\ub798\ub97c \uc774\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc218\uae09 \uc218\uce58\ub3c4 \ub124\uc774\ubc84 \uc2dc\uc7a5\ub3d9\ud5a5 API \ucd5c\uc885\uac12(\uc678\uad6d\uc778 -24,528\uc5b5\uc6d0, \uac1c\uc778 +9,629\uc5b5\uc6d0, \uae30\uad00 +11,334\uc5b5\uc6d0)\uc73c\ub85c \ubc14\ub85c\uc7a1\uc558\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-05-domestic-market-open","metadata":{"permalink":"/blog/en/market/2026-11-05-domestic-market-open","source":"@site/market/2026-11-05-domestic-market-open/index.mdx","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ubbf8\uad6d \uc0c1\uc2b9\uc5d0\ub3c4 \ubc18\ub3c4\uccb4 \uaddc\uc81c \uc6b0\ub824\uc5d0 \uae09\ub77d \ucd9c\ubc1c\ud55c \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-05T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":8.97,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-05-domestic-market-open","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ubbf8\uad6d \uc0c1\uc2b9\uc5d0\ub3c4 \ubc18\ub3c4\uccb4 \uaddc\uc81c \uc6b0\ub824\uc5d0 \uae09\ub77d \ucd9c\ubc1c\ud55c \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ube14\ub8e8 \uc6e8\uc774\ube0c\ubc1c \ubc18\ub3c4\uccb4 \uc1fc\ud06c\uc5d0 \ucf54\uc2a4\ud53c \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ud55c 11\uc6d4 5\uc77c \uc624\uc804\uc7a5","permalink":"/blog/en/market/2026-11-05-domestic-market-midday"},"nextItem":{"title":"2026\ub144 11\uc6d4 5\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-05-nasdaq-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 5\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ubc30\uacbd\\n\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,736.51\ub85c \uc804\uc77c \ub300\ube44 364.50\ud3ec\uc778\ud2b8, 1.44% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,688.62\ub85c \uc804\uc77c \ub300\ube44 119.70\ud3ec\uc778\ud2b8, 1.58% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc555\uc2b9\ud588\ub2e4\ub294 \uc18c\uc2dd\uc774 \ub274\uc695 \uc99d\uc2dc \uc0c1\uc2b9\uc758 \ubc30\uacbd\uc73c\ub85c \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7f0\ub370 \uac19\uc740 \uc18c\uc2dd\uc740 \uad6d\ub0b4 \uc7a5 \uc624\ud508\uc5d0\uc11c\ub294 \uc815\ubc18\ub300\uc758 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9 \uc2b9\ub9ac \uc774\ud6c4 \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124\uc5d0 \ub300\ud55c \uaddc\uc81c \uac15\ud654 \uac00\ub2a5\uc131\uc774 \ubd80\uac01\ub418\uba74\uc11c, \uac04\ubc24 \ubbf8\uad6d \uc2dc\uc7a5\uc5d0\uc11c\ub3c4 \ubc18\ub3c4\uccb4\uc640 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828\uc8fc\ub294 \uc57d\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uadf8 \uc57d\uc138\uac00 \uc7a5 \uc624\ud508 \uc9c1\ud6c4 \ubc18\ub3c4\uccb4\uc640 \uc778\uacf5\uc9c0\ub2a5 \uad00\ub828\uc8fc\ub97c \uc911\uc2ec\uc73c\ub85c \ud655\ub300\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c\uc778 2026\ub144 11\uc6d4 4\uc77c \uad6d\ub0b4 \uc99d\uc2dc\ub294 \uc7a5\uc911 \ud070 \ubcc0\ub3d9 \ub05d\uc5d0 \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 5,683.80\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.62% \uc0c1\uc2b9\ud588\uace0, \ucf54\uc2a4\ub2e5\uc740 714.95\ub85c \uc804\uc77c \ub300\ube44 1.50% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc804\uc77c \uc7a5\uc911 \ucf54\uc2a4\ud53c\ub294 \uace0\uac00 5,828.13\uc5d0\uc11c \uc800\uac00 5,421.72\uae4c\uc9c0 400\ud3ec\uc778\ud2b8 \ub118\uac8c \ud754\ub4e4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9 \ub9c8\uac10\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \ubcc0\ub3d9\uc131\uc774 \ucef8\ub358 \ud558\ub8e8\uc600\ub2e4\ub294 \uc810\uc774 \uc624\ub298 \uae09\ub77d \ucd9c\ubc1c\uc758 \ubc30\uacbd\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,537.21 | -146.59 | -2.58% | 5,580.09 | 5,586.46 | 5,520.92 | 50,538\ucc9c\uc8fc | 3\uc870 6,418\uc5b5\uc6d0 | 2026-11-05 09:30 KST |\\n| \ucf54\uc2a4\ub2e5 | 699.94 | -15.01 | -2.10% | 713.49 | 717.06 | 699.94 | 92,903\ucc9c\uc8fc | 1\uc870 1,555\uc5b5\uc6d0 | 2026-11-05 09:30 KST |\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc740 \ubaa8\ub450 \uae09\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,580.09\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,537.21\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 713.49\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 699.94\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810\uc5d0 700\uc120\uc744 \ubc11\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,683.80, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 714.95\uc785\ub2c8\ub2e4.<br/>\\n\uad50\ucc28 \uac80\uc99d\uc740 \ud604\uc7ac\uac00\ub97c \ub4f1\ub77d\ub960\ub85c \ub098\ub208 \uc5ed\uc0b0\uac12\uc73c\ub85c \uc218\ud589\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\uac12\uc740 \ucf54\uc2a4\ud53c \uc57d 5,683.7, \ucf54\uc2a4\ub2e5 \uc57d 714.9\ub85c \uc77c\ubd09 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc624\ub298 \uae09\ub77d \ucd9c\ubc1c\uc758 \uadfc\ubcf8 \ucd09\ub9e4\ub294 \ubbf8\uad6d \uc815\uce58 \uc9c0\ud615 \ubcc0\ud654\uac00 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790\uc5d0 \ub358\uc9c4 \uaddc\uc81c \ubd88\ud655\uc2e4\uc131\uc785\ub2c8\ub2e4.<br/>\\n\ub274\uc695 \uc99d\uc2dc \uc804\uccb4\uac00 \uc624\ub978 \ub0a0\uc5d0\ub3c4 \ubc18\ub3c4\uccb4\uc640 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828\uc8fc\ub294 \ub530\ub85c \uc57d\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \ub9c8\uc774\ud06c\ub860\uacfc \uc5d4\ube44\ub514\uc544, \ucf54\uc5b4\uc704\ube0c \ub4f1 \ubc18\ub3c4\uccb4\uc640 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828\uc8fc\uac00 \uac04\ubc24 \uc57d\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9 \uc2b9\ub9ac \uc774\ud6c4 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124\uc744 \ub458\ub7ec\uc2fc \uc9c0\uc5ed \uaddc\uc81c \uac15\ud654 \uac00\ub2a5\uc131\uc774 \uac70\ub860\ub41c \uac83\uc774 \uc9c1\uc811\uc801\uc778 \uc774\uc720\uc785\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc774 \uc6b0\ub824\uac00 \ud504\ub9ac\ub9c8\ucf13 \ub2e8\uacc4\ubd80\ud130 \uc0bc\uc131\uc804\uc790\uc640 SK\ud558\uc774\ub2c9\uc2a4 \ub4f1 \ub300\ud615 \ubc18\ub3c4\uccb4\uc8fc\uc5d0 \ub300\ud55c \ub9e4\ub3c4\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \ub450 \uc885\ubaa9\uc740 \ud504\ub9ac\ub9c8\ucf13\uc5d0\uc11c 2%\uc5d0\uc11c 4% \uc218\uc900\uc758 \ud558\ub77d\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uc758 \ubb34\uac8c \uc911\uc2ec\uc774 \ubc18\ub3c4\uccb4\uc5d0 \uc3e0\ub824 \uc788\ub294 \uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc774 \ub9e4\ub3c4\ub9cc\uc73c\ub85c\ub3c4 \uc9c0\uc218 \uc804\uccb4\uac00 \ud06c\uac8c \ud754\ub4e4\ub9bd\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c200\uc774 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 3% \ub118\uac8c \ud558\ub77d\ud558\uace0 \ucf54\uc2a4\ud53c \uc120\ubb3c\uc774 3% \ub118\uac8c \ud558\ub77d\ud55c \uc810\ub3c4 \ub300\ud615\uc8fc \uc911\uc2ec\uc758 \ud558\ub77d\uc784\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 1,342\uc6d0 \uc218\uc900\uc73c\ub85c, \uc804\uc77c \ub300\ube44 0.10% \uc218\uc900\uc758 \uc18c\ud3ed \uc0c1\uc2b9\uc5d0 \uadf8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ud658\uc728 \uae09\ubcc0\ub3d9\uc774 \uc624\ub298 \ud558\ub77d\uc744 \uc8fc\ub3c4\ud55c \ud754\uc801\uc740 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810\uc5d0\uc11c\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc218\uae09 \uad6c\ub3c4\ub3c4 \uc624\ub298 \ud558\ub77d\uc758 \ubc30\uacbd\uc744 \uc124\uba85\ud569\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc678\uad6d\uc778\uc740 \ucf54\uc2a4\ud53c\uc5d0\uc11c \ub300\uaddc\ubaa8 \ub9e4\ub3c4\ub97c \uc774\uc5b4\uac14\uace0, \uac1c\uc778\uacfc \uae30\uad00\uc774 \uadf8 \ubb3c\ub7c9\uc744 \ubc1b\uc544\ub0c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9 \ub9c8\uac10\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \ub9e4\ub3c4 \uc8fc\uccb4\uac00 \uc678\uad6d\uc778\uc774\uc5c8\ub2e4\ub294 \uc810\uc740, \uc218\uae09\uc758 \ubc29\ud5a5\uc774 \uc544\uc9c1 \ub9e4\ub3c4 \ucabd\uc5d0 \ubb34\uac8c\uac00 \uc2e4\ub824 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uacb0\uad6d \uc624\ub298 \ud558\ub77d\uc740 \ubbf8\uad6d \uc99d\uc2dc \uc0c1\uc2b9\uc774\ub77c\ub294 \ud45c\uba74\uc801 \ud638\uc7ac\ubcf4\ub2e4, \ubc18\ub3c4\uccb4\uc640 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c\uc5d0 \ub300\ud55c \uaddc\uc81c \uc6b0\ub824\uc640 \uc678\uad6d\uc778 \ub9e4\ub3c4 \ud750\ub984\uc774 \ub354 \uac15\ud558\uac8c \uc791\uc6a9\ud55c \uacb0\uacfc\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc99d\uc2dc\uac00 \uc62c\ub790\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uad6d\ub0b4 \uc2dc\uc7a5\uc774 \ub530\ub77c \uc624\ub978\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218 \uc5c6\ub294 \ud558\ub8e8\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### 1. \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ubbfc\uc8fc\ub2f9 \uc555\uc2b9\uacfc \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\\n\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc555\uc2b9\ud558\uba74\uc11c \ub274\uc695 \uc99d\uc2dc 3\ub300 \uc9c0\uc218\ub294 \ub3d9\ubc18 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 1.44%, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 1.58% \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7f0\ub370 \uc120\uac70 \uacb0\uacfc\uc758 \ud574\uc11d\uc740 \uc5c5\uc885\ubcc4\ub85c \uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9 \uc2b9\ub9ac \uc774\ud6c4 \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \ud504\ub85c\uc81d\ud2b8\uc5d0 \ucc28\uc9c8\uc774 \uc0dd\uae38 \uc218 \uc788\ub2e4\ub294 \uc6b0\ub824\uac00 \ucee4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \ud655\ub300\ub85c \uc804\uae30\uc694\uae08 \uc0c1\uc2b9\uacfc \ud658\uacbd \ud6fc\uc190\uc744 \uc6b0\ub824\ud558\ub294 \uc9c0\uc5ed \uc8fc\ubbfc\uc758 \ubaa9\uc18c\ub9ac\uac00 \ucee4\uc9c4 \uc810\ub3c4 \ubc30\uacbd\uc73c\ub85c \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc6b0\ub824\ub294 \ubc18\ub3c4\uccb4\uc640 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828\uc8fc\uc758 \uc57d\uc138\ub85c \uc774\uc5b4\uc84c\uace0, \uad6d\ub0b4 \uc7a5 \uc624\ud508\uc5d0\uc11c\ub294 \ub300\ud615 \ubc18\ub3c4\uccb4\uc8fc \ub9e4\ub3c4\ub85c \uc804\ub2ec\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uacb0\uacfc\uac00 \uc815\ucc45\uc73c\ub85c \ud655\uc815\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \uc774 \ubd88\ud655\uc2e4\uc131\uc774 \uc644\uc804\ud788 \ud574\uc18c\ub41c \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc758 \uc2ec\ub9ac\uc801 \ucda9\uaca9\uc740 \uc9c0\uc218 \uc804\uccb4\uc758 \ubc29\ud5a5\ubcf4\ub2e4, \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ubc38\ub958\uccb4\uc778\uc5d0 \ub300\ud55c \uc7ac\ud3c9\uac00 \ucabd\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\uc870\uc801\uc778 \ubc29\ud5a5 \uc804\ud658\uc73c\ub85c \ub2e8\uc815\ud558\uae30\ub294 \uc774\ub974\uc9c0\ub9cc, \uc7a5 \uc624\ud508\uc758 \ud558\ub77d\uc744 \uc124\uba85\ud558\ub294 \uac00\uc7a5 \uc9c1\uc811\uc801\uc778 \ucd09\ub9e4\uc785\ub2c8\ub2e4.<br/>\\n\\n### 2. 9\uc6d4 \uacbd\uc0c1\uc218\uc9c0 614\uc5b5 \ub2ec\ub7ec, \uc0ac\uc0c1 \uccab \uc6d4\uac04 600\uc5b5 \ub2ec\ub7ec \ub3cc\ud30c\\n\\n\ud55c\uad6d\uc740\ud589 \ubc1c\ud45c\uc5d0 \ub530\ub974\uba74 9\uc6d4 \uacbd\uc0c1\uc218\uc9c0 \ud751\uc790\ub294 614\uc5b5 6\ucc9c\ub9cc \ub2ec\ub7ec\ub85c \uc9d1\uacc4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d4\uac04 \uae30\uc900 \uc0ac\uc0c1 \ucc98\uc74c\uc73c\ub85c 600\uc5b5 \ub2ec\ub7ec\ub97c \ub118\uc5c8\uace0, \uc885\uc804 \ucd5c\ub300\uc600\ub358 6\uc6d4 478\uc5b5 9\ucc9c\ub9cc \ub2ec\ub7ec\ub97c \ud06c\uac8c \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n1\uc6d4\ubd80\ud130 9\uc6d4\uae4c\uc9c0 \ub204\uc801 \ud751\uc790\ub294 3,406\uc5b5 6\ucc9c\ub9cc \ub2ec\ub7ec\ub85c, \uc9c0\ub09c\ud574 \uac19\uc740 \uae30\uac04\uc758 4\ubc30\uac00 \ub118\ub294 \uc218\uc900\uc785\ub2c8\ub2e4.<br/>\\n\ud751\uc790\ub97c \uc774\ub048 \uac83\uc740 \ubc18\ub3c4\uccb4 \uc218\ucd9c \uae09\uc99d\uc73c\ub85c, \ubc18\ub3c4\uccb4 \uc218\ucd9c\uc774 1\ub144 \uc0c8 260% \ub118\uac8c \uc99d\uac00\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\ud488\uc218\uc9c0 \ud751\uc790\ub294 627\uc5b5 5\ucc9c\ub9cc \ub2ec\ub7ec\ub85c \uc5ed\ub300 \ucd5c\ub300\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc18c\uc2dd\uc740 \ub2f9\uc77c \uc9c0\uc218\ub97c \ub04c\uc5b4\uc62c\ub9ac\ub294 \uc7ac\ub8cc\ub77c\uae30\ubcf4\ub2e4, \ud55c\uad6d \uacbd\uc81c\uc758 \ub300\uc678 \uac74\uc804\uc131\uacfc \uc218\ucd9c \uacbd\uc7c1\ub825\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc911\uae30\uc801\uc778 \ubc30\uacbd\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \ud558\ub77d\uc774 \ud380\ub354\uba58\ud138 \uc545\ud654\uc5d0\uc11c \ube44\ub86f\ub41c \uac83\uc774 \uc544\ub2c8\ub77c, \uaddc\uc81c \uc6b0\ub824\uc640 \uc218\uae09 \ud750\ub984\uc5d0\uc11c \ube44\ub86f\ub410\ub2e4\ub294 \uc810\uc744 \uad6c\ubd84\ud558\ub294 \uae30\uc900\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uacbd\uc0c1\uc218\uc9c0 \ud638\uc870\uac00 \ub2f9\uc77c \ubc18\ub3c4\uccb4\uc8fc \ub9e4\ub3c4\ub97c \ub9c9\uc544\uc8fc\uc9c0\ub294 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac70\uc2dc \uc9c0\ud45c\uc758 \uac15\ud568\uacfc \ub2f9\uc77c \uc8fc\uac00\uc758 \ubc29\ud5a5\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc624\ub298 \uc7a5\uc758 \uad50\ud6c8\uc785\ub2c8\ub2e4.<br/>\\n\\n### 3. \uae08\uc735\uad8c \uc815\ubcf4 \uc720\ucd9c\uacfc 580\uacf3 \uc804\uc218\uc810\uac80\\n\\n\uae08\uc735 \ub2f9\uad6d\uc740 \uae08\uc735\uc0ac \ubcf4\uc548 \uc810\uac80\uc744 \uc5f0 2\ud68c\ub85c \ud655\ub300\ud558\uace0, 580\uac1c \uae08\uc735\uc0ac\ub97c \uc804\uc218\uc810\uac80\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.<br/>\\n37\uacf3\uc758 \uae08\uc735\uad8c\uc5d0\uc11c 47\ub9cc \uac74\uc774 \ub118\ub294 \uc815\ubcf4\uac00 \uc720\ucd9c\ub41c \uc0ac\uc2e4\uc774 \uc774\ubc88 \uc870\uce58\uc758 \ubc30\uacbd\uc73c\ub85c \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc740 \uc9c0\uc218\ub97c \uc9c1\uc811 \ub04c\uc5b4\ub0b4\ub9ac\ub294 \uc7ac\ub8cc\ub77c\uae30\ubcf4\ub2e4, \uae08\uc735 \uc5c5\uc885 \uc804\ubc18\uc5d0 \ub300\ud55c \uc2e0\ub8b0\uc640 \uaddc\uc81c \ube44\uc6a9\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub9cc\ub4dc\ub294 \uc7ac\ub8cc\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc218\uc810\uac80\uacfc \uc810\uac80 \ud69f\uc218 \ud655\ub300\ub294 \ub2e8\uae30\uc801\uc73c\ub85c \uae08\uc735\uc0ac\uc758 \ucef4\ud50c\ub77c\uc774\uc5b8\uc2a4 \ubd80\ub2f4\uc744 \ud0a4\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \ubcf4\uc548 \ud22c\uc790\uc640 \uad00\ub9ac \uccb4\uacc4 \uac15\ud654\ub294 \uc911\uae30\uc801\uc73c\ub85c \uae08\uc735 \uc2dc\uc2a4\ud15c\uc758 \uc2e0\ub8b0\ub97c \ubcf4\uac15\ud558\ub294 \ubc29\ud5a5\uc785\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc774 \uc0ac\uac74\uc744 \uae08\uc735\uc8fc \uac1c\ubcc4 \uc545\uc7ac\ubcf4\ub2e4, \uae08\uc735 \uc5c5\uc885 \uc804\ubc18\uc758 \uaddc\uc81c \ud658\uacbd \ubcc0\ud654\ub85c \ubc1b\uc544\ub4e4\uc77c \uac00\ub2a5\uc131\uc774 \ud07d\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uc7a5 \uc624\ud508\uc5d0\uc11c\ub294 \ubc18\ub3c4\uccb4 \ud558\ub77d\uc5d0 \uac00\ub824 \uae08\uc735 \uc5c5\uc885\uc758 \uc6c0\uc9c1\uc784\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \ub35c \ubd80\uac01\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc7a5\uc911 \uae08\uc735\uc8fc\uc758 \uc0c1\ub300 \uac15\ub3c4\uac00 \uc720\uc9c0\ub418\ub294\uc9c0\ub294 \uc624\ub298 \ud655\uc778\ud560 \uc810 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc139\ud130\xb7\ud14c\ub9c8 \uc601\ud5a5 \uccb4\uc778\\n\\n\ud558\ub77d\uc758 \ucd9c\ubc1c\uc810\uc740 \ubc18\ub3c4\uccb4\uc640 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c\uc785\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\ub294 \ubc18\ub3c4\uccb4 \uc218\uc694 \uc804\ub9dd\uc5d0 \uc9c1\uc811 \ub2ff\uace0, \ubc18\ub3c4\uccb4\ub294 \uad6d\ub0b4 \uc9c0\uc218\uc640 \uc218\ucd9c\uc758 \uc911\uc2ec\ucd95\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4\uac00 \ud754\ub4e4\ub9ac\uba74 \uc804\uae30\xb7\uc804\uc790 \uc5c5\uc885 \uc804\uccb4\uac00 \ud568\uaed8 \ud754\ub4e4\ub9ac\uace0, \ub370\uc774\ud130\uc13c\ud130\uc640 \uc804\ub825 \uc124\ube44 \uad00\ub828 \uae30\ub300\ub3c4 \ud568\uaed8 \uc870\uc815\ubc1b\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uc7a5 \uc624\ud508\uc5d0\uc11c \uc758\ub8cc\uc815\ubc00\uae30\uae30\uc640 \uc804\uae30\xb7\uc804\uc790 \uc5c5\uc885\uc774 \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc790\ub3d9\ucc28\uc640 \uc77c\ubd80 \uae08\uc735\uc8fc\ub294 \uc0c1\ub300\uc801\uc73c\ub85c \uc120\ubc29\ud558\ub294 \ub4f1 \uc5c5\uc885\ubcc4 \ucc28\ubcc4\ud654\uac00 \ub69c\ub837\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uaddc\uc81c \uc6b0\ub824\uac00 \ubaa8\ub4e0 \uc5c5\uc885\uc5d0 \ub3d9\uc77c\ud558\uac8c \uc791\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc790\ub3d9\ucc28\ub294 \uc804\uae30\ucc28 \uc0dd\uc0b0 \uc9c0\uc6d0 \uac80\ud1a0\uc640 \ub85c\ubd07 \uc0ac\uc5c5 \ud655\uc7a5 \uae30\ub300\ub77c\ub294 \ubcc4\uac1c\uc758 \uc7ac\ub8cc\uac00 \ubc84\ud300\ubaa9\uc774 \ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\uc735\uc740 \ubcf4\uc548 \uc810\uac80\uc774\ub77c\ub294 \uc790\uccb4 \uc7ac\ub8cc\uac00 \uc788\uc9c0\ub9cc, \ubc18\ub3c4\uccb4 \ud558\ub77d\uc758 \uc9c1\uc811\uc801\uc778 \uc804\uc5fc \uacbd\ub85c\uc5d0\uc11c\ub294 \ud55c \ubc1c\uc9dd \ub5a8\uc5b4\uc838 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc14\uc774\uc624\uc640 \ube44\ub9cc\uce58\ub8cc\uc81c, \ub1cc\uc9c8\ud658 \ub4f1 \uc77c\ubd80 \ud14c\ub9c8\uac00 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud14c\ub9c8 \ud654\uba74\uc5d0\uc11c \uc0c1\uc2b9 \uc0c1\uc704\uad8c\uc5d0 \uc624\ub978 \uc810\ub3c4 \ub208\uc5d0 \ub755\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc9c0\uc218 \ud558\ub77d \uad6d\uba74\uc5d0\uc11c \uc18c\uaddc\ubaa8 \ud14c\ub9c8\uc758 \uc0c1\uc2b9\uc774 \uc9c0\uc218 \uc804\uccb4\ub97c \ubc1b\uccd0\uc8fc\ub294 \ud798\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc601\ud5a5 \uccb4\uc778\uc744 \uc815\ub9ac\ud558\uba74, \uaddc\uc81c \uc6b0\ub824\ub294 \ubc18\ub3c4\uccb4\uc640 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c\uc5d0\uc11c \uc2dc\uc791\ud574 \uc9c0\uc218 \uc804\uccb4\ub85c \ubc88\uc9c0\uace0, \ub0b4\uc218\xb7\uc815\ucc45 \uc218\ud61c\uac00 \uc788\ub294 \uc5c5\uc885\uc740 \uc0c1\ub300\uc801\uc73c\ub85c \ubc84\ud2f0\ub294 \uad6c\ub3c4\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\ub3c4\uac00 \uc720\uc9c0\ub418\ub294\uc9c0, \uc544\ub2c8\uba74 \ud558\ub77d\uc774 \uc804 \uc5c5\uc885\uc73c\ub85c \ud655\uc0b0\ub418\ub294\uc9c0\uac00 \uc7a5\uc911 \ud655\uc778\ud560 \ud575\uc2ec\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 228,294\ucc9c\uc8fc |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | 198,130\ucc9c\uc8fc |\\n| 2026-11-03 | 5,715.19 | 5,735.92 | 5,615.80 | 5,648.79 | 207,371\ucc9c\uc8fc |\\n| 2026-11-04 | 5,786.13 | 5,828.13 | 5,421.72 | 5,683.80 | 276,889\ucc9c\uc8fc |\\n| 2026-11-05 | 5,580.09 | 5,586.46 | 5,520.92 | \ud615\uc131 \uc911 | 48,383\ucc9c\uc8fc |\\n\\n\uc704 \ud45c\ub294 \ucf54\uc2a4\ud53c \uae30\uc900\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \ucd5c\uadfc 5\uac70\ub798\uc77c\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 470,174\ucc9c\uc8fc |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | 355,750\ucc9c\uc8fc |\\n| 2026-11-03 | 723.92 | 723.92 | 702.34 | 704.39 | 430,571\ucc9c\uc8fc |\\n| 2026-11-04 | 715.74 | 718.34 | 683.66 | 714.95 | 539,758\ucc9c\uc8fc |\\n| 2026-11-05 | 713.49 | 717.06 | 700.14 | \ud615\uc131 \uc911 | 88,476\ucc9c\uc8fc |\\n\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\uc804\uc77c\uc778 2026\ub144 11\uc6d4 4\uc77c \ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 \uc800\uac00 5,421.72\uae4c\uc9c0 \ubc00\ub838\ub2e4\uac00 5,683.80\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc800\uac00\uac00 \uc624\ub298 \ud558\ub77d\uc758 \uccab \ubc88\uc9f8 \uc9c0\uc9c0 \uad6c\uac04\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uc804\uc77c \uc800\uac00\ub294 683.66\uc73c\ub85c, \uc624\ub298 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 699.94\ub294 \uc544\uc9c1 \uadf8 \uc704\ub97c \uc720\uc9c0\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc804\uc77c \uc218\uae09\\n\\n\uc804\uc77c\uc778 2026\ub144 11\uc6d4 4\uc77c \ucf54\uc2a4\ud53c \uc218\uae09\uc740 \uc678\uad6d\uc778\uc758 \ub9e4\ub3c4\uc640 \uac1c\uc778\xb7\uae30\uad00\uc758 \ub9e4\uc218\uac00 \ub9de\uc120 \uad6c\ub3c4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc740 \ucf54\uc2a4\ud53c\uc5d0\uc11c 2\uc870 4,528\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc778\uc740 9,629\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uace0, \uae30\uad00\uc740 1\uc870 1,134\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 113\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uace0, \uac1c\uc778\uc740 706\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc73c\uba70, \uae30\uad00\uc740 704\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uad6c\ub3c4\ub97c \ud574\uc11d\ud558\uba74, \uc678\uad6d\uc778\uc774 \ub358\uc9c4 \ubb3c\ub7c9\uc744 \uac1c\uc778\uacfc \uae30\uad00\uc774 \ub098\ub220 \ubc1b\uc740 \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uac00 \uc0c1\uc2b9 \ub9c8\uac10\ud588\ub2e4\ub294 \uc0ac\uc2e4\ub9cc \ubcf4\uba74 \uc218\uae09\uc774 \uc548\uc815\ub41c \uac83\ucc98\ub7fc \ubcf4\uc785\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \ub9e4\ub3c4 \uc8fc\uccb4\uac00 \uc678\uad6d\uc778\uc774\uace0 \ub9e4\uc218 \uc8fc\uccb4\uac00 \uac1c\uc778\uacfc \uae30\uad00\uc774\ub77c\ub294 \uc810\uc740, \uc0c1\uc2b9\uc758 \uc8fc\ub3c4\uad8c\uc774 \uc544\uc9c1 \uc678\uad6d\uc778 \ucabd\uc5d0 \uc788\uc9c0 \uc54a\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \ub9e4\ub3c4\uac00 \uc774\uc5b4\uc9c0\ub294 \ub3d9\uc548 \uac1c\uc778\uacfc \uae30\uad00\uc758 \ub9e4\uc218\ub294 \ud558\ub77d\uc744 \ub5a0\ubc1b\uce58\ub294 \ubc29\ud30c\uc81c \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4.<br/>\\n\ubc29\ud30c\uc81c\uac00 \ubc84\ud2f0\ub294 \ub3d9\uc548\uc5d0\ub294 \uc7a5\uc911 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c0\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uae09\ub77d \ucd9c\ubc1c\uc740 \uc804\uc77c \uc678\uad6d\uc778 \ub9e4\ub3c4 \ud750\ub984\uc774 \uc7a5 \uc624\ud508\uae4c\uc9c0 \uc774\uc5b4\uc9c4 \uac83\uc73c\ub85c \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uc7a5\uc911 \uc678\uad6d\uc778 \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc804\uc77c \uc218\uc900\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0, \uc544\ub2c8\uba74 \ucd95\uc18c\ub418\ub294\uc9c0\uac00 \ubc18\ub4f1 \uc5ec\ubd80\ub97c \uac00\ub974\ub294 \uccab \ubc88\uc9f8 \uc2e0\ud638\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ub2e8\uae30\uc801\uc73c\ub85c\ub294 \uc77c\uc2dc\uc801 \uc870\uc815\uc778\uc9c0, \ud558\ub77d \ucd94\uc138\uc758 \uc2dc\uc791\uc778\uc9c0\ub97c \uac00\ub974\ub294 \uad6c\uac04\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \uc885\uac00 5,683.80\uc5d0\uc11c 2% \ub118\uac8c \ubc00\ub9b0 \ucc44 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uac00 \uc804\uc77c \uc7a5\uc911 \uc800\uac00 5,421.72\ub97c \uc9c0\ucf1c\ub0b4\ub294\uc9c0\uac00 \ub2e8\uae30 \uc9c0\uc9c0 \ud655\uc778\uc758 \uae30\uc900\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uac04\uc744 \uc9c0\ucf1c\ub0b4\uba74 \uc624\ub298 \ud558\ub77d\uc740 \uaddc\uc81c \uc6b0\ub824\uc5d0 \ub530\ub978 \uc77c\uc2dc\uc801 \uc870\uc815\uc73c\ub85c \uc815\ub9ac\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uac04\uc744 \ubc11\ub3cc\uba74 \uc870\uc815 \ud3ed\uc774 \ub354 \ucee4\uc9c0\ub294 \uc2dc\ub098\ub9ac\uc624\ub97c \uc5f4\uc5b4\ub450\uc5b4\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 700\uc120\uc774 \ub2e8\uae30 \uc2ec\ub9ac\uc801 \uae30\uc900\uc785\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc2dc\uc810 699.94\ub294 700\uc120\uc744 \ubc11\ub3c8 \uc218\uc900\uc774\uc9c0\ub9cc, \uc7a5 \ucd08\ubc18 \uc774\ud0c8\uc774 \ud655\uc815\ub41c \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n700\uc120\uc744 \ud68c\ubcf5\ud558\ub294\uc9c0, \uc544\ub2c8\uba74 \uc804\uc77c \uc800\uac00 683.66 \ucabd\uc73c\ub85c \ubc00\ub9ac\ub294\uc9c0\uac00 \ucf54\uc2a4\ub2e5 \ub2e8\uae30 \ubc29\ud5a5\uc758 \uae30\uc900\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 9\uc6d4 \uacbd\uc0c1\uc218\uc9c0 \ud751\uc790\ub77c\ub294 \ud380\ub354\uba58\ud138 \ubc30\uacbd\uacfc, \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c\ub77c\ub294 \uc815\ucc45 \ubd88\ud655\uc2e4\uc131\uc774 \ub9de\uc11c\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \uc218\ucd9c \ud638\uc870\uac00 \uc774\uc5b4\uc9c0\ub294 \ud55c \uc911\uae30 \ud380\ub354\uba58\ud138\uc740 \uc5ec\uc804\ud788 \uacac\uace0\ud55c \ud3b8\uc785\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uaddc\uc81c \uc6b0\ub824\uac00 \uc2e4\uc81c \uc815\ucc45\uc73c\ub85c \uad6c\uccb4\ud654\ub418\uba74 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \uc18d\ub3c4\uc5d0 \ub300\ud55c \uc7ac\ud3c9\uac00\uac00 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\ub294 \ub450 \uac00\uc9c0\uc785\ub2c8\ub2e4.<br/>\\n\uccab \ubc88\uc9f8\ub294 \uaddc\uc81c \uc6b0\ub824\uac00 \uad6c\ub450 \uc218\uc900\uc5d0 \uba38\ubb3c\uace0 \uc678\uad6d\uc778 \ub9e4\ub3c4\uac00 \ucd95\uc18c\ub418\uba74\uc11c \uc9c0\uc218\uac00 \uc804\uc77c \uc885\uac00 \ucabd\uc73c\ub85c \ub418\ub3cc\ub9ac\ub294 \uc2dc\ub098\ub9ac\uc624\uc785\ub2c8\ub2e4.<br/>\\n\ub450 \ubc88\uc9f8\ub294 \uc678\uad6d\uc778 \ub9e4\ub3c4\uac00 \uc774\uc5b4\uc9c0\uace0 \ubc18\ub3c4\uccb4 \uc57d\uc138\uac00 \uc804 \uc5c5\uc885\uc73c\ub85c \ud655\uc0b0\ub418\uba74\uc11c \uc804\uc77c \uc800\uac00\ub97c \uc2dc\ud5d8\ud558\ub294 \uc2dc\ub098\ub9ac\uc624\uc785\ub2c8\ub2e4.<br/>\\n\uc5b4\ub290 \ucabd\uc774\ub4e0 \ud2b9\uc815 \uc885\ubaa9\uc5d0 \ub300\ud55c \ub9e4\uc218\ub098 \ub9e4\ub3c4 \ud310\ub2e8\uc774 \uc544\ub2c8\ub77c, \uc9c0\uc218\uc640 \uc139\ud130 \ub2e8\uc704\uc758 \ud750\ub984\uc73c\ub85c \ud655\uc778\ud560 \ubb38\uc81c\uc785\ub2c8\ub2e4.<br/>\\n\ub9ac\uc2a4\ud06c \uad00\ub9ac \uad00\uc810\uc5d0\uc11c\ub294 \uc7a5 \ucd08\ubc18 \ud558\ub77d\ud3ed\uc744 \ucd94\uaca9\ud558\uae30\ubcf4\ub2e4, \uc9c0\uc9c0 \uad6c\uac04\uacfc \uc218\uae09 \ucd95\uc18c \uc5ec\ubd80\ub97c \ud655\uc778\ud55c \ub4a4 \ud310\ub2e8\ud558\ub294 \uac83\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 \uc804\uc77c \uc7a5\uc911 \uc800\uac00 5,421.72\ub97c \uc9c0\ucf1c\ub0b4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 700\uc120\uc744 \ud68c\ubcf5\ud558\ub294\uc9c0, \uc544\ub2c8\uba74 \uc804\uc77c \uc800\uac00 683.66 \ucabd\uc73c\ub85c \ubc00\ub9ac\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc804\uc77c \ucf54\uc2a4\ud53c 2\uc870 4,528\uc5b5\uc6d0 \uc218\uc900\uc5d0\uc11c \ucd95\uc18c\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4\uc640 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \uad00\ub828\uc8fc\uc758 \ud558\ub77d\ud3ed\uc774 \ucd95\uc18c\ub418\ub294\uc9c0, \uc544\ub2c8\uba74 \ud655\uc0b0\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc790\ub3d9\ucc28\uc640 \uae08\uc735 \ub4f1 \uc0c1\ub300\uc801\uc73c\ub85c \uc120\ubc29\ud55c \uc5c5\uc885\uc758 \uac15\ub3c4\uac00 \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc774 1,342\uc6d0 \uc218\uc900\uc5d0\uc11c \uae09\ubcc0\ud558\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ubbf8\uad6d \uc99d\uc2dc \uc0c1\uc2b9\uc5d0\ub3c4 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ubc18\ub3c4\uccb4 \uaddc\uc81c \uc6b0\ub824\uc640 \uc678\uad6d\uc778 \ub9e4\ub3c4 \ud750\ub984\uc5d0 \uae09\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uc7a5\uc740 \uc9c0\uc9c0 \uad6c\uac04\uacfc \uc218\uae09 \ucd95\uc18c \uc5ec\ubd80\ub97c \ud655\uc778\ud558\ub294 \ud558\ub8e8\uac00 \ub420 \uac83\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70, \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub410\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-05-nasdaq-market-close","metadata":{"permalink":"/blog/en/market/2026-11-05-nasdaq-market-close","source":"@site/market/2026-11-05-nasdaq-market-close/index.mdx","title":"2026\ub144 11\uc6d4 5\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-05T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":6.88,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-05-nasdaq-market-close","title":"2026\ub144 11\uc6d4 5\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ubbf8\uad6d \uc0c1\uc2b9\uc5d0\ub3c4 \ubc18\ub3c4\uccb4 \uaddc\uc81c \uc6b0\ub824\uc5d0 \uae09\ub77d \ucd9c\ubc1c\ud55c \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5","permalink":"/blog/en/market/2026-11-05-domestic-market-open"},"nextItem":{"title":"\ubbf8\uad6d \uc911\uac04\uc120\uac70 \uc774\ud6c4 AI \uaddc\uc81c \uc6b0\ub824\uc5d0 \ub098\uc2a4\ub2e5 \uc7a5\uc911 5% \uae09\ub77d","permalink":"/blog/en/market/2026-11-05-nasdaq-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 5\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc804\uc77c \ub300\ube44 5.52% \ud558\ub77d\ud574 24,315.00\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d \ud3ed\uc740 1,421.51\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 \uc9c0\ub09c 10\uc6d4 6\uc77c \uae30\ub85d\ud55c \uc0ac\uc0c1 \ucd5c\uace0 \uc885\uac00 27,599.89 \ub300\ube44 11.90% \ub0ae\uc544\uc838 \uc870\uc815 \uad6c\uac04\uc5d0 \ub4e4\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\uc740 4.36% \ud558\ub77d\ud574 7,353.73\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 3.44% \ud558\ub77d\ud574 51,523.06\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c\uc758 \uc0c1\uc2b9\ubd84\uc744 \uc138 \uc9c0\uc218 \ubaa8\ub450 \ub418\ub3cc\ub838\uace0, \ub098\uc2a4\ub2e5\uacfc S&P500\uc740 \uc804\uc77c \uc0c1\uc2b9\ubd84\uc744 \uc6c3\ub3c4\ub294 \ud3ed\uc73c\ub85c \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \ub2f9\uc77c \uace0\uac00 | \ub2f9\uc77c \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 24,315.00 | -1,421.51 | -5.52% | 25,736.51 | 25,559.03 | 24,262.14 |\\n| S&P500 | 7,353.73 | -334.89 | -4.36% | 7,688.62 | 7,681.29 | 7,350.35 |\\n| \ub2e4\uc6b0\uc9c0\uc218 | 51,523.06 | -1,833.06 | -3.44% | 53,356.12 | 53,710.61 | 51,486.82 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 11\uc6d4 5\uc77c 16\uc2dc 20\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 11\uc6d4 6\uc77c 06\uc2dc 20\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569 \uc218\uce58\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 curl \uc9c1\uc811 \uc870\ud68c\uac00 \ub9c9\ud600 \ube0c\ub77c\uc6b0\uc800\ub85c \uc9c1\uc811 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\ub294 \ubbf8\uad6d 11\uc6d4 5\uc77c 16\uc2dc 21\ubd84 \uc7a5\ub9c8\uac10 \uae30\uc900\uc73c\ub85c \uc885\uac00 24,315.00, \uc804\uc77c \ub300\ube44 1,421.52, \ub4f1\ub77d\ub960 5.52%\uac00 \ud45c\uc2dc\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ud45c\uc2dc\uac12\uc740 \ubc18\uc62c\ub9bc\uc5d0 \ub530\ub77c 1,421.52\ub85c \ubcf4\uc774\uba70, \uc885\uac00\uc5d0\uc11c \uc804\uc77c \uc885\uac00\ub97c \ube80 \uac12\uc740 1,421.51\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc758 \ub098\uc2a4\ub2e5 \uc885\ud569 \uac12\ub3c4 \uc885\uac00 24,315.00, \uc804\uc77c \ub300\ube44 1,421.51, \ub4f1\ub77d\ub960 5.52%\ub85c \ub124\uc774\ubc84 \uac12\uacfc \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\nS&P500 \uc218\uce58\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \uc885\uac00\uc5d0\uc11c \uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc744 \ube7c\ub294 \ubc29\uc2dd\uc73c\ub85c \uc5ed\uc0b0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 \ub098\uc2a4\ub2e5 25,736.51, S&P500 7,688.62, \ub2e4\uc6b0\uc9c0\uc218 53,356.12\uc774\uba70, \uc138 \uac12 \ubaa8\ub450 \uc804 \uac70\ub798\uc77c \ub9c8\uac10 \uae00\uc758 \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc758 \ud45c\uc2dc\uac12\uc774\uba70, Yahoo Finance \uc77c\ubd09\uacfc\ub3c4 \uc2dc\uac00\uc640 \uace0\uac00\uc640 \uc800\uac00\uc640 \uc885\uac00\uae4c\uc9c0 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\nS&P500 \ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 Yahoo Finance \uc77c\ubd09 \uae30\uc900\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218 \uc218\uce58\ub294 Yahoo Finance \uc77c\ubd09\uc73c\ub85c \ud655\uc778\ud55c \uac12\uc774\uba70, \uac19\uc740 \uc77c\ubd09\uc758 \ub098\uc2a4\ub2e5 \uc218\uce58\uac00 \ub124\uc774\ubc84 \ub9c8\uac10 \uc218\uce58\uc640 \uc2dc\uac00\uc640 \uace0\uac00\uc640 \uc800\uac00\uc640 \uc885\uac00\uae4c\uc9c0 \uc77c\uce58\ud574 \uc77c\ubd09 \uae30\uc900\uc758 \uc815\ud569\uc131\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uae30\uc900 1,355.50\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 14.50\uc6d0, 1.08% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc640 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub9c8\uac10 \uc6d0\uc778\uc740 \ubcf8\ubb38\uc5d0 \uc4f0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc774\ub0a0 \ud558\ub77d\uc758 \ud45c\uba74\uc801 \uc774\uc720\ub294 \uc804\uc77c \ub7a0\ub9ac\uc5d0 \ub300\ud55c \ub418\ub3cc\ub9bc\uc785\ub2c8\ub2e4.<br/>\\n\uadfc\ubcf8 \ucd09\ub9e4\ub294 \uc138 \uac00\uc9c0\ub85c \uc555\ucd95\ub429\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \ubbfc\uc8fc\ub2f9\uc758 \uc758\ud68c \uc7a5\uc545 \uc774\ud6c4 \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uac00 \ubcf8\uaca9\ud654\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \ubc29\ud5a5\uc774 \uad6c\uccb4\ud654\ub418\uae30 \uc804\ubd80\ud130 \ud22c\uc790\uc790\ub4e4\uc774 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uc18d\ub3c4\uc640 \uc804\ub825\uacfc \ud658\uacbd \ube44\uc6a9\uc5d0 \ub300\ud55c \uac00\uc815\uc744 \ub2e4\uc2dc \uc4f0\uae30 \uc2dc\uc791\ud588\uace0, \uc774\ub294 \uc131\uc7a5\uc8fc \uc804\ubc18\uc758 \ud560\uc778\uc728\uc744 \ub192\uc774\ub294 \ucabd\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ubc18\ub3c4\uccb4 \uc2e4\uc801\uacfc \uc218\uc694\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uacb9\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ud004\ucef4\uc758 4\ubd84\uae30 \uac00\uc774\ub358\uc2a4 \uc57d\ud654\uc640 \ub9c8\uc774\ud06c\ub860\uc758 \ub300\ub9cc \uacf5\uc7a5 \uacc4\ud68d \uc911\ub2e8 \ubcf4\ub3c4\uac00 \ubc18\ub3c4\uccb4 \ubc38\ub958\uccb4\uc778 \uc804\ubc18\uc758 \ud22c\uc790 \uc2ec\ub9ac\ub97c \uc555\ubc15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uae08\ub9ac \ud558\ub77d\uc774 \uc8fc\uac00 \ubc29\uc5b4\ub85c\ub294 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d 10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc740 4.89%\uc5d0\uc11c 4.84%\ub85c \ub0ae\uc544\uc84c\uc9c0\ub9cc, \uc774\ub0a0 \ud558\ub77d\uc740 \uae08\ub9ac \uacbd\ub85c\ubcf4\ub2e4 \uaddc\uc81c\uc640 \uc218\uc694 \uc6b0\ub824\uac00 \uc6b0\uc138\ud588\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc774 1.08% \uc624\ub974\uba70 \ub2ec\ub7ec \uac15\uc138\uac00 \ub098\ud0c0\ub09c \uc810\ub3c4 \uc704\ud5d8\uc790\uc0b0 \ud68c\ud53c \uc2ec\ub9ac\uc640 \uac19\uc740 \ubc29\ud5a5\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c\uacfc \ube44\uad50\ud558\uba74 \uc9c0\uc218 \uac04 \ud798\uc758 \ubc30\uce58\ub3c4 \ub4a4\uc9d1\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c\uc5d0\ub294 \ub2e4\uc6b0\uc9c0\uc218\uac00 3.03% \uc624\ub974\uba70 \uc0c1\uc2b9\uc744 \uc8fc\ub3c4\ud588\uc9c0\ub9cc, \uc774\ub0a0\uc740 \ub098\uc2a4\ub2e5\uc774 5.52% \ud558\ub77d\ud574 \ub099\ud3ed\uc774 \uac00\uc7a5 \ucef8\uace0 \ub2e4\uc6b0\uc9c0\uc218\ub294 3.44% \ud558\ub77d\uc73c\ub85c \ub099\ud3ed\uc774 \uac00\uc7a5 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ub9e4\ub3c4 \uc555\ub825\uc774 \uae30\uc220\uc8fc\uc640 \uc131\uc7a5\uc8fc\uc5d0 \uc9d1\uc911\ub410\uace0, \uc6b0\ub7c9\uc8fc\uc640 \uac00\uce58\uc8fc \ube44\uc911\uc774 \ub192\uc740 \ub2e4\uc6b0\uc9c0\uc218\ub294 \uc0c1\ub300\uc801\uc73c\ub85c \ub35c \ubc00\ub838\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n\uccab\uc9f8, \ubbfc\uc8fc\ub2f9 \uc758\ud68c \uc7a5\uc545 \uc774\ud6c4 \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uac00 \ud655\uc0b0\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9 \uc18c\uc18d \uc57c\uc0ac\ubbfc \uc548\uc0ac\ub9ac \ud558\uc6d0\uc758\uc6d0\uc774 \uc778\uacf5\uc9c0\ub2a5 \uac1c\ubc1c \uc77c\uc2dc\uc911\ub2e8\uacfc \uc0b0\uc5c5 \uaddc\uc81c, \ucd08\uc9c0\ub2a5 \uae08\uc9c0\ub97c \ucd09\uad6c\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uc8fc \uc8fc\ubbfc\ud22c\ud45c\uc5d0\uc11c\ub294 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828 40\uac1c \uc548\uac74 \uc911 39\uac74\uc5d0\uc11c \uc81c\ud55c \uacb0\uc815\uc774 \ub098\uc654\ub2e4\ub294 \uc9d1\uacc4\ub3c4 \ubcf4\ub3c4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ud14d\uc0ac\uc2a4 \uc8fc\uc9c0\uc0ac \uc120\uac70 \uc774\ubcc0\ub3c4 \uc8fc\ubaa9\ubc1b\uc558\uc73c\uba70, \ud14d\uc0ac\uc2a4\ub294 \uace8\ub4dc\ub9cc\uc0ad\uc2a4 \ucd94\uc0b0 \uae30\uc900 \uacc4\ud68d\ub41c \ub370\uc774\ud130\uc13c\ud130 \uc6a9\ub7c9\uc758 \uc57d 25%\ub97c \ucc28\uc9c0\ud55c\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uc6b0\ub824\uac00 \ucee4\uc9c0\uba74 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uc18d\ub3c4\uc640 \uc804\ub825 \uc870\ub2ec \ube44\uc6a9\uc5d0 \ub300\ud55c \uac00\uc815\uc774 \ubc14\ub00c\uace0, \uc774\ub294 \ubc18\ub3c4\uccb4\uc640 \ub370\uc774\ud130\uc13c\ud130 \ubc38\ub958\uccb4\uc778 \uc804\ubc18\uc758 \ubcc0\ub3d9\uc131\uc73c\ub85c \ubc88\uc9d1\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ub098\uc2a4\ub2e5\uc774 \uc0ac\uc0c1 \ucd5c\uace0 \uc885\uac00 \ub300\ube44 11.90% \ub0ae\uc544\uc838 \uc870\uc815 \uad6c\uac04\uc5d0 \ub4e4\uc5b4\uac04 \uc810\uc740 \uc774 \uc6b0\ub824\uac00 \ub2e8\uae30 \ub178\uc774\uc988\ub97c \ub118\uc5b4 \uc7ac\ud3c9\uac00 \uad6d\uba74\uc73c\ub85c \ubc88\uc84c\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n\ub458\uc9f8, \ubc18\ub3c4\uccb4 \uc2e4\uc801\uacfc \uacf5\uae09 \uc6b0\ub824\uac00 \uacb9\uce58\uba70 \ubc18\ub3c4\uccb4\uc8fc\uac00 \ub3d9\ubc18 \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud004\ucef4\uc740 \uc2e4\uc801\uc774 \uc608\uc0c1\uc744 \uc6c3\ub3cc\uc558\uc9c0\ub9cc 4\ubd84\uae30 \uac00\uc774\ub358\uc2a4\uac00 \uc57d\ud654\ub418\uba70 \uc885\uac00 \uae30\uc900 9.49% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nAMD\ub294 17.26%, \ub9c8\uc774\ud06c\ub860\uc740 17.46%, \ube0c\ub85c\ub4dc\ucef4\uc740 10.43%, \uc5d4\ube44\ub514\uc544\ub294 9.26% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9c8\uc774\ud06c\ub860\uc774 \uc7a5\uae30 \ub178\uc0ac \ubd84\uc7c1\uc744 \uc774\uc720\ub85c \ub300\ub9cc \uba54\ubaa8\ub9ac \uacf5\uc7a5 45\uc5b5 \ub2ec\ub7ec \ud22c\uc790 \uacc4\ud68d\uc744 \uc911\ub2e8\ud588\ub2e4\ub294 \ubcf4\ub3c4\ub3c4 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 \uc7a5\uc911 \ucd5c\ub300 11% \ud558\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\ub3c4 \uc788\uc5b4, \ubc18\ub3c4\uccb4 \uc139\ud130\uc758 \ub099\ud3ed\uc774 2020\ub144 3\uc6d4 \uc774\ud6c4 \uac00\uc7a5 \ucef8\ub2e4\ub294 \ud3c9\uac00\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc790\uccb4\uac00 \uaebe\uc600\ub2e4\ub294 \uc2e0\ud638\ub77c\uae30\ubcf4\ub2e4, \ud22c\uc790 \uc18d\ub3c4\uc640 \uc218\uc775\uc131\uc5d0 \ub300\ud55c \uc7ac\ud3c9\uac00\uac00 \uc9c4\ud589 \uc911\uc774\ub77c\ub294 \uc2e0\ud638\ub85c \ubcf4\ub294 \uac83\uc774 \uc801\uc808\ud569\ub2c8\ub2e4.<br/>\\n\\n\uc14b\uc9f8, \uad6d\uc81c\uc720\uac00\uac00 \ubc18\ub4f1\ud588\uace0 \uace0\uc6a9\uc9c0\ud45c\ub294 \ud638\uc870\ub97c \ubcf4\uc600\uc9c0\ub9cc \uc9c0\uc218 \ud558\ub77d\uc744 \ub9c9\uc9c0\ub294 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0 \uc6d0\uc720\ub294 \ubc30\ub7f4\ub2f9 90.58\ub2ec\ub7ec\ub85c 2.79% \uc62c\ub790\uace0, \ube0c\ub80c\ud2b8\uc720\ub294 \ubc30\ub7f4\ub2f9 98.47\ub2ec\ub7ec\ub85c 4.07% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc720\uc885 \ubaa8\ub450 \uc804\uc77c 8% \uc548\ud30e\uc758 \uae09\ub77d\uc744 \uc77c\ubd80 \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \ub178\ub3d9\ubd80\uac00 \ubc1c\ud45c\ud55c \uc2e0\uaddc \uc2e4\uc5c5\uc218\ub2f9 \uccad\uad6c \uac74\uc218\ub294 18\ub9cc 9\ucc9c \uac74\uc73c\ub85c 7\uc6d4 \uc911\uc21c \uc774\ud6c4 \ucd5c\uc800 \uc218\uc900\uc774\uc5c8\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc5d0\ub108\uc9c0\uc8fc\ub3c4 \uc885\uac00 \uae30\uc900\uc73c\ub85c\ub294 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5d1\uc190\ubaa8\ube4c\uc740 2.35%, \uc170\ube0c\ub860\uc740 1.86% \ud558\ub77d\ud574, \uc720\uac00 \ubc18\ub4f1\uc774 \uc5d0\ub108\uc9c0\uc8fc \ubc29\uc5b4\ub85c \uc774\uc5b4\uc9c0\uc9c0\ub294 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\ub098\uc2a4\ub2e5\uc758 \ub099\ud3ed\uc774 \uac00\uc7a5 \ucef8\ub358 \uac83\uc740 \ubc18\ub3c4\uccb4\uc640 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c\uc8fc\uc758 \ube44\uc911\uc774 \ub192\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc5d4\ube44\ub514\uc544\uc640 \ube0c\ub85c\ub4dc\ucef4, AMD, \ub9c8\uc774\ud06c\ub860\uc774 \ub450 \uc790\ub9bf\uc218\uc5d0 \uac00\uae4c\uc6b4 \ud3ed\uc73c\ub85c \ubc00\ub9ac\uba70 \ub098\uc2a4\ub2e5 \ud558\ub77d\uc744 \uc8fc\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615 \uae30\uc220\uc8fc\ub3c4 \ud568\uaed8 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9c8\uc774\ud06c\ub85c\uc18c\ud504\ud2b8\ub294 3.58%, \uba54\ud0c0\ub294 3.96%, \uc544\ub9c8\uc874\uc740 2.19% \ud558\ub77d\ud588\uace0, \uc560\ud50c\uc740 1.53% \ud558\ub77d\uc73c\ub85c \uc0c1\ub300\uc801\uc73c\ub85c \ub35c \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ub525\uc11c\uce58\ub85c \ud655\uc778\ud55c \uad6d\ub0b4 \uc99d\uad8c\uac00 \ubd84\uc11d\uc5d0\uc11c\ub294 \ube45\ud14c\ud06c\uc758 \ub9c9\ub300\ud55c \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \ud22c\uc790\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \ucee4\uc9c0\ub294 \uac00\uc6b4\ub370 \uc560\ud50c\uc774 \uae30\uc220\uc8fc \ub0b4 \uc548\uc804\uc790\uc0b0\uc73c\ub85c \ud3c9\uac00\ubc1b\uace0 \uc788\ub2e4\ub294 \ubd84\uc11d\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ud14c\uc2ac\ub77c\ub294 10.77%, \uc624\ub77c\ud074\uc740 6.93% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\uc740 \uae30\uc220\uc8fc \ube44\uc911\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub0ae\uc9c0\ub9cc, \ubc18\ub3c4\uccb4\uc640 \ub300\ud615 \uae30\uc220\uc8fc\uc758 \ud558\ub77d\uc774 \ub113\uac8c \ubc88\uc9c0\uba74\uc11c 4.36% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc0b0\uc5c5\uc7ac\uc640 \uac00\uce58\uc8fc\uc640 \uc6b0\ub7c9\uc8fc \ube44\uc911\uc774 \ub192\uc544 \ub099\ud3ed\uc774 3.44%\ub85c \uc0c1\ub300\uc801\uc73c\ub85c \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5d0\ub108\uc9c0 \uc139\ud130\ub294 \uc720\uac00 \ubc18\ub4f1\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \uc8fc\uac00\uac00 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc6d0\uc720 \uac00\uaca9\uacfc \uc5d0\ub108\uc9c0\uc8fc \uc0ac\uc774\uc758 \uc5f0\uacb0\uace0\ub9ac\uac00 \uc774\ub0a0\uc740 \ub04a\uc5b4\uc84c\uace0, \uc2dc\uc7a5 \uc804\ubc18\uc758 \uc704\ud5d8 \ud68c\ud53c \uc2ec\ub9ac\uac00 \uc720\uac00 \ud6a8\uacfc\ub97c \uc6c3\ub3cc\uc558\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc5f0\uacb0\uace0\ub9ac\ub294 \uc815\uce58\uc5d0\uc11c \uc2dc\uc791\ud574 \uaddc\uc81c\uc640 \uc218\uc694 \uc6b0\ub824\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uc6b0\ub824\ub294 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uc18d\ub3c4\uc5d0 \ub300\ud55c \uac00\uc815\uc744 \ubc14\uafb8\uace0, \uc774\ub294 \ubc18\ub3c4\uccb4 \uc218\uc694 \uc804\ub9dd\uacfc \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc73c\ub85c \ud568\uaed8 \ubc88\uc9d1\ub2c8\ub2e4.<br/>\\n\uc815\ub9ac\ud558\uba74 \uc774\ub0a0\uc740 \ud2b9\uc815 \uc139\ud130\ub9cc\uc758 \uc870\uc815\uc774 \uc544\ub2c8\ub77c, \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ub17c\uc7c1\uc774 \uc9c0\uc218 \uc804\ubc18\uc73c\ub85c \ud655\uc0b0\ub41c \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7S&P500 \ub9c8\uac10 \ud750\ub984\\n\\nS&P500\uc740 7,353.73\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 -334.89, \ub4f1\ub77d\ub960\uc740 -4.36%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,688.62\uc785\ub2c8\ub2e4.<br/>\\nYahoo Finance \uc77c\ubd09 \uae30\uc900 S&P500 \ub2f9\uc77c \uace0\uac00\ub294 7,681.29, \ub2f9\uc77c \uc800\uac00\ub294 7,350.35\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 51,523.06\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 -1,833.06, \ub4f1\ub77d\ub960\uc740 -3.44%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\nYahoo Finance \uc77c\ubd09 \uae30\uc900 \ub2e4\uc6b0\uc9c0\uc218 \ub2f9\uc77c \uace0\uac00\ub294 53,710.61, \ub2f9\uc77c \uc800\uac00\ub294 51,486.82\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc0c1\uc2b9\ubd84\uacfc \ube44\uad50\ud558\uba74 \uc138 \uc9c0\uc218 \ubaa8\ub450 \uc0c1\uc2b9\ubd84\uc744 \ucd08\uacfc\ud574 \ubc18\ub0a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc804\uc77c 1,569.40 \uc62c\ub790\ub358 \uac83\ubcf4\ub2e4 263.66 \ub354 \ubc00\ub838\uace0, S&P500\uc740 \uc804\uc77c 119.70 \uc62c\ub790\ub358 \uac83\ubcf4\ub2e4 215.19 \ub354 \ubc00\ub838\uc73c\uba70, \ub098\uc2a4\ub2e5\uc740 \uc804\uc77c 364.50 \uc62c\ub790\ub358 \uac83\ubcf4\ub2e4 1,057.01 \ub354 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc804\uc77c \ub7a0\ub9ac\uac00 \uc548\ub3c4\uc131 \ubc18\ub4f1\uc5d0 \uadf8\ucce4\uace0, \ud558\ub8e8 \ub9cc\uc5d0 \uaddc\uc81c\uc640 \uc218\uc694 \uc6b0\ub824\uac00 \ub2e4\uc2dc \uc6b0\uc138\ud574\uc84c\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \ub2e4\uc74c \uac70\ub798\uc77c \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ud750\ub984 \uc9c0\uc18d\uacfc \uc77c\uc2dc\uc801 \uae09\ub77d\uc744 \uad6c\ubd84\ud558\ub294 \uae30\uc900\uc740 \uc138 \uac00\uc9c0\uc785\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uc800\uac00 24,262.14 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uac04\uc774 \ubb34\ub108\uc9c0\uba74 \uc870\uc815 \uad6c\uac04\uc5d0\uc11c\uc758 \ud558\ub77d\uc774 \uc774\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uc774 25,000 \uad6c\uac04\uacfc \ub2f9\uc77c \uc2dc\uac00 25,558.11 \ubd80\uadfc\uc744 \ud68c\ubcf5\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uac04\uc744 \ud68c\ubcf5\ud558\uc9c0 \ubabb\ud558\uace0 \ub418\ubc00\ub9ac\uba74 \ubc18\ub4f1 \ub3d9\ub825\uc774 \uc57d\ud558\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ubc18\ub3c4\uccb4\uc8fc\uc758 \ub099\ud3ed\uc774 \uc9c4\uc815\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4\uc8fc\uac00 \ucd94\uac00\ub85c \ud06c\uac8c \ubc00\ub9ac\uba74 \uc9c0\uc218 \uc804\ubc18\uc758 \ubcc0\ub3d9\uc131\ub3c4 \uc774\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uac70\ub798\uc77c \uc774\ud6c4 \ud655\uc778\ud560 \uc774\ubca4\ud2b8\ub85c\ub294 11\uc6d4 6\uc77c\ub85c \uc608\uc815\ub41c 10\uc6d4 \uace0\uc6a9\uc9c0\ud45c\uc640 \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4 \uad00\uacc4\uc790 \ubc1c\uc5b8\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\uc9c0\ud45c\uac00 \uc608\uc0c1\uc744 \ud06c\uac8c \ubc97\uc5b4\ub098\uba74 \uae08\ub9ac \uacbd\ub85c\uc5d0 \ub300\ud55c \uac00\uc815\uc774 \ub2e4\uc2dc \ubc14\ub00c\uba74\uc11c \uc9c0\uc218 \ubc29\ud5a5\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc120\ubb3c\uc740 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uae30\uc900 26,679.50\uc73c\ub85c \uc804\uc77c \ub300\ube44 6.61% \ud558\ub77d\ud55c \uc0c1\ud0dc\uc774\uba70, \uc120\ubb3c \uc2dc\uc7a5\uc758 \uc57d\uc138\uac00 \uc774\uc5b4\uc9c0\ub294\uc9c0\ub3c4 \ud655\uc778\ud560 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \ub17c\uc758\uc640 \ubc18\ub3c4\uccb4 \uc218\uc694 \uc804\ub9dd\uc774 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \ubc29\ud5a5\uc774 \uad6c\uccb4\ud654\ub418\uae30 \uc804\uc5d0\ub294 \ud558\ub8e8\uc758 \uae09\ub77d\ub9cc\uc73c\ub85c \ucd94\uc138 \uc804\ud658\uc744 \ub2e8\uc815\ud558\uc9c0 \uc54a\uace0, \uc800\uac00 \uc9c0\uc9c0 \uc5ec\ubd80\uc640 \uc139\ud130 \ud655\uc0b0 \uc5ec\ubd80\ub97c \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0\uc740 \uc804\uc77c \ub7a0\ub9ac\uac00 \ud558\ub8e8 \ub9cc\uc5d0 \ub418\ub3cc\ub824\uc9c4 \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c\uc640 \uc218\uc694 \uc6b0\ub824\uac00 \uac00\ub77c\uc549\ub294\uc9c0, \uace0\uc6a9\uc9c0\ud45c\uac00 \ubc29\ud5a5\uc744 \ubc14\uafb8\ub294\uc9c0\ub97c \ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\uc11c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc21c\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-05-nasdaq-market-midday","metadata":{"permalink":"/blog/en/market/2026-11-05-nasdaq-market-midday","source":"@site/market/2026-11-05-nasdaq-market-midday/index.mdx","title":"\ubbf8\uad6d \uc911\uac04\uc120\uac70 \uc774\ud6c4 AI \uaddc\uc81c \uc6b0\ub824\uc5d0 \ub098\uc2a4\ub2e5 \uc7a5\uc911 5% \uae09\ub77d","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-05T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":7.14,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-05-nasdaq-market-midday","title":"\ubbf8\uad6d \uc911\uac04\uc120\uac70 \uc774\ud6c4 AI \uaddc\uc81c \uc6b0\ub824\uc5d0 \ub098\uc2a4\ub2e5 \uc7a5\uc911 5% \uae09\ub77d","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 11\uc6d4 5\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-05-nasdaq-market-close"},"nextItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uc5d0 3.13% \uae09\ub77d \ucd9c\ubc1c","permalink":"/blog/en/market/2026-11-05-nasdaq-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 5\uc77c \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 \uc7a5\uc911 \ub098\uc2a4\ub2e5 \ud750\ub984\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5\uc911 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc9c0\uc218\ub294 \uc7a5\uc911 5% \ub118\uac8c \ud558\ub77d\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 12\uc2dc 56\ubd84 \uae30\uc900 24,443.71\ub85c, \uc804\uc77c \uc885\uac00 \ub300\ube44 1,292.80\ud3ec\uc778\ud2b8 \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c 3\ub300 \uc9c0\uc218\uac00 \ub3d9\ubc18 \uc0c1\uc2b9 \ub9c8\uac10\ud55c \uc9c0 \ud558\ub8e8 \ub9cc\uc5d0 \ud750\ub984\uc774 \uae09\ubc18\uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\uc758 \uc911\uc2ec\uc5d0\ub294 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uacb0\uacfc \uc774\ud6c4 \ubd88\uac70\uc9c4 \uc778\uacf5\uc9c0\ub2a5 \uc0b0\uc5c5 \uaddc\uc81c \uac15\ud654 \uc6b0\ub824\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uacf5\ud3ec\uc9c0\uc218\ub294 \uc804\uc77c \ub300\ube44 30% \ub118\uac8c \ub6f0\uba70 \ud22c\uc790 \uc2ec\ub9ac\uac00 \ube60\ub974\uac8c \uc704\ucd95\ub41c \ubaa8\uc2b5\uc744 \ubcf4\uc5ec\uc8fc\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 24,443.71 | -1,292.80 | -5.02% | 25,736.51 | 25,559.03 | 24,262.14 |\\n| S&P500 | 7,399.40 | -289.22 | -3.76% | 7,688.62 | 7,681.29 | 7,392.00 |\\n| \ub2e4\uc6b0\uc874\uc2a4 | 51,777.48 | -1,578.64 | -2.96% | 53,356.12 | 53,710.61 | 51,762.78 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 11\uc6d4 5\uc77c 12\uc2dc 56\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 11\uc6d4 6\uc77c 2\uc2dc 56\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc218\uce58\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc640 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \uac00\uaca9 \ud398\uc774\uc9c0](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud588\uc73c\uba70, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uad50\ucc28\uac12\uacfc\ub3c4 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc218\uce58\ub3c4 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \uac00\uaca9 \ud398\uc774\uc9c0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500 \uc218\uce58\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc640 \uc57c\ud6c4 \ud30c\uc774\ub0b8\uc2a4 \uc2dc\uc138\ub85c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 S&P500 \uac00\uaca9 \ud398\uc774\uc9c0\ub294 Npay \uc99d\uad8c \ud648\ud398\uc774\uc9c0\ub85c \ub9ac\ub514\ub809\uc158\ub418\uc5b4 \uc9c1\uc811 \ud655\uc778\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \uac12\uc73c\ub85c, \ub9c8\uac10 \uc804\uae4c\uc9c0 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc7a5\uc911 \uac70\ub798\ub7c9\uc740 990,416\ucc9c\uc8fc\ub85c \uc9d1\uacc4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc774\ubc88 \ud558\ub77d\uc740 \uae08\ub9ac\ub098 \uc2e4\uc801 \uac19\uc740 \uc804\ud1b5\uc801 \uc694\uc778\ubcf4\ub2e4 \uc815\uce58\xb7\uaddc\uc81c \ubcc0\uc218\uac00 \ucd09\ub9e4\uac00 \ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc555\uc2b9\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \ub098\uc628 \ub4a4, \uc778\uacf5\uc9c0\ub2a5 \uc0b0\uc5c5\uc5d0 \ub300\ud55c \uaddc\uc81c \uac15\ud654 \uc6b0\ub824\uac00 \uc2dc\uc7a5\uc744 \ub36e\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc758 \ub2e4\uc218\ub2f9 \uc9c0\uc704\ub97c \ud0c8\ud658\ud588\ub2e4\ub294 \ubcf4\ub3c4\uc640 \ud568\uaed8, \ub370\uc774\ud130\uc13c\ud130\uac00 \ubc00\uc9d1\ud55c \uc9c0\uc5ed\uc758 \uc8fc\uc9c0\uc0ac \uc120\uac70\uc5d0\uc11c\ub3c4 \ubbfc\uc8fc\ub2f9\uc774 \uc2b9\ub9ac\ud588\ub2e4\ub294 \uc18c\uc2dd\uc774 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc5d0\uc11c\ub294 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124\uacfc \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud655\ucda9\uc5d0 \uc81c\ub3d9\uc774 \uac78\ub9b4 \uc218 \uc788\ub2e4\ub294 \ud574\uc11d\uc774 \ud655\uc0b0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uc6b0\ub824\ub294 \ub2e8\uae30 \uc7ac\ub8cc\uac00 \uc544\ub2c8\ub77c \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc0ac\uc774\ud074 \uc804\uccb4\uc758 \uc9c0\uc18d \uac00\ub2a5\uc131\uc744 \ubb3b\ub294 \uc9c8\ubb38\uc73c\ub85c \ubc88\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ube45\ud14c\ud06c \uae30\uc5c5\ub4e4\uc758 \ub9c9\ub300\ud55c \ub370\uc774\ud130\uc13c\ud130 \ud22c\uc790\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \ucee4\uc9c0\ub294 \uac00\uc6b4\ub370, \uae30\uc5c5 \uace0\uac1d\ub4e4\uc758 \uc9c0\ucd9c\uc774 \uacc4\uc18d \ub298\uc5b4\ub098\uc57c \ud22c\uc790\ub97c \uc815\ub2f9\ud654\ud560 \uc218 \uc788\ub2e4\ub294 \uc9c0\uc801\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc5ed\uc0ac\ud68c\uc758 \ub3d9\uc758\uc640 \uc804\ub825 \ube44\uc6a9 \ubd80\ub2f4\uc774 \uc55e\uc73c\ub85c \uc911\uc694\ud55c \ud22c\uc790 \ubcc0\uc218\uac00 \ub420 \uac83\uc774\ub77c\ub294 \ubd84\uc11d\ub3c4 \ud568\uaed8 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \ud750\ub984\uc740 \uc774\ubc88 \ud558\ub77d\uc774 \uae08\ub9ac \uc694\uc778\uc774 \uc544\ub2d8\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d 10\ub144\ubb3c \uad6d\ucc44\uae08\ub9ac\ub294 4.83%\ub85c \uc804\uc77c 4.93%\ubcf4\ub2e4 0.10%\ud3ec\uc778\ud2b8\uac00\ub7c9 \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc548\uc804\uc790\uc0b0 \uc120\ud638\ub85c \uae08\ub9ac\uac00 \ub0b4\ub838\ub294\ub370\ub3c4 \uc8fc\uac00\uac00 \uae09\ub77d\ud588\ub2e4\ub294 \uc810\uc740, \uc774\ubc88 \ub9e4\ub3c4\uac00 \uae08\ub9ac \ubd80\ub2f4\uc774 \uc544\ub2c8\ub77c \uaddc\uc81c\xb7\uc2ec\ub9ac \uc694\uc778\uc5d0\uc11c \ube44\ub86f\ub410\uc74c\uc744 \uc2dc\uc0ac\ud569\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec\uc9c0\uc218\ub294 101.40\uc73c\ub85c \uc804\uc77c 101.75\ubcf4\ub2e4 \uc18c\ud3ed \ub0b4\ub838\uace0, \uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc740 1,353.40\uc6d0\uc73c\ub85c 0.92% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00\ub3c4 \ud558\ub77d \ud750\ub984\uc744 \uc774\uc5b4\uac00\uba70 \uc704\ud5d8\uc790\uc0b0 \uc804\ubc18\uc758 \ud22c\uc790 \uc2ec\ub9ac\uac00 \uc704\ucd95\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c 3\ub300 \uc9c0\uc218\uac00 \ub098\uc2a4\ub2e5 1.44%, S&P500 1.58%, \ub2e4\uc6b0\uc874\uc2a4 3.03% \uc624\ub978 \ub4a4 \ud558\ub8e8 \ub9cc\uc5d0 \uae09\ubc18\uc804\ud588\ub2e4\ub294 \uc810\ub3c4 \ub208\uc5d0 \ub755\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9\ubd84\uc744 \ud558\ub8e8 \ub9cc\uc5d0 \ub418\ub3cc\ub9b0 \uac83\uc740 \ud3ec\uc9c0\uc158 \ub418\ub3cc\ub9bc \uc131\uaca9\uc774 \uac15\ud568\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### 1. \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ubbfc\uc8fc\ub2f9 \uc555\uc2b9\uacfc \uc778\uacf5\uc9c0\ub2a5 \uaddc\uc81c \uc6b0\ub824\\n\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc555\uc2b9\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc7a5\uc911 \ud558\ub77d\uc758 \uc9c1\uc811\uc801\uc778 \uacc4\uae30\uac00 \ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc758 \ub2e4\uc218\ub2f9 \uc9c0\uc704\ub97c \ubaa8\ub450 \ud0c8\ud658\ud588\ub2e4\ub294 \ubcf4\ub3c4\uc640 \ud568\uaed8, \uc8fc\uc694 \uc8fc\uc9c0\uc0ac \uc120\uac70\uc5d0\uc11c\ub3c4 \uc2b9\ub9ac\ud588\ub2e4\ub294 \uc18c\uc2dd\uc774 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc778\uacf5\uc9c0\ub2a5 \uc0b0\uc5c5\uc5d0 \ub300\ud55c \uaddc\uc81c \uac15\ud654 \uac00\ub2a5\uc131\uc5d0 \uc8fc\ubaa9\ud558\ub294 \ubaa8\uc2b5\uc785\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130\uac00 \ubc00\uc9d1\ud55c \ud14d\uc0ac\uc2a4\uc640 \uc870\uc9c0\uc544 \ub4f1\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc2b9\ub9ac\ud558\uba74\uc11c \uaddc\uc81c \uac15\ud654\uc640 \ubc18\ub3c4\uccb4 \uc218\uc694 \uac10\uc18c \uc6b0\ub824\uac00 \uac15\ud574\uc84c\ub2e4\ub294 \ubd84\uc11d\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uc120\uac70 \uacb0\uacfc\uac00 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc0ac\uc774\ud074\uc758 \uc804\uc81c \uc790\uccb4\ub97c \ud754\ub4e4 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uac74\uc124\uc774 \ub2a6\uc5b4\uc9c0\uba74 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud655\ucda9 \uc18d\ub3c4\uac00 \ub5a8\uc5b4\uc9c0\uace0, \ubc18\ub3c4\uccb4\uc640 \uc7a5\ube44 \uc218\uc694 \uc804\ub9dd\ub3c4 \ud568\uaed8 \ub0ae\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uacb0\uacfc\uc758 \uc815\ucc45 \ud568\uc758\uac00 \uc544\uc9c1 \uad6c\uccb4\ud654\ub418\uc9c0 \uc54a\uc740 \ub9cc\ud07c, \ubd88\ud655\uc2e4\uc131 \uc790\uccb4\uac00 \ub9e4\ub3c4 \uc2ec\ub9ac\ub97c \ud0a4\uc6b0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### 2. \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \ud22c\uc790 \uc9c0\uc18d \uac00\ub2a5\uc131 \ub17c\uc7c1 \ud655\uc0b0\\n\\n\ube45\ud14c\ud06c \uae30\uc5c5\ub4e4\uc758 \ub9c9\ub300\ud55c \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \ud22c\uc790\uc5d0 \ub300\ud55c \uc758\ubb38\uc774 \uc7a5\uc911 \ub0b4\ub0b4 \ub9e4\ub3c4\uc138\ub97c \ud0a4\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \uae30\uc5c5\ub4e4\uc774 \ubaa8\ub378 \uac1c\ubc1c\uacfc \uc11c\ube44\uc2a4 \ud655\ub300\ub97c \uc704\ud574 \ub370\uc774\ud130\uc13c\ud130\ub97c \ube60\ub974\uac8c \ud655\ucda9\ud574\uc57c \ud558\uc9c0\ub9cc, \uc9c0\uc5ed\uc0ac\ud68c\uc758 \ub3d9\uc758\uc640 \uc804\ub825 \ube44\uc6a9 \ubd80\ub2f4\uc774 \uc911\uc694\ud55c \ud22c\uc790 \ubcc0\uc218\uac00 \ub420 \uac83\uc774\ub77c\ub294 \ubd84\uc11d\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ud22c\uc790 \ube44\uc6a9\uc744 \uc815\ub2f9\ud654\ud558\ub824\uba74 \uae30\uc5c5 \uace0\uac1d\ub4e4\uc758 \uc9c0\ucd9c\uc774 \uacc4\uc18d \ub298\uc5b4\ub098\uc57c \ud55c\ub2e4\ub294 \uc9c0\uc801\ub3c4 \ud568\uaed8 \uc81c\uae30\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uae30\uc220\uc8fc \uc548\uc5d0\uc11c\ub294 \uc560\ud50c\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \uc120\ubc29\ud558\uba70 \uc548\uc804\uc790\uc0b0 \uc131\uaca9\uc73c\ub85c \ud3c9\uac00\ubc1b\ub294 \ubaa8\uc2b5\ub3c4 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \ud22c\uc790 \uc0ac\uc774\ud074\uc758 \uc18d\ub3c4\uc640 \uaddc\ubaa8\uc5d0 \ub300\ud55c \uc2dc\uc7a5\uc758 \ubbff\uc74c\uc774 \ud754\ub4e4\ub9ac\uace0 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \uc218\uc694\uac00 \uaebe\uc774\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ud22c\uc790 \ud68c\uc218 \uae30\uac04\uc5d0 \ub300\ud55c \uc758\ubb38\uc774 \ucee4\uc84c\ub2e4\ub294 \uc810\uc5d0\uc11c, \uc870\uc815\uc740 \uc2e4\uc801\uc774 \uc544\ub2c8\ub77c \ubc38\ub958\uc5d0\uc774\uc158 \ub17c\uc7c1\uc758 \uc131\uaca9\uc744 \ub760\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc99d\uc2dc\uc5d0\uc11c\ub3c4 \uc0bc\uc131\uc804\uc790\uc640 SK\ud558\uc774\ub2c9\uc2a4\uac00 \uac01\uac01 7.57%\uc640 9.46% \uae09\ub77d\ud558\uba70 \uac19\uc740 \uc6b0\ub824\uac00 \ud655\uc0b0\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### 3. \uc601\ub780\uc740\ud589 \uae30\uc900\uae08\ub9ac \uc778\uc0c1\uacfc \uc720\uac00 \uae09\ub77d\\n\\n\uc601\ub780\uc740\ud589\uc740 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 3.75%\uc5d0\uc11c 4.00%\ub85c 0.25%\ud3ec\uc778\ud2b8 \uc62c\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n2023\ub144 8\uc6d4 \uc774\ud6c4 3\ub144 3\uac1c\uc6d4 \ub9cc\uc758 \uc778\uc0c1\uc774\uba70, \ud1b5\ud654\uc815\ucc45\uc704\uc6d0 9\uba85 \uc804\uc6d0\uc774 \ucc2c\uc131\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc911\ub3d9 \ubd84\uc7c1\uc5d0 \ub530\ub978 \ubb3c\uac00 \uc555\ub825\uc774 \uc778\uc0c1 \ubc30\uacbd\uc73c\ub85c \uc9c0\ubaa9\ub410\uace0, \ucd94\uac00 \uc778\uc0c1 \uac00\ub2a5\uc131\ub3c4 \uc2dc\uc0ac\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138\uacc4 \uc8fc\uc694 \uc911\uc559\uc740\ud589\uc758 \uae34\ucd95 \uae30\uc870\uac00 \uc5ec\uc804\ud788 \uc0b4\uc544\uc788\ub2e4\ub294 \uc2e0\ud638\ub85c \uc77d\ud799\ub2c8\ub2e4.<br/>\\n\uad6d\uc81c\uc720\uac00\ub294 \uc804\uc77c 8% \ub118\uac8c \uae09\ub77d\ud55c \ub370 \uc774\uc5b4 \ub2f9\uc77c\uc5d0\ub3c4 \ud558\ub77d\uc138\ub97c \uc774\uc5b4\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0\uc6d0\uc720\ub294 \uc804\uc77c 8.3% \ub0b4\ub9b0 88.12\ub2ec\ub7ec\uc5d0 \ub9c8\uac10\ud55c \ub4a4 \ub2f9\uc77c 87\ub2ec\ub7ec \uc548\ud30e\uc5d0\uc11c \uac70\ub798\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ube0c\ub80c\ud2b8\uc720\ub3c4 \uc804\uc77c 8.7% \ub0b4\ub9b0 94.62\ub2ec\ub7ec\uc5d0 \ub9c8\uac10\ud55c \ub4a4 93\ub2ec\ub7ec \ud6c4\ubc18\uc5d0\uc11c \uac70\ub798\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc758 \ubc30\uacbd\uc73c\ub85c\ub294 \ubbf8\uad6d\uacfc \uc774\ub780 \uac04 \uc678\uad50\uc801 \ud574\ubc95\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc740 \uc778\ud50c\ub808\uc774\uc158 \uc555\ub825\uc744 \ub0ae\ucd94\ub294 \uc694\uc778\uc778 \ub3d9\uc2dc\uc5d0, \uacbd\uae30 \ub454\ud654 \uc6b0\ub824\uc640 \uc804\uc7c1 \ud504\ub9ac\ubbf8\uc5c4 \uc18c\uba78\uc774 \uacb9\uce5c \uc2e0\ud638\ub85c\ub3c4 \uc77d\ud799\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\ub098\uc2a4\ub2e5\uc774 5.02% \ub0b4\ub9b0 \ubc18\uba74 S&P500\uc740 3.76%, \ub2e4\uc6b0\uc874\uc2a4\ub294 2.96% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc220\uc8fc \ube44\uc911\uc774 \ub192\uc740 \ub098\uc2a4\ub2e5\uc758 \ub099\ud3ed\uc774 \uac00\uc7a5 \ud06c\ub2e4\ub294 \uc810\uc774 \uc774\ubc88 \ud558\ub77d\uc758 \uc131\uaca9\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uc6b0\ub824\uac00 \uc778\uacf5\uc9c0\ub2a5\uacfc \ubc18\ub3c4\uccb4, \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828 \uae30\uc5c5\uc5d0 \uc9c1\uc811 \ub2ff\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uae30\uc220\xb7\ubc18\ub3c4\uccb4 \uc139\ud130\ub294 \uc774\ubc88 \ud558\ub77d\uc758 \uc9c1\uaca9\ud0c4\uc744 \ub9de\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uaddc\uc81c \uc6b0\ub824\ub294 \ubc18\ub3c4\uccb4 \uc218\uc694 \uc804\ub9dd\uc744 \ub0ae\ucd94\uace0, \ud22c\uc790 \ud68c\uc218 \uae30\uac04\uc5d0 \ub300\ud55c \uc758\ubb38\uc740 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc744 \uc555\ubc15\ud569\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\uac00 \ub0b4\ub838\ub294\ub370\ub3c4 \uc131\uc7a5\uc8fc\uac00 \uae09\ub77d\ud588\ub2e4\ub294 \uc810\uc740, \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc774 \uc544\ub2c8\ub77c \uc218\uc694\xb7\uaddc\uc81c \uacbd\ub85c\uac00 \uc791\uc6a9\ud558\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc5d0\ub108\uc9c0 \uc139\ud130\ub294 \uc720\uac00 \uae09\ub77d\uc758 \uc9c1\uc811\uc801\uc778 \uc601\ud5a5\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\uc81c\uc720\uac00\uac00 \uc774\ud2c0 \uc5f0\uc18d \ud070 \ud3ed\uc73c\ub85c \ub0b4\ub9ac\uba74\uc11c \uc5d0\ub108\uc9c0 \uad00\ub828 \uae30\uc5c5\uc758 \uc218\uc775 \uc804\ub9dd\uc774 \ud568\uaed8 \ub0ae\uc544\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc720\uac00 \ud558\ub77d\uc740 \uc5d0\ub108\uc9c0 \ube44\uc6a9\uc744 \ub0ae\ucd94\ub294 \uc694\uc778\uc774\uae30\ub3c4 \ud574\uc11c, \uc81c\uc870\uc5c5\uacfc \uc6b4\uc1a1 \ub4f1 \uc5d0\ub108\uc9c0 \uc18c\ube44 \uc5c5\uc885\uc5d0\ub294 \uc911\ub9bd\uc801\uc778 \uc2e0\ud638\ub85c \uc791\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\uc735 \uc139\ud130\ub294 \uc5c7\uac08\ub9b0 \uc2e0\ud638\ub97c \ubc1b\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc601\ub780\uc740\ud589\uc758 \uae08\ub9ac \uc778\uc0c1\uc740 \uae00\ub85c\ubc8c \uae08\ub9ac \uacbd\ub85c\uc758 \ubd88\ud655\uc2e4\uc131\uc744 \ud0a4\uc6b0\ub294 \uc694\uc778\uc774\uc9c0\ub9cc, \ubbf8\uad6d 10\ub144\ubb3c \uae08\ub9ac \ud558\ub77d\uc740 \uc548\uc804\uc790\uc0b0 \uc120\ud638\ub97c \ubc18\uc601\ud569\ub2c8\ub2e4.<br/>\\n\ubc29\uc5b4\uc8fc\uc640 \ud544\uc218\uc18c\ube44\uc7ac \ub4f1 \uacbd\uae30\ubc29\uc5b4 \uc139\ud130\uc758 \uc0c1\ub300\uc801 \ud750\ub984\uc740 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4\uc758 \ub099\ud3ed\uc774 \uac00\uc7a5 \uc791\uc558\ub2e4\ub294 \uc810\uc740 \uc804\ud1b5 \uc81c\uc870\uc5c5\uacfc \uac00\uce58\uc8fc \uc911\uc2ec \uc9c0\uc218\uc758 \ubc29\uc5b4\uc801 \uc131\uaca9\uc774 \uc77c\ubd80 \uc791\uc6a9\ud588\uc74c\uc744 \uc2dc\uc0ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7S&P500 \ud750\ub984\\n\\n\ub2e4\uc6b0\uc874\uc2a4\ub294 51,777.48\ub85c \uc804\uc77c \ub300\ube44 2.96% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00 53,679.01\ub85c \uc804\uc77c \uc885\uac00\ubcf4\ub2e4 \ub192\uac8c \ucd9c\ubc1c\ud55c \ub4a4 \uc7a5\uc911 \uc800\uac00 51,762.78\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \ucd08\ubc18\uc758 \uc0c1\uc2b9 \uc2dc\ub3c4\uac00 \uc720\uc9c0\ub418\uc9c0 \ubabb\ud558\uace0 \ud558\ub77d\uc73c\ub85c \uc804\ud658\ub41c \ubaa8\uc2b5\uc785\ub2c8\ub2e4.<br/>\\nS&P500\uc740 7,399.40\uc73c\ub85c \uc804\uc77c \ub300\ube44 3.76% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00 7,678.72\ub85c \uc804\uc77c \uc885\uac00\uc5d0 \uadfc\uc811\ud574 \ucd9c\ubc1c\ud588\uc9c0\ub9cc, \uc7a5\uc911 \uc800\uac00 7,392.00\uae4c\uc9c0 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub099\ud3ed\uc774 \uc791\uc9c0\ub9cc, \uc7a5 \ucd08\ubc18 \uc218\uc900\uc744 \uc9c0\ud0a4\uc9c0 \ubabb\ud558\uace0 \ubc00\ub838\ub2e4\ub294 \uc810\uc740 \uacf5\ud1b5\uc801\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4\uc758 \ub099\ud3ed\uc774 \uac00\uc7a5 \uc791\uc558\ub2e4\ub294 \uc810\uc740 \uae30\uc220\uc8fc \uc911\uc2ec\uc758 \ub9e4\ub3c4\uc138\uac00 \uc9c0\uc218\ubcc4\ub85c \ub2e4\ub974\uac8c \uc791\uc6a9\ud588\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uacfc \uc624\ud6c4 \ud750\ub984 \ubcc0\ud654\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc2dc\uac00 25,558.11\ub85c \uc804\uc77c \uc885\uac00\ubcf4\ub2e4 0.69% \ub0ae\uac8c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00 25,559.03\uc740 \uc2dc\uac00\uc640 \uac70\uc758 \uac19\uc544, \uac1c\uc7a5 \uc9c1\ud6c4\ubd80\ud130 \ud558\ub77d \uc77c\ubcc0\ub3c4\uc758 \ud750\ub984\uc774 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc800\uac00 24,262.14\uae4c\uc9c0 \ubc00\ub9b0 \ub4a4 24,400\uc120 \uc548\ud30e\uc5d0\uc11c \uac70\ub798\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uac1c\uc7a5\ubd80\ud130 \uc7a5\uc911 \ud604\uc7ac\uae4c\uc9c0 \ubc29\ud5a5 \uc804\ud658\uc740 \ub098\ud0c0\ub098\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ud55c\ub54c 24,600\uc120 \uc548\ud30e\uc5d0\uc11c \uc18c\ud3ed \uc548\uc815\uc744 \uc2dc\ub3c4\ud588\uc73c\ub098, \ub2e4\uc2dc 24,300\uc120 \uc544\ub798\ub85c \ubc00\ub9ac\ub294 \ub4f1 \ud558\ub77d \uc555\ub825\uc774 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc774 \uc5c6\ub2e4\ub294 \uc810\uc740 \ub9e4\ub3c4\uc138\uac00 \uc77c\uc2dc\uc801\uc778 \ucda9\uaca9\uc774 \uc544\ub2c8\ub77c \uc7a5\uc911 \ub0b4\ub0b4 \uc9c0\uc18d\ub418\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10\uae4c\uc9c0 \uc804\ub9dd\uacfc \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\uc7a5\uc911 \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0, \uc77c\uc2dc\uc801\uc778 \ucda9\uaca9\uc5d0 \uadf8\uce58\ub294\uc9c0\ub97c \uac00\ub974\ub294 \uae30\uc900\uc740 \ub9c8\uac10 \uc885\uac00\uc758 \uc704\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uc800\uac00 24,262.14\ub97c \uc774\ud0c8\ud558\uba74 \ud558\ub77d\uc138\uac00 \ub9c8\uac10\uae4c\uc9c0 \uc774\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c 24,400\uc120\uc744 \uc9c0\ucf1c\ub0b4\uace0 25,000\uc120 \ubc29\ud5a5\uc73c\ub85c \ud68c\ubcf5\ud558\uba74 \uc800\uac00 \ub9e4\uc218 \uc720\uc785\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4\uc640 S&P500\uc758 \ub9c8\uac10 \ub4f1\ub77d\ub960\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\ub9cc \ub099\ud3ed\uc774 \ud070 \ud750\ub984\uc774 \uc720\uc9c0\ub418\uba74 \uae30\uc220\xb7\uc131\uc7a5\uc8fc \uc911\uc2ec\uc758 \uc870\uc815\uc73c\ub85c, \uc138 \uc9c0\uc218\uc758 \ub099\ud3ed\uc774 \ube44\uc2b7\ud574\uc9c0\uba74 \uc2dc\uc7a5 \uc804\ubc18\uc758 \uc704\ud5d8 \ud68c\ud53c\ub85c \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d 10\ub144\ubb3c \uad6d\ucc44\uae08\ub9ac\uc758 \ub9c8\uac10 \uc218\uc900\ub3c4 \ud655\uc778\ud560 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\uac00 \ucd94\uac00\ub85c \ub0b4\ub9ac\uba74 \uc548\uc804\uc790\uc0b0 \uc120\ud638\uac00 \uc774\uc5b4\uc9c0\uace0 \uc788\ub2e4\ub294 \uc2e0\ud638\ub85c, \uae08\ub9ac\uac00 \ubc18\ub4f1\ud558\uba74 \uc704\ud5d8 \ud68c\ud53c \uc2ec\ub9ac\uac00 \uc9c4\uc815\ub418\uace0 \uc788\ub2e4\ub294 \uc2e0\ud638\ub85c \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\uc81c\uc720\uac00\uc758 \ub9c8\uac10\uac00\ub3c4 \ud655\uc778\ud560 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0\uc6d0\uc720\uac00 87\ub2ec\ub7ec \uc120\uc744 \uc9c0\ud0a4\ub294\uc9c0, \ucd94\uac00 \ud558\ub77d\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc5d0\ub108\uc9c0 \uc139\ud130\uc640 \uc778\ud50c\ub808\uc774\uc158 \uc804\ub9dd\uc774 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4.<br/>\\n\uacf5\ud3ec\uc9c0\uc218\ub294 26.14\ub85c \uc804\uc77c 19.42\ubcf4\ub2e4 \ud06c\uac8c \uc62c\ub790\uace0 \uc7a5\uc911 \uace0\uac00\ub294 28.09\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uacf5\ud3ec\uc9c0\uc218\uac00 \ub9c8\uac10\uae4c\uc9c0 \ub192\uc740 \uc218\uc900\uc744 \uc720\uc9c0\ud558\uba74 \ud22c\uc790 \uc2ec\ub9ac\uc758 \ud68c\ubcf5\uc774 \ub354\ub51c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uacb0\uacfc\uc758 \uc815\ucc45 \ud568\uc758\ub294 \uc544\uc9c1 \uad6c\uccb4\ud654\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uad00\ub828 \ubc1c\uc5b8\uc774\ub098 \uc8fc \uc815\ubd80 \ucc28\uc6d0\uc758 \uc6c0\uc9c1\uc784\uc774 \ucd94\uac00\ub85c \uc804\ud574\uc9c0\uba74 \uae30\uc220\uc8fc \ubcc0\ub3d9\uc131\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc120\uac70 \uacb0\uacfc\uc758 \uc815\ucc45 \uc601\ud5a5\uc774 \uacfc\ub3c4\ud558\uac8c \ubc18\uc601\ub410\ub2e4\ub294 \uc778\uc2dd\uc774 \ud655\uc0b0\ub418\uba74 \uc800\uac00 \ub9e4\uc218 \uc720\uc785 \uac00\ub2a5\uc131\ub3c4 \uc5f4\ub824 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc911\uac04\uc120\uac70 \uc774\ud6c4 \uc778\uacf5\uc9c0\ub2a5 \uaddc\uc81c \uc6b0\ub824\ub97c \ucd09\ub9e4\ub85c \uc7a5\uc911 5% \ub118\uac8c \ud558\ub77d\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9c8\uac10\uae4c\uc9c0\ub294 \uc7a5\uc911 \uc800\uac00 \uc774\ud0c8 \uc5ec\ubd80\uc640 10\ub144\ubb3c \uae08\ub9ac, \uc720\uac00 \ub9c8\uac10 \uc218\uc900\uc744 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>"},{"id":"2026-11-05-nasdaq-market-open","metadata":{"permalink":"/blog/en/market/2026-11-05-nasdaq-market-open","source":"@site/market/2026-11-05-nasdaq-market-open/index.mdx","title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uc5d0 3.13% \uae09\ub77d \ucd9c\ubc1c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-05T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":7.81,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-05-nasdaq-market-open","title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uc5d0 3.13% \uae09\ub77d \ucd9c\ubc1c","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"\ubbf8\uad6d \uc911\uac04\uc120\uac70 \uc774\ud6c4 AI \uaddc\uc81c \uc6b0\ub824\uc5d0 \ub098\uc2a4\ub2e5 \uc7a5\uc911 5% \uae09\ub77d","permalink":"/blog/en/market/2026-11-05-nasdaq-market-midday"},"nextItem":{"title":"2026\ub144 11\uc6d4 4\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-04-domestic-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 5\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uac1c\uc7a5 \ubc30\uacbd\\n\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 3\ub300 \uc9c0\uc218\uac00 \ud568\uaed8 \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 4\uc77c \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,736.51\ub85c \uc804\uc77c \ub300\ube44 1.44% \uc0c1\uc2b9\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,688.62\ub85c 1.58% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 53,356.12\ub85c 3.03% \uc0c1\uc2b9\ud574 \uc138 \uc9c0\uc218 \uac00\uc6b4\ub370 \uc0c1\uc2b9\ub960\uc774 \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c\uc5d0\ub294 \ub098\uc2a4\ub2e5\uc774 \uc624\ub974\uace0 \ub2e4\uc6b0\uac00 \ub0b4\ub838\ub358 \uac83\uacfc \ub2ec\ub9ac, 11\uc6d4 4\uc77c\uc5d0\ub294 \uc138 \uc9c0\uc218\uac00 \ud568\uaed8 \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9\uc758 \ud45c\uba74\uc801 \uc774\uc720\ub294 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uacb0\uacfc \ud655\uc815 \uc774\ud6c4\uc758 \uc548\ub3c4\uac10\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud558\uba74\uc11c, \ubd84\uc810 \uc815\ubd80\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \ubd88\ud655\uc2e4\uc131 \ud504\ub9ac\ubbf8\uc5c4\uc744 \ub0ae\ucdc4\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc7a5 \ub9c8\uac10 \uc774\ud6c4\ubd80\ud130 \ubc24\uc0ac\uc774 \ud574\uc11d\uc774 \ub4a4\uc9d1\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uac15\ud654 \uc6b0\ub824\uac00 \ubd80\uac01\ub418\uba74\uc11c, 11\uc6d4 5\uc77c \uc7a5 \uc624\ud508\uc740 \uae09\ub77d \ucd9c\ubc1c\uc774 \ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 24,931.07 | -805.45 | -3.13% | 25,736.51 | 25,559.03 | 24,891.08 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-05 10:03, \ud55c\uad6d\uc2dc\uac04 2026-11-06 00:03 |\\n| \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 | 7,562.89 | -125.73 | -1.64% | 7,688.62 | 7,645.47 | 7,562.89 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-05 10:00\uacbd, \ud55c\uad6d\uc2dc\uac04 2026-11-06 00:00\uacbd |\\n| \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | 53,356.12 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-05 10:00\uacbd, \ud55c\uad6d\uc2dc\uac04 2026-11-06 00:00\uacbd |\\n\\n\ub2f9\uc77c \uc218\uce58\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc758 \uc2dc\uac00\ub294 25,558.11\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\uc640 \ube44\uad50\ud558\uba74 \uc2dc\uac00 \uae30\uc900\uc73c\ub85c\ub294 0.69% \ud558\ub77d \ucd9c\ubc1c\ud588\uace0, \uc774\ud6c4 \ub099\ud3ed\uc774 3.13%\uae4c\uc9c0 \ud655\ub300\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uac12\uc740 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uacfc [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569 \uac00\uaca9](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uacfc \uad50\ucc28 \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 10\uc2dc\uacbd 24,968.18\ub85c \uc804\uc77c \ub300\ube44 768.33\ud3ec\uc778\ud2b8, 2.99% \ud558\ub77d\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,562.89\ub85c 1.64% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uac12\uacfc \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uac12\uc758 \ucc28\uc774\ub294 \uc870\ud68c \uc2dc\uc810 \ucc28\uc774 \ubc94\uc704 \uc548\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\uc758 \uc7a5\uc911 \uace0\uac00\uc640 \uc800\uac00\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ucc28\ud2b8 \ubc30\uc5f4\uc758 \ucd5c\ub300\uac12\uacfc \ucd5c\uc18c\uac12\uc73c\ub85c \uc0b0\ucd9c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0 \ub2e4\uc6b0 \ud56d\ubaa9\uc774 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc544 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8\uc640 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uac12\uc73c\ub85c \uad50\ucc28 \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\ud45c\uba74\uc801\uc73c\ub85c\ub294 \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \ub300\ube44 3.13% \uae09\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadfc\ubcf8 \ucd09\ub9e4\ub294 \uc120\uac70 \uacb0\uacfc\uc5d0 \ub300\ud55c \ud574\uc11d\uc758 \ubc18\uc804\uc785\ub2c8\ub2e4.<br/>\\n11\uc6d4 4\uc77c \uc7a5 \ub9c8\uac10 \ubb34\ub835\uc5d0\ub294 \ubbfc\uc8fc\ub2f9\uc758 \uc591\uc6d0 \uc7a5\uc545\uc774 \uc815\ucc45 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c\ub85c \uc77d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \ubc24\uc0ac\uc774\uc5d0\ub294 \uac19\uc740 \uacb0\uacfc\uac00 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uac15\ud654\ub77c\ub294 \ubc29\ud5a5\uc73c\ub85c \ub2e4\uc2dc \uc77d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud655\uc7a5\uc5d0 \uc81c\ub3d9\uc774 \uac78\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc6b0\ub824\uac00, \uae30\uc220\uc8fc \uc911\uc2ec\uc758 \ub9e4\ub3c4\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc7a5\uc5d0\uc11c\ub3c4 \uade0\uc5f4\uc740 \uc774\ubbf8 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 11\uc6d4 4\uc77c \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 3.13% \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 1.44% \uc624\ub974\ub358 \uac19\uc740 \ub0a0, \ubc18\ub3c4\uccb4\ub294 \uc815\ubc18\ub300\ub85c \uc6c0\uc9c1\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uad11\ubc94\uc704\ud55c \uc9c0\uc218 \uc0c1\uc2b9 \uc18d\uc5d0 \ubc18\ub3c4\uccb4\ub9cc \ube60\uc84c\ub2e4\ub294 \uc810\uc740, \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790\uc5d0 \ub300\ud55c \uc758\uad6c\uc2ec\uc774 \uc7a5 \ub9c8\uac10 \uc804\ubd80\ud130 \ucee4\uc9c0\uace0 \uc788\uc5c8\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804\uc5d0\ub294 \uac1c\ubcc4 \uc7ac\ub8cc\ub3c4 \ub9e4\ub3c4 \ucabd\uc5d0 \ud798\uc744 \ubcf4\ud0f0\uc2b5\ub2c8\ub2e4.<br/>\\n\ud004\ucef4\uc774 \uc2e4\ub9dd\uc2a4\ub7ec\uc6b4 \uac00\uc774\ub358\uc2a4\uc5d0 \uac1c\uc7a5 \uc804 \uae09\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc601\ub780\uc740\ud589\uc774 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 4%\ub85c \uc778\uc0c1\ud55c \uac83\ub3c4 \ubc24\uc0ac\uc774 \ud655\uc778\ub41c \uac70\uc2dc \uc7ac\ub8cc\uc785\ub2c8\ub2e4.<br/>\\n3\ub144 3\uac1c\uc6d4 \ub9cc\uc758 \uc778\uc0c1\uc73c\ub85c, \uae00\ub85c\ubc8c \uae08\ub9ac \uc778\ud558 \uae30\ub300\uc640\ub294 \uacb0\uc774 \ub2e4\ub978 \uc2e0\ud638\uc785\ub2c8\ub2e4.<br/>\\n\uad50\ucc28 \uc790\uc0b0 \ud750\ub984\ub3c4 \uc704\ud5d8 \ud68c\ud53c \ucabd\uc744 \uac00\ub9ac\ud0b5\ub2c8\ub2e4.<br/>\\n\uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc740 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 1,349.2\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.61% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uac15\uc138\uc640 \uc6d0\ud654 \uc57d\uc138\ub294 \uc704\ud5d8\uc790\uc0b0\uc5d0\uc11c \uc790\uae08\uc774 \ube60\uc838\ub098\uac00\ub294 \ud750\ub984\uacfc \uac19\uc740 \ubc29\ud5a5\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c\uc5d0\ub294 \uad6d\uc81c\uc720\uac00\ub3c4 \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ube0c\ub80c\ud2b8\uc720\ub294 \ubc30\ub7f4\ub2f9 94.62\ub2ec\ub7ec\ub85c 8.7% \ud558\ub77d\ud588\uace0, \uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0 \uc6d0\uc720\ub294 \ubc30\ub7f4\ub2f9 88.12\ub2ec\ub7ec\ub85c 8.3% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc740 \ube44\uc6a9 \ubd80\ub2f4\uc744 \ub35c\uc5b4\uc8fc\ub294 \uc694\uc778\uc774\uc9c0\ub9cc, \uc218\uc694 \ub454\ud654 \uc2e0\ud638\ub85c \uc77d\ud790 \uc5ec\uc9c0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d 10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uacfc \uae08\uac12\uc758 \ub2f9\uc77c \uc218\uce58\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc73c\ubbc0\ub85c, \uae08\ub9ac\uc640 \uc548\uc804\uc790\uc0b0 \uacbd\ub85c\uc5d0 \ub300\ud55c \ucd5c\uc885 \ud310\ub2e8\uc740 \ud655\uc778 \ud544\uc694\ub85c \ub0a8\uaca8\ub461\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uac04 \ubc29\ud5a5 \ucc28\uc774\ub3c4 \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 3.13% \ub0b4\ub9b0 \ubc18\uba74 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 1.64% \ub0b4\ub9ac\ub294 \ub370 \uadf8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ub9e4\ub3c4\uac00 \uc2dc\uc7a5 \uc804\ubc18\uc774 \uc544\ub2c8\ub77c \uae30\uc220\uc8fc\uc640 \ubc18\ub3c4\uccb4\uc5d0 \uc9d1\uc911\ub418\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub2e4\uc6b0\uac00 3.03% \uc624\ub974\uba70 \uc0c1\uc2b9\uc744 \uc8fc\ub3c4\ud588\ub358 \uac83\uacfc \ub300\ube44\ub418\ub294, \uae30\uc220\uc8fc \uc911\uc2ec\uc758 \ub418\ub3cc\ub9bc\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ud558\ub8e8\uc758 \uae09\ub77d\ub9cc\uc73c\ub85c \ucd94\uc138 \uc804\ud658\uc744 \ud655\uc815\ud560 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uc6b0\ub824\uac00 \uc2e4\uc81c \ubc95\uc548\uacfc \uc815\ucc45 \ubcc0\ud654\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0\ub294 \uc55e\uc73c\ub85c \ud655\uc778\ud560 \uc0ac\uc548\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### \uccab\uc9f8, \ubbfc\uc8fc\ub2f9\uc758 \uc591\uc6d0 \uc7a5\uc545\uacfc \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uc785\ub2c8\ub2e4\\n\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0\uc11c\ub294 \uc774\ub97c \ube14\ub8e8 \uc4f0\ub098\ubbf8\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc774 \uc8fc\ubaa9\ud55c \uac83\uc740 \uc758\uc11d \uc790\uccb4\ubcf4\ub2e4 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uac15\ud654 \uac00\ub2a5\uc131\uc785\ub2c8\ub2e4.<br/>\\n\uc99d\uad8c\uac00\uc5d0\uc11c\ub294 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uaddc\uc81c \ub9ac\uc2a4\ud06c\uac00 \ud22c\uc790\uc2ec\ub9ac\uc5d0 \ubd80\ub2f4\uc744 \uc904 \uac83\uc774\ub77c\ub294 \uad00\uce21\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub370\uc77c\ub9ac 11\uc6d4 6\uc77c\uc790 \uc2e0\ubb38 \uc608\uace0\uc5d0\uc11c\ub294 \ubbf8\uad6d \ub370\uc774\ud130\uc13c\ud130 \uc808\ubc18\uc5d0 \uc81c\ub3d9\uc774 \uac78\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc81c\ubaa9\uc73c\ub85c \uc774 \uc6b0\ub824\ub97c \ub2e4\ub918\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uad6c\uccb4\uc801\uc778 \ubc95\uc548\uc774\ub098 \uaddc\uc81c\uc548\uc774 \ud655\uc815\ub41c \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc6b0\ub824\uac00 \uc815\ucc45\uc73c\ub85c \uad73\uc5b4\uc9c0\ub294\uc9c0, \uc544\ub2c8\uba74 \ub2e8\uae30 \uc2ec\ub9ac\uc5d0 \uadf8\uce58\ub294\uc9c0\uac00 \uc55e\uc73c\ub85c\uc758 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ub17c\uc7c1\uc758 \uc911\uc2ec\uc5d0 \ub370\uc774\ud130\uc13c\ud130\uac00 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uc18d\ub3c4\uac00 \ub2a6\uc5b4\uc9c0\uba74 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \uaddc\ubaa8 \uc790\uccb4\uc5d0 \ub300\ud55c \uc758\ubb38\uc774 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ubc38\ub958\uc5d0\uc774\uc158 \ub17c\uc7c1\uc744 \ub118\uc5b4, \uc218\uc694 \uc804\ub9dd \uc790\uccb4\ub97c \ud754\ub4dc\ub294 \uc7ac\ub8cc\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ub458\uc9f8, \uc544\uc2dc\uc544 \uc99d\uc2dc\uc758 \uae09\ub77d\uacfc \uc678\uad6d\uc778 \ud22c\ub9e4\uc785\ub2c8\ub2e4\\n\\n11\uc6d4 5\uc77c \uad6d\ub0b4 \uc99d\uc2dc\ub294 5% \ub118\uac8c \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804 \uac70\ub798\uc77c \ub300\ube44 300.00\ud3ec\uc778\ud2b8, 5.28% \ub0b4\ub9b0 5,383.80\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 36.54\ud3ec\uc778\ud2b8, 5.11% \ub0b4\ub9b0 678.41\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \ub098\ub780\ud788 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc740 3.4\uc870 \uc6d0\ub300\ub97c \uc21c\ub9e4\ub3c4\ud588\uace0, \uc0bc\uc131\uc804\uc790\uc640 SK\ud558\uc774\ub2c9\uc2a4\ub294 \uac01\uac01 7.57%\uc640 9.46% \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nSK\uadf8\ub8f9 \ucd5c\ud0dc\uc6d0 \ud68c\uc7a5\uc740 \uc911\uac04\uc120\uac70 \uacb0\uacfc\uac00 \ubc18\ub3c4\uccb4\uc5d0 \uc88b\uc9c0 \uc54a\ub2e4\uace0 \uc2dc\uc7a5\uc774 \ud3c9\uac00\ud55c \uac83 \uac19\ub2e4\uace0 \uc5b8\uae09\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5 \ubcc0\ub3d9\uc131\uc774 \uc55e\uc73c\ub85c\ub3c4 \ubc18\ubcf5\ub420 \uc218 \uc788\ub2e4\ub294 \uacbd\uace0\ub3c4 \ud568\uaed8 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \ubbf8\uad6d \uc7a5 \uc624\ud508 \uc804\uc5d0 \uc774\ubbf8 \ud55c \ucc28\ub840 \ub9e4\ub3c4\uac00 \uc18c\ud654\ub410\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc544\uc2dc\uc544\uc758 \uae09\ub77d\uc740 \ubbf8\uad6d \ud22c\uc790\uc790\uc5d0\uac8c\ub3c4 \uac19\uc740 \uc6b0\ub824\uac00 \uc804\uc774\ub418\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc7a5\uc774 \uc544\uc2dc\uc544\uc640 \uac19\uc740 \ubc29\ud5a5\uc73c\ub85c \ucd9c\ubc1c\ud55c \uac83\uc740, \uc6b0\ub824\uac00 \uc9c0\uc5ed\uc744 \ub118\uc5b4 \ud655\uc0b0\ub418\uace0 \uc788\ub2e4\ub294 \uc2e0\ud638\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uc14b\uc9f8, \uc601\ub780\uc740\ud589 \uae08\ub9ac \uc778\uc0c1\uacfc \uac1c\uc7a5 \uc804 \uac1c\ubcc4 \uc7ac\ub8cc\uc785\ub2c8\ub2e4\\n\\n\uc601\ub780\uc740\ud589\uc740 \uae30\uc900\uae08\ub9ac\ub97c \uc5f0 4%\ub85c \uc778\uc0c1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n3\ub144 3\uac1c\uc6d4 \ub9cc\uc758 \uc778\uc0c1\uc785\ub2c8\ub2e4.<br/>\\n\uc8fc\uc694\uad6d \uc911\uc559\uc740\ud589\uc758 \uae08\ub9ac \uc778\ud558 \uae30\ub300\uac00 \uc6b0\uc138\ud558\ub358 \ud750\ub984\uacfc\ub294 \ub2e4\ub978 \ubc29\ud5a5\uc758 \uacb0\uc815\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uc778\uc0c1 \uc790\uccb4\uac00 \ubbf8\uad6d \uc99d\uc2dc\uc758 \uc9c1\uc811 \uc7ac\ub8cc\ub294 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uae00\ub85c\ubc8c \uc720\ub3d9\uc131 \ud658\uacbd\uc5d0 \ub300\ud55c \uae30\ub300\ub97c \ub418\ub3cc\uc544\ubcf4\uac8c \ub9cc\ub4dc\ub294 \uc2e0\ud638\ub85c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804\uc5d0\ub294 \ud004\ucef4\uc774 \uc2e4\ub9dd\uc2a4\ub7ec\uc6b4 \uac00\uc774\ub358\uc2a4\uc5d0 \uae09\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \uc218\uc694 \uc99d\uac70\uc640 \uacf5\uae09 \uc6b0\ub824\uac00 \ucda9\ub3cc\ud558\ub294 \uad6c\uac04\uc5d0\uc11c\ub294, \uac1c\ubcc4 \uae30\uc5c5\uc758 \uac00\uc774\ub358\uc2a4 \ud558\ub098\ub3c4 \uc139\ud130 \uc2ec\ub9ac\ub97c \uc88c\uc6b0\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \ub450 \uc7ac\ub8cc\ub294 \uaddc\ubaa8\ub294 \ub2e4\ub974\uc9c0\ub9cc \uac19\uc740 \ubc29\ud5a5\uc744 \uac00\ub9ac\ud0b5\ub2c8\ub2e4.<br/>\\n\ub099\uad00\uc801\uc778 \uc804\ub9dd\uc744 \ub418\ub3cc\uc544\ubcf4\uac8c \ub9cc\ub4dc\ub294 \uc7ac\ub8cc\uac00 \ubc24\uc0ac\uc774\uc5d0 \uc313\uc600\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\uaddc\uc81c\uc5d0\uc11c \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\uac00 \uba3c\uc800 \uc791\ub3d9\ud569\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uaddc\uc81c \uc6b0\ub824\ub294 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud655\uc7a5\uc758 \uc18d\ub3c4\ub97c \ub2a6\ucd9c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ubc18\ub3c4\uccb4\uc640 \uba54\ubaa8\ub9ac \uc218\uc694 \uc804\ub9dd\uc5d0 \uc9c1\uc811\uc801\uc778 \ubd80\ub2f4\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n11\uc6d4 4\uc77c \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\uac00 3.13% \uae09\ub77d\ud55c \uac83\uc774\ub098, 11\uc6d4 5\uc77c \uad6d\ub0b4 \ubc18\ub3c4\uccb4 \ub300\ud615\uc8fc\uac00 7% \ub118\uac8c \uae09\ub77d\ud55c \uac83\uc774 \uac19\uc740 \uc5f0\uacb0\uace0\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4\uc5d0\uc11c \ud558\ub4dc\uc6e8\uc5b4\uc640 \uc804\ub825\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub3c4 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uac74\uc124\uc774 \ub2a6\uc5b4\uc9c0\uba74 \ub0c9\uac01\uacfc \uc804\ub825\uae30\uae30, \uc11c\ubc84\uc6a9 \ubd80\ud488 \uc218\uc694\uc5d0\ub3c4 \uc18d\ub3c4 \uc870\uc808 \uc555\ub825\uc774 \uc0dd\uae41\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc778\uacf5\uc9c0\ub2a5 \uc804\ub825\ub9dd \ube44\uc6a9\uc744 \ube45\ud14c\ud06c\uac00 \ub354 \ubd80\ub2f4\ud574\uc57c \ud55c\ub2e4\ub294 \uc555\ubc15\uc774 \ucee4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uad00\uce21\ub3c4 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ube45\ud14c\ud06c\uc758 \ube44\uc6a9 \uad6c\uc870\uc5d0 \ub300\ud55c \uc0c8\ub85c\uc6b4 \ubcc0\uc218\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac\uc5d0\uc11c \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub294 \uc544\uc9c1 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc601\ub780\uc740\ud589\uc758 \uae08\ub9ac \uc778\uc0c1\uc740 \uae08\ub9ac \uc778\ud558 \uae30\ub300\ub97c \ub418\ub3cc\uc544\ubcf4\uac8c \ud558\uc9c0\ub9cc, \ubbf8\uad6d 10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc758 \ub2f9\uc77c \uc218\uce58\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uac15\uc138\ub294 \uc131\uc7a5\uc8fc\uc5d0 \uc6b0\ud638\uc801\uc774\uc9c0 \uc54a\uc740 \ud658\uacbd\uc785\ub2c8\ub2e4.<br/>\\n\uc6d0\xb7\ub2ec\ub7ec \ud658\uc728 \uc0c1\uc2b9\uacfc \uc678\uad6d\uc778 \ub9e4\ub3c4\ub294 \uac19\uc740 \ubc29\ud5a5\uc758 \uc790\uae08 \ud750\ub984\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc720\uac00\uc5d0\uc11c \uc5d0\ub108\uc9c0\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub294 \uc591\uba74\uc801\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc720\uac00 \ud558\ub77d\uc740 \uc5d0\ub108\uc9c0\uc8fc\uc758 \ub9e4\ucd9c \uc804\ub9dd\uc5d0\ub294 \ubd80\ub2f4\uc774\uc9c0\ub9cc, \ubb3c\uac00\uc640 \ube44\uc6a9 \ubd80\ub2f4\uc744 \ub35c\uc5b4\uc8fc\ub294 \uc694\uc778\uc785\ub2c8\ub2e4.<br/>\\n\uc5b4\ub290 \ucabd \ud574\uc11d\uc774 \uc6b0\uc704\ub97c \uc810\ud558\ub294\uc9c0\ub294 \ub2f9\uc77c \uc5d0\ub108\uc9c0 \uc139\ud130\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\ud61c\uc640 \ud0c0\uaca9\uc744 \ub2e8\uc21c\ud788 \ub098\ub204\uae30\ubcf4\ub2e4, \uac19\uc740 \uc120\uac70 \uacb0\uacfc\uac00 \uc139\ud130\ub9c8\ub2e4 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud55c\ub2e4\ub294 \uc810\uc774 \uc774\ubc88 \uc7a5\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc 11\uc6d4 5\uc77c \uc7a5 \ucd08\ubc18\uc5d0\ub294 \ud0c0\uaca9 \ucabd \ud574\uc11d\uc774 \uc6b0\uc704\ub97c \uc810\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \ud750\ub984\\n\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 11\uc6d4 4\uc77c 7,688.62\ub85c 1.58% \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 5\uc77c \uc7a5 \uc624\ud508 \ubb34\ub835\uc5d0\ub294 7,562.89\ub85c 1.64% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \ud558\ub77d\ub960 3.13%\uc758 \uc808\ubc18 \uc218\uc900\uc73c\ub85c, \ub099\ud3ed\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \uc791\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ub9e4\ub3c4\uac00 \uae30\uc220\uc8fc\uc5d0 \uc9d1\uc911\ub418\uace0, \uc2dc\uc7a5 \uc804\ubc18\uc73c\ub85c \uace0\ub974\uac8c \ud655\uc0b0\ub418\uc9c0\ub294 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 11\uc6d4 4\uc77c 53,356.12\ub85c 3.03% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138 \uc9c0\uc218 \uac00\uc6b4\ub370 \uc0c1\uc2b9\ub960\uc774 \uac00\uc7a5 \ucef8\uace0, \uac00\uce58\uc8fc\uc640 \uc0b0\uc5c5\uc8fc\uac00 \uc0c1\uc2b9\uc744 \uc8fc\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 5\uc77c \uc7a5\uc911 \uc218\uce58\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0 \ub2e4\uc6b0 \ud56d\ubaa9\uc774 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc544 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub2e4\uc6b0\uac00 \uac00\uc7a5 \uac15\ud588\ub358 \ub9cc\ud07c, \ub2f9\uc77c \ub2e4\uc6b0\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc740\uc9c0\uac00 \ud655\uc778\ud560 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ud750\ub984 \uc9c0\uc18d\uacfc \uc77c\uc2dc\uc801 \ub178\uc774\uc988\ub97c \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \uc6b0\ub824\uac00 \uc2e4\uc81c \uc815\ucc45\uc73c\ub85c \uc774\uc5b4\uc9c0\uba74 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \ub17c\uc7c1\uc740 \uc911\uae30 \uc7ac\ub8cc\uac00 \ub429\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc6b0\ub824\uac00 \uc2ec\ub9ac\uc5d0 \uadf8\uce58\uba74, \uae09\ub77d \uc774\ud6c4 \ub418\ub3cc\ub9bc\uc774 \ub098\uc62c \uc5ec\uc9c0\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\uc5d0 \ud655\uc778\ud560 \uc218\uce58\ub294 \uc804\uc77c \uc885\uac00\uc640 \uc7a5\uc911 \uc800\uac00\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 \uc804\uc77c \uc885\uac00 25,736.51\uc744 \uc774\ubbf8 \ubc11\ub3cc\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc800\uac00 24,891.08\uc744 \uc9c0\ucf1c\ub0b4\ub294\uc9c0, \uc544\ub2c8\uba74 \ub354 \ubc11\uc73c\ub85c \ubc00\ub9ac\ub294\uc9c0\uac00 \ub2e8\uae30 \ubc29\ud5a5\uc744 \uac00\ub985\ub2c8\ub2e4.<br/>\\n\uc2ec\ub9ac\uc801 \uc9c0\uc9c0\uc120\uc73c\ub85c\ub294 25,000\uc120\uc774 \uc788\uc73c\uba70, \uc2a4\ub0c5\uc0f7 \uae30\uc900\uc73c\ub85c\ub294 \uc774\ubbf8 \ubc11\uc73c\ub85c \ub0b4\ub824\uac04 \uc0c1\ud0dc\uc785\ub2c8\ub2e4.<br/>\\n\ub418\ub3cc\ub9bc\uc774 \ub098\uc628\ub2e4\uba74 \uc804 \uac70\ub798\uc77c \uc885\uac00 25,372.01 \ud68c\ubcf5 \uc5ec\ubd80\uac00 \uccab \ubc88\uc9f8 \ud655\uc778 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc139\ud130 \ub2e8\uc704\uc5d0\uc11c\ub294 \ubc18\ub3c4\uccb4\uc9c0\uc218\uc758 \uc6c0\uc9c1\uc784\uc774 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c 3.13% \uae09\ub77d\ud55c \ubc18\ub3c4\uccb4\uac00 \ub2f9\uc77c \ub099\ud3ed\uc744 \ub354 \ud0a4\uc6b0\ub294\uc9c0, \uc544\ub2c8\uba74 \uc800\uac00 \ub9e4\uc218\ub85c \ub418\ub3cc\ub9ac\ub294\uc9c0\uac00 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec\uc640 \uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc758 \uc6c0\uc9c1\uc784\ub3c4 \ud568\uaed8 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uac15\uc138\uac00 \uc774\uc5b4\uc9c0\uba74 \uc678\uad6d\uc778 \uc790\uae08 \uc774\ud0c8 \uc555\ub825\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 \ubbfc\uc8fc\ub2f9\uc758 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uad00\ub828 \uc785\ubc95 \uc6c0\uc9c1\uc784\uacfc \ube45\ud14c\ud06c\uc758 \uc790\ubcf8\uc9c0\ucd9c \uacc4\ud68d\uc744 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc81c \ubc95\uc548\uc774\ub098 \uac00\uc774\ub358\uc2a4 \ubcc0\uacbd\uc774 \ud655\uc778\ub418\uae30 \uc804\uc5d0\ub294, \uaddc\uc81c \uc6b0\ub824\ub97c \ud655\uc815\uc801\uc778 \uc815\ucc45 \ubcc0\ud654\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n11\uc6d4 5\uc77c \ub098\uc2a4\ub2e5\uc740 \ube14\ub8e8 \uc4f0\ub098\ubbf8 \uc774\ud6c4 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uac00 \ubd80\uac01\ub418\uba70 3.13% \uae09\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\uc5d0\ub294 \uc800\uac00 \uc9c0\uc9c0 \uc5ec\ubd80\uc640 \ubc18\ub3c4\uccb4 \uc139\ud130\uc758 \ub418\ub3cc\ub9bc \uc5ec\ubd80\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-04-domestic-market-close","metadata":{"permalink":"/blog/en/market/2026-11-04-domestic-market-close","source":"@site/market/2026-11-04-domestic-market-close/index.mdx","title":"2026\ub144 11\uc6d4 4\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-04T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":7.56,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-04-domestic-market-close","title":"2026\ub144 11\uc6d4 4\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uc5d0 3.13% \uae09\ub77d \ucd9c\ubc1c","permalink":"/blog/en/market/2026-11-05-nasdaq-market-open"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \uae09\ub4f1 \ucd9c\ubc1c \ub4a4 \ubc18\uc804\ud574 \ucf54\uc2a4\ud53c 5,460\uc120 \ubd80\uadfc","permalink":"/blog/en/market/2026-11-04-domestic-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 4\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc774 \ubaa8\ub450 \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 0.62% \uc624\ub978 5,683.80\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \ub300\ube44 1.50% \uc624\ub978 714.95\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc885\uac00\ub9cc \ubcf4\uba74 \ud3c9\uc628\ud55c \ubc18\ub4f1\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc7a5\uc911 \ud750\ub984\uc740 \uc804\ud600 \uadf8\ub807\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5 \ucd08\ubc18 5,828.13\uae4c\uc9c0 \uc62c\ub790\ub2e4\uac00 \uc7a5\uc911 5,421.72\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uac00\uc640 \uc800\uac00\uc758 \ucc28\uc774\ub294 406.41\ud3ec\uc778\ud2b8\uc5d0 \ub2ec\ud569\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00 \uae30\uc900\uc73c\ub85c\ub294 \uace0\uac00\uc5d0\uc11c 3.17% \uc0c1\uc2b9\ud588\ub2e4\uac00 \uc800\uac00\uc5d0\uc11c 4.02% \ud558\ub77d\ud55c \uc148\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 718.34\uc5d0\uc11c 683.66\uae4c\uc9c0 \uc624\uac00\uba70 \uc7a5\uc911 34.68\ud3ec\uc778\ud2b8\uc758 \ubcc0\ub3d9\ud3ed\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uacb0\uad6d \ub450 \uc9c0\uc218\ub294 \uc7a5 \ud6c4\ubc18 \uc800\uac00 \ub9e4\uc218\uc138\uc5d0 \ud798\uc785\uc5b4 \uc0c1\uc2b9\uc73c\ub85c \ub3cc\uc544\uc130\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uae09\ub77d\uc744 \ud558\ub8e8 \ub9cc\uc5d0 \ub418\ub3cc\ub9b0 \ubc18\ub4f1\uc774\uc9c0\ub9cc, \uc804\uc804\uc77c \uc885\uac00\uc5d0\ub294 \uc544\uc9c1 \ubbf8\uce58\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc804\uc77c \uc885\uac00\ub294 5,859.08, \ucf54\uc2a4\ub2e5 \uc804\uc804\uc77c \uc885\uac00\ub294 734.36\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,683.80 | +35.01 | +0.62% | 5,786.13 | 5,828.13 | 5,421.72 | 258,778\ucc9c\uc8fc | 22\uc870 5,140\uc5b5\uc6d0 |\\n| \ucf54\uc2a4\ub2e5 | 714.95 | +10.56 | +1.50% | 715.74 | 718.34 | 683.66 | 509,755\ucc9c\uc8fc | 5\uc870 8,098\uc5b5\uc6d0 |\\n\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,648.79, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 704.39\uc785\ub2c8\ub2e4.<br/>\\n\uad50\ucc28 \uac80\uc99d\uc740 \ud604\uc7ac\uac00\ub97c \ub4f1\ub77d\ub960\ub85c \ub098\ub208 \uc5ed\uc0b0\uac12\uc73c\ub85c \uc218\ud589\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc624\ub298 \ubc18\ub4f1\uc758 \ucd9c\ubc1c\uc810\uc740 \uc804\uc77c \uae09\ub77d\uacfc \uac04\ubc24 \ubbf8\uad6d \uae30\uc220\uc8fc \ubc18\ub4f1\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ucf54\uc2a4\ud53c\ub294 3.59%, \ucf54\uc2a4\ub2e5\uc740 4.08% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,372.01\ub85c 0.83% \uc0c1\uc2b9\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,568.92\ub85c 0.36% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc870\ud569\uc740 \uc624\ub298 \uc7a5 \uc624\ud508\uc5d0\uc11c \uac15\ud55c \ub418\ub3cc\ub9bc \ucd9c\ubc1c\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \uc885\uac00\ubcf4\ub2e4 2.43% \ub192\uc740 5,786.13\uc5d0 \ucd9c\ubc1c\ud588\uace0, \ucf54\uc2a4\ub2e5\uc740 1.61% \ub192\uc740 715.74\uc5d0 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \ucd9c\ubc1c \uac15\ub3c4\ub294 \uc7a5\uc911 \uadf8\ub300\ub85c \uc720\uc9c0\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0\uc11c\ub294 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uacb0\uacfc\uc5d0 \ub300\ud55c \uacbd\uacc4\uac10\uc774 \uc7a5\uc911 \ubcc0\ub3d9\uc131\uc758 \ubc30\uacbd\uc73c\ub85c \uc9c0\ubaa9\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uacb0\uacfc\uac00 \uc815\ucc45 \uae30\ub300\ub97c \uc5b4\ub5bb\uac8c \ubc14\uafc0\uc9c0 \ud655\uc815\ub418\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\uc5d0\uc11c\ub294, \uc0c1\uc2b9 \ucd9c\ubc1c \ub4a4 \ucc28\uc775 \ub9e4\ubb3c\uc774 \ub098\uc624\uae30 \uc26c\uc6b4 \uad6c\uc870\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc81c\ub85c \ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 2\uc870 5,094\uc5b5\uc6d0 \uaddc\ubaa8\uc758 \uc21c\ub9e4\ub3c4\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \ub9e4\ub3c4\uac00 \uc3df\uc544\uc9c0\uc790 \uc9c0\uc218\ub294 \uc804\uc77c \uc885\uac00 \uc544\ub798\ub85c \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ud6c4 \ub4e4\uc5b4\uc11c\ub294 \uac1c\uc778\uacfc \uae30\uad00\uc758 \uc800\uac00 \ub9e4\uc218\uac00 \ub099\ud3ed\uc744 \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c \uac1c\uc778\uc740 1\uc870 1,465\uc5b5\uc6d0, \uae30\uad00\uc740 1\uc870 136\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc774 \ud310 \ubb3c\ub7c9\uc744 \uad6d\ub0b4 \ud22c\uc790\uc790\uac00 \ubc1b\uc544\ub0b8 \uad6c\ub3c4\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\ub3c4\ub294 \ucd94\uc138 \uc804\ud658\uc758 \uc2e0\ud638\ub77c\uae30\ubcf4\ub2e4, \uae09\ub77d \ub4a4 \uc800\uac00 \ub9e4\uc218\uac00 \uc720\uc785\ub41c \ub418\ub3cc\ub9bc\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.<br/>\\n\uac70\ub798\ub7c9\uc774 \uc804\uc77c\ubcf4\ub2e4 \ub298\uc5b4\ub09c \uc810\ub3c4 \uac19\uc740 \ud574\uc11d\uc744 \ub4b7\ubc1b\uce68\ud569\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uac70\ub798\ub7c9\uc740 258,778\ucc9c\uc8fc\ub85c \uc804\uc77c \uc77c\ubd09 \uae30\uc900 207,371\ucc9c\uc8fc\ubcf4\ub2e4 \ub298\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uac70\ub798\ub7c9\ub3c4 509,755\ucc9c\uc8fc\ub85c \uc804\uc77c \uc77c\ubd09 \uae30\uc900 430,571\ucc9c\uc8fc\ubcf4\ub2e4 \ub298\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc870\uc6a9\ud55c \uc0c1\uc2b9\uc774 \uc544\ub2c8\ub77c, \ub9e4\ub3c4\uc640 \ub9e4\uc218\uac00 \ub9de\ubd80\ub52a\ud78c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 1,342.00\uc6d0\uc73c\ub85c 0.23% \ub0b4\ub9b0 \uc218\uc900\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud658\uc728 \uae09\ubcc0\ub3d9\uc774 \uc7a5\uc911 \uae09\ub77d\uc744 \uc9c1\uc811 \ucd09\ub9e4\ud588\ub2e4\uace0 \ubcfc \uadfc\uac70\ub294 \uc774\ub0a0 \uc218\uce58\uc5d0\uc11c\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uacb0\uad6d \uc624\ub298 \uc7a5\uc138\uc758 \ud575\uc2ec \ucd09\ub9e4\ub294 \uc0c8\ub85c\uc6b4 \ud638\uc7ac\ubcf4\ub2e4, \uc804\uc77c \uae09\ub77d\uacfc \ubbf8\uad6d \uc99d\uc2dc \ubc18\ub4f1, \uadf8\ub9ac\uace0 \uc911\uac04\uc120\uac70 \uacbd\uacc4\uac10\uc774 \ub9de\ubb3c\ub9b0 \ud3ec\uc9c0\uc158 \uc870\uc815\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### 1. \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uacbd\uacc4\uac10\uacfc \uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc \ubc18\ub4f1\\n\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\ub97c \uc804\ud6c4\ud574 \uc815\ucc45 \ubc29\ud5a5\uc5d0 \ub300\ud55c \ubd88\ud655\uc2e4\uc131\uc774 \ucee4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 \ud63c\uc870 \uc18d\uc5d0\uc11c \ub098\uc2a4\ub2e5\uc774 0.83% \ubc18\ub4f1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \ubc18\ub4f1\uc774 \uad6d\ub0b4 \uc7a5 \uc624\ud508\uc758 \uc0c1\uc2b9 \ucd9c\ubc1c\uc744 \uc774\ub04c\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc120\uac70 \uacb0\uacfc\uc758 \uc2dc\uc7a5 \ud568\uc758\uac00 \ud655\uc815\ub418\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\uc5d0\uc11c\ub294, \uc0c1\uc2b9\uc774 \uace7\ubc14\ub85c \ucd94\uc138\ub85c \uc774\uc5b4\uc9c0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18 \uac15\uc138\uac00 \uc7a5\uc911 \uae09\ub77d\uc73c\ub85c \ubc14\ub010 \uc810\uc774 \uc774\ub97c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uacb0\uacfc \ud574\uc11d\uc774 \uc815\ub9ac\ub418\ub294 \uacfc\uc815 \uc790\uccb4\uac00 \ub2e8\uae30 \ubcc0\ub3d9\uc131\uc758 \uc6d0\uc778\uc774 \ub418\ub294 \uad6d\uba74\uc785\ub2c8\ub2e4.<br/>\\n\\n### 2. \ucfe0\ud321 3\ubd84\uae30 \uc601\uc5c5\uc190\uc2e4 6,423\uc5b5\uc6d0, 3\ubd84\uae30 \uc5f0\uc18d \uc801\uc790\\n\\n\ub525\uc11c\uce58 \ud2b8\ub80c\ub529 \ud1a0\ud53d \uae30\uc900, \ucfe0\ud321\uc740 3\ubd84\uae30 \ub9e4\ucd9c\uc774 \ucc98\uc74c\uc73c\ub85c 14\uc870\uc6d0\uc744 \ub118\uacbc\uc74c\uc5d0\ub3c4 \uc601\uc5c5\uc190\uc2e4 6,423\uc5b5\uc6d0\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc801\uc790\ub294 3\ubd84\uae30 \uc5f0\uc18d\uc73c\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc131\uc7a5 \uc9c0\ud45c\uc640 \uc218\uc775 \uc9c0\ud45c\uac00 \ubc18\ub300 \ubc29\ud5a5\uc744 \uac00\ub9ac\ud0a8 \uc0ac\ub840\uc785\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5 \uc2ec\ub9ac\uc5d0 \uc8fc\ub294 \ucda9\uaca9\uc740 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ub300\ud55c \uc758\ubb38\uc73c\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ucfe0\ud321\uc740 \ubbf8\uad6d \uc0c1\uc7a5 \uae30\uc5c5\uc774\ubbc0\ub85c, \uad6d\ub0b4 \uc9c0\uc218\uc5d0 \ub300\ud55c \uc9c1\uc811\uc801\uc778 \uad6c\uc131 \ud6a8\uacfc\ubcf4\ub2e4 \uc2ec\ub9ac\uc801\uc778 \ud30c\uae09\uc73c\ub85c \uc774\ud574\ud558\ub294 \ud3b8\uc774 \uc801\uc808\ud569\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc131\uc7a5\uc8fc\uc5d0 \ub300\ud55c \uae30\ub300\ub97c \uc77c\uad04\uc801\uc73c\ub85c \ub0ae\ucd94\ub294 \uadfc\uac70\ub85c \uc0bc\uc744 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### 3. \ud604\ub300\ubc31\ud654\uc810 3\ubd84\uae30 \uc601\uc5c5\uc774\uc775 30% \uc99d\uac00\uc640 \ud604\ub300\ucc28\uadf8\ub8f9 \uc218\uc18c \uc0dd\ud0dc\uacc4 \ube44\uc804\\n\\n\ub525\uc11c\uce58 \ud2b8\ub80c\ub529 \ud1a0\ud53d 1\uc704\ub294 \ud604\ub300\ubc31\ud654\uc810 3\ubd84\uae30 \uc2e4\uc801\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc31\ud654\uc810\uacfc \uba74\uc138\uc810 \ud638\uc870 \uc18d\uc5d0 \uc601\uc5c5\uc774\uc775\uc774 30% \uc99d\uac00\ud55c \uac83\uc73c\ub85c \uc815\ub9ac\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc18c\ube44 \uad00\ub828 \uc2e4\uc801\uc774 \uc608\uc0c1\ubcf4\ub2e4 \uacac\uc870\ud558\ub2e4\ub294 \uc2e0\ud638\ub85c \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ub2e8\uc77c \uae30\uc5c5\uc758 \uc2e4\uc801\uc774 \uc9c0\uc218 \uc804\uccb4\ub97c \uc6c0\uc9c1\uc774\ub294 \ucd09\ub9e4\ub77c\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub0a0 \ud2b8\ub80c\ub529 2\uc704\ub294 \ud604\ub300\ucc28\uadf8\ub8f9\uc758 \uc218\uc18c \uc0dd\ud0dc\uacc4 \ube44\uc804 \uacf5\uac1c\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n5MW\uae09 \uc218\uc804\ud574 \ubaa8\ub4c8 \uacf5\uac1c\uc640 \uc0c8\ub9cc\uae08 \uc218\uc18c \uc0dd\ud0dc\uacc4 \uccad\uc0ac\uc9c4\uc774 \ud3ec\ud568\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ub2f9\uc77c \uc2e4\uc801\ubcf4\ub2e4 \uc911\uc7a5\uae30 \uc5d0\ub108\uc9c0 \uc804\ud658 \ubc38\ub958\uccb4\uc778\uc5d0 \ub300\ud55c \uae30\ub300\ub97c \uc790\uadf9\ud558\ub294 \uc0ac\uac74\uc785\ub2c8\ub2e4.<br/>\\n\ub2e8\uae30 \uc9c0\uc218 \ubc29\ud5a5\ubcf4\ub2e4\ub294 \uc804\ub825\ub9dd\uacfc \uc218\uc18c \uad00\ub828 \ud14c\ub9c8\uc758 \uad00\uc2ec \uc9c0\uc18d \uc5ec\ubd80\ub97c \uac00\ub2a0\ud558\ub294 \uc7ac\ub8cc\ub85c \ubcf4\ub294 \ud3b8\uc774 \uc801\uc808\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc139\ud130\xb7\ud14c\ub9c8 \uc601\ud5a5 \uccb4\uc778\\n\\n\uc624\ub298 \uac15\uc138\uc758 \uc911\uc2ec\uc740 2\ucc28\uc804\uc9c0\uc640 \uc5d0\ub108\uc9c0 \uc804\ud658 \ubc38\ub958\uccb4\uc778\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ud3f4\ub9ac\uc2e4\ub9ac\ucf58 \ud14c\ub9c8\ub294 8.76% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\nESS \ud14c\ub9c8\ub294 6.21% \uc62c\ub790\uace0, \ud3ec\ud568\ub41c 17\uac1c \uc885\ubaa9\uc774 \ubaa8\ub450 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uace0\uccb4\ubc30\ud130\ub9ac\ub294 6.15%, \ud0dc\uc591\uad11\ubc1c\uc804\uc740 6.10% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n2\ucc28\uc804\uc9c0 \uc0dd\uc0b0 \ud14c\ub9c8\ub294 5.50%, 2\ucc28\uc804\uc9c0 LFP \ud14c\ub9c8\ub294 4.81%, \ubc30\ud130\ub9ac \ud14c\ub9c8\ub294 4.77% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc5f0\uacb0\uace0\ub9ac\ub294 ESS \uc218\uc694 \uae30\ub300\uc5d0\uc11c \ucd9c\ubc1c\ud569\ub2c8\ub2e4.<br/>\\nESS \uc218\uc694\uac00 \ucee4\uc9c0\uba74 \ubc30\ud130\ub9ac \uc140\uacfc \uc18c\uc7ac, \uc804\ub825 \uc800\uc7a5 \uc2dc\uc2a4\ud15c\uc774 \ud568\uaed8 \uc8fc\ubaa9\ubc1b\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5d8\uc564\uc5d0\ud504\uc758 LG\uc5d0\ub108\uc9c0\uc194\ub8e8\uc158 \ub300\uc0c1 1\uc870\uc6d0\ub300 LFP \uacf5\uae09\uacc4\uc57d \uc18c\uc2dd\uc774 \uac19\uc740 \ub9e5\ub77d\uc5d0\uc11c \uc815\ub9ac\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ud3f4\ub9ac\uc2e4\ub9ac\ucf58\uacfc \ud0dc\uc591\uad11 \uac15\uc138\ub294 \uc5d0\ub108\uc9c0 \uc804\ud658\uc758 \ub2e4\ub978 \ucd95\uc785\ub2c8\ub2e4.<br/>\\n\uc804\ub825\ub9dd \ud655\ucda9\uacfc \ud0dc\uc591\uad11 \uc124\ube44 \uc218\uc694\uac00 \ub9de\ubb3c\ub9ac\uba74, \uc18c\uc7ac\uc640 \uc804\ub825\uae30\uae30 \ucabd\uc73c\ub85c \uad00\uc2ec\uc774 \ud655\uc0b0\ub429\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uc2dc\uc7a5 \ube0c\ub9ac\ud551\uc740 ESS\uc640 LFP, HBM \uae30\ud310\uc774 \uc9c0\uc218\ub97c \uacac\uc778\ud588\ub2e4\uace0 \uc815\ub9ac\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\ub825\ub9dd\uacfc \ud0dc\uc591\uad11 \uac15\uc138 \uc18d\uc5d0\uc11c\ub294 \ub85c\ubd07 \ud14c\ub9c8\uc758 \uc885\ubaa9\ubcc4 \uc628\ub3c4\ucc28\uac00 \uc788\uc5c8\ub2e4\uace0\ub3c4 \uc815\ub9ac\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 \ucf54\uc2a4\ud53c\ubcf4\ub2e4 \uac15\ud588\ub358 \uc810\ub3c4 \uac19\uc740 \ud750\ub984\uacfc \ub9de\ub2ff\uc544 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615 \uc9c0\uc218\ubcf4\ub2e4 \uc911\uc18c\ud615 \uc131\uc7a5\uc8fc\uc640 \ud14c\ub9c8\uc8fc \ucabd\uc73c\ub85c \uc790\uae08\uc774 \ubd84\uc0b0\ub41c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uc9c0\uc218 \uc0c1\ub2e8\uc740 \uc678\uad6d\uc778\uc758 \ub300\uaddc\ubaa8 \uc21c\ub9e4\ub3c4 \uc18d\uc5d0 \uc81c\ud55c\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ud14c\ub9c8 \uac15\uc138\uac00 \uc9c0\uc218 \uc804\uccb4\uc758 \uac15\uc138\ub85c \uace7\ubc14\ub85c \ud655\uc0b0\ub418\uc9c0\ub294 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 228,294 |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | 198,130 |\\n| 2026-11-03 | 5,715.19 | 5,735.92 | 5,615.80 | 5,648.79 | 207,371 |\\n| 2026-11-04 | 5,786.13 | 5,828.13 | 5,421.72 | 5,683.80 | 258,778 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 470,174 |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | 355,750 |\\n| 2026-11-03 | 723.92 | 723.92 | 702.34 | 704.39 | 430,571 |\\n| 2026-11-04 | 715.74 | 718.34 | 683.66 | 714.95 | 509,755 |\\n\\n\ucf54\uc2a4\ud53c\ub294 11\uc6d4 2\uc77c 5,859.08\uc5d0\uc11c 11\uc6d4 3\uc77c 5,648.79\ub85c \uae09\ub77d\ud55c \ub4a4, \uc624\ub298 5,683.80\uc73c\ub85c \uc77c\ubd80\ub9cc \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 11\uc6d4 2\uc77c 734.36\uc5d0\uc11c 11\uc6d4 3\uc77c 704.39\ub85c \uae09\ub77d\ud55c \ub4a4, \uc624\ub298 714.95\ub85c \uc77c\ubd80\ub9cc \ub418\ub3cc\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc804\uc77c \uae09\ub77d\ud3ed\uc744 \uc644\uc804\ud788 \ud68c\ubcf5\ud558\uc9c0\ub294 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \uc77c\ubd09\uc740 \uc2dc\uac00\ubcf4\ub2e4 \uc885\uac00\uac00 \ub0ae\uc9c0 \uc54a\uc9c0\ub9cc, \uc7a5\uc911 \uc800\uc810\uc774 \uae4a\uc5c8\ub2e4\ub294 \uc810\uc5d0\uc11c \ubcc0\ub3d9\uc131 \uc790\uccb4\uac00 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2f9\uc77c \uc218\uae09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +11,465 |\\n| \uc678\uad6d\uc778 | -25,094 |\\n| \uae30\uad00 | +10,136 |\\n| \uae30\ud0c0\ubc95\uc778 | +3,493 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | -522 |\\n| \uc678\uad6d\uc778 | +9 |\\n| \uae30\uad00 | +635 |\\n| \uae30\ud0c0\ubc95\uc778 | -122 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 \ub300\uaddc\ubaa8\ub85c \uc21c\ub9e4\ub3c4\ud588\uace0, \uac1c\uc778\uacfc \uae30\uad00\uc774 \uc774\ub97c \ubc1b\uc544\ub0c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \uc21c\ub9e4\ub3c4\ub294 \uc804\uc77c\uc5d0 \uc774\uc5b4 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc774 \ub3cc\uc544\uc628 \ubc18\ub4f1\uc774 \uc544\ub2c8\ub77c, \uc678\uad6d\uc778\uc774 \ud310 \ubb3c\ub7c9\uc744 \uad6d\ub0b4 \ud22c\uc790\uc790\uac00 \ud761\uc218\ud55c \ubc18\ub4f1\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\ub3c4\uac00 \ubc14\ub00c\uc9c0 \uc54a\uc73c\uba74 \uc0c1\uc2b9\uc758 \uc9c0\uc18d\ub825\uc740 \uc81c\ud55c\ub420 \uc218\ubc16\uc5d0 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uad6c\ub3c4\uac00 \ub2ec\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uc774 635\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud558\uba70 \ubc18\ub4f1\uc744 \uc774\ub04c\uc5c8\uace0, \uac1c\uc778\uc740 522\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc740 9\uc5b5\uc6d0 \uc21c\ub9e4\uc218\ub85c \uc0ac\uc2e4\uc0c1 \uc911\ub9bd\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uc0c1\uc2b9\uc740 \uc678\uad6d\uc778 \uc8fc\ub3c4\uac00 \uc544\ub2c8\ub77c \uae30\uad00 \uc911\uc2ec\uc758 \ub418\ub3cc\ub9bc\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uae09 \uc218\uce58\ub294 \ub124\uc774\ubc84 \ud22c\uc790\uc790\ubcc4 \ub9e4\ub9e4\ub3d9\ud5a5 \ub2f9\uc77c \ud56d\ubaa9 \uae30\uc900\uc774\uba70, \ucd5c\uc885 \uc9d1\uacc4 \uacfc\uc815\uc5d0\uc11c \uc77c\ubd80 \uc870\uc815\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984\\n\\n\uc2dc\uc7a5 \uc804\uccb4\uac00 \ucd9c\ub801\uc778 \uac00\uc6b4\ub370\uc5d0\uc11c\ub3c4 \uc5d0\ub108\uc9c0 \uc804\ud658 \ud14c\ub9c8\ub294 \ub69c\ub837\ud558\uac8c \uac15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud3f4\ub9ac\uc2e4\ub9ac\ucf58 \ud14c\ub9c8\ub294 8.76%, ESS \ud14c\ub9c8\ub294 6.21% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uace0\uccb4\ubc30\ud130\ub9ac \ud14c\ub9c8\ub294 6.15%, \ud0dc\uc591\uad11\ubc1c\uc804 \ud14c\ub9c8\ub294 6.10% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n2\ucc28\uc804\uc9c0 \uc0dd\uc0b0 \ud14c\ub9c8\ub294 5.50%, MLCC \ud14c\ub9c8\ub294 4.89%, \ud1b5\uc2e0\uc0ac \ud14c\ub9c8\ub294 4.88% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n2\ucc28\uc804\uc9c0 LFP \ud14c\ub9c8\ub294 4.81%, \ubc30\ud130\ub9ac \ud14c\ub9c8\ub294 4.77% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uc0c1\uc2b9\ub960\ubcf4\ub2e4 \ud14c\ub9c8 \uc0c1\uc2b9\ub960\uc774 \ud6e8\uc52c \ucef8\ub2e4\ub294 \uc810\uc774 \uc624\ub298\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\uc790\uae08\uc774 \uc9c0\uc218 \uc804\uccb4\uac00 \uc544\ub2c8\ub77c \ud2b9\uc815 \ubc38\ub958\uccb4\uc778\uc73c\ub85c \uc9d1\uc911\ub41c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \ub0b4\uc77c \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ub2e8\uae30\uc801\uc73c\ub85c \uc624\ub298 \uc7a5\uc138\ub294 \ubcc0\ub3d9\uc131 \uad6d\uba74\uc774 \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc2e0\ud638\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uae30\uc900\uc73c\ub85c \uc624\ub298 \uc800\uc810 5,421.72\uac00 \uccab \uc9c0\uc9c0 \uad6c\uac04\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uac70\ub798\uc77c\uc5d0 \uc774 \uc800\uc810\uc744 \uc9c0\ucf1c\ub0b4\uba74, \uae09\ub77d \ub4a4 \uc800\uc810 \ud655\uc778 \uacfc\uc815\uc73c\ub85c \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc800\uc810\uc744 \ub2e4\uc2dc \ubc11\ub3cc\uba74 \uc804\uc77c \uae09\ub77d \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\ub294 \uac83\uc73c\ub85c \ubd10\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc704\ucabd\uc5d0\uc11c\ub294 \uc624\ub298 \uace0\uc810 5,828.13\uc774 \uccab \uc800\ud56d \uad6c\uac04\uc785\ub2c8\ub2e4.<br/>\\n\uc885\uac00 5,683.80\uc774 \uace0\uc810\ubcf4\ub2e4 144.33\ud3ec\uc778\ud2b8 \ub0ae\ub2e4\ub294 \uc810\uc740, \ub418\ub3cc\ub9bc\uc758 \ud798\uc774 \uc544\uc9c1 \uc81c\ud55c\uc801\uc784\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5 \uae30\uc900\uc73c\ub85c\ub3c4 \uc624\ub298 \uc800\uc810 683.66\uacfc \uace0\uc810 718.34\ub97c \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uac70\ub798\uc77c\uc5d0 \ud655\uc778\ud560 \uccab \ubc88\uc9f8 \uc218\uce58\ub294 \uc678\uad6d\uc778\uc758 \uc21c\ub9e4\ub3c4 \uc9c0\uc18d \uc5ec\ubd80\uc785\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \ucf54\uc2a4\ud53c \uc678\uad6d\uc778 \uc21c\ub9e4\ub3c4 2\uc870 5,094\uc5b5\uc6d0\uc774 \ud558\ub8e8 \ub9cc\uc5d0 \ucd95\uc18c\ub418\ub294\uc9c0\uac00 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\ub450 \ubc88\uc9f8\ub85c \ud655\uc778\ud560 \uc810\uc740 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uacb0\uacfc \ud574\uc11d\uacfc \uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\uc138 \ubc88\uc9f8\ub85c \ud655\uc778\ud560 \uc810\uc740 \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc758 1,342\uc6d0 \uc218\uc900 \uc720\uc9c0 \uc5ec\ubd80\uc785\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 ESS\uc640 LFP, \ud0dc\uc591\uad11 \ud14c\ub9c8\uc758 \uac15\uc138\uac00 \uae30\ub300\ub9cc\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uacf5\uae09\uacc4\uc57d\uacfc \uc2e4\uc801 \uac19\uc740 \uc2e4\uc81c \uc218\uce58\ub85c \ub4b7\ubc1b\uce68\ub418\uc9c0 \uc54a\uc73c\uba74, \ud14c\ub9c8 \uc0c1\uc2b9\uc740 \ubcc0\ub3d9\uc131\ub9cc \ud0a4\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc2e4\uc81c \uc218\uc8fc\uac00 \ud655\uc778\ub418\uba74 \uc5d0\ub108\uc9c0 \uc804\ud658 \ubc38\ub958\uccb4\uc778\uc5d0 \ub300\ud55c \uad00\uc2ec\uc740 \uc9c0\uc218\ubcf4\ub2e4 \uc624\ub798 \uc9c0\uc18d\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcc0\ub3d9\uc131\uc774 \ud070 \uad6d\uba74\uc5d0\uc11c\ub294 \uc9c0\uc218 \ubc29\ud5a5\uc744 \ub2e8\uc815\ud558\uae30\ubcf4\ub2e4, \uc800\uc810\uacfc \uace0\uc810 \uac19\uc740 \uac00\uaca9 \ub808\ubca8\uc744 \uae30\uc900\uc73c\ub85c \ud750\ub984\uc744 \ud655\uc778\ud558\ub294 \ud3b8\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc624\ub298\uc740 400\ud3ec\uc778\ud2b8\uac00 \ub118\ub294 \uc7a5\uc911 \ubcc0\ub3d9 \ub05d\uc5d0 \ub450 \uc9c0\uc218\uac00 \ubaa8\ub450 \uc0c1\uc2b9 \ub9c8\uac10\ud55c \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uc218\uce58\uc640 \ud750\ub984\uc744 \uc815\ub9ac\ud55c \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uae30\ub85d\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\ub294 \ub0b4\uc6a9\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-04-domestic-market-midday","metadata":{"permalink":"/blog/en/market/2026-11-04-domestic-market-midday","source":"@site/market/2026-11-04-domestic-market-midday/index.mdx","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \uae09\ub4f1 \ucd9c\ubc1c \ub4a4 \ubc18\uc804\ud574 \ucf54\uc2a4\ud53c 5,460\uc120 \ubd80\uadfc","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-04T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":6.2,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-04-domestic-market-midday","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \uae09\ub4f1 \ucd9c\ubc1c \ub4a4 \ubc18\uc804\ud574 \ucf54\uc2a4\ud53c 5,460\uc120 \ubd80\uadfc","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 11\uc6d4 4\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-04-domestic-market-close"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \uc804\uc77c \uae09\ub77d \ub4a4 \ubc18\ub4f1 \ucd9c\ubc1c\ud55c \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5","permalink":"/blog/en/market/2026-11-04-domestic-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 4\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uc7a5 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \uc885\uac00 5,648.79\uc5d0\uc11c 5,786.13\uc73c\ub85c 2.43% \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \uc885\uac00 704.39\uc5d0\uc11c 715.74\ub85c \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18 \ucf54\uc2a4\ud53c\ub294 5,828.13\uae4c\uc9c0 \uc62c\ub790\uc73c\ub098, \uc774\ud6c4 \ud558\ub77d\uc73c\ub85c \uc804\ud658\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc815\uc624 \ubb34\ub835 \ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 \ub300\ube44 5.57% \ub0ae\uc740 5,463.80 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 \ub300\ube44 3.69% \ub0ae\uc740 689.34 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \uc624\uc804\uc7a5\uc758 \ud575\uc2ec\uc740 \uc0c1\uc2b9 \ucd9c\ubc1c\uc774 \uc544\ub2c8\ub77c \ucd9c\ubc1c \ub4a4\uc758 \ubc18\uc804\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,463.80 | -184.99 | -3.27% | 5,786.13 | 5,828.13 | 5,439.54 | 141,387\ucc9c\uc8fc | 12\uc870 1,134\uc5b5\uc6d0 | 2026-11-04 12:29 KST |\\n| \ucf54\uc2a4\ub2e5 | 689.34 | -15.05 | -2.14% | 715.74 | 718.34 | 683.66 | 357,899\ucc9c\uc8fc | 3\uc870 7,598\uc5b5\uc6d0 | 2026-11-04 12:29 KST |\\n\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,786.13\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,463.80\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 715.74\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 689.34\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,648.79, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 704.39\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\ucd9c\ubc1c \uc7ac\ub8cc\uc640 \uc7a5\uc911 \ubc18\uc804 \uc7ac\ub8cc\uac00 \uc815\ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd9c\ubc1c \uc7ac\ub8cc\ub294 \uac04\ubc24 \ubbf8\uad6d \ubc18\ub3c4\uccb4 \uac15\uc138\uc640 \uad6d\uc81c\uc720\uac00 \ud558\ub77d\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ub274\uc695\uc99d\uc2dc\uc5d0\uc11c \ub098\uc2a4\ub2e5 \uc885\ud569\uc9c0\uc218\ub294 25,372.01\ub85c 0.83% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,568.92\ub85c 0.36% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc9c0\uc218\ub294 51,786.72\ub85c 0.38% \ub0b4\ub9ac\uba70 \ud63c\uc870\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \uc800\uac00 \ub9e4\uc218\uc138\uac00 \uc720\uc785\ub418\uba74\uc11c \uad6d\ub0b4 \uc99d\uc2dc\ub3c4 \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc0c1\uc2b9 \ucd9c\ubc1c\uc740 \uc624\ub798 \uc720\uc9c0\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70 \uac1c\ud45c \uacbd\uacc4\uac10\uc774 \uc7a5\uc911\uc5d0 \ucee4\uc9c0\uba74\uc11c \uc704\ud5d8 \ud68c\ud53c \uc2ec\ub9ac\uac00 \uac15\ud654\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc218\uc775\uc131\uc5d0 \ub300\ud55c \uc758\uad6c\uc2ec\ub3c4 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ubd80\ub2f4\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc218\uae09 \uad6c\ub3c4\ub294 \uc774\ub7ec\ud55c \ubc18\uc804\uc5d0 \ucde8\uc57d\ud55c \uc0c1\ud0dc\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 3\uc77c \ucf54\uc2a4\ud53c\uc5d0\uc11c \uc678\uad6d\uc778\uc740 1\uc870 5,799\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub0a0 \uae30\uad00\uc740 7,300\uc5b5\uc6d0 \uc21c\ub9e4\ub3c4\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub0a0 \uac1c\uc778\uc740 1\uc870 9,568\uc5b5\uc6d0 \uc21c\ub9e4\uc218\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \ud310 \ubb3c\ub7c9\uc744 \uac1c\uc778\uc774 \ubc1b\uc740 \uad6c\ub3c4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\ub3c4\ub294 \uc0c1\uc2b9\uc7a5\uc5d0\uc11c \ubc1b\uccd0\uc8fc\ub294 \ud798\uc774 \uc544\ub2c8\ub77c \ud558\ub77d\uc7a5\uc5d0\uc11c \ubd80\ub2f4\uc774 \ub418\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc7a5\uc911 \uc218\uae09 \ud655\uc815\uce58\ub294 \uc544\uc9c1 \uc9d1\uacc4\ub418\uc9c0 \uc54a\uc544 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uc7a5\uc911 \uc9d1\uacc4 \uae30\uc900\uc73c\ub85c\ub294 \uc678\uad6d\uc778 \uc21c\ub9e4\ub3c4 \ubc29\ud5a5\uc774 \uc774\uc5b4\uc9c0\ub294 \uac83\uc73c\ub85c \ud45c\uc2dc\ub429\ub2c8\ub2e4.<br/>\\n\ud574\ub2f9 \uc218\uce58\ub294 \ud655\uc815\uce58\uac00 \uc544\ub2c8\ubbc0\ub85c \ubc29\ud5a5 \ucc38\uace0\uc6a9\uc73c\ub85c\ub9cc \uc774\ud574\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0\xb7\ub2ec\ub7ec \ud658\uc728\uc740 1,338.10\uc6d0 \uc218\uc900\uc73c\ub85c \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\ud658\uc728 \uc790\uccb4\ub294 \uc774\ub0a0 \uae09\ub77d\uc758 \uc9c1\uc811 \ucd09\ub9e4\ub85c \ub2e8\uc815\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n\uccab\uc9f8, \uad6d\ub0b4 \uc99d\uc2dc\uc758 \uc7a5\uc911 \ubc18\uc804\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 2.43% \uc0c1\uc2b9 \ucd9c\ubc1c\ud574 \uc7a5 \ucd08\ubc18 5,800\uc120\uc744 \ud68c\ubcf5\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ud6c4 \ud558\ub77d\uc73c\ub85c \uc804\ud658\ud574 \uc815\uc624 \ubb34\ub835 \uc804\uc77c \ub300\ube44 3% \ub118\uac8c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 700\uc120\uc744 \ubc11\ub3cc\uba70 689\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9 \ucd9c\ubc1c \ub4a4 \ud558\ub77d \uc804\ud658\uc740 \ucd94\uaca9 \ub9e4\uc218 \uc2ec\ub9ac\ub97c \ube60\ub974\uac8c \uc704\ucd95\uc2dc\ud0b5\ub2c8\ub2e4.<br/>\\n\uace0\uac00\uc5d0\uc11c \uc0b0 \ubb3c\ub7c9\uc774 \uc190\uc2e4\uc744 \ub5a0\uc548\ub294 \uad6c\uc870\uac00 \ub418\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ubc18\uc804\uc740 \ub2e8\uc21c\ud55c \ucc28\uc775 \uc2e4\ud604\uc744 \ub118\uc5b4 \uc218\uae09 \ubd80\ub2f4\uc774 \uacb9\uce5c \uacb0\uacfc\ub85c \ubcf4\uc785\ub2c8\ub2e4.<br/>\\n\\n\ub458\uc9f8, \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uac1c\ud45c \uacbd\uacc4\uac10\uc785\ub2c8\ub2e4.<br/>\\n4\uc77c \uc624\uc804 \uae30\uc900 \ubbf8\uad6d \uc8fc\uac00\uc9c0\uc218 \uc120\ubb3c\uc740 \ud558\ub77d\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5100 \uc120\ubb3c\uc740 0.81% \ud558\ub77d\ud55c \uac83\uc73c\ub85c \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9\uc758 \uc0c1\xb7\ud558\uc6d0 \uc7a5\uc545 \uac00\ub2a5\uc131\uc774 \ubd80\uac01\ub418\uba74\uc11c \uc815\ucc45 \ubd88\ud655\uc2e4\uc131\uc774 \ucee4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uac15\ud654 \uc6b0\ub824\ub3c4 \uae30\uc220\uc8fc\uc5d0 \ubd80\ub2f4\uc73c\ub85c \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\ud45c \uacb0\uacfc\uac00 \ub098\uc624\uae30 \uc804\uae4c\uc9c0 \uc2dc\uc7a5\uc740 \ubc29\ud5a5\uc744 \ud655\uc815 \uc9d3\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \ubd88\ud655\uc2e4\uc131\uc740 \uc7a5\uc911 \uc678\uad6d\uc778 \ub9e4\ub3c4\uc640 \ub9de\ubb3c\ub824 \ud558\ub77d \uc555\ub825\uc744 \ud0a4\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\uc14b\uc9f8, \ucfe0\ud321\uc758 3\ubd84\uae30 \ub300\uaddc\ubaa8 \uc601\uc5c5\uc190\uc2e4\uc785\ub2c8\ub2e4.<br/>\\n\ucfe0\ud321 \ubaa8\ud68c\uc0ac\ub294 3\ubd84\uae30 \uc601\uc5c5\uc190\uc2e4 6,423\uc5b5\uc6d0\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubd84\uae30 \ucd5c\ub300 \ub9e4\ucd9c\uc5d0\ub3c4 3\ubd84\uae30 \uc5f0\uc18d \uc801\uc790\uac00 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ubb3c\ub958\uc13c\ud130 \ud654\uc7ac\uc5d0 \ub530\ub978 \uc190\uc2e4 \ube44\uc6a9 \uc57d 3,540\uc5b5\uc6d0\uc774 \ubc18\uc601\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uacfc\uc9d5\uae08 \ubd80\ub2f4\ub3c4 \uc2e4\uc801 \ud68c\ubcf5\uc744 \ub354\ub514\uac8c \ud558\ub294 \uc694\uc778\uc73c\ub85c \uac70\ub860\ub429\ub2c8\ub2e4.<br/>\\n\ucfe0\ud321\uc740 \uad6d\ub0b4 \uc99d\uc2dc \uc9c1\uc811 \uad6c\uc131 \uc885\ubaa9\uc774 \uc544\ub2c8\ubbc0\ub85c \uc9c0\uc218 \ud558\ub77d\uc758 \uc9c1\uc811 \uc6d0\uc778\uc73c\ub85c \ubcf4\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ub300\ud615 \ud50c\ub7ab\ud3fc \uae30\uc5c5\uc758 \uc801\uc790 \uc9c0\uc18d\uc740 \uc18c\ube44\xb7\uc720\ud1b5 \uad00\ub828 \ud22c\uc790 \uc2ec\ub9ac\uc5d0 \ubd80\ub2f4\uc73c\ub85c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ud558\ub77d\uc758 \uc911\uc2ec\ucd95\uc740 \ubc18\ub3c4\uccb4\xb7\uc131\uc7a5\uc8fc \uc870\uc815\uacfc \uc678\uad6d\uc778 \ub9e4\ub3c4\uc774\uba70, \ucfe0\ud321 \uc2e4\uc801\uc740 \uc2ec\ub9ac \uc694\uc778\uc73c\ub85c \uc774\ud574\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc139\ud130\xb7\ud14c\ub9c8 \uc601\ud5a5 \uccb4\uc778\\n\\n\uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc218\uc775\uc131 \uc6b0\ub824\ub294 \ubc18\ub3c4\uccb4\uc640 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc744 \uc9c1\uc811 \uc555\ubc15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc38\ub958\uc5d0\uc774\uc158\uc774 \ub192\uc740 \uc885\ubaa9\uc77c\uc218\ub85d \uae08\ub9ac\xb7\uc131\uc7a5 \uae30\ub300 \ubcc0\ud654\uc5d0 \ubbfc\uac10\ud558\uac8c \ubc18\uc751\ud569\ub2c8\ub2e4.<br/>\\n\uae30\ub300 \uc218\uc775\uc5d0 \ub300\ud55c \uc758\uad6c\uc2ec\uc774 \ucee4\uc9c0\uba74 \ud560\uc778\uc728 \ubd80\ub2f4\uc774 \uba3c\uc800 \uac00\uaca9\uc5d0 \ubc18\uc601\ub429\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c200\uc774 3% \ub118\uac8c \ud558\ub77d\ud55c \uc810\uc740 \ub300\ud615\uc8fc \uc804\ubc18\uc73c\ub85c \uc870\uc815\uc774 \ud655\uc0b0\ub410\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc120\ubb3c \uc9c0\uc218\ub3c4 \ube44\uc2b7\ud55c \ud3ed\uc73c\ub85c \ud558\ub77d\ud574 \ub2e8\uae30 \ubc29\ud5a5\uc5d0 \ub300\ud55c \uacbd\uacc4\uac10\uc774 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\uad6d\uc81c\uc720\uac00 \ud558\ub77d\uc740 \uc5d0\ub108\uc9c0 \uad00\ub828\uc8fc\uc5d0 \ubd80\ub2f4\uc774 \ub418\ub294 \ubc18\uba74, \uc6b4\uc1a1\xb7\uc18c\ube44 \ube44\uc6a9 \ubd80\ub2f4\uc740 \ub35c\uc5b4\uc8fc\ub294 \ubc29\ud5a5\uc785\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc774\ub0a0\uc740 \uc720\uac00 \ud558\ub77d\uc758 \uae0d\uc815\uc801 \ud6a8\uacfc\uac00 \ud558\ub77d\uc7a5 \ubd84\uc704\uae30\uc5d0 \ubb3b\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\ub300\uc801\uc73c\ub85c \uac15\ud588\ub358 \ucabd\uc740 \ud1b5\uc2e0\uc0ac\uc640 \ud0dc\uc591\uad11\xb7\ud3f4\ub9ac\uc2e4\ub9ac\ucf58 \uad00\ub828 \ud14c\ub9c8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud1b5\uc2e0\uc0ac\ub294 \ud558\ub77d\uc7a5\uc5d0\uc11c \ubc29\uc5b4\uc801 \uc131\uaca9\uc774 \ubd80\uac01\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud0dc\uc591\uad11\xb7\ud3f4\ub9ac\uc2e4\ub9ac\ucf58 \ud14c\ub9c8\ub294 \ubbf8\uad6d \uc911\uac04\uc120\uac70\ub97c \uc55e\ub454 \uc815\ucc45 \uae30\ub300\uc640 \ubbf8\uad6d \ud604\uc9c0 \uc0dd\uc0b0 \uc218\ud61c \uae30\ub300\uac00 \uac70\ub860\ub429\ub2c8\ub2e4.<br/>\\n\ub18d\uc5c5\xb7\uc81c\ubd84 \ud14c\ub9c8\uc758 \uc0c1\uc2b9\ub3c4 \uc9c0\uc218 \ud558\ub77d \uc18d \uc77c\ubd80 \uc790\uae08\uc774 \ubc29\uc5b4\xb7\uc815\ucc45 \ud14c\ub9c8\ub85c \uc774\ub3d9\ud588\uc74c\uc744 \uc2dc\uc0ac\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ud14c\ub9c8 \uc0c1\uc2b9\uc774 \uc9c0\uc218 \ud558\ub77d\uc744 \uc0c1\uc1c4\ud560 \uaddc\ubaa8\ub294 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ud558\ub77d\uc774 \uc8fc\ub3c4\ud558\ub294 \uc7a5\uc5d0\uc11c\ub294 \ud14c\ub9c8 \uac15\uc138\ub3c4 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 228,294 |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | 198,130 |\\n| 2026-11-03 | 5,715.19 | 5,735.92 | 5,615.80 | 5,648.79 | 207,371 |\\n| 2026-11-04 | 5,786.13 | 5,828.13 | 5,439.54 | 5,463.80 | 141,387 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 470,174 |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | 355,750 |\\n| 2026-11-03 | 723.92 | 723.92 | 702.34 | 704.39 | 430,571 |\\n| 2026-11-04 | 715.74 | 718.34 | 683.66 | 689.34 | 357,899 |\\n\\n2026\ub144 11\uc6d4 4\uc77c \ubd09\uc740 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc77c\ubd09 \ud45c\uc758 \ub2f9\uc77c \uc885\uac00\ub294 \ud45c \uc791\uc131 \uc2dc\uc810\uc758 \ud615\uc131 \uc911 \uc218\uce58\uc774\uba70 \uc2e4\uc2dc\uac04 \ud604\uc7ac\uac00\uc640 \uc2dc\ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 10\uc6d4 28\uc77c 6,012.44 \uace0\uc810 \uc774\ud6c4 \ud558\ub77d \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 10\uc6d4 28\uc77c 771.28 \uc774\ud6c4 \ud558\ub77d \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984 \ubcc0\ud654\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\ud1b5\uc2e0\uc0ac \ud14c\ub9c8\uac00 4.38% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud3f4\ub9ac\uc2e4\ub9ac\ucf58 \ud14c\ub9c8\uac00 2.61% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc81c\ubd84 \ud14c\ub9c8\uac00 2.29% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud0dc\uc591\uad11\ubc1c\uc804 \ud14c\ub9c8\uac00 1.92% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac74\uc124\uae30\uacc4 \ud14c\ub9c8\uac00 1.66% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00 \ub300\ube44 \uc0c1\uc2b9 \uc804\ud658\uc740 \ud655\uc778\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,786.13\ubcf4\ub2e4 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,463.80\uc774 \ub0ae\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 715.74\ubcf4\ub2e4 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 689.34\uac00 \ub0ae\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc7a5\uc911 \uc218\uae09 \ud655\uc815\uce58\ub294 \uc544\uc9c1 \uc9d1\uacc4\ub418\uc9c0 \uc54a\uc544 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ud6c4 \uc804\ub9dd\uacfc \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\uc624\uc804 \ud750\ub984\uc774 \uc9c0\uc18d\ub418\ub294\uc9c0, \uc77c\uc2dc\uc801 \uacfc\ub9e4\ub3c4\uc5d0 \uadf8\uce58\ub294\uc9c0\ub97c \uad6c\ubd84\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \ub2f9\uc77c \uc800\uac00 5,439.54 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0\uac00 \uccab \ud655\uc778 \uc9c0\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc800\uac00\ub97c \uc9c0\ud0a4\uc9c0 \ubabb\ud558\uba74 5,400\uc120 \uc544\ub798 \uad6c\uac04\uc774 \ub2e4\uc74c \uc9c0\uc9c0 \uad6c\uac04\uc73c\ub85c \uac70\ub860\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\ud55c\ub2e4\uba74 \uc2dc\uac00 5,786.13 \ud68c\ubcf5\uc774 \uc544\ub2c8\ub77c 5,500\uc120 \uc548\ucc29 \uc5ec\ubd80\uac00 \uba3c\uc800 \ud655\uc778\ub3fc\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 683.66 \uc800\uac00 \ubd80\uadfc\uacfc 690\uc120 \uc548\ucc29 \uc5ec\ubd80\ub97c \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70 \uac1c\ud45c \uacb0\uacfc\uc640 \ubbf8\uad6d \uc8fc\uac00\uc9c0\uc218 \uc120\ubb3c \ubc29\ud5a5\uc774 \uc624\ud6c4 \uc2ec\ub9ac\ub97c \uc88c\uc6b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \ub9e4\ub3c4 \ubc29\ud5a5\uc774 \uc624\ud6c4\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ub9c8\uac10 \ubb34\ub835 \uc218\uae09 \ud655\uc815\uce58\uac00 \uc5b4\ub5bb\uac8c \uc9d1\uacc4\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uac15\ud588\ub358 \ud1b5\uc2e0\uc0ac\xb7\ud0dc\uc591\uad11 \uad00\ub828 \ud14c\ub9c8\uc758 \uc0c1\ub300\uc801 \uac15\uc138\uac00 \uc624\ud6c4\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub4f1\uc774 \ub098\uc640\ub3c4 \uac70\ub798\ub7c9\uacfc \uc678\uad6d\uc778 \ub9e4\ub3c4 \ucd95\uc18c\uac00 \ub3d9\ubc18\ub418\uc9c0 \uc54a\uc73c\uba74 \ub418\ub3cc\ub9bc\uc73c\ub85c \ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \uae09\ub4f1 \ucd9c\ubc1c \ub4a4 \ubc18\uc804\ud574 \uc815\uc624 \ubb34\ub835 \ub450 \uc9c0\uc218 \ubaa8\ub450 \uc804\uc77c \ub300\ube44 2% \ub118\uac8c \ud558\ub77d\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-04-domestic-market-open","metadata":{"permalink":"/blog/en/market/2026-11-04-domestic-market-open","source":"@site/market/2026-11-04-domestic-market-open/index.mdx","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \uc804\uc77c \uae09\ub77d \ub4a4 \ubc18\ub4f1 \ucd9c\ubc1c\ud55c \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-04T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":7.16,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-04-domestic-market-open","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \uc804\uc77c \uae09\ub77d \ub4a4 \ubc18\ub4f1 \ucd9c\ubc1c\ud55c \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \uae09\ub4f1 \ucd9c\ubc1c \ub4a4 \ubc18\uc804\ud574 \ucf54\uc2a4\ud53c 5,460\uc120 \ubd80\uadfc","permalink":"/blog/en/market/2026-11-04-domestic-market-midday"},"nextItem":{"title":"2026\ub144 11\uc6d4 4\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-04-nasdaq-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 4\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ubc30\uacbd\\n\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 \ud63c\uc870 \uc18d\uc5d0\uc11c \ub098\uc2a4\ub2e5\uc774 \ubc18\ub4f1 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,372.01\ub85c \uc804\uc77c \ub300\ube44 207.65\ud3ec\uc778\ud2b8, 0.83% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,568.92\ub85c \uc804\uc77c \ub300\ube44 27.52\ud3ec\uc778\ud2b8, 0.36% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c\uc778 2026\ub144 11\uc6d4 3\uc77c \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ud06c\uac8c \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 5,648.79\ub85c \uc804\uc77c \ub300\ube44 3.59% \ud558\ub77d\ud588\uace0, \ucf54\uc2a4\ub2e5\uc740 704.39\ub85c \uc804\uc77c \ub300\ube44 4.08% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub7ec\ud55c \ubc30\uacbd \uc18d\uc5d0\uc11c \uc624\ub298 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc7a5 \ucd08\ubc18 \uc0c1\uc2b9\ud3ed\uc774 \uc2dc\uac00\ubcf4\ub2e4 \ucd95\uc18c\ub418\uace0 \uc788\uc5b4, \ubc18\ub4f1\uc758 \uc9c0\uc18d \uc5ec\ubd80\ub294 \uc7a5\uc911 \ud750\ub984\uc73c\ub85c \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,741.56 | +92.77 | +1.64% | 5,786.13 | 5,828.13 | 5,738.73 | 36,484\ucc9c\uc8fc | 2\uc870 6,797\uc5b5\uc6d0 | 2026-11-04 09:30 KST |\\n| \ucf54\uc2a4\ub2e5 | 707.73 | +3.34 | +0.47% | 715.74 | 718.34 | 707.73 | 133,878\ucc9c\uc8fc | 1\uc870 2,669\uc5b5\uc6d0 | 2026-11-04 09:30 KST |\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc740 \ubaa8\ub450 \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,786.13\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,741.56\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 715.74\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 707.73\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,648.79, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 704.39\uc785\ub2c8\ub2e4.<br/>\\n\uad50\ucc28 \uac80\uc99d\uc740 \ud604\uc7ac\uac00\ub97c \ub4f1\ub77d\ub960\ub85c \ub098\ub208 \uc5ed\uc0b0\uac12\uc73c\ub85c \uc218\ud589\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc624\ub298 \uc7a5 \uc624\ud508 \ubc18\ub4f1\uc758 \uc9c1\uc811\uc801\uc778 \ucd09\ub9e4\ub294 \uac04\ubc24 \ubbf8\uad6d \ubc18\ub3c4\uccb4\uc8fc \ubc18\ub4f1\uacfc \uc804\uc77c \uae09\ub77d\uc5d0 \ub530\ub978 \uc800\uac00 \ub9e4\uc218 \uc720\uc778\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70 \ub2f9\uc77c \ub274\uc695 \uc99d\uc2dc\ub294 \ud63c\uc870\uc600\uc9c0\ub9cc, \ubc18\ub3c4\uccb4\uc8fc\uac00 \ubc18\ub4f1\ud558\uba74\uc11c \ub098\uc2a4\ub2e5\uc774 0.83% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \ud750\ub984\uc740 \uad6d\ub0b4 \uc7a5 \uc624\ud508\uc5d0\uc11c \ub300\ud615 \uae30\uc220\uc8fc \uc911\uc2ec\uc758 \uc0c1\uc2b9 \ucd9c\ubc1c\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uad6d\ub0b4 \uc9c0\uc218\uac00 3% \ub118\uac8c \ud558\ub77d\ud55c \ub4a4\ub77c\ub294 \uc810\ub3c4 \ubc18\ub4f1\uc758 \ubc30\uacbd\uc785\ub2c8\ub2e4.<br/>\\n\uae09\ub77d \ub2e4\uc74c \ub0a0\uc5d0\ub294 \ud558\ub77d\ud3ed\uc774 \ucef8\ub358 \uc9c0\uc218\uc77c\uc218\ub85d \uae30\uc220\uc801 \ub418\ub3cc\ub9bc\uc774 \ub098\ud0c0\ub098\uae30 \uc27d\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc2dc\uac00 \ub300\ube44 \uc0c1\uc2b9\ud3ed\uc774 \ucd95\uc18c\ub41c \uc810\uc740 \ub418\ub3cc\ub9bc\uc758 \uac15\ub3c4\ub97c \uac00\ub2a0\ud558\ub294 \uccab \uc2e0\ud638\uc785\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \uc885\uac00 \ub300\ube44 2.43% \ub192\uc740 \uc218\uc900\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc9c0\ub9cc, \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \uc0c1\uc2b9\ub960\uc740 1.64%\ub85c \uc904\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \uc885\uac00 \ub300\ube44 1.61% \ub192\uc740 \uc218\uc900\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc9c0\ub9cc, \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \uc0c1\uc2b9\ub960\uc740 0.47%\ub85c \uc904\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 1,343.60\uc6d0 \uc218\uc900\uc73c\ub85c, \uc804\uc77c \ub300\ube44 \ud070 \ubcc0\ub3d9\uc740 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud658\uc728 \uae09\ubcc0\ub3d9\uc774 \uc7a5 \uc624\ud508\uc744 \ud754\ub4e0 \ud754\uc801\uc740 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810\uc5d0\uc11c\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n10\uc6d4 \uc678\ud658\ubcf4\uc720\uc561 \uc99d\uac00 \uc18c\uc2dd\uc740 \uac70\uc2dc\uc801\uc778 \uc644\ucda9 \uc5ec\ub825\uc744 \ubcf4\uc5ec\uc8fc\uc9c0\ub9cc, \uc7a5 \uc624\ud508 \ub2f9\uc77c\uc758 \uc9c1\uc811 \ucd09\ub9e4\ub85c \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\uacb0\uad6d \uc624\ub298 \ubc18\ub4f1\uc740 \uc0c8\ub85c\uc6b4 \ud638\uc7ac\ubcf4\ub2e4, \uc804\uc77c \uae09\ub77d\uacfc \uac04\ubc24 \ubbf8\uad6d \uae30\uc220\uc8fc \ubc18\ub4f1\uc774 \ub9de\ubb3c\ub9b0 \ub418\ub3cc\ub9bc \uc131\uaca9\uc774 \uac15\ud569\ub2c8\ub2e4.<br/>\\n\ub418\ub3cc\ub9bc\uc778\uc9c0 \ucd94\uc138 \uc804\ud658\uc778\uc9c0\ub294 \uc7a5\uc911 \uc218\uae09\uacfc \uc0c1\uc2b9\ud3ed \uc720\uc9c0 \uc5ec\ubd80\ub85c \uac00\ub9b4 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### 1. \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ub2f9\uc77c, \ubc18\ub3c4\uccb4\uc8fc \ubc18\ub4f1\uc5d0 \ub098\uc2a4\ub2e5 \uc0c1\uc2b9\\n\\n\uac04\ubc24 \ub274\uc695 \uc99d\uc2dc\ub294 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ub2f9\uc77c\uc5d0 \ud63c\uc870\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,372.01\ub85c 0.83% \uc0c1\uc2b9\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,568.92\ub85c 0.36% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4\uc8fc\uac00 4\uac70\ub798\uc77c \ub9cc\uc5d0 \ubc18\ub4f1\ud55c \uc810\uc774 \ub098\uc2a4\ub2e5 \uc0c1\uc2b9\uc744 \uc774\ub04c\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uacb0\uacfc\uc758 \ubd88\ud655\uc2e4\uc131 \uc18d\uc5d0\uc11c\ub3c4 \ub300\uae30\ud558\ub358 \uc790\uae08\uc774 \uae30\uc220\uc8fc\ub85c \uba3c\uc800 \uc6c0\uc9c1\uc600\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc2dc\uc7a5\uc5d0\ub294 \uac1c\uc7a5 \uc804\ubd80\ud130 \uae30\uc220\uc8fc \uc911\uc2ec\uc758 \ubc18\ub4f1 \uae30\ub300\uac00 \uc804\ub2ec\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc120\uac70 \uc774\ud6c4 \uc815\ucc45 \ubc29\ud5a5\uc774 \ud655\uc815\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \ubd88\ud655\uc2e4\uc131\uc774 \uc644\uc804\ud788 \ud574\uc18c\ub41c \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc774 \uc0ac\uac74\uc758 \uc2ec\ub9ac\uc801 \ucda9\uaca9\uc740 \uacf5\ud3ec \uc644\ud654 \ucabd\uc5d0 \uac00\uae5d\uace0, \uad6c\uc870\uc801\uc778 \ubc29\ud5a5 \uc804\ud658\uc73c\ub85c \ub2e8\uc815\ud558\uae30\ub294 \uc774\ub985\ub2c8\ub2e4.<br/>\\n\\n### 2. \uc804\uc77c \uad6d\ub0b4 \uae09\ub77d\uacfc \uac1c\uc778\uc758 \ub300\uaddc\ubaa8 \uc800\uac00 \ub9e4\uc218\\n\\n\uc804\uc77c \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ucf54\uc2a4\ud53c 3.59%, \ucf54\uc2a4\ub2e5 4.08% \ud558\ub77d\uc774\ub77c\ub294 \uac15\ud55c \uc870\uc815\uc744 \uacaa\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc870\uc815 \uad6d\uba74\uc5d0\uc11c \uac1c\uc778\uc740 \ucf54\uc2a4\ud53c\uc5d0\uc11c 1\uc870 6,388\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub3c4 \uac1c\uc778\uc740 3,180\uc5b5\uc6d0\uc744 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uc678\uad6d\uc778\uc740 \ucf54\uc2a4\ud53c\uc5d0\uc11c 1\uc870 5,086\uc5b5\uc6d0\uc744 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae09\ub77d \ub2f9\uc77c \uac1c\uc778\uc774 \ubb3c\ub7c9\uc744 \ubc1b\uc558\ub2e4\ub294 \uc810\uc774 \uc624\ub298 \ubc18\ub4f1\uc758 \uad6d\ub0b4 \uc218\uae09 \ubc30\uacbd\uc785\ub2c8\ub2e4.<br/>\\n\uac1c\uc778 \ub9e4\uc218\uac00 \ucd94\uc138\uc758 \ubc14\ub2e5\uc744 \ubcf4\uc7a5\ud558\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc804\uc77c \ub9e4\ub3c4 \uc8fc\uccb4\uc640 \ub9e4\uc218 \uc8fc\uccb4\uac00 \ub69c\ub837\ud558\uac8c \uac08\ub838\ub2e4\ub294 \uc810\uc740 \uc624\ub298 \uc7a5 \ucd08\ubc18 \uc218\uae09 \ud574\uc11d\uc758 \uae30\uc900\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\\n### 3. 10\uc6d4 \uc678\ud658\ubcf4\uc720\uc561 \uc99d\uac00\uc640 \ub300\uc678 \uc644\ucda9 \uc5ec\ub825 \ud655\uc778\\n\\n\ud55c\uad6d\uc740\ud589 \ubc1c\ud45c\uc5d0 \ub530\ub974\uba74 10\uc6d4 \ub9d0 \uc678\ud658\ubcf4\uc720\uc561\uc740 4,431\uc5b5 6\ucc9c\ub9cc \ub2ec\ub7ec\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n9\uc6d4 \ub9d0\ubcf4\ub2e4 26\uc5b5 \ub2ec\ub7ec \uc99d\uac00\ud588\uace0, \uc678\ud654\uc790\uc0b0 \uc6b4\uc6a9\uc218\uc775\uacfc \uae08\uc735\uae30\uad00 \uc678\ud654 \uc608\uc218\uae08 \uc99d\uac00\uac00 \uc6d0\uc778\uc73c\ub85c \uc124\uba85\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\uc758 \uc678\ud658\ubcf4\uc720\uc561 \uaddc\ubaa8\ub294 9\uc6d4 \ub9d0 \uae30\uc900 \uc138\uacc4 9\uc704 \uc218\uc900\uc73c\ub85c \uc9d1\uacc4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc18c\uc2dd\uc740 \ub2f9\uc77c \uc9c0\uc218\ub97c \uc9c1\uc811 \ub04c\uc5b4\uc62c\ub9ac\ub294 \uc7ac\ub8cc\ub77c\uae30\ubcf4\ub2e4, \ub300\uc678 \ucda9\uaca9\uc5d0 \ub300\ud55c \uc644\ucda9 \uc5ec\ub825\uc744 \ud655\uc778\ud558\ub294 \uc7ac\ub8cc\uc785\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc774 1,343\uc6d0\ub300\uc5d0\uc11c \uc548\uc815\ub41c \ud750\ub984\uc744 \ubcf4\uc778 \uc810\uacfc \ud568\uaed8 \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5 \uc2ec\ub9ac\uac00 \ubd88\uc548\ud560 \ub54c\uc5d0\ub294 \uc774\ub7ec\ud55c \uac70\uc2dc \uc9c0\ud45c\uac00 \ubcc0\ub3d9\uc131 \ud655\ub300\ub97c \uc81c\ud55c\ud558\ub294 \uc2ec\ub9ac\uc801 \uc9c0\uc9c0\uc120\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc678\ud658\ubcf4\uc720\uc561 \uc790\uccb4\uac00 \uc8fc\uac00 \ubc29\ud5a5\uc744 \uacb0\uc815\ud558\uc9c0\ub294 \uc54a\uc73c\ubbc0\ub85c, \uacfc\ub3c4\ud55c \uc758\ubbf8\ub97c \ubd80\uc5ec\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc801\uc808\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc139\ud130\xb7\ud14c\ub9c8 \uc601\ud5a5 \uccb4\uc778\\n\\n\uc7a5 \uc624\ud508 \ud14c\ub9c8 \ud750\ub984\uc740 \ud2b9\uc815 \uc5c5\uc885\ub9cc\uc758 \uac15\uc138\uac00 \uc544\ub2c8\ub77c, \ub418\ub3cc\ub9bc\uc774 \uc5ec\ub7ec \ud14c\ub9c8\ub85c \ubc88\uc9c4 \ubaa8\uc2b5\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \uc624\uc804 \ud14c\ub9c8 \uc0c1\uc2b9\ub960 \uc0c1\uc704\uc5d0\ub294 \ubc29\uc0b0 \uad00\ub828 \ud14c\ub9c8\uac00 4.23%, \uac74\uc124\uae30\uacc4\uac00 4.17%\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc120\uc5c5\uccb4\ub294 4.03%, \uc804\ub825\uae30\uae30\ub294 3.52%, PCB\ub294 3.40% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6b0\uc8fc \uad00\ub828 \ud14c\ub9c8\ub3c4 3.22% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5f0\uacb0\uace0\ub9ac\ub294 AI \ub370\uc774\ud130\uc13c\ud130 \ud22c\uc790\uc5d0\uc11c \uc2dc\uc791\ub429\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \ud655\ucda9\uc740 \uc804\ub825\uae30\uae30\uc640 \uc804\uc120 \uc218\uc694\ub85c \uc774\uc5b4\uc9c0\uace0, \uc804\ub825 \uc778\ud504\ub77c \uae30\ub300\ub294 \uad00\ub828 \ud14c\ub9c8\ub85c \ubc88\uc9d1\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \uc5c5\ud669 \uae30\ub300\ub294 \uae30\ud310\uacfc \uc7a5\ube44 \ucabd\uc73c\ub85c \uc5f0\uacb0\ub418\uba70, PCB \ud14c\ub9c8 \uc0c1\uc2b9\uacfc \uac19\uc740 \ubc29\ud5a5\uc744 \ubcf4\uc785\ub2c8\ub2e4.<br/>\\n\ubc29\uc0b0\uacfc \uc6b0\uc8fc \ud14c\ub9c8\ub294 \uc218\uc8fc \uae30\ub300\ub77c\ub294 \ubcc4\uac1c\uc758 \ucd95\uc73c\ub85c \uc6c0\uc9c1\uc774\uc9c0\ub9cc, \uc624\ub298\uc740 \ub418\ub3cc\ub9bc \uad6d\uba74\uc5d0\uc11c \ud568\uaed8 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc804\uc77c \uae09\ub77d\uc758 \ucda9\uaca9\uc774 \ucef8\ub358 \uc131\uc7a5\uc8fc \uc601\uc5ed\uc740 \ubc18\ub4f1\ud3ed\uc774 \uc2dc\uac00\ubcf4\ub2e4 \ucd95\uc18c\ub418\ub294 \uc591\uc0c1\uc744 \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uae08\ub9ac\uc640 \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc774 \uc644\uc804\ud788 \ud574\uc18c\ub418\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc2e0\ud638\ub85c \uc77d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud14c\ub9c8 \ub4f1\ub77d\ub960\ub9cc\uc73c\ub85c \uc5c5\uc885 \uc804\ud658\uc744 \ub2e8\uc815\ud558\uc9c0 \uc54a\uace0, \uc7a5\uc911\uc5d0\ub3c4 \uc774 \uc5f0\uacb0\uace0\ub9ac\uac00 \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 228,294 |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | 198,130 |\\n| 2026-11-03 | 5,715.19 | 5,735.92 | 5,615.80 | 5,648.79 | 207,371 |\\n| 2026-11-04 | 5,786.13 | 5,828.13 | 5,738.73 | 5,743.73 | 36,342 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 470,174 |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | 355,750 |\\n| 2026-11-03 | 723.92 | 723.92 | 702.34 | 704.39 | 430,571 |\\n| 2026-11-04 | 715.74 | 718.34 | 707.81 | 707.90 | 133,301 |\\n\\n2026\ub144 11\uc6d4 4\uc77c \ubd09\uc740 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc77c\ubd09 \ud45c\uc758 \ub2f9\uc77c \uc885\uac00\ub294 \ud45c \uc791\uc131 \uc2dc\uc810\uc758 \ud615\uc131 \uc911 \uc218\uce58\uc774\uba70 \uc2e4\uc2dc\uac04 \ud604\uc7ac\uac00\uc640 \uc2dc\ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c 5,648.79\uc5d0\uc11c \uc0c1\uc2b9 \ucd9c\ubc1c\ud574 5,740\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c 704.39\uc5d0\uc11c \uc0c1\uc2b9 \ucd9c\ubc1c\ud574 707\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc804\uc77c \uc218\uae09\\n\\n\uc804\uc77c\uc778 2026\ub144 11\uc6d4 3\uc77c \uc218\uae09\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +16,388 |\\n| \uc678\uad6d\uc778 | -15,086 |\\n| \uae30\uad00 | -4,941 |\\n| \uae30\ud0c0\ubc95\uc778 | +3,639 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +3,180 |\\n| \uc678\uad6d\uc778 | -713 |\\n| \uae30\uad00 | -2,359 |\\n| \uae30\ud0c0\ubc95\uc778 | -108 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub3c4 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uac1c\uc778 \uc21c\ub9e4\uc218 \uaddc\ubaa8\uac00 \uc774\ub0a0 \uc218\uae09\uc5d0\uc11c \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\ub3c4\ub85c \ubcf4\uba74, \uae09\ub77d \ub2f9\uc77c \uc678\uad6d\uc778\uc774 \ub358\uc9c4 \ubb3c\ub7c9\uc744 \uac1c\uc778\uc774 \ubc1b\uc558\ub2e4\ub294 \ud574\uc11d\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uae4c\uc9c0 \uc21c\ub9e4\ub3c4\uc5d0 \uac00\uc138\ud588\ub2e4\ub294 \uc810\uc740 \uae09\ub77d \ub2f9\uc77c \uae30\uad00\uc774 \ud558\ub77d\uc744 \ubc29\uc5b4\ud558\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc758\ubbf8\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc804\uc77c \ud558\ub77d\uc774 \ud2b9\uc815 \uc8fc\uccb4\uc758 \uc77c\uc2dc\uc801 \ub9e4\ub3c4\ub77c\uae30\ubcf4\ub2e4, \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \ud568\uaed8 \ubb3c\ub7c9\uc744 \uc904\uc778 \ub0a0\uc774\uc5c8\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc624\ub298 \ubc18\ub4f1\uc774 \uc774\uc5b4\uc9c0\ub824\uba74 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc758 \ub9e4\ub3c4\uc138\uac00 \uc57d\ud574\uc9c0\ub294\uc9c0\uac00 \ud575\uc2ec \ud655\uc778 \uc9c0\ud45c\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ub2e8\uae30\uc801\uc73c\ub85c\ub294 \ub418\ub3cc\ub9bc \uc9c0\uc18d\uacfc \ub418\ub3cc\ub9bc \uc18c\uba78\uc774\ub77c\ub294 \ub450 \uc2dc\ub098\ub9ac\uc624\uac00 \uac08\ub9bd\ub2c8\ub2e4.<br/>\\n\ub418\ub3cc\ub9bc\uc774 \uc9c0\uc18d\ub418\ub294 \uacbd\uc6b0, \ucf54\uc2a4\ud53c\ub294 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,741\uc120 \uc704\ub97c \uc720\uc9c0\ud558\uba70 \uc804\uc77c \uace0\uc810 \ubd80\uadfc\uc744 \uc2dc\ud5d8\ud558\uac8c \ub429\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uace0\uc810\uc740 5,735.92\uc600\uace0, \uc624\ub298 \uc2dc\uac00\ub294 \uc774\ubbf8 \uc774\ub97c \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 710\uc120 \uc548\ucc29 \uc5ec\ubd80\uac00 \uccab \uad00\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \ucf54\uc2a4\ub2e5\uc740 707.73\uc73c\ub85c 710\uc120\uc744 \ubc11\ub3cc\uace0 \uc788\uc5b4, 710\uc120 \ud68c\ubcf5\uc774 \ub2e8\uae30 \ud655\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub418\ub3cc\ub9bc\uc774 \uc18c\uba78\ub418\ub294 \uacbd\uc6b0, \ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \uc885\uac00 5,648.79 \ubd80\uadfc\uc73c\ub85c \ub418\ub3cc\uc544\uac00\uace0, \ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \uc800\uc810 702.34 \ubd80\uadfc\uc744 \uc2dc\ud5d8\ud558\uac8c \ub429\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 11\uc6d4 2\uc77c \uc885\uac00\uac00 \uae30\uc900\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c 5,859.08\uacfc \ucf54\uc2a4\ub2e5 734.36 \ud68c\ubcf5 \uc5ec\ubd80\uac00 \uc911\uae30 \ubc29\ud5a5\uc758 \ubd84\uae30\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uc218\uc900\uc744 \ud68c\ubcf5\ud558\uc9c0 \ubabb\ud558\uba74 \uc804\uc77c \uae09\ub77d\uc740 \ub2e8\uc21c \uc870\uc815\uc774 \uc544\ub2c8\ub77c, \uace0\uc810 \uc774\ud6c4\uc758 \ubcc0\ub3d9\uc131 \ud655\ub300 \uad6d\uba74\uc73c\ub85c \ud574\uc11d\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ud560 \uc774\ubca4\ud2b8\ub294 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uc774\ud6c4 \uc815\ucc45 \ubc29\ud5a5, \uad6d\ub0b4\uc678 \uc2e4\uc801 \ubc1c\ud45c, \uc6d0/\ub2ec\ub7ec \ud658\uc728\uc758 1,340\uc6d0\ub300 \uc720\uc9c0 \uc5ec\ubd80\uc785\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \ubc29\ud5a5\uc5d0 \ub300\ud55c \uc0c8\ub85c\uc6b4 \uc218\uce58\ub098 \ubc1c\uc5b8\uc774 \ub098\uc624\uba74 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ub300\ud55c \ud574\uc11d\uc774 \ub2e4\uc2dc \ubc14\ub014 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uc9c0\uc218\xb7\uc139\ud130 \ub2e8\uc704\uc758 \uc2dc\ub098\ub9ac\uc624 \uc815\ub9ac\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc5d0 \ub300\ud55c \ud310\ub2e8\uc740 \ud3ec\ud568\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 5,740\uc120 \ubd80\uadfc\uc5d0\uc11c \uc0c1\uc2b9\ud3ed\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 710\uc120\uc744 \ud68c\ubcf5\ud558\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uacfc \uae30\uad00\uc758 \uc7a5 \ucd08\ubc18 \uc218\uae09 \ubc29\ud5a5\uc774 \uc804\uc77c\uacfc \ub2ec\ub77c\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uae30\uc220\uc8fc \ubc18\ub4f1 \ud750\ub984\uc774 \uc7a5\uc911\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc774 1,343\uc6d0\ub300\uc5d0\uc11c \uc548\uc815\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uc7a5 \ucd08\ubc18 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \uc804\uc77c \uae09\ub77d \ub4a4 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ubc18\ub4f1 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-04-nasdaq-market-close","metadata":{"permalink":"/blog/en/market/2026-11-04-nasdaq-market-close","source":"@site/market/2026-11-04-nasdaq-market-close/index.mdx","title":"2026\ub144 11\uc6d4 4\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-04T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":6.14,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-04-nasdaq-market-close","title":"2026\ub144 11\uc6d4 4\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \uc804\uc77c \uae09\ub77d \ub4a4 \ubc18\ub4f1 \ucd9c\ubc1c\ud55c \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5","permalink":"/blog/en/market/2026-11-04-domestic-market-open"},"nextItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911, \ubbfc\uc8fc\ub2f9 \uc2a4\uc715 \ud655\uc815 \ud6c4 2%\ub300 \uac15\uc138 \uc9c0\uc18d","permalink":"/blog/en/market/2026-11-04-nasdaq-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 4\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc804\uc77c \ub300\ube44 \uc0c1\uc2b9\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9\ub960\uc740 1.44%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\ub3c4 \uc0c1\uc2b9\uc73c\ub85c \ub9c8\uac10\ud588\uc73c\uba70 \uc0c1\uc2b9\ub960\uc740 1.58%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 3.03% \uc0c1\uc2b9\ud574 \uc138 \uc9c0\uc218 \uac00\uc6b4\ub370 \uc0c1\uc2b9\ub960\uc774 \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c\uc5d0\ub294 \ub098\uc2a4\ub2e5\uc774 \uc624\ub974\uace0 \ub2e4\uc6b0\uc9c0\uc218\uac00 \ub0b4\ub838\ub358 \uac83\uacfc \ub2ec\ub9ac, \uc774\ub0a0\uc740 \uc138 \uc9c0\uc218\uac00 \ud568\uaed8 \uc62c\ub790\uace0 \ub2e4\uc6b0\uc9c0\uc218\uac00 \uc0c1\uc2b9\uc744 \uc8fc\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \ub2f9\uc77c \uace0\uac00 | \ub2f9\uc77c \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,736.51 | +364.50 | +1.44% | 25,372.01 | 26,048.83 | 25,602.14 |\\n| S&P500 | 7,688.62 | +119.70 | +1.58% | 7,568.92 | 7,712.12 | 7,649.39 |\\n| \ub2e4\uc6b0\uc9c0\uc218 | 53,356.12 | +1,569.40 | +3.03% | 51,786.72 | 53,492.40 | 52,410.23 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 11\uc6d4 4\uc77c 16\uc2dc 20\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 11\uc6d4 5\uc77c 06\uc2dc 20\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569 \uc218\uce58\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\ub294 \ubbf8\uad6d 11\uc6d4 4\uc77c 16\uc2dc 21\ubd84 \uc7a5\ub9c8\uac10 \uae30\uc900\uc73c\ub85c \uc885\uac00 25,736.51, \uc804\uc77c \ub300\ube44 364.50, \ub4f1\ub77d\ub960 1.44%\uac00 \ud45c\uc2dc\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc758 \ub098\uc2a4\ub2e5 \uc885\ud569 \uac12\ub3c4 \uc885\uac00 25,736.51, \uc804\uc77c \ub300\ube44 364.50, \ub4f1\ub77d\ub960 1.44%\ub85c \ub124\uc774\ubc84 \uac12\uacfc \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\nS&P500 \uc218\uce58\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \uc885\uac00\uc5d0\uc11c \uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc744 \ube7c\ub294 \ubc29\uc2dd\uc73c\ub85c \uc5ed\uc0b0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 \ub098\uc2a4\ub2e5 25,372.01, S&P500 7,568.92, \ub2e4\uc6b0\uc9c0\uc218 51,786.72\uc774\uba70, \uc138 \uac12 \ubaa8\ub450 \uc804 \uac70\ub798\uc77c \ub9c8\uac10 \uae00\uc758 \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc758 \ud45c\uc2dc\uac12\uc785\ub2c8\ub2e4.<br/>\\nS&P500 \ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 \ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4\uc758 \ucd5c\ub300\uac12\uacfc \ucd5c\uc18c\uac12\uc73c\ub85c \uc0b0\ucd9c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218 \uc218\uce58\ub294 Yahoo Finance \uc77c\ubd09\uc73c\ub85c \ud655\uc778\ud55c \uac12\uc774\uba70, \uac19\uc740 \uc77c\ubd09\uc758 \ub098\uc2a4\ub2e5 \uc218\uce58\uac00 \ub124\uc774\ubc84 \ub9c8\uac10 \uc218\uce58\uc640 \uc2dc\uac00\uc640 \uace0\uac00\uc640 \uc800\uac00\uc640 \uc885\uac00\uae4c\uc9c0 \uc77c\uce58\ud574 \uc77c\ubd09 \uae30\uc900\uc758 \uc815\ud569\uc131\uc744 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc640 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub9c8\uac10 \uc6d0\uc778\uc740 \ubcf8\ubb38\uc5d0 \uc4f0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc774\ub0a0 \uc0c1\uc2b9\uc758 \ud45c\uba74\uc801 \uc774\uc720\ub294 \uc911\uac04\uc120\uac70 \uacb0\uacfc \ud655\uc815 \uc774\ud6c4\uc758 \uc548\ub3c4\uac10\uc785\ub2c8\ub2e4.<br/>\\n\uadfc\ubcf8 \ucd09\ub9e4\ub294 \uc138 \uac00\uc9c0\ub85c \uc555\ucd95\ub429\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud558\uba74\uc11c \ubd84\uc810 \uc815\ubd80\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \ucee4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ec\ub2f9\uacfc \uc758\ud68c\uac00 \ub098\ub258\uba74 \uae09\uaca9\ud55c \uc815\ucc45 \ubcc0\ud654\uac00 \uc904\uc5b4\ub4e4 \uac83\uc774\ub77c\ub294 \uae30\ub300\uac00 \ubd88\ud655\uc2e4\uc131 \ud504\ub9ac\ubbf8\uc5c4\uc744 \ub0ae\ucdc4\uc2b5\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uad6d\uc81c\uc720\uac00\uac00 \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d\ud558\uba74\uc11c \uc778\ud50c\ub808\uc774\uc158\uacfc \ube44\uc6a9 \ubd80\ub2f4\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uc644\ud654\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ube0c\ub80c\ud2b8\uc720\ub294 \ubc30\ub7f4\ub2f9 94.62\ub2ec\ub7ec\ub85c 8.7% \ud558\ub77d\ud574 \ub9c8\uac10\ud588\uace0, \uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0 \uc6d0\uc720\ub294 \ubc30\ub7f4\ub2f9 88.12\ub2ec\ub7ec\ub85c 8.3% \ud558\ub77d\ud574 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uae08\ub9ac \uc548\uc815 \uae30\ub300\uac00 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc744 \ub35c\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub525\uc11c\uce58\ub85c \ud655\uc778\ud55c \uad6d\ub0b4 \uc99d\uad8c\uac00 \ubd84\uc11d\uc5d0\uc11c\ub294 \ubbfc\uc8fc\ub2f9\uc758 \uc758\ud68c \uc7a5\uc545\uc774 \uad6d\ucc44\uae08\ub9ac \ud558\ub77d\uc73c\ub85c \uc774\uc5b4\uc9c8 \uacbd\uc6b0 \uc99d\uc2dc\uc5d0 \uae0d\uc815\uc801\uc774\ub77c\ub294 \ud3c9\uac00\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc7a5 \ub9c8\uac10 \uc2dc\uc810\uc758 \ubbf8\uad6d 10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960 \uc885\uac00\ub294 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc73c\ubbc0\ub85c, \uae08\ub9ac \uacbd\ub85c\uc5d0 \ub300\ud55c \ucd5c\uc885 \ud310\ub2e8\uc740 \ud655\uc778 \ud544\uc694\ub85c \ub0a8\uaca8\ub461\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c\uacfc \ube44\uad50\ud558\uba74 \uc9c0\uc218 \uac04 \ud798\uc758 \ubc30\uce58\uac00 \ub4a4\uc9d1\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c\uc5d0\ub294 \ub098\uc2a4\ub2e5\uc774 0.83% \uc624\ub974\uace0 \ub2e4\uc6b0\uc9c0\uc218\uac00 0.38% \ub0b4\ub838\uc9c0\ub9cc, \uc774\ub0a0\uc740 \ub2e4\uc6b0\uc9c0\uc218\uac00 3.03% \uc624\ub974\uba70 \ub098\uc2a4\ub2e5 \uc0c1\uc2b9\ub960 1.44%\ub97c \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc0c1\uc2b9 \ub3d9\ub825\uc774 \uae30\uc220\uc8fc\uc5d0\ub9cc \ud3b8\uc911\ub418\uc9c0 \uc54a\uace0 \ub300\ud615 \uc6b0\ub7c9\uc8fc\uc640 \ubc29\uc5b4 \uc139\ud130\uae4c\uc9c0 \ub113\uac8c \ud37c\uc84c\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n\uccab\uc9f8, \ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc11d\uad8c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n3\uc77c(\ud604\uc9c0\uc2dc\uac04) \ud22c\ud45c \ub4a4 4\uc77c\uc5d0\ub294 \ubbfc\uc8fc\ub2f9\uc758 \uc591\uc6d0 \uc7a5\uc545 \ud750\ub984\uc774 \uc2dc\uc7a5 \uac00\uaca9\uc5d0 \ubcf8\uaca9\uc801\uc73c\ub85c \ubc18\uc601\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5\uc774 \uc8fc\ubaa9\ud55c \uac83\uc740 \ud2b9\uc815 \uc815\ub2f9\uc758 \uc2b9\ud328 \uc790\uccb4\ubcf4\ub2e4 \ubd84\uc810 \uc815\ubd80\ub85c \uc778\ud55c \uc815\ucc45 \ubcc0\ud654 \uc18d\ub3c4 \ub454\ud654\uc785\ub2c8\ub2e4.<br/>\\n\uc815\ucc45 \ubd88\ud655\uc2e4\uc131\uc774 \uc904\uc5b4\ub4e4\uba74 \uae30\uc5c5 \ud22c\uc790\uc640 \uc18c\ube44 \uacc4\ud68d\uc758 \uac00\uc815\uc774 \uc548\uc815\ub418\uace0, \uc774\ub294 \uc704\ud5d8\uc790\uc0b0 \uc804\ubc18\uc758 \ud560\uc778\uc728\uc744 \ub0ae\ucd94\ub294 \ucabd\uc73c\ub85c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc758\ud68c \uc7a5\uc545 \uc774\ud6c4 \uc2e4\uc81c \uc785\ubc95 \ubc29\ud5a5\uc774 \uc5b4\ub5bb\uac8c \uc815\ud574\uc9c8\uc9c0\ub294 \uc544\uc9c1 \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc73c\ubbc0\ub85c, \uc774\ub0a0 \uc0c1\uc2b9\ub9cc\uc73c\ub85c \uc911\uae30 \uc815\ucc45 \ud6a8\uacfc\ub97c \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\ub458\uc9f8, \uad6d\uc81c\uc720\uac00\uac00 8% \uc548\ud30e\uc73c\ub85c \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ube0c\ub80c\ud2b8\uc720 \uc120\ubb3c\uc740 8.98\ub2ec\ub7ec \ud558\ub77d\ud55c \ubc30\ub7f4\ub2f9 94.62\ub2ec\ub7ec\ub85c \ub9c8\uac10\ud588\uace0, \uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0 \uc6d0\uc720 \uc120\ubb3c\uc740 7.97\ub2ec\ub7ec \ud558\ub77d\ud55c \ubc30\ub7f4\ub2f9 88.12\ub2ec\ub7ec\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc720\uc885 \ubaa8\ub450 8\uc6d4 31\uc77c \uc774\ud6c4 \ucd5c\uc800 \uc218\uc900\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\uc758 \ubc30\uacbd\uc73c\ub85c\ub294 \ubbfc\uc8fc\ub2f9 \uc758\ud68c \uc7a5\uc545 \uc774\ud6c4 \ubbf8\uad6d\uacfc \uc774\uc2a4\ub77c\uc5d8\uc758 \uc774\ub780 \uc804\uc7c1 \uc885\uacb0 \uae30\ub300\uac00 \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc740 \uc5d0\ub108\uc9c0 \uc139\ud130\uc5d0\ub294 \ubd80\ub2f4\uc774\uc9c0\ub9cc, \uc6b4\uc1a1\uacfc \uc81c\uc870\uc640 \uc18c\ube44 \uc139\ud130\uc758 \ube44\uc6a9 \ubd80\ub2f4\uc744 \ub35c\uc5b4\uc8fc\ub294 \ucabd\uc73c\ub85c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc774 \uc804\uc7c1 \uc885\uacb0 \uae30\ub300\uc5d0 \uae30\ubc18\ud55c \uac83\uc778 \ub9cc\ud07c, \uc2e4\uc81c \uc678\uad50 \uc804\uac1c\uac00 \ud655\uc778\ub418\uc9c0 \uc54a\uc73c\uba74 \ub418\ub3cc\ub9bc\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\uc14b\uc9f8, \uc790\uae08\uc774 \ub300\ud615\uc8fc\uc640 \ubc29\uc5b4 \uc139\ud130\ub85c \uc774\ub3d9\ud558\uba74\uc11c \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828\uc8fc\ub294 \uc555\ubc15\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ubcf4\ub3c4 \uae30\uc900\uc73c\ub85c\ub294 \ub300\ud615 \ud50c\ub7ab\ud3fc \uae30\uc5c5\uacfc \uc18c\ub9e4\uc640 \ud544\uc218\uc18c\ube44 \uad00\ub828\uc8fc\uac00 \uac15\uc138\ub97c \ubcf4\uc778 \ubc18\uba74, \uc77c\ubd80 \ubc18\ub3c4\uccb4\uc640 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828\uc8fc\ub294 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9 \uc758\ud68c \uc544\ub798\uc5d0\uc11c \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uac15\ud654 \uac00\ub2a5\uc131\uc774 \uac70\ub860\ub41c \uc810\uc774 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790\uc5d0 \ub300\ud55c \uc6b0\ub824\ub85c \uc5f0\uacb0\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc790\uccb4\uac00 \uaebe\uc600\ub2e4\ub294 \uc2e0\ud638\ub77c\uae30\ubcf4\ub2e4, \ud22c\uc790 \uc18d\ub3c4\uc640 \uaddc\uc81c \ube44\uc6a9\uc5d0 \ub300\ud55c \uc7ac\ud3c9\uac00\uac00 \uc9c4\ud589 \uc911\uc774\ub77c\ub294 \uc2e0\ud638\ub85c \ubcf4\ub294 \uac83\uc774 \uc801\uc808\ud569\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \ubc29\ud5a5\uc774 \uad6c\uccb4\ud654\ub418\uae30 \uc804\uc5d0\ub294 \uad00\ub828 \uc139\ud130\uc758 \ubcc0\ub3d9\uc131\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\ub098\uc2a4\ub2e5\uc758 \uc0c1\uc2b9\uc740 \ub300\ud615 \ud50c\ub7ab\ud3fc \uae30\uc5c5\uc758 \uac15\uc138\uac00 \ubc1b\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ubcf4\ub3c4 \uae30\uc900\uc73c\ub85c\ub294 \ub300\ud615 \uae30\uc220 \ud50c\ub7ab\ud3fc \uae30\uc5c5\uc758 \uc0c1\uc2b9\ub960\uc774 \ub450\ub4dc\ub7ec\uc84c\uace0, \uc774\ub294 \ub098\uc2a4\ub2e5 \uc0c1\uc2b9\ub960 1.44%\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\uc740 \uae30\uc220\uc8fc \ube44\uc911\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub0ae\uc9c0\ub9cc \uae08\uc735\uacfc \ud544\uc218\uc18c\ube44\uc640 \ud1b5\uc2e0\uc11c\ube44\uc2a4 \ub4f1 \ub113\uc740 \uc139\ud130\uac00 \ud568\uaed8 \uc624\ub974\uba74\uc11c 1.58% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc0b0\uc5c5\uc7ac\uc640 \uac00\uce58\uc8fc\uc640 \uc6b0\ub7c9\uc8fc \ube44\uc911\uc774 \ub192\uc544 \ubc29\uc5b4 \uc139\ud130\ub85c\uc758 \uc790\uae08 \uc774\ub3d9 \uc218\ud61c\uac00 \uac00\uc7a5 \ucef8\uace0, 3.03% \uc0c1\uc2b9\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5f0\uacb0\uace0\ub9ac\ub294 \uc815\uce58\uc5d0\uc11c \uc2dc\uc791\ud574 \uae08\ub9ac\uc640 \uc720\uac00\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\ubd84\uc810 \uc815\ubd80 \uae30\ub300\ub294 \uc815\ucc45 \ubd88\ud655\uc2e4\uc131\uc744 \ub0ae\ucd94\uace0 \uae08\ub9ac \uc548\uc815 \uae30\ub300\ub85c \uc5f0\uacb0\ub410\uc73c\uba70, \uc774\ub294 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc744 \ub35c\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \uae09\ub77d\uc740 \uc5d0\ub108\uc9c0 \uc139\ud130\uc5d0\ub294 \ubd80\ub2f4\uc774\uc9c0\ub9cc, \uc5d0\ub108\uc9c0 \uc18c\ube44 \uc139\ud130\uc758 \ube44\uc6a9 \ubd80\ub2f4\uc744 \ub0ae\ucd94\ub294 \ucabd\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uad00\ub828\uc8fc\ub294 \uaddc\uc81c \uc6b0\ub824\ub77c\ub294 \uc0c8\ub85c\uc6b4 \uc5f0\uacb0\uace0\ub9ac\ub97c \ub9cc\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\uaddc\uc81c \ube44\uc6a9 \uc6b0\ub824\uac00 \ucee4\uc9c0\uba74 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \uc18d\ub3c4\uc5d0 \ub300\ud55c \uac00\uc815\uc774 \ubc14\ub00c\uace0, \uc774\ub294 \ubc18\ub3c4\uccb4\uc640 \ub370\uc774\ud130\uc13c\ud130 \ubc38\ub958\uccb4\uc778 \uc804\ubc18\uc758 \ubcc0\ub3d9\uc131\uc73c\ub85c \ubc88\uc9d1\ub2c8\ub2e4.<br/>\\n\uc815\ub9ac\ud558\uba74 \uc774\ub0a0\uc740 \uae30\uc220\uc8fc\ub9cc\uc758 \uc0c1\uc2b9\uc774 \uc544\ub2c8\ub77c, \uc815\uce58 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c\uc640 \uc720\uac00 \ud558\ub77d\uc774\ub77c\ub294 \ub450 \uac00\uc9c0 \uc644\ud654\uac00 \uc6b0\ub7c9\uc8fc\uc640 \ubc29\uc5b4 \uc139\ud130\uae4c\uc9c0 \ub113\uac8c \ud37c\uc9c4 \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7S&P500 \ub9c8\uac10 \ud750\ub984\\n\\nS&P500\uc740 7,688.62\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 +119.70, \ub4f1\ub77d\ub960\uc740 +1.58%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,568.92\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \ub2f9\uc77c \uace0\uac00\ub294 7,712.12, \ub2f9\uc77c \uc800\uac00\ub294 7,649.39\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 53,356.12\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 +1,569.40, \ub4f1\ub77d\ub960\uc740 +3.03%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\nYahoo Finance \uc77c\ubd09 \uae30\uc900 \ub2e4\uc6b0\uc9c0\uc218 \ub2f9\uc77c \uace0\uac00\ub294 53,492.40, \ub2f9\uc77c \uc800\uac00\ub294 52,410.23\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\uacfc \ub2e4\uc6b0\uc9c0\uc218\uac00 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub354 \ud06c\uac8c \uc62c\ub790\ub2e4\ub294 \uc810\uc5d0\uc11c, \uc774\ub0a0 \uc0c1\uc2b9 \ub3d9\ub825\uc740 \uae30\uc220\uc8fc\ubcf4\ub2e4 \uc2dc\uc7a5 \uc804\ubc18\uacfc \uc6b0\ub7c9\uc8fc \ucabd\uc5d0 \ub354 \ub113\uac8c \ud37c\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \ub2e4\uc74c \uac70\ub798\uc77c \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ud750\ub984 \uc9c0\uc18d\uacfc \uc77c\uc2dc\uc801 \uc548\ub3c4 \ub7a0\ub9ac\ub97c \uad6c\ubd84\ud558\ub294 \uae30\uc900\uc740 \uc138 \uac00\uc9c0\uc785\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uc800\uac00 25,602.14 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uac04\uc774 \uc9c0\ucf1c\uc9c0\uba74 \ubc18\ub4f1 \ud750\ub984\uc774 \uc774\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uace0\uac00 26,048.83 \ubd80\uadfc\uacfc 26,000 \uad6c\uac04\uc744 \ud68c\ubcf5\ud574 \uc720\uc9c0\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uace0\uac00 \uad6c\uac04\uc744 \ud68c\ubcf5\ud558\uc9c0 \ubabb\ud558\uace0 \ub418\ubc00\ub9ac\uba74 \uc774\ub0a0 \uc0c1\uc2b9\uc740 \ub2e8\uae30 \uc548\ub3c4 \ub7a0\ub9ac\uc5d0 \uadf8\uce60 \uac00\ub2a5\uc131\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uad6d\uc81c\uc720\uac00\uac00 94\ub2ec\ub7ec \ubd80\uadfc\uc5d0\uc11c \uc548\uc815\ub418\ub294\uc9c0, \ub2e4\uc2dc \ubc18\ub4f1\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ub418\ub3cc\ub9bc\uc774 \ub098\ud0c0\ub098\uba74 \ube44\uc6a9 \ubd80\ub2f4 \uc644\ud654 \ud6a8\uacfc\ub3c4 \ud568\uaed8 \uc57d\ud574\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uac70\ub798\uc77c \uc774\ud6c4 \ud655\uc778\ud560 \uc774\ubca4\ud2b8\ub85c\ub294 11\uc6d4 6\uc77c\ub85c \uc608\uc815\ub41c 10\uc6d4 \uace0\uc6a9\uc9c0\ud45c\uc640 \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4 \uad00\uacc4\uc790 \ubc1c\uc5b8\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uace0\uc6a9\uc9c0\ud45c\uac00 \uc608\uc0c1\uc744 \ud06c\uac8c \ubc97\uc5b4\ub098\uba74 \uae08\ub9ac \uacbd\ub85c\uc5d0 \ub300\ud55c \uac00\uc815\uc774 \ub2e4\uc2dc \ubc14\ub00c\uba74\uc11c \uc9c0\uc218 \ubc29\ud5a5\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 \uc911\uac04\uc120\uac70 \uc774\ud6c4 \uc2e4\uc81c \uc785\ubc95 \ubc29\ud5a5\uacfc \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \ub17c\uc758\uac00 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\uc815\ucc45 \ubc29\ud5a5\uc774 \uad6c\uccb4\ud654\ub418\uae30 \uc804\uc5d0\ub294 \ud558\ub8e8\uc758 \uae09\ub4f1\ub9cc\uc73c\ub85c \ucd94\uc138 \uc804\ud658\uc744 \ub2e8\uc815\ud558\uc9c0 \uc54a\uace0, \uc800\uac00 \uc9c0\uc9c0 \uc5ec\ubd80\uc640 \uc139\ud130 \ud655\uc0b0 \uc5ec\ubd80\ub97c \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc5d0\uc11c \uc81c\uc2dc\ud55c \uad6c\uac04\uacfc \uc2dc\ub098\ub9ac\uc624\ub294 \uc9c0\uc218\uc640 \uc139\ud130 \ub2e8\uc704\uc758 \ucc38\uace0 \uae30\uc900\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \ud310\ub2e8 \uadfc\uac70\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n2026\ub144 11\uc6d4 4\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc740 \uc815\uce58 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c\uc640 \uc720\uac00 \uae09\ub77d\uc774 \uacb9\uce58\uba74\uc11c \uc138 \uc9c0\uc218\uac00 \ud568\uaed8 \uc0c1\uc2b9\ud55c \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub294 \uc800\uac00 \uc9c0\uc9c0 \uc5ec\ubd80\uc640 \uc720\uac00 \uc548\uc815 \uc5ec\ubd80\uc640 \uace0\uc6a9\uc9c0\ud45c \ubc1c\ud45c\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.<br/>"},{"id":"2026-11-04-nasdaq-market-midday","metadata":{"permalink":"/blog/en/market/2026-11-04-nasdaq-market-midday","source":"@site/market/2026-11-04-nasdaq-market-midday/index.mdx","title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911, \ubbfc\uc8fc\ub2f9 \uc2a4\uc715 \ud655\uc815 \ud6c4 2%\ub300 \uac15\uc138 \uc9c0\uc18d","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-04T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":7.47,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-04-nasdaq-market-midday","title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911, \ubbfc\uc8fc\ub2f9 \uc2a4\uc715 \ud655\uc815 \ud6c4 2%\ub300 \uac15\uc138 \uc9c0\uc18d","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 11\uc6d4 4\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-04-nasdaq-market-close"},"nextItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ubbfc\uc8fc\ub2f9 \uc591\uc6d0 \uc7a5\uc545 \ud6c4 \uae09\ubc18\uc804 \uac15\uc138 \ucd9c\ubc1c","permalink":"/blog/en/market/2026-11-04-nasdaq-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 4\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5\uc911 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc7a5\uc911 25,913.52\ub85c \uc804\uc77c \ub300\ube44 541.51\ud3ec\uc778\ud2b8, 2.13% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub3c4 7,710.23\uc73c\ub85c 141.31\ud3ec\uc778\ud2b8, 1.87% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0\uc740 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \uacb0\uacfc \ud655\uc815 \ub2e4\uc74c \ub0a0\uc758 \uc7a5\uc785\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud588\ub2e4\ub294 \uacb0\uacfc\uac00 \ud655\uc815\ub418\uba74\uc11c, \uc7a5 \ucd08\ubc18\uc758 \uac15\uc138\uac00 \uc7a5\uc911\uae4c\uc9c0 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\ud45c \ucd08\ubc18 \uc120\ubb3c \uae09\ub77d\uc774\ub77c\ub294 \ubcc0\ub3d9\uc131\uc744 \uac70\uce5c \ub4a4\uc758 \ubc18\uc804\uc774\ub77c\ub294 \uc810\uc774 \uc774\ub0a0 \ud750\ub984\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,913.52 | +541.51 | +2.13% | 25,372.01 | 26,028.32 | 25,602.14 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-04 12:57, \ud55c\uad6d\uc2dc\uac04 2026-11-05 02:57 |\\n| \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 | 7,710.23 | +141.31 | +1.87% | 7,568.92 | 7,710.76 | 7,649.39 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-04 12:57, \ud55c\uad6d\uc2dc\uac04 2026-11-05 02:57 |\\n| \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | 51,786.72 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-04 12:57, \ud55c\uad6d\uc2dc\uac04 2026-11-05 02:57 |\\n\\n\ub2f9\uc77c \uc218\uce58\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc758 \uc2dc\uac00\ub294 25,652.78\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00\uc640 \uc800\uac00\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uc7a5\uc911 \uc2dc\uacc4\uc5f4\uc758 \ucd5c\ub300\uac12\uacfc \ucd5c\uc18c\uac12\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 \uc9c1\uc811 \uc870\ud68c \uc2dc \uac00\uaca9 \ub370\uc774\ud130\ub97c \ud3ec\ud568\ud55c \ubcf8\ubb38\uc744 \ud655\ubcf4\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uc704 \uc2a4\ub0c5\uc0f7\uc740 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uc73c\ub85c \ucc44\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uac12\uc740 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uacfc [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569 \uac00\uaca9](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0 \ub2e4\uc6b0 \ud56d\ubaa9\uc774 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc544 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\ud45c\uba74\uc801\uc73c\ub85c\ub294 \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \ub300\ube44 2.13% \uac15\uc138\uc785\ub2c8\ub2e4.<br/>\\n\uadfc\ubcf8 \ucd09\ub9e4\ub294 \ub124 \uac00\uc9c0\ub85c \uc815\ub9ac\ub429\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \uc120\uac70 \uacb0\uacfc\uc758 \ud655\uc815\uc785\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud588\ub2e4\ub294 \uacb0\uacfc\uac00 \ud655\uc815\ub418\uba74\uc11c, \ubd84\ub2e8 \uc815\ubd80\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \uc815\ucc45 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c \uc694\uc778\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd5c\uc885 \uc758\uc11d\uc218\ub294 \uc544\uc9c1 \uc9d1\uacc4 \uc911\uc778 \ubd80\ubd84\ub3c4 \uc788\uc73c\ubbc0\ub85c, \uc758\uc11d\uc218 \uc790\uccb4\ub97c \ud655\uc815 \uc218\uce58\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc120\ubb3c \uae09\ub77d \ud6c4 \ubc18\uc804\uc785\ub2c8\ub2e4.<br/>\\n\uac1c\ud45c \ucd08\ubc18\uc5d0\ub294 \ub098\uc2a4\ub2e5 100 \uc120\ubb3c\uc774 2.4%\uae4c\uc9c0 \ud558\ub77d\ud558\uace0 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc120\ubb3c\uc774 1.4%\uae4c\uc9c0 \ud558\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ud6c4 \ub099\ud3ed\uc740 \ub300\ubd80\ubd84 \ub418\ub3cc\ub824\uc84c\uace0, \uac1c\uc7a5 \uc774\ud6c4\uc5d0\ub294 \uac15\uc138 \ud750\ub984\uc774 \uc7a5\uc911\uae4c\uc9c0 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc778\uacf5\uc9c0\ub2a5 \uc218\uc694 \uc99d\uac70\uc785\ub2c8\ub2e4.<br/>\\n11\uc6d4 3\uc77c \uc7a5 \ub9c8\uac10 \ud6c4 \uc778\uacf5\uc9c0\ub2a5 \uc218\uc694 \uac15\uc138\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc2e4\uc801 \uc7ac\ub8cc\uac00 \uc774\uc5b4\uc84c\uace0, \uc774\ub294 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uc640 \uc815\ubc18\ub300 \ubc29\ud5a5\uc758 \uc7ac\ub8cc\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911\uc5d0\ub294 \uc218\uc694 \uc99d\uac70 \ucabd\uc774 \ub354 \uac15\ud558\uac8c \ubc18\uc601\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \ub418\ub3cc\ub9bc\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 11\uc6d4 3\uc77c \ubc18\ub4f1\ud558\uae30 \uc804\uae4c\uc9c0 3\uac70\ub798\uc77c \uc5f0\uc18d \ud558\ub77d\ud588\uace0, \ub098\uc2a4\ub2e5 100 \uc9c0\uc218\ub294 11\uc6d4 2\uc77c\uc5d0 \uae30\uc220\uc801 \uc870\uc815 \uad6c\uac04 \uc9c4\uc785\uc774 \ud655\uc778\ub410\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub099\ud3ed\uc774 \ub204\uc801\ub41c \ub4a4\uc5d0\ub294 \ub2e8\uae30 \ub418\ub3cc\ub9bc \ub9e4\uc218\uac00 \ub4e4\uc5b4\uc624\uae30 \uc26c\uc6b4 \uad6c\uac04\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc9c0\uc218 \uac04 \ubc29\ud5a5 \ucc28\uc774\ub3c4 \uc758\ubbf8\ub97c \uac00\uc9d1\ub2c8\ub2e4.<br/>\\n11\uc6d4 3\uc77c \ub098\uc2a4\ub2e5\uc740 0.83% \uc0c1\uc2b9\ud588\uace0 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 0.36% \uc0c1\uc2b9\ud588\uc9c0\ub9cc, \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 0.38% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc7a5\uc911\uc740 \uc774 \uad6c\ub3c4\uac00 \ubc14\ub00c\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc0c1\uc2b9\ub960 2.13%\uac00 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218 \uc0c1\uc2b9\ub960 1.87%\ub97c \uc6c3\ub3cc\uc558\uace0, \uc678\uc2e0 \ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \ub2e4\uc6b0\ub3c4 \uc7a5 \ucd08\ubc18 2.5% \uc548\ud30e\uc758 \uac15\uc138\ub97c \ubcf4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc220\uc8fc \uc911\uc2ec\uc758 \ubc18\ub4f1\uc774 \uc9c0\uc218 \uc804\ubc18\uc758 \uc0c1\uc2b9\uc73c\ub85c \ud655\uc0b0\ub418\ub294 \uad6c\ub3c4\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uad6d\ucc44\uc218\uc775\ub960\uacfc \ub2ec\ub7ec\uc758 \ub2f9\uc77c \uc7a5\uc911 \ud655\uc815 \uc218\uce58\ub294 \ubcc4\ub3c4\ub85c \ud655\uc778\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc740 4.92% \uc548\ud30e\uc73c\ub85c \ud558\ub77d \ubc29\ud5a5\uc774\uc5c8\uace0, \ubcc0\ub3d9\uc131 \uc9c0\uc218\ub294 16% \ud558\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uc775\ub960 \ud558\ub77d\uacfc \ubcc0\ub3d9\uc131 \ucd95\uc18c\ub294 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc744 \ub35c\uc5b4\uc8fc\ub294 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n\uccab\uc9f8, \ubbfc\uc8fc\ub2f9 \uc591\uc6d0 \uc7a5\uc545 \ud655\uc815\uacfc \ud2b8\ub7fc\ud504 \ub300\ud1b5\ub839\uc758 \uacb0\uacfc \uc218\uc6a9\uc785\ub2c8\ub2e4.<br/>\\n\ub85c\uc774\ud130 \ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \ubbfc\uc8fc\ub2f9\uc740 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud588\uace0, \ud14d\uc0ac\uc2a4\uc640 \uc624\ud558\uc774\uc624 \ub4f1 \uacf5\ud654\ub2f9 \uac15\uc138 \uc9c0\uc5ed\uc5d0\uc11c\ub3c4 \uc758\uc11d\uc744 \ub4a4\uc9d1\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud2b8\ub7fc\ud504 \ub300\ud1b5\ub839\uc740 \uc120\uac70 \uacb0\uacfc\ub97c \uc218\uc6a9\ud558\uaca0\ub2e4\ub294 \uc785\uc7a5\uc744 \ubc1d\ud614\uace0, \uc774\ub780\uacfc\uc758 \uc804\uc7c1\uc5d0 \ub530\ub978 \uace0\uc720\uac00 \ubd80\ub2f4\uc774 \uacf5\ud654\ub2f9 \ud328\ubc30\uc758 \ud55c \uc694\uc778\uc774\ub77c\uace0 \uc5b8\uae09\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2ec\ub9ac\uc801\uc73c\ub85c\ub294 \uacb0\uacfc \ubd88\ubcf5\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uc7a6\uc544\ub4e4\uba74\uc11c, \uac1c\ud45c \ucd08\ubc18\uc758 \uc120\ubb3c \uae09\ub77d\uc774 \ubc18\uc804\ub418\ub294 \uacc4\uae30\uac00 \ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\uc870\uc801\uc73c\ub85c\ub294 \ubd84\ub2e8 \uc815\ubd80\uac00 \ub4e4\uc5b4\uc11c\uba74\uc11c, \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c\uc640 \ub370\uc774\ud130\uc13c\ud130\uc5d0 \ub300\ud55c \uaddc\uc81c \uacbd\ub85c\uac00 \uc758\ud68c \ub17c\uc758\uc5d0 \ub354 \ud06c\uac8c \uc88c\uc6b0\ub418\ub294 \uad6c\uc870\uac00 \ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uacb0\uacfc\uac00 \ud655\uc815\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \ubc29\ud5a5\uc131 \ubca0\ud305\uc774 \uc790\uc81c\ub410\uace0, \uacb0\uacfc \ud655\uc778 \uc774\ud6c4\uc5d0\ub294 \ub20c\ub838\ub358 \ub9e4\uc218\uac00 \ud55c\uaebc\ubc88\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ud750\ub984\uc774 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\ub458\uc9f8, AMD\uc758 3\ubd84\uae30 \uc2e4\uc801 \uc11c\ud504\ub77c\uc774\uc988\uc640 2027\ub144 \uc131\uc7a5 \uc804\ub9dd \uc0c1\ud5a5\uc785\ub2c8\ub2e4.<br/>\\nAMD\uc758 3\ubd84\uae30 \ub9e4\ucd9c\uc740 133\uc5b5 8,000\ub9cc \ub2ec\ub7ec\ub85c \uc804\ub144 \ub3d9\uae30 \ub300\ube44 45% \uc99d\uac00\ud588\uace0, \uc2dc\uc7a5 \uc608\uc0c1\uce58 \uc57d 130\uc5b5 9,000\ub9cc \ub2ec\ub7ec\ub97c \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc870\uc815 \uc8fc\ub2f9\uc21c\uc774\uc775\uc740 2.09\ub2ec\ub7ec\ub85c \uc608\uc0c1\uce58 \uc57d 1.95\ub2ec\ub7ec\ub97c \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \ub9e4\ucd9c\uc740 85\uc5b5 5,000\ub9cc \ub2ec\ub7ec\ub85c \uc804\ub144 \ub3d9\uae30 \ub300\ube44 97% \uc99d\uac00\ud574 \ubd84\uae30 \ub9e4\ucd9c\uc758 64%\ub97c \ucc28\uc9c0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n4\ubd84\uae30 \ub9e4\ucd9c \uac00\uc774\ub358\uc2a4\ub294 \uc57d 170\uc5b5 \ub2ec\ub7ec\ub85c \uc81c\uc2dc\ub410\uace0, \ub9ac\uc0ac \uc218 \ucd5c\uace0\uacbd\uc601\uc790\ub294 2027\ub144 \ub9e4\ucd9c\uc774 80% \uc774\uc0c1 \uc99d\uac00\ud560 \uac83\uc73c\ub85c \uc804\ub9dd\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00\ub294 11\uc6d4 3\uc77c \uc815\uaddc\uc7a5\uc5d0\uc11c 3.65% \uc624\ub978 483.90\ub2ec\ub7ec\ub85c \ub9c8\uac10\ud55c \ub4a4, \uc2dc\uac04\uc678 \uac70\ub798\uc5d0\uc11c 7%\uc5d0\uc11c 8% \uc548\ud30e\uc73c\ub85c \ucd94\uac00 \uc0c1\uc2b9\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2ec\ub9ac\uc801\uc73c\ub85c\ub294 \uc778\uacf5\uc9c0\ub2a5 \uc9c0\ucd9c \uc9c0\uc18d \uac00\ub2a5\uc131\uc5d0 \ub300\ud55c \uc758\uad6c\uc2ec\uc744 \ub35c\uc5b4\uc8fc\ub294 \uc7ac\ub8cc\uc785\ub2c8\ub2e4.<br/>\\n\uad6c\uc870\uc801\uc73c\ub85c\ub294 \ub370\uc774\ud130\uc13c\ud130\uc6a9 \ud504\ub85c\uc138\uc11c\uc640 \uc778\uacf5\uc9c0\ub2a5 \uac00\uc18d\uae30 \uc218\uc694\uac00 \uc2e4\uc801 \uc218\uce58\ub85c \ud655\uc778\ub410\ub2e4\ub294 \uc810\uc774 \uc911\uc694\ud558\uace0, \uc774\ub294 \ubc18\ub3c4\uccb4 \uc139\ud130 \uc804\ubc18\uc758 \ubc38\ub958\uc5d0\uc774\uc158 \ub17c\uc7c1\uc5d0 \uc2e4\ubb3c \uc99d\uac70\ub97c \ub354\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc AMD \uce21\uc740 \uace0\ub300\uc5ed\ud3ed \uba54\ubaa8\ub9ac \ubd80\uc871\uc774 \ucd9c\ud558\ub97c \uc81c\uc57d\ud558\ub294 \uc694\uc778\uc774\ub77c\uace0 \ubc1d\ud614\uc73c\ubbc0\ub85c, \uc218\uc694 \uac15\uc138\uc640 \uacf5\uae09 \uc81c\uc57d\uc744 \ud568\uaed8 \ubd10\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n\uc14b\uc9f8, \uae08\ub9ac \ud558\ub77d\uacfc \ubcc0\ub3d9\uc131 \ucd95\uc18c, \uc815\ucc45 \uae30\ub300 \uc139\ud130\uc758 \ubc18\uc751\uc785\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc740 4.92% \uc548\ud30e\uc73c\ub85c \ud558\ub77d \ubc29\ud5a5\uc744 \ubcf4\uc600\uace0, \ubcc0\ub3d9\uc131 \uc9c0\uc218\ub294 16% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud0dc\uc591\uad11 \uc885\ubaa9\uad70\uc5d0\uc11c\ub294 \ud37c\uc2a4\ud2b8\uc194\ub77c\uac00 15.1%, \uc5d4\ud398\uc774\uc988 \uc5d0\ub108\uc9c0\uac00 12.1% \uc0c1\uc2b9\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub7ec\uc140 2000 \uc9c0\uc218\ub3c4 1.3% \uc548\ud30e\uc758 \uc0c1\uc2b9\uc744 \ubcf4\uc600\uace0, \uc218\uc775\uc774 \uc5c6\ub294 \uae30\uc220\uc8fc \ubc14\uc2a4\ucf13\uc740 3.0% \uc62c\ub790\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2ec\ub9ac\uc801\uc73c\ub85c\ub294 \uc120\uac70 \ubd88\ud655\uc2e4\uc131\uc774 \uc0ac\ub77c\uc9c4 \ub4a4 \uc704\ud5d8 \uc120\ud638\uac00 \uc911\uc18c\ud615\uc8fc\uc640 \uc131\uc7a5\uc8fc\uae4c\uc9c0 \ud655\uc0b0\ub418\ub294 \ubaa8\uc2b5\uc785\ub2c8\ub2e4.<br/>\\n\uad6c\uc870\uc801\uc73c\ub85c\ub294 \uae08\ub9ac \ud558\ub77d\uc774 \uc131\uc7a5\uc8fc \ud560\uc778\uc728 \ubd80\ub2f4\uc744 \ub0ae\ucd94\ub294 \uacbd\ub85c\uc640, \ubd84\ub2e8 \uc815\ubd80 \ud558\uc758 \uc815\ucc45 \uae30\ub300\uac00 \ud2b9\uc815 \uc139\ud130\uc5d0 \uba3c\uc800 \ubc18\uc601\ub418\ub294 \uacbd\ub85c\uac00 \ub3d9\uc2dc\uc5d0 \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc815\ucc45 \uae30\ub300\ub9cc\uc73c\ub85c \uc624\ub978 \uc885\ubaa9\uad70\uc740 \uc2e4\uc81c \uc758\ud68c \ub17c\uc758\uac00 \ud655\uc778\ub418\uae30 \uc804\uae4c\uc9c0 \ubcc0\ub3d9\uc131\uc774 \ud074 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\ub098\uc2a4\ub2e5 \uc0c1\uc2b9\ub960\uc774 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218 \uc0c1\uc2b9\ub960\uc744 \uc6c3\ub3c8 \uc810\uc774 \uac00\uc7a5 \ud070 \ucc28\ubcc4\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc5f0\uacb0\uace0\ub9ac\ub294 \uae08\ub9ac\uc5d0\uc11c \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc73c\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc218\uc775\ub960 \ud558\ub77d\uc774 \uc7a5\uae30 \uc131\uc7a5\uc8fc\uc758 \ud560\uc778\uc728 \ubd80\ub2f4\uc744 \ub35c\uc5b4\uc8fc\uba74, \ub098\uc2a4\ub2e5 \ube44\uc911\uc774 \ub192\uc740 \uae30\uc220\uc8fc\uc640 \ubc18\ub3c4\uccb4\uc8fc\uac00 \uba3c\uc800 \ubc18\uc751\ud569\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \uc139\ud130\ub294 AMD \uc2e4\uc801\uc744 \uacc4\uae30\ub85c \uc9c1\uc811\uc801\uc778 \uc218\ud61c\ub97c \ubc1b\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \ub9e4\ucd9c\uc774 \ub450 \ubc30 \uac00\uae4c\uc774 \ub298\uc5c8\ub2e4\ub294 \uc218\uce58\ub294 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \uc0ac\uc774\ud074\uc774 \uc544\uc9c1 \uc9c4\ud589 \uc911\uc774\ub77c\ub294 \uc2e0\ud638\ub85c \uc77d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc220\uc8fc \uc804\ubc18\ub3c4 \uac19\uc740 \uacbd\ub85c\ub85c \ubc18\ub4f1\ud588\uc9c0\ub9cc, \uc2e4\uc801\uacfc \ub9c8\uc9c4 \uc99d\uba85\uc774 \ub418\ub294 \uc885\ubaa9\uacfc \uadf8\ub807\uc9c0 \uc54a\uc740 \uc885\ubaa9\uc774 \uac08\ub9ac\ub294 \uc120\ubcc4 \ud750\ub984\uc740 \uc774\uc5b4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud0dc\uc591\uad11 \ub4f1 \uc815\ucc45 \uae30\ub300 \uc139\ud130\ub294 \uc120\uac70 \uacb0\uacfc\uc5d0 \uac00\uc7a5 \ubbfc\uac10\ud558\uac8c \ubc18\uc751\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubd84\ub2e8 \uc815\ubd80 \ud558\uc5d0\uc11c\ub294 \ub300\uaddc\ubaa8 \uc815\ucc45 \uc804\ud658\ubcf4\ub2e4\ub294 \uae30\uc874 \uc815\ucc45 \uacbd\ub85c \uc720\uc9c0\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \uba3c\uc800 \ubc18\uc601\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\uc735 \uc139\ud130\ub294 \uce74\ub4dc\uae08\ub9ac \uc0c1\ud55c \ub17c\uc758 \ub4f1 \uc120\uac70 \uacb0\uacfc\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub294 \ubcc0\uc218\uc5d0 \ub178\ucd9c\ub3fc \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc7a5\uc911 \uae08\uc735 \uc139\ud130\uc758 \ubc29\ud5a5\uc740 \ubcc4\ub3c4\ub85c \ud655\uc778\ub418\uc9c0 \uc54a\uc544 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\uc5d0\ub108\uc9c0 \uc139\ud130\uc758 \ub2f9\uc77c \uc7a5\uc911 \ubc29\ud5a5\ub3c4 \ubcc4\ub3c4\ub85c \ud655\uc778\ub418\uc9c0 \uc54a\uc544 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\ud5ec\uc2a4\ucf00\uc5b4 \uc139\ud130\ub294 \ubbfc\uc8fc\ub2f9 \uc2b9\ub9ac \uc2dc \uc9c0\uc6d0 \ud655\ub300 \uae30\ub300\uac00 \uac70\ub860\ub418\ub294 \ucabd\uc774\uc9c0\ub9cc, \ub2f9\uc77c \uc7a5\uc911 \ubc29\ud5a5\uc740 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7S&P500 \ud750\ub984\\n\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,710.23\uc73c\ub85c \uc804\uc77c \ub300\ube44 141.31\ud3ec\uc778\ud2b8, 1.87% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00\ub294 7,710.76, \uc7a5\uc911 \uc800\uac00\ub294 7,649.39\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 10\uc2dc\uacbd 1.64% \uc0c1\uc2b9\uc5d0\uc11c \uc7a5\uc911 1.87%\ub85c \uc0c1\uc2b9\ud3ed\uc774 \ucee4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615\uc8fc \uc804\ubc18\uc758 \uc644\ub9cc\ud55c \ubc18\ub4f1 \ud750\ub984\uc73c\ub85c, \ub098\uc2a4\ub2e5\ubcf4\ub2e4\ub294 \uc0c1\uc2b9\ud3ed\uc774 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0 \ud56d\ubaa9\uc774 \uc5c6\uc5b4 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 51,786.72\ub85c \uc804\uc77c \ub300\ube44 0.38% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uc2e0 \ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \ub2e4\uc6b0\ub294 \uc7a5 \ucd08\ubc18 1,300\ud3ec\uc778\ud2b8 \uc548\ud30e, 2.5% \uc548\ud30e\uc758 \uc0c1\uc2b9\uc744 \ubcf4\uc774\uba70 4\uc6d4 \uc774\ud6c4 \uac00\uc7a5 \uac15\ud55c \ud558\ub8e8\ub97c \ud5a5\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c\uc5d0\ub294 \ub2e4\uc6b0\ub9cc \ud558\ub77d\ud588\ub358 \uad6c\ub3c4\uc640 \ub2ec\ub9ac, \ub2f9\uc77c \uc7a5\uc911\uc740 \uc138 \uc9c0\uc218\uac00 \ud568\uaed8 \uc624\ub974\ub294 \ud655\uc0b0 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uacfc \uc624\ud6c4 \ud750\ub984 \ubcc0\ud654\\n\\n\uc624\uc804 10\uc2dc 3\ubd84 \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \ub124\uc774\ubc84 \uac12 \uae30\uc900 25,951.62\ub85c 2.28% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900\uc73c\ub85c\ub294 \uc624\uc804 10\uc2dc\uacbd 25,908.09\ub85c 2.11% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 12\uc2dc 57\ubd84 \uae30\uc900 25,913.52\ub85c 2.13% \uc0c1\uc2b9\ud558\uba74\uc11c \uc0c1\uc2b9 \ud750\ub984\uc774 \uadf8\ub300\ub85c \uc720\uc9c0\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc740 \uc5c6\uc5c8\uace0, \uc0c1\uc2b9 \ud750\ub984\uc774 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uace0\uc810 25,983.98\uc740 \uc7a5\uc911 \uace0\uc810 26,028.32\ub85c \uc0c1\ud5a5 \ub3cc\ud30c\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ud604\uc7ac\uac00 \uae30\uc900\uc73c\ub85c\ub294 \uc624\uc804 \ub124\uc774\ubc84 \uc2a4\ub0c5\uc0f7\ubcf4\ub2e4 \uc18c\ud3ed \ub0ae\uc544, \uace0\uc810\uc740 \ub192\uc600\uc9c0\ub9cc \uc0c1\uc2b9\ud3ed\uc740 \uc624\uc804\ubcf4\ub2e4 \ub2e4\uc18c \uc881\ud600\uc9c4 \uc0c1\ud0dc\uc785\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub3c4 \uc624\uc804 1.64%\uc5d0\uc11c \uc7a5\uc911 1.87%\ub85c \uc0c1\uc2b9\ud3ed\uc744 \ud0a4\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10\uae4c\uc9c0 \uc804\ub9dd\uacfc \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\uc7a5\uc911 \ud750\ub984\uc774 \uc9c0\uc18d\ub418\ub294\uc9c0, \uc77c\uc2dc\uc801 \ub178\uc774\uc988\uc778\uc9c0\ub97c \uac00\ub974\ub294 \uae30\uc900\uc740 \uace0\uc810 \uc720\uc9c0 \uc5ec\ubd80\uc785\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5 \uc885\ud569\uc774 \uc7a5\uc911 \uace0\uc810 26,028.32 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uace0\uc810\uc744 \uc9c0\ud0a4\uba74 \uc0c1\uc2b9 \ud750\ub984\uc774 \uc720\uc9c0\ub418\ub294 \ucabd\uc774\uace0, 25,900\uc120 \uc544\ub798\ub85c \ubc00\ub9ac\uba74 \uc624\uc804 \uc0c1\uc2b9\ud3ed\uc744 \ubc18\ub0a9\ud558\ub294 \ucabd\uc73c\ub85c \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\uac00 7,700\uc120\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uc810 7,710.76 \ubd80\uadfc \uc548\ucc29 \uc5ec\ubd80\uac00 \ub300\ud615\uc8fc \uc804\ubc18\uc758 \uac15\ub3c4\ub97c \uac00\ub985\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ubbfc\uc8fc\ub2f9\uc758 \uc815\ucc45 \uc6b0\uc120\uc21c\uc704 \ubc1c\uc5b8\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uc138\uc81c \ud61c\ud0dd\uacfc \uc778\uacf5\uc9c0\ub2a5 \uaddc\uc81c \uad00\ub828 \ubc1c\uc5b8\uc774 \ub098\uc62c \uacbd\uc6b0, \ubc18\ub3c4\uccb4\uc640 \uae30\uc220\uc8fc\uc758 \ubcc0\ub3d9\uc131\uc774 \ub2e4\uc2dc \ucee4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \uae08\ub9ac\uc640 \ubcc0\ub3d9\uc131 \ubc29\ud5a5\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n10\ub144\ubb3c \uad6d\ucc44\uc218\uc775\ub960\uc774 4.92% \uc548\ud30e\uc5d0\uc11c \ub354 \ud558\ub77d\ud558\ub294\uc9c0, \ubcc0\ub3d9\uc131 \uc9c0\uc218\uac00 \ub0ae\uc740 \uc218\uc900\uc744 \uc720\uc9c0\ud558\ub294\uc9c0\uac00 \uc131\uc7a5\uc8fc \uac15\uc138\uc758 \uc9c0\uc18d \uc870\uac74\uc785\ub2c8\ub2e4.<br/>\\n\ub2e4\uc12f\uc9f8, \uc7a5 \ub9c8\uac10 \ud6c4 \ucd94\uac00 \uac1c\ud45c \uacb0\uacfc\uc640 \uc758\uc11d \ud655\uc815 \uc18c\uc2dd\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ucd5c\uc885 \uc758\uc11d\uc218\uac00 \ud655\uc815\ub418\ub294 \uacfc\uc815\uc5d0\uc11c \uc815\ucc45 \uacbd\ub85c\uc5d0 \ub300\ud55c \ud574\uc11d\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uc640 \uc139\ud130 \ub2e8\uc704\uc758 \ud750\ub984 \uc815\ub9ac\uc640 \ub9c8\uac10\uae4c\uc9c0 \ud655\uc778\ud560 \uae30\uc900\uc744 \uc81c\uc2dc\ud558\ub294 \uac83\uc774 \ubaa9\uc801\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ubbfc\uc8fc\ub2f9 \uc591\uc6d0 \uc7a5\uc545 \ud655\uc815\uacfc AMD \uc2e4\uc801\uc774\ub77c\ub294 \ub450 \uac00\uc9c0 \uc7ac\ub8cc\uac00 \ub9de\ubb3c\ub9ac\uba70, \ub098\uc2a4\ub2e5\uc758 \uc7a5\uc911 \uac15\uc138\uac00 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9c8\uac10\uae4c\uc9c0\ub294 \uace0\uc810 \uc720\uc9c0 \uc5ec\ubd80\uc640 \uc815\ucc45 \ubc1c\uc5b8, \uae08\ub9ac \ubc29\ud5a5\uc744 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-04-nasdaq-market-open","metadata":{"permalink":"/blog/en/market/2026-11-04-nasdaq-market-open","source":"@site/market/2026-11-04-nasdaq-market-open/index.mdx","title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ubbfc\uc8fc\ub2f9 \uc591\uc6d0 \uc7a5\uc545 \ud6c4 \uae09\ubc18\uc804 \uac15\uc138 \ucd9c\ubc1c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-04T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":7.96,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-04-nasdaq-market-open","title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ubbfc\uc8fc\ub2f9 \uc591\uc6d0 \uc7a5\uc545 \ud6c4 \uae09\ubc18\uc804 \uac15\uc138 \ucd9c\ubc1c","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911, \ubbfc\uc8fc\ub2f9 \uc2a4\uc715 \ud655\uc815 \ud6c4 2%\ub300 \uac15\uc138 \uc9c0\uc18d","permalink":"/blog/en/market/2026-11-04-nasdaq-market-midday"},"nextItem":{"title":"2026\ub144 11\uc6d4 3\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-03-domestic-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 4\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uac1c\uc7a5 \ubc30\uacbd\\n\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 \ud63c\uc870 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 3\uc77c \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,372.01\ub85c \uc804\uc77c \ub300\ube44 0.83% \uc0c1\uc2b9\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,568.92\ub85c 0.36% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 51,786.72\ub85c 0.38% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uacfc \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 3\uac70\ub798\uc77c \ud558\ub77d\uc744 \uba48\ucdc4\uace0, \ub2e4\uc6b0\ub9cc \ud558\ub77d\ud55c \ucc28\ubcc4\ud654\ub41c \ub9c8\uac10\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 3\uc77c\uc740 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ud22c\ud45c\uc77c\uc774\uc5c8\uace0, \uc7a5 \ub9c8\uac10 \uc774\ud6c4 \uac1c\ud45c\uac00 \uc9c4\ud589\ub418\uba74\uc11c 11\uc6d4 4\uc77c \uc7a5 \uc624\ud508\uc758 \uc7ac\ub8cc\ub294 \uc120\uac70 \uacb0\uacfc\ub85c \uc62e\uaca8\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\ud45c \ucd08\ubc18\uc5d0\ub294 \uc778\uacf5\uc9c0\ub2a5\uacfc \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uac00 \ubd80\uac01\ub418\uba70 \uc120\ubb3c\uc774 \uae09\ub77d\ud588\uc73c\ub098, \uc7a5 \uc624\ud508 \ubb34\ub835\uc5d0\ub294 \ub099\ud3ed\uc744 \ub418\ub3cc\ub9ac\uace0 \uac15\uc138\ub85c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,951.62 | +579.61 | +2.28% | 25,372.01 | 25,983.98 | 25,602.14 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-04 10:03, \ud55c\uad6d\uc2dc\uac04 2026-11-05 00:03 |\\n| \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 | 7,693.30 | +124.38 | +1.64% | 7,568.92 | 7,701.84 | 7,649.39 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-04 10:00\uacbd, \ud55c\uad6d\uc2dc\uac04 2026-11-05 00:00\uacbd |\\n| \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | 51,786.72 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-04 10:00\uacbd, \ud55c\uad6d\uc2dc\uac04 2026-11-05 00:00\uacbd |\\n\\n\ub2f9\uc77c \uc218\uce58\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc758 \uc2dc\uac00\ub294 25,652.78\uc774\uc5c8\uace0, \uac70\ub798\ub7c9\uc740 310,394\ucc9c\uc8fc\ub85c \ud45c\uc2dc\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uac12\uc740 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uacfc [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569 \uac00\uaca9](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uacfc \uad50\ucc28 \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 10\uc2dc\uacbd 25,908.09\ub85c \uc804\uc77c \ub300\ube44 536.08\ud3ec\uc778\ud2b8, 2.11% \uc0c1\uc2b9\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,693.30\uc73c\ub85c 1.64% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uac12\uacfc \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uac12\uc758 \ucc28\uc774\ub294 \uc870\ud68c \uc2dc\uc810 \ucc28\uc774 \ubc94\uc704 \uc548\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0 \ub2e4\uc6b0 \ud56d\ubaa9\uc774 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc544 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\ud45c\uba74\uc801\uc73c\ub85c\ub294 \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \ub300\ube44 2.28% \uac15\uc138 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadfc\ubcf8 \ucd09\ub9e4\ub294 \uc120\uac70 \uacb0\uacfc\uc758 \ud655\uc815, \uc120\ubb3c \uae09\ub77d \ud6c4 \ub418\ub3cc\ub9bc, \uc778\uacf5\uc9c0\ub2a5 \uc218\uc694 \uc99d\uac70\uc758 \uacb0\ud569\uc73c\ub85c \uc815\ub9ac\ub429\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \uc120\uac70 \uacb0\uacfc\uc758 \ud655\uc815\uc785\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc774\uc5b4\uc9c0\uba74\uc11c, \ubd84\ub2e8 \uc815\ubd80\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \uc815\ucc45 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c \uc694\uc778\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucd5c\uc885 \uc758\uc11d\uc218\ub294 \uc544\uc9c1 \uc9d1\uacc4 \uc911\uc774\ubbc0\ub85c, \uc758\uc11d\uc218 \uc790\uccb4\ub97c \ud655\uc815 \uc218\uce58\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc120\ubb3c \uae09\ub77d \ud6c4 \ubc18\uc804\uc785\ub2c8\ub2e4.<br/>\\n\uac1c\ud45c \ucd08\ubc18\uc5d0\ub294 \ub098\uc2a4\ub2e5 100 \uc120\ubb3c\uc774 2.4%\uae4c\uc9c0 \ud558\ub77d\ud558\uace0 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc120\ubb3c\uc774 1.4%\uae4c\uc9c0 \ud558\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ud6c4 \ub099\ud3ed\uc740 \ub300\ubd80\ubd84 \ub418\ub3cc\ub824\uc84c\uace0, \uac1c\uc7a5 \uc804\uc5d0\ub294 \ub2e4\uc6b0 \uc120\ubb3c\uc774 1.5%\uc5d0\uc11c 2.1% \uc548\ud30e, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc120\ubb3c\uc774 1.1% \uc548\ud30e, \ub098\uc2a4\ub2e5 100 \uc120\ubb3c\uc774 0.4%\uc5d0\uc11c 1% \uc548\ud30e \uc0c1\uc2b9\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4 \uc2dc\uc810\uc774 \ub2ec\ub77c \uc120\ubb3c \uc0c1\uc2b9 \ud3ed\uc5d0 \ubc94\uc704\uac00 \uc788\ub294 \uc810\uc740 \ucc38\uace0\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc778\uacf5\uc9c0\ub2a5 \uc218\uc694 \uc99d\uac70\uc785\ub2c8\ub2e4.<br/>\\n11\uc6d4 3\uc77c \uc7a5 \ub9c8\uac10 \ud6c4 \uc778\uacf5\uc9c0\ub2a5 \uc218\uc694 \uac15\uc138\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc2e4\uc801 \uc7ac\ub8cc\uac00 \uc774\uc5b4\uc84c\uace0, \uac1c\uc7a5 \uc804\uc5d0\ub294 AMD\uac00 2027\ub144 \uc131\uc7a5 \uc804\ub9dd \uac15\ud654\ub85c 7% \uc774\uc0c1 \uc0c1\uc2b9\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\uc640 \uc815\ubc18\ub300 \ubc29\ud5a5\uc758 \uc7ac\ub8cc\ub85c, \uc7a5 \ucd08\ubc18\uc5d0\ub294 \uc218\uc694 \uc99d\uac70 \ucabd\uc774 \ub354 \uac15\ud558\uac8c \ubc18\uc601\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uad50\ucc28 \uc790\uc0b0 \ud750\ub984\ub3c4 \uac19\uc740 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uae08 \ud604\ubb3c\uc740 2.93% \uc0c1\uc2b9\ud574 \uc628\uc2a4\ub2f9 4,043.45\ub2ec\ub7ec\ub97c \uae30\ub85d\ud588\uace0, \ub2ec\ub7ec\uc640 \uad6d\ucc44\uc218\uc775\ub960\uc740 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec \uc57d\uc138\uc640 \uc218\uc775\ub960 \ud558\ub77d\uc740 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc744 \ub35c\uc5b4\uc8fc\ub294 \uc694\uc778\uc73c\ub85c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uac04 \ubc29\ud5a5 \ucc28\uc774\ub3c4 \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 2.28% \uc624\ub978 \ubc18\uba74 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 1.64% \uc624\ub974\ub294 \ub370 \uadf8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uae30\uc220\uc8fc\uc640 \ubc18\ub3c4\uccb4 \uc911\uc2ec\uc758 \ub418\ub3cc\ub9bc\uc774 \uc7a5 \ucd08\ubc18 \uc0c1\uc2b9\uc744 \uc8fc\ub3c4\ud558\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc0c1\uc2b9 \ud3ed\uc774 \ud06c\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\uac00 \ucd94\uc138 \uc804\ud658\uc744 \ud655\uc815\ud558\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uacb0\uacfc\uac00 \uc2e4\uc81c \ubc95\uc548\uacfc \uaddc\uc81c \ubcc0\ud654\ub85c \uc774\uc5b4\uc9c0\ub294\uc9c0\ub294 \uc55e\uc73c\ub85c \ud655\uc778\ud560 \uc0ac\uc548\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### \uccab\uc9f8, \ubbfc\uc8fc\ub2f9\uc758 \uc0c1\uc6d0\uacfc \ud558\uc6d0 \ub3d9\uc2dc \uc7a5\uc545\uc785\ub2c8\ub2e4\\n\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70\uc5d0\uc11c \ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ud2b8\ub7fc\ud504 \ud589\uc815\ubd80\uc758 \uacbd\uc81c \uc758\uc81c\uc5d0 \ub300\ud55c \uc758\ud68c \uacac\uc81c\uac00 \uac15\ud574\uc84c\uc74c\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5 \uad00\uc810\uc5d0\uc11c\ub294 \ub450 \uac00\uc9c0 \ud574\uc11d\uc774 \ub3d9\uc2dc\uc5d0 \uc791\ub3d9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub098\ub294 \ubd84\ub2e8 \uc815\ubd80\ub85c \uc815\ucc45 \ubd88\ud655\uc2e4\uc131\uc774 \uc904\uc5b4\ub4e0\ub2e4\ub294 \ud574\uc11d\uc774\uace0, \ub2e4\ub978 \ud558\ub098\ub294 \ub370\uc774\ud130\uc13c\ud130 \uac74\uc124 \uaddc\uc81c\uc640 \uc778\uacf5\uc9c0\ub2a5 \uaddc\uc81c \uac15\ud654 \uac00\ub2a5\uc131\uc774\ub77c\ub294 \ud574\uc11d\uc785\ub2c8\ub2e4.<br/>\\n\uac1c\ud45c \ucd08\ubc18\uc5d0\ub294 \ub450 \ubc88\uc9f8 \ud574\uc11d\uc774 \uc120\ubb3c\uc744 \ub04c\uc5b4\ub0b4\ub838\uace0, \uc7a5 \uc624\ud508 \ubb34\ub835\uc5d0\ub294 \uccab \ubc88\uc9f8 \ud574\uc11d\uacfc \uc800\uac00 \ub9e4\uc218\uac00 \uc6b0\uc704\ub97c \uc810\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub525\uc11c\uce58 \ubb38\uc11c \uac80\uc0c9\uc5d0\uc11c\ub3c4 \ubbfc\uc8fc\ub2f9 \uc0c1\uc6d0\uacfc \ud558\uc6d0 \uc7a5\uc545\uc744 \uc804\uc81c\ub85c \uad00\uc138 \uc815\ucc45\uc5d0 \ub300\ud55c \uc555\ubc15\uc774 \ucee4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uad00\uce21\uc774 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uad00\uc138 \uc815\ucc45\uc774 \uc2e4\uc81c\ub85c \ubc14\ub00c\uc5c8\ub2e4\uace0 \ubcf4\uae30\ub294 \uc5b4\ub835\ub2e4\ub294 \uc2e0\uc911\ud55c \uad00\uce21\ub3c4 \ud568\uaed8 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uc120\uac70 \uacb0\uacfc\ub294 \ubc29\ud5a5\uc744 \ubc14\uafbc \uc0ac\uac74\uc774\uc9c0, \uc815\ucc45 \ubcc0\ud654\ub97c \ud655\uc815\ud558\ub294 \uc0ac\uac74\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n### \ub458\uc9f8, \uc7a5 \ub9c8\uac10 \ud6c4 \uc778\uacf5\uc9c0\ub2a5 \uc218\uc694 \uac15\uc138 \uc7ac\ub8cc\uc785\ub2c8\ub2e4\\n\\n11\uc6d4 3\uc77c \uc7a5 \ub9c8\uac10 \ud6c4 AMD\uc640 \uc544\ub9ac\uc2a4\ud0c0 \ub124\ud2b8\uc6cd\uc2a4, \uc288\ud37c \ub9c8\uc774\ud06c\ub85c \ucef4\ud4e8\ud130\uac00 \uc778\uacf5\uc9c0\ub2a5 \uc218\uc694 \uac15\uc138\uc5d0 \uc0c1\uc2b9\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804\uc5d0\ub294 AMD\uac00 2027\ub144 \uc131\uc7a5 \uc804\ub9dd\uc744 \uac15\ud654\ud558\uba74\uc11c 7% \uc774\uc0c1 \uc0c1\uc2b9\ud588\ub2e4\ub294 \ubcf4\ub3c4\ub3c4 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub525\uc11c\uce58 \ubb38\uc11c \uac80\uc0c9\uc5d0\uc11c\ub3c4 AMD\uc758 \uc2e4\uc801\uacfc \ub370\uc774\ud130\uc13c\ud130 \ub9e4\ucd9c \uc99d\uac00 \uc804\ub9dd\uc774 \uc911\uad6d \uc778\uacf5\uc9c0\ub2a5 \ubc18\ub3c4\uccb4 \uae30\uc5c5\uc758 \ud22c\uc790\uc2ec\ub9ac \uac1c\uc120\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4\ub294 \ubcf4\ub3c4\uac00 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\uc774 \uc7ac\ub8cc\uac00 \uc911\uc694\ud55c \uc774\uc720\ub294 10\uc6d4 \ub9d0 \ub098\uc2a4\ub2e5 100 \uc9c0\uc218\uac00 \uc870\uc815 \uad6c\uac04\uc5d0 \ub4e4\uc5b4\uac08 \ub9cc\ud07c \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uacfc\uc789 \uc6b0\ub824\uac00 \ucee4\uc84c\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.<br/>\\n\uc6b0\ub824\uac00 \ucee4\uc9c4 \uc0c1\ud0dc\uc5d0\uc11c \uc218\uc694 \uc99d\uac70\uac00 \ub098\uc624\uba74, \ub9e4\ub3c4 \ub17c\ub9ac\uc640 \ub9e4\uc218 \ub17c\ub9ac\uac00 \uc815\uba74\uc73c\ub85c \ucda9\ub3cc\ud569\ub2c8\ub2e4.<br/>\\n11\uc6d4 4\uc77c \uc7a5 \ucd08\ubc18\uc5d0\ub294 \uc218\uc694 \uc99d\uac70\uac00 \uc6b0\uc704\ub97c \uc810\ud588\uc73c\ub098, \uc774\ub294 \ud558\ub8e8\uc758 \ud750\ub984\uc77c \ubfd0 \uc218\uc694 \ub454\ud654 \ub17c\uc7c1\uc774 \ub05d\ub0ac\uc74c\uc744 \uc758\ubbf8\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \uc14b\uc9f8, \uc544\uc2dc\uc544 \uc2dc\uc7a5\uc758 \ub864\ub7ec\ucf54\uc2a4\ud130\uc785\ub2c8\ub2e4\\n\\n11\uc6d4 4\uc77c \uc544\uc2dc\uc544 \uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc120\uac70 \uacb0\uacfc\uc5d0 \ub300\ud55c \ubc18\uc751\uc774 \uadf9\uc2ec\ud55c \ubcc0\ub3d9\uc131\uc73c\ub85c \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 4% \ub118\uac8c \uae09\ub77d\ud588\ub2e4\uac00 \uac15\ubcf4\ud569\uc73c\ub85c \ub9c8\uac10\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub525\uc11c\uce58 \ubb38\uc11c \uac80\uc0c9\uc5d0\uc11c\ub3c4 \uc0bc\uc131\uc804\uc790\uc640 SK\ud558\uc774\ub2c9\uc2a4\uac00 \uc7a5 \ucd08\ubc18 \uc0c1\uc2b9\ubd84\uc744 \ubc18\ub0a9\ud558\uace0 \uc57d\ubcf4\ud569\uc73c\ub85c \ub9c8\uac10\ud588\ub2e4\ub294 \ubd84\uc11d\uc774 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\uc6d0\uc778\uc73c\ub85c\ub294 \ubbfc\uc8fc\ub2f9 \uc2b9\ub9ac \uac00\ub2a5\uc131\uc5d0 \ub530\ub978 \uc778\uacf5\uc9c0\ub2a5 \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uac15\ud654\uc640 \uac74\uc124 \ub454\ud654 \uc6b0\ub824\uac00 \uc9c0\ubaa9\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uac19\uc740 \ubd84\uc11d\uc5d0\uc11c\ub294 \uba54\ubaa8\ub9ac \uc7ac\uace0\uac00 10\uc77c\uce58 \ubbf8\ub9cc\uc774\uace0, \ub0b4\ub144 HBM \uc0dd\uc0b0 \ube44\uc911 \ud655\ub300\uac00 \ubc94\uc6a9 \uba54\ubaa8\ub9ac \uacf5\uae09 \uc808\ubcbd\uc744 \uc2ec\ud654\uc2dc\ud0ac \uc218 \uc788\ub2e4\ub294 \uc804\ub9dd\ub3c4 \ud568\uaed8 \uc81c\uc2dc\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc544\uc2dc\uc544 \uc2dc\uc7a5\uc758 \ubcc0\ub3d9\uc131\uc740 \ubbf8\uad6d \uc7a5 \uc624\ud508\uc758 \uacf5\ud3ec\uac00 \uc544\ub2c8\ub77c, \ubbf8\uad6d \uc7a5 \uc624\ud508 \uc804\uc5d0 \uc774\ubbf8 \ud55c \ucc28\ub840 \uc18c\ud654\ub410\ub2e4\ub294 \uc2e0\ud638\ub85c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc7a5\uc774 \uac15\uc138\ub85c \ucd9c\ubc1c\ud55c \uac83\uc740 \uc544\uc2dc\uc544\uc758 \uacf5\ud3ec\uac00 \ubbf8\uad6d\uc5d0\uc11c\ub3c4 \uadf8\ub300\ub85c \ubc18\ubcf5\ub418\uc9c0 \uc54a\uc558\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\uae08\ub9ac\uc5d0\uc11c \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\uac00 \uba3c\uc800 \uc791\ub3d9\ud569\ub2c8\ub2e4.<br/>\\n\ub2ec\ub7ec\uc640 \uad6d\ucc44\uc218\uc775\ub960\uc774 \ud558\ub77d\ud558\uba74 \ubbf8\ub798 \uc774\uc775\uc744 \ud604\uc7ac \uac00\uce58\ub85c \ud658\uc0b0\ud558\ub294 \ud560\uc778\uc728 \ubd80\ub2f4\uc774 \uc644\ud654\ub418\uace0, \uc131\uc7a5\uc8fc\uc5d0 \uc6b0\ud638\uc801\uc778 \ud658\uacbd\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\ubc18\ub300\ub85c \ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c \uc6b0\ub824\ub294 \uac19\uc740 \uc131\uc7a5\uc8fc \uc548\uc5d0\uc11c\ub3c4 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \uad00\ub828\uc8fc\uc758 \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ubd80\ub2f4\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n11\uc6d4 4\uc77c \uc7a5 \ucd08\ubc18\uc5d0\ub294 \ud560\uc778\uc728 \uc644\ud654\uc640 \uc218\uc694 \uc99d\uac70\uac00 \uaddc\uc81c \uc6b0\ub824\ub97c \uc55e\uc9c8\ub800\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4\uc5d0\uc11c \ud558\ub4dc\uc6e8\uc5b4\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub3c4 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \uc218\uc694 \uc99d\uac70\ub294 \ubc18\ub3c4\uccb4 \uc218\uc694 \uc804\ub9dd\uc744 \uc9c0\uc9c0\ud558\uc9c0\ub9cc, \ub370\uc774\ud130\uc13c\ud130 \uc778\ud5c8\uac00 \uc9c0\uc5f0 \uc6b0\ub824\ub294 \uac74\uc124\uacfc \uc778\ud504\ub77c \ud22c\uc790 \uc18d\ub3c4\ub97c \ub2a6\ucd9c \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uc694\uc640 \uacf5\uae09 \uc81c\uc57d\uc774 \ub3d9\uc2dc\uc5d0 \uac70\ub860\ub418\ub294 \uad6c\uac04\uc5d0\uc11c\ub294, \uc2e4\uc801 \uc99d\uac70\uc640 \uaddc\uc81c \uc2e0\ud638 \uc911 \uc5b4\ub290 \ucabd\uc774 \uba3c\uc800 \ud655\uc778\ub418\ub294\uc9c0\uac00 \uc139\ud130 \ubc29\ud5a5\uc744 \uac00\ub985\ub2c8\ub2e4.<br/>\\n\uccad\uc815\uc5d0\ub108\uc9c0\uc5d0\uc11c \uc804\ud1b5 \uc5d0\ub108\uc9c0\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub294 \uc815\ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbfc\uc8fc\ub2f9 \uc2b9\ub9ac\uac00 \uccad\uc815\uc5d0\ub108\uc9c0 \uacf5\uae09\ub9dd\uc5d0 \uc6b0\ud638\uc801\uc774\ub77c\ub294 \ud574\uc11d \uc18d\uc5d0 \uc7ac\uc0dd\uc5d0\ub108\uc9c0 \uad00\ub828\uc8fc\uac00 \uc544\uc2dc\uc544\uc640 \uc720\ub7fd, \ubbf8\uad6d \uac1c\uc7a5 \uc804 \uc2dc\uc7a5\uc5d0\uc11c \uac15\uc138\ub97c \ubcf4\uc600\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc29\uc0b0 \uad00\ub828\uc8fc\ub294 \uad70\uc0ac \uc9c0\ucd9c \ud655\ub300 \uae30\ub300\uac00 \ub0ae\uc544\uc9c8 \uc218 \uc788\ub2e4\ub294 \ud574\uc11d \uc18d\uc5d0 \uac1c\uc7a5 \uc804 \uc57d\uc138\ub97c \ubcf4\uc600\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\uc138\uc5d0\uc11c \uc18c\ube44 \uc2ec\ub9ac\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub294 \uc544\uc9c1 \uae30\ub300 \ub2e8\uacc4\uc785\ub2c8\ub2e4.<br/>\\n\uad00\uc138\ub85c \ucd09\ubc1c\ub41c \ubbf8\uad6d \uc18c\ube44\uc790\uc758 \ubb3c\uac00 \ubd80\ub2f4\uc774 \uc120\uac70 \uc7c1\uc810\uc774\uc5c8\ub358 \ub9cc\ud07c, \uad00\uc138 \uc815\ucc45\uc5d0 \ub300\ud55c \uc555\ubc15\uc774 \ucee4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uad00\uce21\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc2e4\uc81c \uad00\uc138 \ubcc0\ud654\uac00 \ud655\uc778\ub418\uae30 \uc804\uc5d0\ub294 \uc18c\ube44 \uad00\ub828\uc8fc\uc5d0 \ub300\ud55c \uc9c1\uc811\uc801\uc778 \uc218\ud61c\ub85c \ub2e8\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\ud61c\uc640 \ud0c0\uaca9\uc744 \ub2e8\uc21c\ud788 \ub098\ub204\uae30\ubcf4\ub2e4, \uac19\uc740 \uc120\uac70 \uacb0\uacfc\uac00 \uc139\ud130\ub9c8\ub2e4 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud55c\ub2e4\ub294 \uc810\uc774 \uc774\ubc88 \uc7a5\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \ud750\ub984\\n\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 11\uc6d4 3\uc77c 0.38% \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc560\ud50c\uc774 1.9% \ud558\ub77d\ud558\uba74\uc11c \uac00\uaca9 \uac00\uc911 \ubc29\uc2dd\uc758 \ub2e4\uc6b0\uc5d0 \ubd80\ub2f4\uc744 \uc900 \uac83\uc73c\ub85c \ubcf4\ub3c4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub0a0 \ub098\uc2a4\ub2e5\uacfc \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\uac00 \uc0c1\uc2b9\ud55c \uac83\uacfc \ub300\ube44\ub418\ub294, \ub2e4\uc6b0\ub9cc \ud558\ub77d\ud55c \ud750\ub984\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 4\uc77c \uac1c\uc7a5 \uc804\uc5d0\ub294 \ub2e4\uc6b0 \uc120\ubb3c\uc774 \uac00\uc7a5 \uac15\ud558\uac8c \ubc18\ub4f1\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc804\uc77c\uc758 \ubc29\uc5b4\uc8fc \uc57d\uc138\uac00 \ub418\ub3cc\ub9bc \uad6d\uba74\uc5d0 \ub4e4\uc5b4\uac14\uc744 \uac00\ub2a5\uc131\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ub2e4\uc6b0\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud558\ubbc0\ub85c, \uac1c\uc7a5 \ud6c4 \ub2e4\uc6b0\uc758 \uc2e4\uc81c \uc0c1\uc2b9 \ud3ed\uc740 \ubcc4\ub3c4\ub85c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 11\uc6d4 3\uc77c 0.36% \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 4\uc77c \uc7a5 \ucd08\ubc18\uc5d0\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 1.64% \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\ubcf4\ub2e4\ub294 \uc0c1\uc2b9 \ud3ed\uc774 \uc791\uc544, \uae30\uc220\uc8fc \ub418\ub3cc\ub9bc\uc774 \uc9c0\uc218 \uc0c1\uc2b9\uc744 \uc8fc\ub3c4\ud558\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\uc758 \uc7a5\uc911 \uace0\uac00\ub294 7,701.84, \uc800\uac00\ub294 7,649.39\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uc804\uccb4\uc758 \uc0c1\uc2b9\uc774 \uae30\uc220\uc8fc\uc5d0 \uc9d1\uc911\ub41c \uac83\uc778\uc9c0, \uc885\ubaa9 \uc804\ubc18\uc73c\ub85c \ud655\uc0b0\ub418\ub294 \uac83\uc778\uc9c0\ub294 \uc7a5\uc911 \ud750\ub984\uc5d0\uc11c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ub2e8\uae30\uc801\uc73c\ub85c\ub294 \uac15\uc138 \ucd9c\ubc1c \uc9c0\uc18d\uacfc \uc77c\uc2dc\uc801 \ub178\uc774\uc988\ub97c \uad6c\ubd84\ud558\ub294 \uad6c\uac04\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\uc5d0 \ud655\uc778\ud560 \uccab \ubc88\uc9f8 \uc218\uce58\ub294 \ub098\uc2a4\ub2e5 \uc885\ud569\uc758 \uc804\uc77c \uc885\uac00 25,372.01 \uc548\ucc29 \uc5ec\ubd80\uc785\ub2c8\ub2e4.<br/>\\n\ud604\uc7ac\uac00 25,951.62\ub294 \uc804\uc77c \uc885\uac00\ub97c \ud06c\uac8c \uc6c3\ub3cc\uace0 \uc788\uc73c\ub098, \uc774 \uc218\uc900\uc744 \uc7a5\uc911 \ub0b4\ub0b4 \uc720\uc9c0\ud558\ub294\uc9c0\uac00 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\ub450 \ubc88\uc9f8 \uc218\uce58\ub294 \uc7a5\uc911 \uace0\uac00 25,983.98 \ub3cc\ud30c \uc9c0\uc18d \uc5ec\ubd80\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uace0\uac00\ub97c \uc9c0\ucf1c\ub0b4\uba74 \uac15\uc138\uc758 \ud798\uc774 \uc774\uc5b4\uc9c0\ub294 \uc2e0\ud638\ub85c \ubcfc \uc218 \uc788\uace0, \ubc18\ub0a9\ud558\uba74 \uae09\ubc18\uc804\uc758 \ud798\uc774 \uc57d\ud55c \uac83\uc73c\ub85c \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138 \ubc88\uc9f8 \uad6c\uac04\uc740 \ub2f9\uc77c \uc2dc\uac00 25,652.78\uacfc \uc7a5\uc911 \uc800\uac00 25,602.14\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uac04 \uc544\ub798\ub85c \ub0b4\ub824\uac00\uba74 \uac15\uc138 \ucd9c\ubc1c\uc774 \ubb34\ub108\uc9c0\ub294 \uc2e0\ud638\ub85c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 \uc804\uc77c \uc885\uac00 7,568.92\uc640 \uc7a5\uc911 \uace0\uac00 7,701.84\ub97c \uae30\uc900\uc73c\ub85c \uac19\uc740 \ud310\ub2e8\uc744 \uc801\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 \uc804\uc77c \uc885\uac00 51,786.72\ub97c \uae30\uc900\uc73c\ub85c \ud750\ub984\uc744 \uc810\uac80\ud558\ub418, \uc7a5\uc911 \uc218\uce58\ub294 \ud655\uc778\ub418\ub294 \ub300\ub85c \ub300\uc785\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 \uc120\uac70 \uacb0\uacfc\uc758 \uc815\ucc45 \uc804\ud658 \uc5ec\ubd80\ub97c \uac00\ub9ac\ub294 \uad6d\uba74\uc785\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c\uc640 \uad00\uc138, \uc7ac\uc815 \ubc29\ud5a5\uc5d0 \ub300\ud55c \uc2e4\uc81c \ubc95\uc548\uacfc \ud589\uc815 \uc870\uce58\uac00 \uadf8 \ud310\ub2e8 \uc7ac\ub8cc\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 \uc8fc \ud6c4\ubc18\uc5d0\ub294 11\uc6d4 6\uc77c \uace0\uc6a9\uc9c0\ud45c \ubc1c\ud45c\uac00 \uc608\uc815\ub3fc \uc788\uace0, \ub2e4\uc74c \uc8fc\uc5d0\ub294 \ubb3c\uac00 \uc9c0\ud45c\uac00 \uc774\uc5b4\uc9c4\ub2e4\ub294 \ubcf4\ub3c4\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc9c0\ud45c\ub4e4\uc774 \uae08\ub9ac \uae30\ub300\ub97c \ubc14\uafb8\uba74, \uc120\uac70 \uc7ac\ub8cc\uc640 \ubcc4\uac1c\ub85c \uc9c0\uc218 \ubc29\ud5a5\uc774 \ub2e4\uc2dc \uc870\uc815\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9ac\uc2a4\ud06c \uad00\ub9ac \uad00\uc810\uc5d0\uc11c\ub294 \uc9c0\uc218 \ub2e8\uc704\uc5d0\uc11c \uc804\uc77c \uc885\uac00\uc640 \uc7a5\uc911 \uace0\uc800\ub97c \uae30\uc900\uc73c\ub85c \ud750\ub984\uc744 \uc810\uac80\ud558\uace0, \ub2e8\uc77c \uc7ac\ub8cc\uc5d0 \uc758\ud55c \uae09\ub4f1\ub77d\uc5d0 \uacfc\ub3c4\ud558\uac8c \ubc18\uc751\ud558\uc9c0 \uc54a\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uc9c0\uc218\uc640 \uc139\ud130 \ub2e8\uc704\uc758 \ud574\uc124\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc624\ub298 \uc7a5\uc740 \uc120\uac70 \uacb0\uacfc \ud655\uc815\uacfc \uc120\ubb3c \uae09\ub77d \ud6c4 \ubc18\uc804\uc774 \uacb9\uce5c, \ubcc0\ub3d9\uc131\uc774 \ud070 \uac15\uc138 \ucd9c\ubc1c\ub85c \uc2dc\uc791\ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\uc5d0\ub294 \uc804\uc77c \uc885\uac00 \uc548\ucc29 \uc5ec\ubd80\uc640 \uc7a5\uc911 \uace0\uac00 \ub3cc\ud30c \uc9c0\uc18d \uc5ec\ubd80\ub97c \uc911\uc2ec\uc73c\ub85c \ud750\ub984\uc744 \ud655\uc778\ud558\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc758 \uc815\ub9ac\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-03-domestic-market-close","metadata":{"permalink":"/blog/en/market/2026-11-03-domestic-market-close","source":"@site/market/2026-11-03-domestic-market-close/index.mdx","title":"2026\ub144 11\uc6d4 3\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-03T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":2.82,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-03-domestic-market-close","title":"2026\ub144 11\uc6d4 3\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ubbfc\uc8fc\ub2f9 \uc591\uc6d0 \uc7a5\uc545 \ud6c4 \uae09\ubc18\uc804 \uac15\uc138 \ucd9c\ubc1c","permalink":"/blog/en/market/2026-11-04-nasdaq-market-open"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ud558\ub77d \ucd9c\ubc1c \ub4a4 \ub099\ud3ed \ud655\ub300\ud574 5,660\uc120 \ubd80\uadfc","permalink":"/blog/en/market/2026-11-03-domestic-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 3\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc774 \ubaa8\ub450 \ud06c\uac8c \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 3.59% \ud558\ub77d\ud55c 5,648.79\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \ub300\ube44 4.08% \ud558\ub77d\ud55c 704.39\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00\ubd80\ud130 \uc804\uc77c \uc885\uac00\ub97c \ubc11\ub3cc\uc558\uace0, \uc7a5\uc911 \ubc18\ub4f1 \uc5c6\uc774 \uc57d\uc138\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 5,735.92\uae4c\uc9c0 \uc62c\ub790\ub2e4\uac00 5,615.80\uae4c\uc9c0 \ub0b4\ub824\uac04 \ub4a4 5,648.79\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00\uac00 \uace7 \uc7a5\uc911 \uace0\uac00\uc600\uace0, 702.34\uae4c\uc9c0 \ub0b4\ub824\uac04 \ub4a4 704.39\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ubc18\ub4f1 \ud750\ub984\uc774 \ud558\ub8e8 \ub9cc\uc5d0 \ub418\ub3cc\ub824\uc9c4 \uc148\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,648.79 | -210.29 | -3.59% | 5,715.19 | 5,735.92 | 5,615.80 | 192,393\ucc9c\uc8fc | 14\uc870 894\uc5b5\uc6d0 |\\n| \ucf54\uc2a4\ub2e5 | 704.39 | -29.97 | -4.08% | 723.92 | 723.92 | 702.34 | 404,464\ucc9c\uc8fc | 5\uc870 3,307\uc5b5\uc6d0 |\\n\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,859.08, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 734.36\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 228,294 |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | 198,130 |\\n| 2026-11-03 | 5,715.19 | 5,735.92 | 5,615.80 | 5,648.79 | 192,393 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 470,174 |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | 355,750 |\\n| 2026-11-03 | 723.92 | 723.92 | 702.34 | 704.39 | 404,464 |\\n\\n\ucf54\uc2a4\ud53c\ub294 10\uc6d4 30\uc77c 5,730.74\uae4c\uc9c0 \ub0b4\ub824\uac14\ub2e4\uac00 11\uc6d4 2\uc77c 5,859.08\ub85c \ubc18\ub4f1\ud588\uc73c\ub098, \uc624\ub298 5,648.79\ub85c \ub2e4\uc2dc \ub0b4\ub824\uac14\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 10\uc6d4 30\uc77c 724.38\uc5d0\uc11c 11\uc6d4 2\uc77c 734.36\uc73c\ub85c \ubc18\ub4f1\ud588\uc73c\ub098, \uc624\ub298 704.39\ub85c \ucd5c\uadfc 5\uac70\ub798\uc77c \uc911 \uac00\uc7a5 \ub0ae\uac8c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2f9\uc77c \uc218\uae09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +16,606 |\\n| \uc678\uad6d\uc778 | -15,151 |\\n| \uae30\uad00 | -5,113 |\\n| \uae30\ud0c0\ubc95\uc778 | +3,657 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +3,197 |\\n| \uc678\uad6d\uc778 | -747 |\\n| \uae30\uad00 | -2,345 |\\n| \uae30\ud0c0\ubc95\uc778 | -105 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \ud568\uaed8 \uc21c\ub9e4\ub3c4\ud588\uace0, \uac1c\uc778\uc774 \uc774\ub97c \ubc1b\uc544\ub0c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub3c4 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uace0, \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uae09 \uc218\uce58\ub294 \ub124\uc774\ubc84 \ud22c\uc790\uc790\ubcc4 \ub9e4\ub9e4\ub3d9\ud5a5 \ub2f9\uc77c \ud56d\ubaa9 \uae30\uc900\uc774\uba70, \ucd5c\uc885 \uc9d1\uacc4 \uacfc\uc815\uc5d0\uc11c \uc77c\ubd80 \uc870\uc815\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984\\n\\n\uc2dc\uc7a5 \uc804\uccb4\uac00 \ud558\ub77d\ud55c \uac00\uc6b4\ub370\uc5d0\uc11c\ub3c4 \uc77c\ubd80 \ud14c\ub9c8\ub294 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc8fc\ub958\ud310\ub9e4 \ud14c\ub9c8\ub294 5.27% \uc62c\ub790\uace0, \ud56d\uacf5 \ud14c\ub9c8\ub294 3.56% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc790\uc0c1\uac70\ub798 \ud14c\ub9c8\ub294 3.25%, \uc7ac\ud0dd\uadfc\ubb34 \ud14c\ub9c8\ub294 2.80%, \uc2a4\ud3ec\uce20\ud589\uc0ac \uc218\ud61c \ud14c\ub9c8\ub294 2.74% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\ubcc4 \uc885\ubaa9\uc73c\ub85c\ub294 \ud55c\uc9c4\uce7c\uc774 29.97%, AP\uc704\uc131\uc774 29.98% \uc624\ub974\uba70 \uc0c1\ud55c\uac00\uc5d0 \uadfc\uc811\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \uc2dc\uc7a5 \uc694\uc57d\uc5d0\uc11c\ub294 \ubc18\ub3c4\uccb4\uc640 \uc804\ub825\uae30\uae30\uac00 \uc2e4\uc801 \uc6b0\ub824 \uc18d\uc5d0 \uc57d\uc138\ub97c \ubcf4\uc778 \uac83\uc73c\ub85c \uc815\ub9ac\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ud558\ub77d \uc18d\uc5d0\uc11c\ub3c4 \uc885\ubaa9\ubcc4 \ud750\ub984\uc774 \ud06c\uac8c \uac08\ub9b0 \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub0b4\uc77c \ud655\uc778\ud560 \uc810\\n\\n\uc678\uad6d\uc778\uacfc \uae30\uad00\uc758 \uc21c\ub9e4\ub3c4 \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c 5,615.80, \ucf54\uc2a4\ub2e5 702.34\ub85c \uae30\ub85d\ub41c \uc624\ub298 \uc800\uc810\uc744 \ub2e4\uc74c \uac70\ub798\uc77c\uc5d0 \uc9c0\ucf1c\ub0b4\ub294\uc9c0\ub3c4 \ud655\uc778\ud560 \uc810\uc785\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uc2dc\uc7a5 \ud750\ub984\uacfc \ubc18\ub3c4\uccb4 \uad00\ub828 \uc18c\uc2dd\uc774 \ub2e4\uc74c \uac70\ub798\uc77c \ucd9c\ubc1c\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \uc8fc\ub294\uc9c0\ub3c4 \ud568\uaed8 \uc0b4\ud3b4\ubcfc \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc624\ub298\uc740 \ub450 \uc9c0\uc218\uac00 \ubaa8\ub450 3% \ub118\uac8c \ud558\ub77d\ud558\uba70 \uc804\uc77c \ubc18\ub4f1\uc744 \ub418\ub3cc\ub9b0 \ud558\ub8e8\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uc218\uce58\uc640 \ud750\ub984\uc744 \uc815\ub9ac\ud55c \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uae30\ub85d\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\ub294 \ub0b4\uc6a9\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-03-domestic-market-midday","metadata":{"permalink":"/blog/en/market/2026-11-03-domestic-market-midday","source":"@site/market/2026-11-03-domestic-market-midday/index.mdx","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ud558\ub77d \ucd9c\ubc1c \ub4a4 \ub099\ud3ed \ud655\ub300\ud574 5,660\uc120 \ubd80\uadfc","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-03T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":2.87,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-03-domestic-market-midday","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ud558\ub77d \ucd9c\ubc1c \ub4a4 \ub099\ud3ed \ud655\ub300\ud574 5,660\uc120 \ubd80\uadfc","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 11\uc6d4 3\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-03-domestic-market-close"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ud558\ub77d \ucd9c\ubc1c","permalink":"/blog/en/market/2026-11-03-domestic-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 3\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uc7a5 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \uc885\uac00 5,859.08\uc5d0\uc11c 5,715.19\ub85c \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \uc885\uac00 734.36\uc5d0\uc11c 723.92\ub85c \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18 \ubc18\ub4f1\ubcf4\ub2e4\ub294 \ud558\ub77d \ud750\ub984\uc774 \uc774\uc5b4\uc84c\uace0, \uc815\uc624 \ubb34\ub835 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ub099\ud3ed\uc744 \ud655\ub300\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,662.94\ub85c \uc804\uc77c \ub300\ube44 3.35% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 711.04\ub85c \uc804\uc77c \ub300\ube44 3.18% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,662.94 | -196.14 | -3.35% | 5,715.19 | 5,735.92 | 5,638.06 | 114,202\ucc9c\uc8fc | 7\uc870 8,374\uc5b5\uc6d0 | 2026-11-03 12:28 KST |\\n| \ucf54\uc2a4\ub2e5 | 711.04 | -23.32 | -3.18% | 723.92 | 723.92 | 708.73 | 262,840\ucc9c\uc8fc | 3\uc870 3,667\uc5b5\uc6d0 | 2026-11-03 12:28 KST |\\n\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,715.19\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,662.94\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 723.92\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 711.04\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,859.08, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 734.36\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 228,294 |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | 198,130 |\\n| 2026-11-03 | 5,715.19 | 5,735.92 | 5,638.06 | 5,665.52 | 114,071 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 470,174 |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | 355,750 |\\n| 2026-11-03 | 723.92 | 723.92 | 708.73 | 711.36 | 262,560 |\\n\\n2026\ub144 11\uc6d4 3\uc77c \ubd09\uc740 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc77c\ubd09 \ud45c\uc758 \ub2f9\uc77c \uc885\uac00\ub294 \ud45c \uc791\uc131 \uc2dc\uc810\uc758 \ud615\uc131 \uc911 \uc218\uce58\uc774\uba70 \uc2e4\uc2dc\uac04 \ud604\uc7ac\uac00\uc640 \uc2dc\ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c 5,859.08\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 5,660\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c 734.36\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 711\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984 \ubcc0\ud654\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\ud56d\uacf5 \ud14c\ub9c8\uac00 4.67% \uc0c1\uc2b9\ud588\uace0, \uc8fc\ub958\ud310\ub9e4 \ud14c\ub9c8\uac00 4.30% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7ac\ud0dd\uadfc\ubb34 \ud14c\ub9c8\uac00 3.26% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00 \ub300\ube44 \uc0c1\uc2b9 \uc804\ud658\uc740 \ud655\uc778\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,715.19\ubcf4\ub2e4 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,662.94\uac00 \ub0ae\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 723.92\ubcf4\ub2e4 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 711.04\uac00 \ub0ae\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc7a5\uc911 \uc218\uae09 \ud655\uc815\uce58\ub294 \uc544\uc9c1 \uc9d1\uacc4\ub418\uc9c0 \uc54a\uc544 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ud6c4\uc5d0 \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 5,660\uc120 \ubd80\uadfc\uc5d0\uc11c \ub099\ud3ed\uc744 \uc904\uc774\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 711\uc120 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\uc758 \uc0c1\ub300\uc801 \uac15\uc138\uac00 \uc624\ud6c4\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ub9c8\uac10 \ubb34\ub835 \uc218\uae09 \ud655\uc815\uce58\uac00 \uc5b4\ub5bb\uac8c \uc9d1\uacc4\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ud558\ub77d \ucd9c\ubc1c \ub4a4 \uc815\uc624 \ubb34\ub835 \ub450 \uc9c0\uc218 \ubaa8\ub450 \uc804\uc77c \ub300\ube44 3% \ub118\uac8c \ud558\ub77d\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-03-domestic-market-open","metadata":{"permalink":"/blog/en/market/2026-11-03-domestic-market-open","source":"@site/market/2026-11-03-domestic-market-open/index.mdx","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ud558\ub77d \ucd9c\ubc1c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-03T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":2.9,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-03-domestic-market-open","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ud558\ub77d \ucd9c\ubc1c","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ud558\ub77d \ucd9c\ubc1c \ub4a4 \ub099\ud3ed \ud655\ub300\ud574 5,660\uc120 \ubd80\uadfc","permalink":"/blog/en/market/2026-11-03-domestic-market-midday"},"nextItem":{"title":"2026\ub144 11\uc6d4 3\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-03-nasdaq-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 3\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ubc30\uacbd\\n\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,164.32\ub85c \uc804\uc77c \ub300\ube44 272.68\ud3ec\uc778\ud2b8, 1.07% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,541.40\uc73c\ub85c \uc804\uc77c \ub300\ube44 38.67\ud3ec\uc778\ud2b8, 0.51% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c\uc778 2026\ub144 11\uc6d4 2\uc77c \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ubc18\ub4f1 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 5,859.08\ub85c 2.24% \uc0c1\uc2b9\ud588\uace0, \ucf54\uc2a4\ub2e5\uc740 734.36\uc73c\ub85c 1.38% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub7ec\ud55c \ubc30\uacbd \uc18d\uc5d0\uc11c \uc624\ub298 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uac1c\ubcc4 \uc885\ubaa9\uc758 \ud750\ub984\uc744 \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub824\uc6b0\uba70, \uc774\ub294 \ucc38\uace0\uc6a9 \ubc30\uacbd \uc815\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,659.59 | -199.49 | -3.40% | 5,715.19 | 5,715.30 | 5,647.29 | 48,096\ucc9c\uc8fc | 3\uc870 1,322\uc5b5\uc6d0 | 2026-11-03 09:43 KST |\\n| \ucf54\uc2a4\ub2e5 | 712.14 | -22.22 | -3.03% | 723.92 | 723.92 | 712.14 | 118,323\ucc9c\uc8fc | 1\uc870 6,385\uc5b5\uc6d0 | 2026-11-03 09:43 KST |\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc740 \ubaa8\ub450 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,715.19\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,659.59\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 723.92\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 712.14\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,859.08, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 734.36\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 228,294 |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | 198,130 |\\n| 2026-11-03 | 5,715.19 | 5,715.30 | 5,647.29 | 5,682.74 | 44,928 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 470,174 |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | 355,750 |\\n| 2026-11-03 | 723.92 | 723.92 | 712.60 | 715.18 | 111,932 |\\n\\n2026\ub144 11\uc6d4 3\uc77c \ubd09\uc740 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc77c\ubd09 \ud45c\uc758 \ub2f9\uc77c \uc885\uac00\ub294 \ud45c \uc791\uc131 \uc2dc\uc810\uc758 \ud615\uc131 \uc911 \uc218\uce58\uc774\uba70 \uc2e4\uc2dc\uac04 \ud604\uc7ac\uac00\uc640 \uc2dc\ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c 5,859.08\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 5,650\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c 734.36\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 710\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc804\uc77c \uc218\uae09\\n\\n\uc804\uc77c\uc778 2026\ub144 11\uc6d4 2\uc77c \uc218\uae09\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | -13,303 |\\n| \uc678\uad6d\uc778 | -3,845 |\\n| \uae30\uad00 | +12,257 |\\n| \uae30\ud0c0\ubc95\uc778 | +4,890 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | -223 |\\n| \uc678\uad6d\uc778 | -366 |\\n| \uae30\uad00 | +627 |\\n| \uae30\ud0c0\ubc95\uc778 | -38 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uae30\uad00\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uac1c\uc778\uacfc \uc678\uad6d\uc778\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uae30\uad00\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uac1c\uc778\uacfc \uc678\uad6d\uc778\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uae30\uad00 \uc21c\ub9e4\uc218 \uaddc\ubaa8\uac00 \uc774\ub0a0 \uc218\uae09\uc5d0\uc11c \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 5,650\uc120 \ubd80\uadfc\uc5d0\uc11c \ub099\ud3ed\uc744 \uc904\uc774\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 710\uc120 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uacfc \uae30\uad00\uc758 \uc7a5 \ucd08\ubc18 \uc218\uae09 \ubc29\ud5a5\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \ud558\ub77d \ud750\ub984\uc774 \uc7a5\uc911 \uc644\ud654\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uc7a5 \ucd08\ubc18 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-03-nasdaq-market-close","metadata":{"permalink":"/blog/en/market/2026-11-03-nasdaq-market-close","source":"@site/market/2026-11-03-nasdaq-market-close/index.mdx","title":"2026\ub144 11\uc6d4 3\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-03T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":5.72,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-03-nasdaq-market-close","title":"2026\ub144 11\uc6d4 3\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ud558\ub77d \ucd9c\ubc1c","permalink":"/blog/en/market/2026-11-03-domestic-market-open"},"nextItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911, \uc911\uac04\uc120\uac70 \ub300\uae30 \uc18d \ubc18\ub4f1\ud3ed \ud655\ub300","permalink":"/blog/en/market/2026-11-03-nasdaq-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 3\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc804\uc77c \ub300\ube44 \uc0c1\uc2b9\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9\ub960\uc740 0.83%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\ub3c4 \uc0c1\uc2b9\uc73c\ub85c \ub9c8\uac10\ud588\uc73c\ub098 \uc0c1\uc2b9\ub960\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud574 \uc9c0\uc218 \uac04 \ubc29\ud5a5\uc774 \uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d\ud588\ub358 \uae30\uc220\uc8fc\uac00 \ubc18\ub4f1\ud558\uba74\uc11c \ub098\uc2a4\ub2e5\uc774 3\uac70\ub798\uc77c \ub9cc\uc758 \ud558\ub77d \ud750\ub984\uc744 \ub04a\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \ub2f9\uc77c \uace0\uac00 | \ub2f9\uc77c \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,372.01 | +207.65 | +0.83% | 25,164.36 | 25,474.46 | 25,246.64 |\\n| S&P500 | 7,568.92 | +27.52 | +0.36% | 7,541.40 | 7,594.24 | 7,557.60 |\\n| \ub2e4\uc6b0\uc9c0\uc218 | 51,786.72 | -197.26 | -0.38% | 51,983.98 | 51,932.63 | 51,593.16 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 11\uc6d4 3\uc77c 16\uc2dc 20\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 11\uc6d4 4\uc77c 06\uc2dc 20\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569 \uc218\uce58\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\ub294 \ubbf8\uad6d 11\uc6d4 3\uc77c 16\uc2dc 21\ubd84 \uc7a5\ub9c8\uac10 \uae30\uc900\uc73c\ub85c \uc885\uac00 25,372.01, \uc804\uc77c \ub300\ube44 207.65, \ub4f1\ub77d\ub960 0.83%\uac00 \ud45c\uc2dc\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc758 \ub098\uc2a4\ub2e5 \uc885\ud569 \uac12\ub3c4 \uc885\uac00 25,372.01, \uc804\uc77c \ub300\ube44 207.65, \ub4f1\ub77d\ub960 0.83%\ub85c \ub124\uc774\ubc84 \uac12\uacfc \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\nS&P500 \uc218\uce58\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \uc885\uac00\uc5d0\uc11c \uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc744 \ube7c\ub294 \ubc29\uc2dd\uc73c\ub85c \uc5ed\uc0b0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00 7,541.40\uacfc \ub2e4\uc6b0\uc9c0\uc218 \uc804\uc77c \uc885\uac00 51,983.98\uc740 \uc804 \uac70\ub798\uc77c \ub9c8\uac10 \uae00\uc758 \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c \ub098\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00 25,164.36\uc740 \uc804 \uac70\ub798\uc77c \ub9c8\uac10 \uae00\uc758 \uc885\uac00 25,164.32\uc640 0.04 \ucc28\uc774\uc774\uba70, \uc774\ub294 \uc790\ub8cc\uc6d0 \uac04 \ubc18\uc62c\ub9bc \ucc28\uc774\ub85c \ubcf4\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc758 \ud45c\uc2dc\uac12\uc785\ub2c8\ub2e4.<br/>\\nS&P500 \ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 \ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4\uc758 \ucd5c\ub300\uac12\uacfc \ucd5c\uc18c\uac12\uc73c\ub85c \uc0b0\ucd9c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218 \uc218\uce58\ub294 Yahoo Finance \uc77c\ubd09\uc73c\ub85c \ud655\uc778\ud55c \uac12\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc640 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub9c8\uac10 \uc6d0\uc778\uc740 \ubcf8\ubb38\uc5d0 \uc4f0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\uc774\ub0a0 \uc0c1\uc2b9\uc758 \ud45c\uba74\uc801 \uc774\uc720\ub294 \uae30\uc220\uc8fc \ubc18\ub4f1\uc785\ub2c8\ub2e4.<br/>\\n\uadfc\ubcf8 \ucd09\ub9e4\ub294 \uc138 \uac00\uc9c0\ub85c \uc555\ucd95\ub429\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \uc911\uac04\uc120\uac70 \ub2f9\uc77c\uc774\ub77c\ub294 \uc815\uce58 \uc77c\uc815\uc774 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c \uae30\ub300\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uacb0\uacfc\uac00 \ub098\uc624\uae30 \uc804\ubd80\ud130 \uc2dc\uc7a5\uc740 \ubd88\ud655\uc2e4\uc131\uc774 \uac77\ud78c \ub4a4 \uc790\uae08\uc774 \ub2e4\uc2dc \uc720\uc785\ub420 \uac00\ub2a5\uc131\uc744 \uac00\uaca9\uc5d0 \ubc18\uc601\ud558\uae30 \uc2dc\uc791\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uacac\uc870\ud55c \uacbd\uc81c\uc9c0\ud45c\uac00 \uae08\ub9ac \uc778\ud558 \uae30\ub300\ub97c \ub418\ub3cc\ub838\uc74c\uc5d0\ub3c4 \uc8fc\uac00\ub294 \ubc84\ud17c\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\uc778 \uac74\uc218\uc640 \uacf5\uc7a5\uc8fc\ubb38 \uc9c0\ud45c\uac00 \uc608\uc0c1\ubcf4\ub2e4 \uac15\ud558\uac8c \ub098\uc624\uba74\uc11c \uacf5\uaca9\uc801\uc778 \uae08\ub9ac \uc778\ud558 \uae30\ub300\ub294 \ud6c4\ud1f4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud1b5\uc0c1 \uae08\ub9ac \uc778\ud558 \uae30\ub300 \ud6c4\ud1f4\ub294 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ubd80\ub2f4\uc774\uc9c0\ub9cc, \uc774\ub0a0\uc740 \uae30\uc220\uc8fc \ubc18\ub4f1 \ud750\ub984\uc774 \uadf8 \ubd80\ub2f4\uc744 \ub20c\ub800\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc720\uac00 \ud558\ub77d\uc774 \ud22c\uc790 \uc2ec\ub9ac\ub97c \ubc1b\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ube0c\ub80c\ud2b8\uc720\uac00 \ubc30\ub7f4\ub2f9 107\ub2ec\ub7ec \ubd80\uadfc\uc5d0\uc11c 102\ub2ec\ub7ec \ubd80\uadfc\uc73c\ub85c \ub0b4\ub824\uc624\uba74\uc11c \uc5d0\ub108\uc9c0 \ube44\uc6a9 \ubd80\ub2f4\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uc644\ud654\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uc138 \uac00\uc9c0\uac00 \uacb9\uce58\uba74\uc11c \uc804 \uac70\ub798\uc77c \uae09\ub77d \ub4a4 \ub418\ub3cc\ub9bc \ub9e4\uc218\uc640 \uc20f\ucee4\ubc84\uac00 \uae30\uc220\uc8fc \ucabd\uc73c\ub85c \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c \uc9c0\uc218 \uac04 \ubc29\ud5a5\uc774 \uac08\ub838\ub358 \ud750\ub984\uc740 \uc774\ub0a0\ub3c4 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 0.83% \uc624\ub974\uace0 S&P500\uc774 0.36% \uc624\ub974\ub294 \ub3d9\uc548 \ub2e4\uc6b0\uc9c0\uc218\ub294 0.38% \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc0c1\uc2b9 \ub3d9\ub825\uc774 \uc2dc\uc7a5 \uc804\ubc18\uc774 \uc544\ub2c8\ub77c \uae30\uc220\uc8fc\uc640 \uc131\uc7a5\uc8fc\uc5d0 \ud3b8\uc911\ub410\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n\uccab\uc9f8, \ubbf8\uad6d \uc911\uac04\uc120\uac70\uac00 \uc2e4\uc2dc\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n3\uc77c(\ud604\uc9c0\uc2dc\uac04)\uc740 \uc911\uac04\uc120\uac70 \ud22c\ud45c\uc77c\uc774\uc5c8\uace0, \uc2dc\uc7a5\uc740 \uc120\uac70 \uacb0\uacfc\uc5d0 \ub300\ud55c \uacbd\uacc4\uac10 \uc18d\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc120\uac70\ub294 \uc5b4\ub290 \uc815\ub2f9\uc774 \uc758\ud68c\ub97c \uc7a5\uc545\ud560\uc9c0\ub97c \uac00\ub974\ub294 \uc0ac\uac74\uc774\uba70, \uc774\ud6c4 \uc815\ucc45 \ubc29\ud5a5\uacfc \uc790\uae08 \ubc30\ubd84\uc5d0 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \uae30\uc220\uc8fc\uac00 \ubc18\ub4f1\ud55c \ubc30\uacbd\uc5d0\ub294 \uc120\uac70 \ubd88\ud655\uc2e4\uc131\uc774 \uc815\uc810\uc744 \uc9c0\ub0ac\ub2e4\ub294 \uc778\uc2dd\uc774 \uae54\ub824 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc120\uac70 \uacb0\uacfc\uac00 \uc2dc\uc7a5\uc5d0 \ubbf8\uce60 \uc2e4\uc81c \uc601\ud5a5\uc740 \uac1c\ud45c \uacb0\uacfc\uac00 \ub098\uc628 \ub4a4\uc5d0 \ud655\uc778\ud574\uc57c \ud558\uba70, \uc774\ub0a0 \uc0c1\uc2b9\ub9cc\uc73c\ub85c \uacb0\uacfc\ub97c \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\ub458\uc9f8, \ub178\ub3d9\uc2dc\uc7a5\uacfc \uc81c\uc870\uc5c5 \uc9c0\ud45c\uac00 \uacac\uc870\ud558\uac8c \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5 \ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uad6c\uc778 \uac74\uc218\ub294 752\ub9cc 3\ucc9c \uac74, \uacf5\uc7a5\uc8fc\ubb38\uc740 \uc804\uc6d4 \ub300\ube44 1.8% \uc99d\uac00\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\ud45c \ubaa8\ub450 \uae08\ub9ac \uc778\ud558\ub97c \uc11c\ub450\ub97c \ud544\uc694\uac00 \uc5c6\ub2e4\ub294 \ucabd\uc73c\ub85c \ud574\uc11d\ub410\uace0, \uacf5\uaca9\uc801\uc778 \uae08\ub9ac \uc778\ud558 \uae30\ub300\ub294 \ud6c4\ud1f4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7fc\uc5d0\ub3c4 \uc8fc\uac00\uac00 \uc624\ub978 \uc810\uc740 \uc2dc\uc7a5\uc774 \uacbd\uae30 \uc790\uccb4\uc758 \uacac\uc870\ud568\uc744 \uae0d\uc815\uc801\uc73c\ub85c \ubc1b\uc544\ub4e4\uc600\ub2e4\ub294 \uc2e0\ud638\ub85c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc9c0\ud45c \ud574\uc11d\uc740 \ubcf4\ub3c4 \uae30\uc900\uc774\uba70, \uae08\ub9ac \uacbd\ub85c\uc5d0 \ub300\ud55c \ucd5c\uc885 \ud310\ub2e8\uc740 \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4\uc758 \ubc1c\uc5b8\uacfc \ub2e4\uc74c \ubb3c\uac00 \uc9c0\ud45c\uc5d0\uc11c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\\n\uc14b\uc9f8, \ubc18\ub3c4\uccb4\uc8fc\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \uae30\uc220\uc8fc \ub418\ub3cc\ub9bc\uc774 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c \ub098\uc2a4\ub2e5100 \uc9c0\uc218\ub294 10\uc6d4 \uace0\uc810 \ub300\ube44 10% \uc774\uc0c1 \ud558\ub77d\ud574 \uc870\uc815 \uad6d\uba74\uc5d0 \ub4e4\uc5b4\uac04 \uc0c1\ud0dc\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \uc9c0\uc218\ub294 \uc55e\uc120 3\uac70\ub798\uc77c \ub3d9\uc548 10% \uc548\ud30e\uc73c\ub85c \ud558\ub77d\ud55c \ub4a4 \uc774\ub0a0 \uc7a5\uc911 3% \uc774\uc0c1 \ubc18\ub4f1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790\uc5d0 \ub300\ud55c \uc790\uae08 \uc870\ub2ec \uc6b0\ub824\uac00 \ub2e8\uae30\uac04\uc5d0 \uacfc\ub3c4\ud558\uac8c \ubc18\uc601\ub410\ub2e4\uac00 \ub418\ub3cc\ub824\uc9c4 \ud750\ub984\uc73c\ub85c \ud574\uc11d\ub429\ub2c8\ub2e4.<br/>\\n\uc7a5 \ub9c8\uac10 \ub4a4\uc5d0\ub294 \uc8fc\uc694 \ubc18\ub3c4\uccb4 \uae30\uc5c5\uc758 \uc2e4\uc801 \ubc1c\ud45c\uac00 \uc608\uc815\ub418\uc5b4 \uc788\uc5b4, \ub418\ub3cc\ub9bc\uc774 \uc774\uc5b4\uc9c8\uc9c0\ub294 \uc2e4\uc801 \ud655\uc778 \ub4a4\uc5d0 \uac08\ub9b4 \uc804\ub9dd\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\ub098\uc2a4\ub2e5\uc758 \uc0c1\uc2b9\uc740 \ubc18\ub3c4\uccb4\uc640 \ub300\ud615 \uae30\uc220\uc8fc\uac00 \uc8fc\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4\ub294 \uc778\uacf5\uc9c0\ub2a5 \ubc38\ub958\uccb4\uc778\uc758 \uc0c1\ub958\uc5d0 \uc704\uce58\ud558\uba70, \ubc18\ub3c4\uccb4 \ubc18\ub4f1\uc740 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uc644\ud654\ub410\ub2e4\ub294 \uc2e0\ud638\ub85c \uc77d\ud799\ub2c8\ub2e4.<br/>\\n\ubc18\ub3c4\uccb4 \ubc18\ub4f1\uc774 \ub098\uc2a4\ub2e5 \uc804\uccb4\ub85c \ubc88\uc9c0\uba74\uc11c \ub300\ud615 \uae30\uc220\uc8fc\ub3c4 \ud568\uaed8 \uc62c\ub790\uace0, \uc774\ub294 \ub098\uc2a4\ub2e5 \uc0c1\uc2b9\ub960 0.83%\ub85c \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\uc740 \uae30\uc220\uc8fc \ube44\uc911\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub0ae\uace0 \uc0b0\uc5c5\uc7ac\uc640 \uae08\uc735 \ub4f1 \uac00\uce58\uc8fc \ube44\uc911\uc774 \ub192\uae30 \ub54c\ubb38\uc5d0 \uc0c1\uc2b9\ub960\uc774 0.36%\uc5d0 \uadf8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc0b0\uc5c5\uc7ac\uc640 \uac00\uce58\uc8fc \ube44\uc911\uc774 \ub354 \ub192\uc544 \uae30\uc220\uc8fc \ubc18\ub4f1\uc758 \uc218\ud61c\uac00 \uc791\uc558\uace0, 0.38% \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5f0\uacb0\uace0\ub9ac\ub294 \uae08\ub9ac\uc5d0\uc11c \uc2dc\uc791\ub429\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uc778\ud558 \uae30\ub300 \ud6c4\ud1f4\ub294 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ubd80\ub2f4\uc774\uc9c0\ub9cc, \uc774\ub0a0\uc740 \uacbd\uae30 \uacac\uc870\ud568\uacfc \uc120\uac70 \ubd88\ud655\uc2e4\uc131 \ud574\uc18c \uae30\ub300\uac00 \uadf8 \ubd80\ub2f4\uc744 \uc0c1\uc1c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc740 \uc5d0\ub108\uc9c0 \uc139\ud130\uc5d0\ub294 \ubd80\ub2f4\uc774\uc9c0\ub9cc, \uc6b4\uc1a1\uacfc \uc81c\uc870 \ub4f1 \uc5d0\ub108\uc9c0 \uc18c\ube44 \uc139\ud130\uc758 \ube44\uc6a9 \ubd80\ub2f4\uc744 \ub35c\uc5b4\uc8fc\ub294 \ucabd\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc815\ub9ac\ud558\uba74 \uc774\ub0a0\uc740 \uae30\uc220\uc8fc\uc640 \ubc18\ub3c4\uccb4\uac00 \uc218\ud61c\ub97c \uc785\uace0, \ub2e4\uc6b0\uc9c0\uc218\uc5d0 \ud3b8\uc785\ub41c \uc804\ud1b5 \uc0b0\uc5c5\uc8fc\uac00 \uc0c1\ub300\uc801\uc73c\ub85c \uc18c\uc678\ub41c \ub0a0\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7S&P500 \ub9c8\uac10 \ud750\ub984\\n\\nS&P500\uc740 7,568.92\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 +27.52, \ub4f1\ub77d\ub960\uc740 +0.36%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,541.40\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \ub2f9\uc77c \uace0\uac00\ub294 7,594.24, \ub2f9\uc77c \uc800\uac00\ub294 7,557.60\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 51,786.72\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 -197.26, \ub4f1\ub77d\ub960\uc740 -0.38%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218 \ub2f9\uc77c \uace0\uac00\ub294 51,932.63, \ub2f9\uc77c \uc800\uac00\ub294 51,593.16\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\uc740 \uc0c1\uc2b9\ud588\uc9c0\ub9cc \ub2e4\uc6b0\uc9c0\uc218\uac00 \ud558\ub77d\ud588\ub2e4\ub294 \uc810\uc5d0\uc11c \uc0c1\uc2b9 \ub3d9\ub825\uc740 \uc2dc\uc7a5 \uc804\ubc18\ubcf4\ub2e4 \uae30\uc220\uc8fc \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \ub2e4\uc74c \uac70\ub798\uc77c \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ud750\ub984 \uc9c0\uc18d\uacfc \uc77c\uc2dc\uc801 \ub418\ub3cc\ub9bc\uc744 \uad6c\ubd84\ud558\ub294 \uae30\uc900\uc740 \uc138 \uac00\uc9c0\uc785\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uc800\uac00 25,246.64 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uac04\uc774 \uc9c0\ucf1c\uc9c0\uba74 \ub418\ub3cc\ub9bc\uc774 \uc544\ub2c8\ub77c \ubc18\ub4f1 \ud750\ub984\uc73c\ub85c \uc774\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uace0\uac00 25,474.46 \ubd80\uadfc\uc744 \ub118\uc5b4\uc11c\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uace0\uac00\ub97c \ub118\uc9c0 \ubabb\ud558\uace0 \ub418\ubc00\ub9ac\uba74 \uc774\ub0a0 \uc0c1\uc2b9\uc740 \ub2e8\uae30 \ub418\ub3cc\ub9bc\uc5d0 \uadf8\uce60 \uac00\ub2a5\uc131\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc911\uac04\uc120\uac70 \uac1c\ud45c \uacb0\uacfc\uc640 \uc7a5 \ub9c8\uac10 \ub4a4 \ubc1c\ud45c\ub41c \ubc18\ub3c4\uccb4 \uae30\uc5c5 \uc2e4\uc801\uc774 \ub2e4\uc74c \uac70\ub798\uc77c \uc9c0\uc218 \ubc29\ud5a5\uc744 \uac00\ub97c \ubcc0\uc218\uc785\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801\uc774 \uae30\ub300\uc5d0 \ubbf8\uce58\uc9c0 \ubabb\ud558\uba74 \ubc18\ub3c4\uccb4 \ubc18\ub4f1\uc774 \ub418\ub3cc\ub824\uc9c8 \uc218 \uc788\uace0, \uc2e4\uc801\uc774 \uacac\uc870\ud558\uba74 \ubc18\ub4f1 \ud750\ub984\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 \ub098\uc2a4\ub2e5100 \uc9c0\uc218\uac00 10\uc6d4 \uace0\uc810 \ub300\ube44 10% \uc774\uc0c1 \ud558\ub77d\ud55c \uc870\uc815 \uad6d\uba74\uc5d0\uc11c \ubc97\uc5b4\ub098\ub294\uc9c0\uac00 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\uc870\uc815 \uad6d\uba74 \ud0c8\ucd9c \uc5ec\ubd80\ub294 \ub2e8 \ud558\ub8e8 \ubc18\ub4f1\uc774 \uc544\ub2c8\ub77c \uba70\uce60\uc5d0 \uac78\uce5c \uc800\uac00 \uc9c0\uc9c0 \uc5ec\ubd80\ub85c \ud310\ub2e8\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uae08\ub9ac \uacbd\ub85c\uc5d0 \ub300\ud574\uc11c\ub294 \ub2e4\uc74c \ubb3c\uac00 \uc9c0\ud45c\uc640 \uc5f0\ubc29\uc900\ube44\uc81c\ub3c4 \ubc1c\uc5b8\uc744 \ud568\uaed8 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc758 \uc804\ub9dd\uc740 \uc2dc\ub098\ub9ac\uc624 \uc815\ub9ac\uc774\uba70, \ub2e4\uc74c \uac70\ub798\uc77c\uc758 \uacb0\uacfc\ub97c \ubcf4\uc7a5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n2026\ub144 11\uc6d4 3\uc77c \ub098\uc2a4\ub2e5\uc740 0.83% \uc0c1\uc2b9\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub294 \uc800\uac00 \uc9c0\uc9c0 \uc5ec\ubd80\uc640 \ubc18\ub3c4\uccb4 \uc2e4\uc801, \uc120\uac70 \uacb0\uacfc\uc758 \uc601\ud5a5\uc744 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub418\uba70, \uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-03-nasdaq-market-midday","metadata":{"permalink":"/blog/en/market/2026-11-03-nasdaq-market-midday","source":"@site/market/2026-11-03-nasdaq-market-midday/index.mdx","title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911, \uc911\uac04\uc120\uac70 \ub300\uae30 \uc18d \ubc18\ub4f1\ud3ed \ud655\ub300","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-03T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":6.5,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-03-nasdaq-market-midday","title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911, \uc911\uac04\uc120\uac70 \ub300\uae30 \uc18d \ubc18\ub4f1\ud3ed \ud655\ub300","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 11\uc6d4 3\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-03-nasdaq-market-close"},"nextItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ubc18\ub4f1 \ucd9c\ubc1c \uc18d \uae30\uc220\uc8fc \ubd80\ub2f4\uc740 \uc5ec\uc804","permalink":"/blog/en/market/2026-11-03-nasdaq-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 3\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5\uc911 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc7a5\uc911 25,412.35\ub85c \uc804\uc77c \ub300\ube44 247.99\ud3ec\uc778\ud2b8, 0.99% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub3c4 7,578.94\ub85c 0.50% \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0\uc740 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ud22c\ud45c\uc77c\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5\uc740 \uc815\uc0c1 \uac1c\uc7a5\ud588\uace0, \uc120\uac70 \uacb0\uacfc\ub294 \uc7a5 \ub9c8\uac10 \uc774\ud6c4\ubd80\ud130 \uc724\uacfd\uc774 \ub4dc\ub7ec\ub0a9\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uae09\ub77d\uc5d0 \ub300\ud55c \ub418\ub3cc\ub9bc\uc774 \uc7a5\uc911\uae4c\uc9c0 \uc774\uc5b4\uc84c\uace0, \uc624\uc804\ubcf4\ub2e4 \uc0c1\uc2b9\ud3ed\uc774 \ucee4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,412.35 | +247.99 | +0.99% | 25,164.36 | 25,438.23 | 25,304.02 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-03 12:58, \ud55c\uad6d\uc2dc\uac04 2026-11-04 02:58 |\\n| \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 | 7,578.94 | +37.54 | +0.50% | 7,541.40 | 7,586.22 | 7,557.60 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-03 12:58, \ud55c\uad6d\uc2dc\uac04 2026-11-04 02:58 |\\n| \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | 51,983.98 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-03 12:58, \ud55c\uad6d\uc2dc\uac04 2026-11-04 02:58 |\\n\\n\ub2f9\uc77c \uc218\uce58\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc758 \uc2dc\uac00\ub294 25,246.64\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00\uc640 \uc800\uac00\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uc7a5\uc911 \uc2dc\uacc4\uc5f4\uc758 \ucd5c\ub300\uac12\uacfc \ucd5c\uc18c\uac12\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 \uc9c1\uc811 \uc870\ud68c \uc2dc \uac00\uaca9 \ub370\uc774\ud130\ub97c \ud3ec\ud568\ud55c \ubcf8\ubb38\uc744 \ud655\ubcf4\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \uc704 \uc2a4\ub0c5\uc0f7\uc740 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uc73c\ub85c \ucc44\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uac12\uc740 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uacfc [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569 \uac00\uaca9](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0 \ub2e4\uc6b0 \ud56d\ubaa9\uc774 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc544 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\ud45c\uba74\uc801\uc73c\ub85c\ub294 \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \ub300\ube44 0.99% \ubc18\ub4f1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadfc\ubcf8 \ucd09\ub9e4\ub294 \uc138 \uac00\uc9c0\ub85c \uc815\ub9ac\ub429\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \ub418\ub3cc\ub9bc\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 11\uc6d4 2\uc77c\uae4c\uc9c0 3\uac70\ub798\uc77c \uc5f0\uc18d \ud558\ub77d\ud588\uace0, 10\uc6d4\uc5d0\ub294 2025\ub144 3\uc6d4 \uc774\ud6c4 \uac00\uc7a5 \ud070 \uc6d4\uac04 \ud558\ub77d\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub099\ud3ed\uc774 \ub204\uc801\ub41c \ub4a4\uc5d0\ub294 \ub2e8\uae30 \ub418\ub3cc\ub9bc \ub9e4\uc218\uac00 \ub4e4\uc5b4\uc624\uae30 \uc26c\uc6b4 \uad6c\uac04\uc785\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc720\uac00 \uae09\ub77d\uc5d0 \ub530\ub978 \ubd80\ub2f4 \uc644\ud654\uc785\ub2c8\ub2e4.<br/>\\n11\uc6d4 2\uc77c \uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0 \uc6d0\uc720\ub294 \uc57d 8% \ud558\ub77d\ud574 \ubc30\ub7f4\ub2f9 95.80\ub2ec\ub7ec \uc548\ud30e\uc744 \uae30\ub85d\ud588\uace0, \ube0c\ub80c\ud2b8\uc720\ub294 7.6% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc740 \uc5d0\ub108\uc9c0 \ube44\uc6a9 \ubd80\ub2f4\uc744 \ub0ae\ucd94\uace0, \uc778\ud50c\ub808\uc774\uc158 \uc555\ub825 \uc644\ud654 \uae30\ub300\ub97c \ud1b5\ud574 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158 \ubd80\ub2f4\uc744 \ub35c\uc5b4\uc8fc\ub294 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc120\uac70 \ub2f9\uc77c\uc5d0\ub3c4 \uc7a5\uc774 \uc815\uc0c1 \uac1c\uc7a5\ud588\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4.<br/>\\n\ubd88\ud655\uc2e4\uc131\uc774 \uc0ac\ub77c\uc9c4 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \ud734\uc7a5\uc774 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4 \uc790\uccb4\uac00 \uc7a5\uc911 \uac70\ub798\ub97c \uc815\uc0c1 \uada4\ub3c4\uc5d0 \uc62c\ub824\ub193\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc9c0\uc218 \uac04 \ubc29\ud5a5 \ucc28\uc774\ub3c4 \uc758\ubbf8\ub97c \uac00\uc9d1\ub2c8\ub2e4.<br/>\\n11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5\uc740 1.07% \ud558\ub77d\ud588\uace0 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 0.51% \ud558\ub77d\ud588\uc9c0\ub9cc, \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 0.41% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc220\uc8fc\uc640 \uc131\uc7a5\uc8fc \uc911\uc2ec\uc758 \uc870\uc815\uc774 \uc9c4\ud589\ub418\ub294 \ub3d9\uc548 \ubc29\uc5b4\uc801\uc778 \uc131\uaca9\uc758 \uc885\ubaa9\uad70\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \ubc84\ud2f4 \uad6c\ub3c4\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc7a5\uc911\uc740 \uc774 \uad6c\ub3c4\uac00 \ub4a4\uc9d1\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc0c1\uc2b9\ub960 0.99%\uac00 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218 \uc0c1\uc2b9\ub960 0.50%\ub97c \uc6c3\ub3cc\uc558\uace0, \ub099\ud3ed\uc774 \ucef8\ub358 \uae30\uc220\uc8fc\uc758 \ub418\ub3cc\ub9bc\uc774 \uc9c0\uc218 \ucc28\ubcc4\ud654\ub97c \uc8fc\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uad6d\ucc44\uc218\uc775\ub960\uacfc \ub2ec\ub7ec\uc758 \ub2f9\uc77c \uc7a5\uc911 \uc218\uce58\ub294 \ubcc4\ub3c4\ub85c \ud655\uc778\ub418\uc9c0 \uc54a\uc544 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n\uccab\uc9f8, \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ud22c\ud45c\uc77c\uacfc \uacb0\uacfc \ub300\uae30\uc785\ub2c8\ub2e4.<br/>\\n\uc5f0\ud569\ub274\uc2a4 \ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \ub274\uc695\uc99d\uc2dc\ub294 \uc911\uac04\uc120\uac70 \uacb0\uacfc\ub97c \uc8fc\uc2dc\ud558\uba70 \ud63c\uc870 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d\uacfc \uc911\uad6d\uc758 \ubb34\uc5ed\uc815\ucc45 \uc804\uac1c \uc0c1\ud669\ub3c4 \ud575\uc2ec \uad00\uc2ec\uc0ac\ub85c \ud568\uaed8 \uac70\ub860\ub410\uace0, \ud2b8\ub7fc\ud504 \ub300\ud1b5\ub839\uc758 \ub099\uad00\uc801 \ubc1c\uc5b8\uc774 \uc911\uac04\uc120\uac70\ub97c \uc55e\ub454 \uc120\uc2ec\uc131 \ubc1c\uc5b8\uc77c \uc218 \uc788\ub2e4\ub294 \uc9c0\uc801\ub3c4 \uc2dc\uc7a5 \uc77c\ubd80\uc5d0\uc11c \uc81c\uae30\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub370\uc77c\ub9ac \ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \ubbfc\uc8fc\ub2f9\uc774 \uc0c1\uc6d0\uacfc \ud558\uc6d0\uc744 \ubaa8\ub450 \uc7a5\uc545\ud558\uba74 \ub274\uc695\uc99d\uc2dc\uac00 \ub2e8\uae30 \ucda9\uaca9\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4\ub294 \uc804\ub9dd\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\nJP\ubaa8\uac74\uc740 \ubbfc\uc8fc\ub2f9 \uc555\uc2b9 \uc2dc \ub2e4\uc74c \ub0a0 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\uac00 0.5% \ud558\ub77d\ud560 \uc218 \uc788\ub2e4\uace0 \uc804\ub9dd\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uace8\ub4dc\ub9cc\uc0ad\uc2a4\ub294 \ubbfc\uc8fc\ub2f9 \uc758\ud68c\uac00 \ub370\uc774\ud130\uc13c\ud130 \uc138\uc81c \ud61c\ud0dd\uc744 \uc81c\ud55c\ud560 \uc218 \uc788\uc9c0\ub9cc, \uc5b4\ub5a4 \uc120\uac70 \uacb0\uacfc\uc5d0\uc11c\ub3c4 \uc804\uad6d\uc801\uc778 \uac74\uc124 \uc720\uc608 \uc870\uce58\ub294 \uac00\ub2a5\uc131\uc774 \ub0ae\ub2e4\uace0 \ud3c9\uac00\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubcd1\uc6d0\uc8fc\uc640 \ubcf4\ud5d8\uc8fc\uc5d0 \ub300\ud55c \uc9c0\uc6d0 \ud655\ub300 \uae30\ub300, \uce74\ub4dc\uae08\ub9ac \uc0c1\ud55c \ub17c\uc758, \uc774\ub780\uc804 \ubcc0\uc218\ub3c4 \ud568\uaed8 \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2ec\ub9ac\uc801\uc73c\ub85c\ub294 \uacb0\uacfc\uc5d0 \ub530\ub77c \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \uc815\ucc45\uacfc \uaddc\uc81c \uacbd\ub85c\uac00 \uac08\ub9b0\ub2e4\ub294 \uc810\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4.<br/>\\n\uacb0\uacfc\uac00 \ud655\uc778\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \ubc29\ud5a5\uc131 \ubca0\ud305\uc774 \uc790\uc81c\ub418\uace0, \uacb0\uacfc \ud655\uc778 \uc774\ud6c4\uc5d0 \uc139\ud130\ubcc4 \ub85c\ud14c\uc774\uc158\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\\n\ub458\uc9f8, \ube4c \uc560\ud06c\uba3c\uc758 \ub808\ubc84\ub9ac\uc9c0\uc640 \ud22c\uae30 \uac70\ub798 \uacbd\uace0\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub370\uc77c\ub9ac \ubcf4\ub3c4\uc5d0 \ub530\ub974\uba74 \uc5b5\ub9cc\uc7a5\uc790 \ud22c\uc790\uc790 \ube4c \uc560\ud06c\uba3c\uc740 \ud22c\uae30\uc801 \uac70\ub798\uc640 \ub808\ubc84\ub9ac\uc9c0 \ud655\uc0b0\uc73c\ub85c \ubbf8\uad6d \uc8fc\uc2dd\uc2dc\uc7a5\uc774 \uce74\uc9c0\ub178\ucc98\ub7fc \uc6c0\uc9c1\uc774\uace0 \uc788\ub2e4\uace0 \uacbd\uace0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud37c\uc2f1\uc2a4\ud018\uc5b4\ub294 \ub9c8\uc774\ud06c\ub85c\uc18c\ud504\ud2b8\uc640 \uc544\ub9c8\uc874 \ud558\ub77d \ub54c \ub9e4\uc218\ud588\uace0, \ube44\uc790\uc640 \ub9c8\uc2a4\ud130\uce74\ub4dc, \ub137\ud50c\ub9ad\uc2a4\uc5d0 \uae0d\uc815\uc801 \ud3c9\uac00\ub97c \ub0b4\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc560\ud06c\uba3c\uc740 \uc2dc\uc7a5\uc758 \uac00\uaca9 \uc65c\uace1\uc774 \uc7a5\uae30 \ud22c\uc790\uc790\uc5d0\uac8c \ub9e4\uc218 \uae30\ud68c\ub97c \uc81c\uacf5\ud55c\ub2e4\uace0 \uc124\uba85\ud558\uba74\uc11c\ub3c4, \uad6d\uac00 \uc804\uccb4\ub85c \ubcf4\uba74 \ubc14\ub78c\uc9c1\ud558\uc9c0 \uc54a\ub2e4\uace0 \ub367\ubd99\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\uc870\uc801\uc73c\ub85c\ub294 \ubcc0\ub3d9\uc131 \ud655\ub300 \uad6c\uac04\uc5d0\uc11c \uac00\uaca9 \ubc1c\uacac \uae30\ub2a5\uc774 \uc57d\ud574\uc9c8 \uc218 \uc788\ub2e4\ub294 \uacbd\uace0\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ubc18\ub4f1 \uc18d\uc5d0\uc11c\ub3c4 \uace0\ubcc0\ub3d9\uc131 \uc885\ubaa9\uad70\uc758 \uae09\ub4f1\ub77d\uc774 \uc774\uc5b4\uc9c8 \uc218 \uc788\ub2e4\ub294 \uacbd\uacc4\uac10\uc744 \ud568\uaed8 \ub0a8\uacbc\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\uc14b\uc9f8, \uc560\ud50c \uc2e4\uc801 \uc774\ud6c4 \ub9c8\uc9c4 \ubd80\ub2f4\uacfc \uc778\uacf5\uc9c0\ub2a5 \uc885\ubaa9 \ub0b4 \uc120\ubcc4\uc785\ub2c8\ub2e4.<br/>\\n\uc560\ud50c\uc758 3\ubd84\uae30 \ub9e4\ucd9c\uc740 1,144\uc5b5 8,000\ub9cc \ub2ec\ub7ec\ub85c \uc804\ub144 \ub3d9\uae30 \ub300\ube44 \uc57d 12% \uc99d\uac00\ud574 \uc2dc\uc7a5 \uc608\uc0c1\uce58 1,133\uc5b5 9,000\ub9cc \ub2ec\ub7ec\ub97c \uc6c3\ub3cc\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc11c\ube44\uc2a4 \ub9e4\ucd9c \uc131\uc7a5\ub960 \uc804\ub9dd\uc774 8\uc5d0\uc11c 9%\ub85c \uc2dc\uc7a5 \uc608\uc0c1\uce58 10.7%\ub97c \ud558\ud68c\ud588\uace0, 10\uc6d4\uc5d0\uc11c 12\uc6d4 \ubd84\uae30 \ub9e4\ucd9c\ucd1d\uc774\uc775\ub960\uc740 45\uc5d0\uc11c 46%\ub85c 9\uc6d4 \ubd84\uae30 47.9%\ubcf4\ub2e4 \ub0ae\uc544\uc9c8 \uac83\uc73c\ub85c \uc804\ub9dd\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uba54\ubaa8\ub9ac \uac00\uaca9 \uc0c1\uc2b9\uc5d0 \ub530\ub978 \uc6d0\uac00 \ubd80\ub2f4\uacfc \uc11c\ube44\uc2a4 \uc131\uc7a5 \ub454\ud654 \uc6b0\ub824\uac00 \uacb9\uce58\uba74\uc11c \uc8fc\uac00\ub294 \uc2dc\uac04\uc678 \uac70\ub798\uc5d0\uc11c \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ub274\uc2a4 \ubaa9\ub85d\uc5d0 \ub530\ub974\uba74 \uc70c\ub9ac\uc5c4 \ube14\ub808\uc5b4\ub294 \ud314\ub780\ud2f0\uc5b4\uc5d0 \ub300\ud574 \uc778\uacf5\uc9c0\ub2a5 \uc139\ud130 \ub0b4\uc5d0\uc11c\ub3c4 \ud380\ub354\uba58\ud138\uc774 \uacac\uace0\ud558\ub2e4\uace0 \ud3c9\uac00\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc220\uc8fc \ub0b4\ubd80\uc5d0\uc11c\ub3c4 \uc2e4\uc801\uacfc \ub9c8\uc9c4 \uc99d\uba85\uc774 \ub418\ub294 \uc885\ubaa9\uacfc \uadf8\ub807\uc9c0 \uc54a\uc740 \uc885\ubaa9\uc774 \uac08\ub9ac\ub294 \uc120\ubcc4 \uc7a5\uc138\uac00 \uc7a5\uc911 \ubc18\ub4f1\uc758 \uc9c8\uc744 \uac00\ub974\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\ub098\uc2a4\ub2e5 \uc0c1\uc2b9\ub960\uc774 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218 \uc0c1\uc2b9\ub960\uc744 \uc6c3\ub3c8 \uc810\uc774 \uac00\uc7a5 \ud070 \ucc28\ubcc4\uc810\uc785\ub2c8\ub2e4.<br/>\\n\uc5f0\uacb0\uace0\ub9ac\ub294 \uae08\ub9ac\uc5d0\uc11c \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc73c\ub85c \uc774\uc5b4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc774 \uc778\ud50c\ub808\uc774\uc158 \uc555\ub825 \uc644\ud654 \uae30\ub300\ub85c \uc774\uc5b4\uc9c0\uba74, \uc7a5\uae30 \uc131\uc7a5\uc8fc\uc758 \ud560\uc778\uc728 \ubd80\ub2f4\uc774 \ub35c\uc5b4\uc9c0\uace0 \ub098\uc2a4\ub2e5 \ube44\uc911\uc774 \ub192\uc740 \uae30\uc220\uc8fc\uac00 \uba3c\uc800 \ubc18\uc751\ud569\ub2c8\ub2e4.<br/>\\n\uc5d0\ub108\uc9c0 \uc139\ud130\ub294 \ubc18\ub300 \ubc29\ud5a5\uc758 \uc555\ub825\uc744 \ubc1b\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub9c8\uac10\uc5d0\uc11c\ub294 \uc720\uac00 \uae09\ub77d\uc5d0 \ub530\ub978 \uc5d0\ub108\uc9c0\uc8fc \uc57d\uc138\uac00 \ud63c\uc870 \ub9c8\uac10\uc758 \ud55c \uc694\uc778\uc774\uc5c8\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc7a5\uc911 \uc5d0\ub108\uc9c0 \uc139\ud130\uc758 \ubc29\ud5a5\uc740 \ubcc4\ub3c4\ub85c \ud655\uc778\ub418\uc9c0 \uc54a\uc544 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\uae08\uc735 \uc139\ud130\ub294 \uc120\uac70 \uacb0\uacfc\uc5d0 \ubbfc\uac10\ud55c \ubcc0\uc218\uc5d0 \ub178\ucd9c\ub3fc \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uce74\ub4dc\uae08\ub9ac \uc0c1\ud55c \ub17c\uc758\uac00 \uacb0\uacfc\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uae08\uc735\uc8fc \ubc29\ud5a5\uc744 \uac00\ub974\ub294 \uc694\uc778\uc785\ub2c8\ub2e4.<br/>\\n\ud5ec\uc2a4\ucf00\uc5b4 \uc139\ud130\ub294 \ubbfc\uc8fc\ub2f9 \uc2b9\ub9ac \uc2dc \uc9c0\uc6d0 \ud655\ub300 \uae30\ub300\uac00 \uac70\ub860\ub418\ub294 \ucabd\uc785\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c\uc640 \ubc18\ub3c4\uccb4 \uc139\ud130\ub294 \ub370\uc774\ud130\uc13c\ud130 \uc138\uc81c \ud61c\ud0dd \uc81c\ud55c \uac00\ub2a5\uc131\uacfc \uc804\uad6d\uc801 \uac74\uc124 \uc720\uc608 \uac00\ub2a5\uc131 \ub0ae\uc74c\uc774\ub77c\ub294 \ub450 \uac00\uc9c0 \ud3c9\uac00 \uc0ac\uc774\uc5d0\uc11c \ubd88\ud655\uc2e4\uc131\uc774 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uba74 \uc911\ub2e8 \uc2dc\ub098\ub9ac\uc624\ub294 \ub0ae\uac8c \ud3c9\uac00\ub410\uc9c0\ub9cc, \uc138\uc81c \ud61c\ud0dd \ucd95\uc18c \ub17c\uc758 \uc790\uccb4\ub294 \uad00\ub828 \uc885\ubaa9\uad70\uc758 \ubcc0\ub3d9\uc131\uc744 \ud0a4\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7S&P500 \ud750\ub984\\n\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,578.94\ub85c \uc804\uc77c \ub300\ube44 37.54\ud3ec\uc778\ud2b8, 0.50% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00\ub294 7,586.22, \uc7a5\uc911 \uc800\uac00\ub294 7,557.60\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 09\uc2dc 59\ubd84 \uae30\uc900 0.26% \uc0c1\uc2b9\uc5d0\uc11c \uc7a5\uc911 0.50%\ub85c \uc0c1\uc2b9\ud3ed\uc774 \ucee4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ud615\uc8fc \uc804\ubc18\uc758 \uc644\ub9cc\ud55c \ubc18\ub4f1 \ud750\ub984\uc73c\ub85c, \ub098\uc2a4\ub2e5\ubcf4\ub2e4\ub294 \uc0c1\uc2b9\ud3ed\uc774 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0 \ud56d\ubaa9\uc774 \uc5c6\uc5b4 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 51,983.98\ub85c \uc804\uc77c \ub300\ube44 0.41% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c\uc5d0\ub294 \ub2e4\uc6b0\ub9cc \uc62c\ub790\ub358 \uad6c\ub3c4\uc640 \ub2ec\ub9ac, \ub2f9\uc77c \uc7a5\uc911\uc740 \uae30\uc220\uc8fc \uc8fc\ub3c4 \ubc18\ub4f1\uc73c\ub85c \uc9c0\uc218 \uac04 \uaca9\ucc28\uac00 \ucd95\uc18c\ub418\ub294 \ubc29\ud5a5\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uacfc \uc624\ud6c4 \ud750\ub984 \ubcc0\ud654\\n\\n\uc624\uc804 09\uc2dc 59\ubd84 \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,319.33\uc73c\ub85c 0.62% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 12\uc2dc 58\ubd84 \uae30\uc900 25,412.35\ub85c 0.99% \uc0c1\uc2b9\ud558\uba74\uc11c \uc0c1\uc2b9\ud3ed\uc774 \ucee4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc740 \uc5c6\uc5c8\uace0, \uc0c1\uc2b9 \ud750\ub984\uc774 \uadf8\ub300\ub85c \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uace0\uc810 25,385.18\uc740 \uc7a5\uc911 \uace0\uc810 25,438.23\uc73c\ub85c \uc0c1\ud5a5 \ub3cc\ud30c\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub3c4 \uc624\uc804 0.26%\uc5d0\uc11c \uc7a5\uc911 0.50%\ub85c \uc0c1\uc2b9\ud3ed\uc744 \ud0a4\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10\uae4c\uc9c0 \uc804\ub9dd\uacfc \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\uc7a5\uc911 \ud750\ub984\uc774 \uc9c0\uc18d\ub418\ub294 \uc2dc\ub098\ub9ac\uc624\ub294 \uc7a5\uc911 \uace0\uc810 25,438.23 \uc720\uc9c0\uc640 25,400\uc120 \uc548\ucc29\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uad6c\uac04\uc774 \uc9c0\ucf1c\uc9c0\uba74 \ubc18\ub4f1 \ud750\ub984\uc774 \ub9c8\uac10\uae4c\uc9c0 \uc774\uc5b4\uc9c8 \uac00\ub2a5\uc131\uc774 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc77c\uc2dc\uc801 \ub178\uc774\uc988\ub85c \ub418\ub3cc\ub824\uc9c0\ub294 \uc2dc\ub098\ub9ac\uc624\ub294 \uc624\ud6c4 \ub4e4\uc5b4 \uc120\uac70 \uacb0\uacfc \ubc1c\ud45c\ub97c \uc55e\ub454 \uacbd\uacc4\uac10\uc5d0 \ucc28\uc775 \ub9e4\ubb3c\uc774 \ub098\uc624\ub294 \uacbd\uc6b0\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uacbd\uc6b0 \uc624\uc804 \uace0\uc810 25,385.18 \uc774\ud0c8 \uc5ec\ubd80\ub97c \uba3c\uc800 \ud655\uc778\ud558\uace0, \uc544\ub798\ub85c\ub294 \uc2dc\uac00 25,246.64 \ubd80\uadfc\uc774 \uc9c0\uc9c0 \uad6c\uac04\uc774 \ub429\ub2c8\ub2e4.<br/>\\n\uc800\ud56d \uad6c\uac04\uc740 \uc7a5\uc911 \uace0\uc810 25,438.23\uc785\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ud560 \uc774\ubca4\ud2b8\ub294 \uc911\uac04\uc120\uac70 \uac1c\ud45c \uc724\uacfd\uc73c\ub85c, \ud55c\uad6d\uc2dc\uac04 11\uc6d4 4\uc77c \uc624\uc804\ubd80\ud130 \uc724\uacfd\uc774 \ub4dc\ub7ec\ub0a9\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ucd94\uac00 \uc6c0\uc9c1\uc784\ub3c4 \ud568\uaed8 \ud655\uc778\ud560 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uad6d\ucc44\uc218\uc775\ub960\uacfc \ub2ec\ub7ec\uc758 \ubc29\ud5a5\uc740 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uacb0\uacfc\uc5d0 \ub530\ub77c \uc7a5 \ub9c8\uac10 \ud6c4 \uc2dc\uac04\uc678 \ubcc0\ub3d9\uc131\uc774 \ucee4\uc9c8 \uc218 \uc788\uc5b4, \uc9c0\uc218 \ub2e8\uc704\uc5d0\uc11c\ub3c4 \uac2d \ubcc0\ub3d9 \uac00\ub2a5\uc131\uc744 \uc5fc\ub450\uc5d0 \ub454 \ub9ac\uc2a4\ud06c \uad00\ub9ac \uad00\uc810\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc911\uac04\uc120\uac70 \ud22c\ud45c\uc77c \uc7a5\uc911 \ud750\ub984\uc740 \uc804\uc77c \uae09\ub77d\uc5d0 \ub300\ud55c \ub418\ub3cc\ub9bc\uacfc \uacb0\uacfc \ub300\uae30 \uc2ec\ub9ac\uac00 \ud568\uaed8 \uc791\uc6a9\ud55c \ubaa8\uc2b5\uc785\ub2c8\ub2e4.<br/>\\n\ub9c8\uac10\uae4c\uc9c0\ub294 \uac1c\ud45c \uc724\uacfd\uacfc \uc7a5\uc911 \uace0\uc810 \uc720\uc9c0 \uc5ec\ubd80\ub97c \ud655\uc778\ud558\ub294 \uac83\uc774 \uc21c\uc11c\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-03-nasdaq-market-open","metadata":{"permalink":"/blog/en/market/2026-11-03-nasdaq-market-open","source":"@site/market/2026-11-03-nasdaq-market-open/index.mdx","title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ubc18\ub4f1 \ucd9c\ubc1c \uc18d \uae30\uc220\uc8fc \ubd80\ub2f4\uc740 \uc5ec\uc804","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-03T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":7.48,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-03-nasdaq-market-open","title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ubc18\ub4f1 \ucd9c\ubc1c \uc18d \uae30\uc220\uc8fc \ubd80\ub2f4\uc740 \uc5ec\uc804","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5\uc911, \uc911\uac04\uc120\uac70 \ub300\uae30 \uc18d \ubc18\ub4f1\ud3ed \ud655\ub300","permalink":"/blog/en/market/2026-11-03-nasdaq-market-midday"},"nextItem":{"title":"2026\ub144 11\uc6d4 2\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-02-domestic-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 3\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uac1c\uc7a5 \ubc30\uacbd\\n\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 \ud63c\uc870 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,164.36\uc73c\ub85c \uc804\uc77c \ub300\ube44 1.07% \ud558\ub77d\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,541.40\uc73c\ub85c 0.51% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 51,983.98\ub85c 0.41% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub298 11\uc6d4 3\uc77c\uc740 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ud22c\ud45c\uc77c\uc774\uba70, \ub274\uc695\uc99d\uad8c\uac70\ub798\uc18c\uc640 \ub098\uc2a4\ub2e5\uc740 \uc815\uc0c1 \uac1c\uc7a5\ud569\ub2c8\ub2e4.<br/>\\n\uc120\uac70\ub294 \uc5f0\ubc29 \uacf5\ud734\uc77c\uc774 \uc544\ub2c8\ubbc0\ub85c \uc7a5\uc740 \uc815\uaddc \uc2dc\uac04\uc778 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 09\uc2dc 30\ubd84\ubd80\ud130 16\uc2dc\uae4c\uc9c0 \uc5f4\ub9bd\ub2c8\ub2e4.<br/>\\n\uc774\ub7ec\ud55c \ubc30\uacbd \uc18d\uc5d0\uc11c \ub098\uc2a4\ub2e5\uc740 \ubc18\ub4f1 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,319.33 | +154.96 | +0.62% | 25,164.36 | 25,385.18 | 25,246.64 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-03 09:59, \ud55c\uad6d\uc2dc\uac04 2026-11-03 23:59 |\\n| \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 | 7,561.04 | +19.64 | +0.26% | 7,541.40 | 7,567.55 | 7,558.52 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-03 09:59\uacbd, \ud55c\uad6d\uc2dc\uac04 2026-11-03 23:59\uacbd |\\n| \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | 51,983.98 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026-11-03 09:59\uacbd, \ud55c\uad6d\uc2dc\uac04 2026-11-03 23:59\uacbd |\\n\\n\ub2f9\uc77c \uc218\uce58\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc758 \uc2dc\uac00\ub294 25,246.64\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uac12\uc740 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uacfc [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ub098\uc2a4\ub2e5 \uc885\ud569 \uac00\uaca9](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 \uc9c1\uc811 \ud14d\uc2a4\ud2b8 \uc870\ud68c\uac00 \ucc28\ub2e8\ub418\uc5b4 \ube0c\ub77c\uc6b0\uc800\ub85c \uac12\uc744 \ud655\uc778\ud588\uace0, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uacfc \uad50\ucc28 \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,311.67\ub85c \uc804\uc77c \ub300\ube44 147.31\ud3ec\uc778\ud2b8, 0.59% \uc0c1\uc2b9\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,561.04\ub85c 0.26% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \ucd9c\ucc98\uc758 \ub098\uc2a4\ub2e5 \uac12 \ucc28\uc774\ub294 \uc870\ud68c \uc2dc\uc810 \ucc28\uc774 \ubc94\uc704 \uc548\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0 \ub2e4\uc6b0 \ud56d\ubaa9\uc774 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc544 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804 \uc120\ubb3c \ub3d9\ud5a5\uc740 \ud63c\uc870\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 100 \uc120\ubb3c\uc740 0.28% \uc0c1\uc2b9\ud55c \ubc18\uba74, \ub2e4\uc6b0 \uc120\ubb3c\uc740 0.75% \ud558\ub77d\ud588\uace0, \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc120\ubb3c\uc740 0.12% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \uc6d0\uc778\xb7\ucd09\ub9e4 \ubd84\uc11d\\n\\n\ud45c\uba74\uc801\uc73c\ub85c\ub294 \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \ub300\ube44 0.62% \ubc18\ub4f1 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadfc\ubcf8 \ucd09\ub9e4\ub294 \uc138 \uac00\uc9c0\ub85c \uc815\ub9ac\ub429\ub2c8\ub2e4.<br/>\\n\uccab\uc9f8, \ub418\ub3cc\ub9bc\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 11\uc6d4 2\uc77c\uae4c\uc9c0 3\uac70\ub798\uc77c \uc5f0\uc18d \ud558\ub77d\ud588\uace0, 10\uc6d4\uc5d0\ub294 2025\ub144 3\uc6d4 \uc774\ud6c4 \uac00\uc7a5 \ud070 \uc6d4\uac04 \ud558\ub77d\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub099\ud3ed\uc774 \ub204\uc801\ub41c \ub4a4\uc5d0\ub294 \ub2e8\uae30 \ub418\ub3cc\ub9bc \ub9e4\uc218\uac00 \ub4e4\uc5b4\uc624\uae30 \uc26c\uc6b4 \uad6c\uac04\uc785\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc720\uac00 \uae09\ub77d\uc5d0 \ub530\ub978 \ubd80\ub2f4 \uc644\ud654 \uae30\ub300\uc785\ub2c8\ub2e4.<br/>\\n11\uc6d4 2\uc77c \uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0 \uc6d0\uc720\ub294 \uc57d 8% \ud558\ub77d\ud574 \ubc30\ub7f4\ub2f9 95.80\ub2ec\ub7ec \uc548\ud30e\uc744 \uae30\ub85d\ud588\uace0, \ube0c\ub80c\ud2b8\uc720\ub294 7.6% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc740 \uc5d0\ub108\uc9c0 \ube44\uc6a9 \ubd80\ub2f4\uc744 \ub0ae\ucd94\uace0, \uc18c\ube44 \uc5ec\ub825\uacfc \uc6b4\uc1a1 \ube44\uc6a9 \uce21\uba74\uc5d0\uc11c \uc6b0\ud638\uc801\uc778 \uc694\uc778\uc73c\ub85c \uc791\uc6a9\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc120\uac70 \ub2f9\uc77c\uc5d0\ub3c4 \uc7a5\uc774 \uc815\uc0c1 \uac1c\uc7a5\ud55c\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4.<br/>\\n\ubd88\ud655\uc2e4\uc131\uc774 \uc0ac\ub77c\uc9c4 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \ud734\uc7a5\uc774 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4 \uc790\uccb4\uac00 \uc7a5 \ucd08\ubc18 \uac70\ub798\ub97c \uc815\uc0c1 \uada4\ub3c4\uc5d0 \uc62c\ub824\ub193\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \ubc18\ub4f1\uc758 \uc9c8\uc740 \uc544\uc9c1 \ud655\uc778 \ub2e8\uacc4\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5 \ub9c8\uac10 \ud6c4 \ubc1c\ud45c\ub41c \uc560\ud50c \uc2e4\uc801\uc5d0\uc11c \ub9e4\ucd9c\uacfc \uc8fc\ub2f9\uc21c\uc774\uc775\uc740 \uc608\uc0c1\uc744 \uc6c3\uc5c8\uc73c\ub098, 12\uc6d4 \ubd84\uae30 \ub9e4\ucd9c\ucd1d\uc774\uc775\ub960 \uac00\uc774\ub358\uc2a4\uac00 9\uc6d4 \ubd84\uae30 47.9%\ubcf4\ub2e4 \ub0ae\uc740 45%\uc5d0\uc11c 46%\ub85c \uc81c\uc2dc\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uba54\ubaa8\ub9ac \ube44\uc6a9 \uc0c1\uc2b9\uc774 \uc9c1\uc811\uc801\uc778 \uc555\ubc15 \uc694\uc778\uc73c\ub85c \uc9c0\ubaa9\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \ub54c\ubb38\uc5d0 \uc9c0\uc218\ub294 \uc62c\ub790\uc9c0\ub9cc, \uae30\uc220\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ub300\ud55c \ubd80\ub2f4\uc740 \uc7a5 \ucd08\ubc18\uc5d0\ub3c4 \uadf8\ub300\ub85c \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uac04 \ubc29\ud5a5 \ucc28\uc774\ub3c4 \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc774 0.62% \uc624\ub978 \ubc18\uba74 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 0.26% \uc624\ub974\ub294 \ub370 \uadf8\ucce4\uace0, \uac1c\uc7a5 \uc804 \ub2e4\uc6b0 \uc120\ubb3c\uc740 \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uae30\uc220\uc8fc \ub418\ub3cc\ub9bc\uc774 \ubc18\ub4f1\uc744 \uc8fc\ub3c4\ud558\uace0, \ubc29\uc5b4\uc8fc \uc911\uc2ec\uc758 \ub2e4\uc6b0 \uac15\uc138\ub294 \ub418\ub3cc\ub9bc \uad6d\uba74\uc5d0 \ub4e4\uc5b4\uac14\uc744 \uac00\ub2a5\uc131\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804 \uad6d\ucc44\uc218\uc775\ub960 \uc0c1\uc2b9 \ubcf4\ub3c4\ub294 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ubd80\ub2f4\uc73c\ub85c \uc791\uc6a9\ud560 \uc218 \uc788\ub294 \uc694\uc778\uc774\ub098, \uad6c\uccb4\uc801\uc778 \uc218\uc775\ub960 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ud575\uc2ec \uc0ac\uac74 3\uac00\uc9c0\\n\\n### \uccab\uc9f8, \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ud22c\ud45c\uc77c\uc785\ub2c8\ub2e4\\n\\n11\uc6d4 3\uc77c\uc740 \ubbf8\uad6d \uc911\uac04\uc120\uac70 \ud22c\ud45c\uc77c\uc785\ub2c8\ub2e4.<br/>\\n\ud558\uc6d0\uc758\uc6d0\uacfc \uc0c1\uc6d0\uc758\uc6d0, \uc8fc\uc9c0\uc0ac\ub97c \uc120\ucd9c\ud558\ub294 \uc120\uac70\uc774\uba70, \uacb0\uacfc\ub294 \uc7a5 \ub9c8\uac10 \uc774\ud6c4 \uac1c\ud45c\uc640 \ud568\uaed8 \uc120\ubb3c \uc2dc\uc7a5\uc5d0 \uba3c\uc800 \ubc18\uc601\ub429\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uacb0\uacfc\uac00 \uc7ac\uc815 \ubc29\ud5a5\uacfc \uc815\ucc45 \ubd88\ud655\uc2e4\uc131\uc5d0 \uc601\ud5a5\uc744 \uc904 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0, \uc7a5\uc911\uc5d0\ub294 \uacb0\uacfc\ub97c \uc608\ub2e8\ud558\uae30\ubcf4\ub2e4 \ubcc0\ub3d9\uc131 \ud655\ub300 \uac00\ub2a5\uc131\uc5d0 \ub300\ube44\ud558\ub294 \ud750\ub984\uc774 \ub098\ud0c0\ub0a0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub525\uc11c\uce58 \ubb38\uc11c \uac80\uc0c9\uc5d0\uc11c\ub3c4 11\uc6d4 4\uc77c\uc790 \ud55c\uad6d \uc2e0\ubb38 \ubbf8\ub9ac\ubcf4\uae30\uc5d0\uc11c \uc911\uac04\uc120\uac70\ub97c \uc2ec\ud310\ub300\ub77c\ub294 \ud45c\ud604\uc73c\ub85c \ub2e4\ub8e8\uace0 \uc788\uc5b4, \uc120\uac70\uc758 \uc815\uce58\uc801 \ubb34\uac8c\uac00 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\uc2dc\uc7a5 \uad00\uc810\uc5d0\uc11c\ub294 \uc120\uac70 \uc790\uccb4\ubcf4\ub2e4 \uc7a5 \ub9c8\uac10 \ud6c4 \uac1c\ud45c \ud750\ub984\uc774 \ub354 \ud070 \ubcc0\uc218\uc785\ub2c8\ub2e4.<br/>\\n\\n### \ub458\uc9f8, \uc560\ud50c \uc2e4\uc801 \ubc1c\ud45c\uc640 \ub9c8\uc9c4 \uac00\uc774\ub358\uc2a4\uc785\ub2c8\ub2e4\\n\\n\uc560\ud50c\uc740 11\uc6d4 2\uc77c \uc7a5 \ub9c8\uac10 \ud6c4 2026 \ud68c\uacc4\uc5f0\ub3c4 4\ubd84\uae30 \uc2e4\uc801\uc744 \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub9e4\ucd9c\uc740 1,144\uc5b5 8,000\ub9cc \ub2ec\ub7ec\ub85c \uc804\ub144 \ub300\ube44 \uc57d 12% \uc99d\uac00\ud588\uace0, \uc8fc\ub2f9\uc21c\uc774\uc775\uc740 2.10\ub2ec\ub7ec\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc218\uce58 \ubaa8\ub450 \uc2dc\uc7a5 \uc608\uc0c1\uc778 \ub9e4\ucd9c \uc57d 1,134\uc5b5 \ub2ec\ub7ec\uc640 \uc8fc\ub2f9\uc21c\uc774\uc775 1.99\ub2ec\ub7ec\ub97c \uc6c3\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc544\uc774\ud3f0 \ub9e4\ucd9c\uc740 575\uc5b5 8,000\ub9cc \ub2ec\ub7ec\ub85c \uc804\ub144 \ub300\ube44 \uc57d 17% \uc99d\uac00\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 12\uc6d4 \ubd84\uae30 \ub9e4\ucd9c\ucd1d\uc774\uc775\ub960 \uac00\uc774\ub358\uc2a4\ub294 45%\uc5d0\uc11c 46%\ub85c \uc81c\uc2dc\ub3fc 9\uc6d4 \ubd84\uae30 47.9%\ubcf4\ub2e4 \ub0ae\uc544\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uacbd\uc601\uc9c4\uc740 \uba54\ubaa8\ub9ac \uac00\uaca9 \uc0c1\uc2b9\uacfc \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \uc218\uc694 \uacbd\uc7c1\uc744 \uc555\ubc15 \uc694\uc778\uc73c\ub85c \uc124\uba85\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 3\uc77c \uac1c\uc7a5 \uc804 \uc560\ud50c \uc8fc\uac00\ub294 \uc57d 4% \ud558\ub77d\ud55c 323\ub2ec\ub7ec \uc548\ud30e\uc5d0\uc11c \uac70\ub798\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2e4\uc801 \uc790\uccb4\ub294 \uc608\uc0c1\uc744 \uc6c3\uc5c8\uc73c\ub098, \ub9c8\uc9c4 \uc804\ub9dd\uc774 \uc2dc\uc7a5 \uc2ec\ub9ac\ub97c \ub204\ub978 \uc804\ud615\uc801\uc778 \uac00\uc774\ub358\uc2a4 \ubc18\uc751\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uac1c\ubcc4 \uc885\ubaa9\uc758 \ubb38\uc81c\ub97c \ub118\uc5b4, \uba54\ubaa8\ub9ac \ube44\uc6a9\uc774 \ud558\ub4dc\uc6e8\uc5b4 \uc804\ubc18\uc758 \uc218\uc775\uc131\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc0ac\uac74\uc785\ub2c8\ub2e4.<br/>\\n\\n### \uc14b\uc9f8, \uc720\uac00 \uae09\ub77d\uacfc \uae30\uc220\uc8fc \ub9e4\ub3c4 \uc9c0\uc18d\uc785\ub2c8\ub2e4\\n\\n11\uc6d4 2\uc77c \uc720\uac00\ub294 \ubbf8\uad6d\uacfc \uc774\ub780 \uac04 \uc678\uad50 \uae30\ub300\uac10\uc5d0 \uae09\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc11c\ubd80\ud14d\uc0ac\uc2a4\uc0b0 \uc6d0\uc720\ub294 \uc57d 8% \ud558\ub77d\ud588\uace0, \ube0c\ub80c\ud2b8\uc720\ub294 7.6% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac19\uc740 \ub0a0 \uc5d0\ub108\uc9c0 \uc139\ud130\ub294 3.97% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 \ud56d\uacf5\uacfc \uc6b4\uc1a1 \uad00\ub828\uc8fc\ub294 \uc720\uac00 \ud558\ub77d \uc218\ud61c \uae30\ub300\uc5d0 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc220\uc8fc \ub9e4\ub3c4\ub294 \uc774\ub0a0\ub3c4 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uae30\uc220 \uc139\ud130\ub294 2.66% \ud558\ub77d\ud588\uace0, \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\ub294 3.37% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\ud154\uc740 \uc804 \uac70\ub798\uc77c \uc57d 30% \uae09\ub77d\uc5d0 \uc774\uc5b4 8.8% \ucd94\uac00 \ud558\ub77d\ud588\uace0, \ub9c8\ubca8 \ud14c\ud06c\ub180\ub85c\uc9c0\ub294 \ub8e8\uba58\ud140 \uc778\uc218 \uc18c\uc2dd\uc5d0 12.7% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\ub77c\ud074\ub3c4 8.85% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 100 \uc9c0\uc218\ub294 10\uc6d4 \ud55c \ub2ec \ub3d9\uc548 2\uc870 \ub2ec\ub7ec\uac00 \ub118\ub294 \uc2dc\uac00\ucd1d\uc561 \uac10\uc18c\ub97c \uae30\ub85d\ud55c \uac83\uc73c\ub85c \ubcf4\ub3c4\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc774 \ubb3c\uac00 \ubd80\ub2f4\uc744 \ub35c\uc5b4\uc8fc\ub294 \uc7ac\ub8cc\uc778 \ub3d9\uc2dc\uc5d0, \uae30\uc220\uc8fc \ub9e4\ub3c4\uac00 \uba48\ucd94\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc774 11\uc6d4 2\uc77c \uc7a5\uc758 \uc774\uc911 \uad6c\uc870\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc9c0\uc218\xb7\uc139\ud130 \uc601\ud5a5 \uccb4\uc778\\n\\n\uae08\ub9ac\uc5d0\uc11c \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\uac00 \uba3c\uc800 \uc791\ub3d9\ud569\ub2c8\ub2e4.<br/>\\n\uad6d\ucc44\uc218\uc775\ub960\uc774 \uc624\ub974\uba74 \ubbf8\ub798 \uc774\uc775\uc744 \ud604\uc7ac \uac00\uce58\ub85c \ud658\uc0b0\ud558\ub294 \ud560\uc778\uc728\uc774 \ub192\uc544\uc838 \uc131\uc7a5\uc8fc \ubc38\ub958\uc5d0\uc774\uc158\uc5d0 \ubd80\ub2f4\uc774 \ucee4\uc9d1\ub2c8\ub2e4.<br/>\\n\uc560\ud50c\uc758 \ub9c8\uc9c4 \uac00\uc774\ub358\uc2a4\ucc98\ub7fc \uc774\uc775\uc758 \uc9c8\uc5d0 \ub300\ud55c \uc758\ubb38\uc774 \ub354\ud574\uc9c0\uba74, \uac19\uc740 \uae08\ub9ac \uc218\uc900\uc5d0\uc11c\ub3c4 \uae30\uc220\uc8fc\uc5d0 \ub300\ud55c \uc694\uad6c \uc218\uc775\ub960\uc740 \ub192\uc544\uc9d1\ub2c8\ub2e4.<br/>\\n\uc720\uac00\uc5d0\uc11c \uc5d0\ub108\uc9c0\uc640 \uc6b4\uc1a1\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub294 \uc815\ubc18\ub300 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc720\uac00 \ud558\ub77d\uc740 \uc5d0\ub108\uc9c0 \uae30\uc5c5 \uc2e4\uc801\uc5d0\ub294 \ubd80\uc815\uc801\uc774\uc9c0\ub9cc, \ud56d\uacf5\uacfc \uc6b4\uc1a1, \uc18c\ube44 \uad00\ub828 \uae30\uc5c5\uc758 \ube44\uc6a9 \ubd80\ub2f4\uc744 \ub0ae\ucda5\ub2c8\ub2e4.<br/>\\n11\uc6d4 2\uc77c \uc5d0\ub108\uc9c0 \uc139\ud130 \ud558\ub77d\uacfc \ud56d\uacf5\uc8fc \uc0c1\uc2b9\uc774 \ub3d9\uc2dc\uc5d0 \ub098\ud0c0\ub09c \uc774\uc720\uc785\ub2c8\ub2e4.<br/>\\n\uba54\ubaa8\ub9ac \ube44\uc6a9\uc5d0\uc11c \ubc18\ub3c4\uccb4\uc640 \ud558\ub4dc\uc6e8\uc5b4\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub3c4 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \uacbd\uc7c1\uc774 \uba54\ubaa8\ub9ac \uc218\uc694\ub97c \ub04c\uc5b4\uc62c\ub9ac\uba74\uc11c, \ud558\ub4dc\uc6e8\uc5b4 \uae30\uc5c5\uc758 \uc6d0\uac00 \ubd80\ub2f4\uc774 \ucee4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ubc18\ub3c4\uccb4 \uc5c5\ud669 \uc790\uccb4\uc758 \ud638\uc870\uc640 \ud558\ub4dc\uc6e8\uc5b4 \uae30\uc5c5\uc758 \ub9c8\uc9c4 \uc555\ubc15\uc774 \uacf5\uc874\ud560 \uc218 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\uc120\uac70\uc5d0\uc11c \uc815\ucc45 \ubd88\ud655\uc2e4\uc131\uc73c\ub85c \uc774\uc5b4\uc9c0\ub294 \uc5f0\uacb0\uace0\ub9ac\ub294 \uc7a5 \ub9c8\uac10 \ud6c4\uc5d0 \ubcf8\uaca9\ud654\ub429\ub2c8\ub2e4.<br/>\\n\uacb0\uacfc\uc5d0 \ub530\ub77c \uc7ac\uc815\uacfc \uaddc\uc81c \ubc29\ud5a5\uc5d0 \ub300\ud55c \uae30\ub300\uac00 \ubc14\ub00c\uace0, \uc120\ubb3c \uc2dc\uc7a5\uc774 \uba3c\uc800 \ubc18\uc751\ud558\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.<br/>\\n\uc218\ud61c\uc640 \ud0c0\uaca9\uc744 \ub2e8\uc21c\ud788 \ub098\ub204\uae30\ubcf4\ub2e4, \uac19\uc740 \uc7ac\ub8cc\uac00 \uc139\ud130\ub9c8\ub2e4 \ub2e4\ub978 \ubc29\ud5a5\uc73c\ub85c \uc791\uc6a9\ud55c\ub2e4\ub294 \uc810\uc774 \uc774\ubc88 \uc7a5\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\xb7\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \ud750\ub984\\n\\n\ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 11\uc6d4 2\uc77c 0.41% \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \ub098\uc2a4\ub2e5\uacfc \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\uac00 \ud558\ub77d\ud55c \ub0a0 \ub2e4\uc6b0\ub9cc \uc624\ub978, \ucc28\ubcc4\ud654\ub41c \ud750\ub984\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n11\uc6d4 2\uc77c \uc7a5\uc5d0\uc11c\ub294 \uc18c\ube44\uc7ac\uc640 \uae08\uc735, \uc18c\uc7ac \uad00\ub828\uc8fc\uac00 \uc0c1\ub300\uc801\uc73c\ub85c \uac15\ud588\uace0, \uc5d0\ub108\uc9c0\uc8fc\ub294 \uc720\uac00 \ud558\ub77d\uc5d0 \uc57d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uae30\uc220\uc8fc \ub9e4\ub3c4 \uad6d\uba74\uc5d0\uc11c \uc790\uae08\uc774 \ubc29\uc5b4\uc801\uc778 \uc131\uaca9\uc758 \ub300\ud615\uc8fc\ub85c \uc774\ub3d9\ud588\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n11\uc6d4 3\uc77c \uac1c\uc7a5 \uc804 \ub2e4\uc6b0 \uc120\ubb3c\uc774 0.75% \ud558\ub77d\ud55c \uc810\uc740, \uc804\uc77c\uc758 \ubc29\uc5b4\uc8fc \uac15\uc138\uac00 \ub418\ub3cc\ub9bc \uad6d\uba74\uc5d0 \ub4e4\uc5b4\uac14\uc744 \uac00\ub2a5\uc131\uc744 \uc2dc\uc0ac\ud569\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 11\uc6d4 2\uc77c 0.51% \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\uc5d0\ub294 1.1%\uae4c\uc9c0 \uc62c\ub790\uc73c\ub098 \uc624\ud6c4 \ub4e4\uc5b4 \uae30\uc220\uc8fc \uc57d\uc138\uc5d0 \ubc00\ub824 \ud558\ub77d \uc804\ud658\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uc804\uccb4\ub85c \ubcf4\uba74 \uc57d 70%\uc5d0 \uac00\uae4c\uc6b4 \uc885\ubaa9\uc774 \uc0c1\uc2b9\ud588\uc74c\uc5d0\ub3c4 \uc9c0\uc218\uac00 \ud558\ub77d\ud588\ub2e4\ub294 \uc810\uc774 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\uc774\ub294 \uc9c0\uc218 \ud558\ub77d\uc774 \uc2dc\uc7a5 \uc804\ubc18\uc758 \uc57d\uc138\uac00 \uc544\ub2c8\ub77c, \uc2dc\uac00\ucd1d\uc561 \ube44\uc911\uc774 \ud070 \uae30\uc220\uc8fc\uc758 \ud558\ub77d\uc5d0 \uc758\ud574 \uc8fc\ub3c4\ub410\uc74c\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.<br/>\\n11\uc6d4 3\uc77c \uc7a5 \ucd08\ubc18 \uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 \ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 0.26% \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\ubcf4\ub2e4\ub294 \uc0c1\uc2b9 \ud3ed\uc774 \uc791\uc544, \uae30\uc220\uc8fc \ub418\ub3cc\ub9bc\uc774 \uc9c0\uc218 \uc0c1\uc2b9\uc744 \uc8fc\ub3c4\ud558\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\\n## \ub2e8\uae30\xb7\uc911\uae30 \uc804\ub9dd\uacfc \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc2dc\ub098\ub9ac\uc624\\n\\n\ub2e8\uae30\uc801\uc73c\ub85c\ub294 \ubc18\ub4f1 \uc9c0\uc18d\uacfc \uc77c\uc2dc\uc801 \ub178\uc774\uc988\ub97c \uad6c\ubd84\ud558\ub294 \uad6c\uac04\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\uc5d0 \ud655\uc778\ud560 \uccab \ubc88\uc9f8 \uc218\uce58\ub294 \ub098\uc2a4\ub2e5 \uc885\ud569\uc758 \uc804\uc77c \uc885\uac00 25,164.36 \uc548\ucc29 \uc5ec\ubd80\uc785\ub2c8\ub2e4.<br/>\\n\ud604\uc7ac\uac00 25,319.33\uc740 \uc804\uc77c \uc885\uac00\ub97c \uc6c3\ub3cc\uace0 \uc788\uc73c\ub098, \uc774 \uc218\uc900\uc744 \uc7a5\uc911 \ub0b4\ub0b4 \uc720\uc9c0\ud558\ub294\uc9c0\uac00 \uad00\uac74\uc785\ub2c8\ub2e4.<br/>\\n\ub450 \ubc88\uc9f8 \uc218\uce58\ub294 \uc7a5\uc911 \uace0\uac00 25,385.18 \ub3cc\ud30c \uc9c0\uc18d \uc5ec\ubd80\uc785\ub2c8\ub2e4.<br/>\\n\uc774 \uace0\uac00\ub97c \uc9c0\ucf1c\ub0b4\uba74 \ubc18\ub4f1\uc758 \ud798\uc774 \uc774\uc5b4\uc9c0\ub294 \uc2e0\ud638\ub85c \ubcfc \uc218 \uc788\uace0, \ubc18\ub0a9\ud558\uba74 \ub418\ub3cc\ub9bc\uc758 \ud798\uc774 \uc57d\ud55c \uac83\uc73c\ub85c \ud574\uc11d\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc138 \ubc88\uc9f8 \uad6c\uac04\uc740 \uc804\uc77c \uc7a5\uc911 \ubc94\uc704\uc785\ub2c8\ub2e4.<br/>\\n11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc885\ud569\uc758 \uc7a5\uc911 \uace0\uac00\ub294 25,799.46, \uc800\uac00\ub294 25,145.95\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc800\uac00 \uc544\ub798\ub85c \ub0b4\ub824\uac00\uba74 \ubc18\ub4f1\uc774 \ubb34\ub108\uc9c0\ub294 \uc2e0\ud638\ub85c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 \uc804\uc77c \uc885\uac00 7,541.40, \ub2e4\uc6b0\uc874\uc2a4 \uc0b0\uc5c5\ud3c9\uade0\uc9c0\uc218\ub294 \uc804\uc77c \uc885\uac00 51,983.98\uc744 \uae30\uc900\uc73c\ub85c \uac19\uc740 \ud310\ub2e8\uc744 \uc801\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc911\uae30\uc801\uc73c\ub85c\ub294 10\uc6d4 \uae09\ub77d \uc774\ud6c4\uc758 \ub418\ub3cc\ub9bc\uc778\uc9c0 \ucd94\uc138 \uc804\ud658\uc778\uc9c0\ub97c \uac00\ub9ac\ub294 \uad6d\uba74\uc785\ub2c8\ub2e4.<br/>\\n\uc120\uac70 \uacb0\uacfc\uc640 \uc774\ubc88 \uc8fc \uc2e4\uc801 \ubc1c\ud45c, \uac70\uc2dc\uc9c0\ud45c\uac00 \uadf8 \ud310\ub2e8 \uc7ac\ub8cc\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5 \ub9c8\uac10 \ud6c4 \uac1c\ud45c \ud750\ub984\uacfc \uc120\ubb3c \ubc18\uc751, \uadf8\ub9ac\uace0 \uae30\uc220\uc8fc \ub9c8\uc9c4 \uc555\ubc15\uc774 \uc2e4\uc801 \uc804\ubc18\uc73c\ub85c \ud655\uc0b0\ub418\ub294\uc9c0\ub97c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.<br/>\\n\ub9ac\uc2a4\ud06c \uad00\ub9ac \uad00\uc810\uc5d0\uc11c\ub294 \uc9c0\uc218 \ub2e8\uc704\uc5d0\uc11c \uc804\uc77c \uc885\uac00\uc640 \uc7a5\uc911 \uace0\uc800\ub97c \uae30\uc900\uc73c\ub85c \ud750\ub984\uc744 \uc810\uac80\ud558\uace0, \ub2e8\uc77c \uc7ac\ub8cc\uc5d0 \uc758\ud55c \uae09\ub4f1\ub77d\uc5d0 \uacfc\ub3c4\ud558\uac8c \ubc18\uc751\ud558\uc9c0 \uc54a\ub294 \ud0dc\ub3c4\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uc9c0\uc218\uc640 \uc139\ud130 \ub2e8\uc704\uc758 \ud574\uc124\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc624\ub298 \uc7a5\uc740 \ubc18\ub4f1 \ucd9c\ubc1c\uacfc \uae30\uc220\uc8fc \ubd80\ub2f4\uc774 \uacf5\uc874\ud558\ub294 \uad6c\uac04\uc5d0\uc11c \uc2dc\uc791\ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18\uc5d0\ub294 \uc804\uc77c \uc885\uac00 \uc548\ucc29 \uc5ec\ubd80\uc640 \uc7a5\uc911 \uace0\uac00 \ub3cc\ud30c \uc9c0\uc18d \uc5ec\ubd80\ub97c \uc911\uc2ec\uc73c\ub85c \ud750\ub984\uc744 \ud655\uc778\ud558\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc758 \uc815\ub9ac\uc774\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-02-domestic-market-close","metadata":{"permalink":"/blog/en/market/2026-11-02-domestic-market-close","source":"@site/market/2026-11-02-domestic-market-close/index.mdx","title":"2026\ub144 11\uc6d4 2\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-02T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":2.56,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-02-domestic-market-close","title":"2026\ub144 11\uc6d4 2\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508, \ubc18\ub4f1 \ucd9c\ubc1c \uc18d \uae30\uc220\uc8fc \ubd80\ub2f4\uc740 \uc5ec\uc804","permalink":"/blog/en/market/2026-11-03-nasdaq-market-open"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ud558\ub77d \ucd9c\ubc1c \ub4a4 \uc0c1\uc2b9 \uc804\ud658\ud574 5,800\uc120 \ud68c\ubcf5","permalink":"/blog/en/market/2026-11-02-domestic-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 2\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc774 \ubaa8\ub450 \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 2.24% \uc0c1\uc2b9\ud55c 5,859.08\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \ub300\ube44 1.38% \uc0c1\uc2b9\ud55c 734.36\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00\uc5d0\uc11c\ub294 \uc804\uc77c \uc885\uac00\ub97c \ubc11\ub3cc\uc558\uc73c\ub098 \uc7a5\uc911 \uc0c1\uc2b9 \uc804\ud658\ud574 \uc591\ubd09\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 5,910.83\uae4c\uc9c0 \uc62c\ub790\ub2e4\uac00 5,859.08\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc7a5\uc911 738.01\uae4c\uc9c0 \uc62c\ub790\ub2e4\uac00 734.36\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\ub09c\uc8fc \ub9d0 \uc774\ud2c0 \uc5f0\uc18d \ud558\ub77d \uc774\ud6c4 \ubc18\ub4f1\ud558\ub294 \ud750\ub984\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,859.08 | +128.34 | +2.24% | 5,637.77 | 5,910.83 | 5,616.50 | 186,383\ucc9c\uc8fc | 14\uc870 8,702\uc5b5\uc6d0 |\\n| \ucf54\uc2a4\ub2e5 | 734.36 | +9.98 | +1.38% | 716.44 | 738.01 | 716.21 | 332,464\ucc9c\uc8fc | 4\uc870 8,000\uc5b5\uc6d0 |\\n\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,730.74, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 724.38\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 228,294 |\\n| 2026-11-02 | 5,637.77 | 5,910.83 | 5,616.50 | 5,859.08 | 186,383 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 470,174 |\\n| 2026-11-02 | 716.44 | 738.01 | 716.21 | 734.36 | 332,464 |\\n\\n\ucf54\uc2a4\ud53c\ub294 10\uc6d4 30\uc77c 5,730.74\uae4c\uc9c0 \ub0b4\ub824\uac14\ub2e4\uac00 \uc624\ub298 5,859.08\ub85c \ubc18\ub4f1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 10\uc6d4 30\uc77c 724.38\uae4c\uc9c0 \ub0b4\ub824\uac14\ub2e4\uac00 \uc624\ub298 734.36\uc73c\ub85c \ubc18\ub4f1\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2f9\uc77c \uc218\uae09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | -13,466 |\\n| \uc678\uad6d\uc778 | -3,743 |\\n| \uae30\uad00 | +12,331 |\\n| \uae30\ud0c0\ubc95\uc778 | +4,878 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | -261 |\\n| \uc678\uad6d\uc778 | -322 |\\n| \uae30\uad00 | +623 |\\n| \uae30\ud0c0\ubc95\uc778 | -40 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uae30\uad00\uacfc \uae30\ud0c0\ubc95\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uac1c\uc778\uacfc \uc678\uad6d\uc778\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uae30\uad00\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uac1c\uc778\uacfc \uc678\uad6d\uc778\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc218\uae09 \uc218\uce58\ub294 \ub124\uc774\ubc84 \uc2dc\uc7a5 \uc218\uae09 \uc790\ub8cc\ub97c \uae30\uc900\uc73c\ub85c \ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub2f9\uc77c \uac15\uc138 \ud14c\ub9c8\ub294 \uc804\ub825\uae30\uae30, \uc870\uc120, \uc870\uc120\uae30\uc790\uc7ac\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\ub825\uae30\uae30 \ud14c\ub9c8\ub294 7.91% \uc0c1\uc2b9\ud588\uace0, \uc870\uc120 \ud14c\ub9c8\ub294 5.62% \uc0c1\uc2b9\ud588\uc73c\uba70, \uc870\uc120\uae30\uc790\uc7ac \ud14c\ub9c8\ub294 4.98% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\uc2ec\uc774 \ucef8\ub358 \ub300\uc678 \ubcc0\uc218\ub85c\ub294 \ubbf8\uad6d \uae30\uc220\uc8fc \uc870\uc815 \uc6b0\ub824\uc640 \ubbf8\uad6d \uc911\uac04\uc120\uac70, \uc8fc\uc694 \uacbd\uc81c\uc9c0\ud45c \ubc1c\ud45c\uac00 \uc5b8\uae09\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \uc0c1\uc2b9\uc5d0\ub3c4 \uc678\uad6d\uc778\uc774 \uc21c\ub9e4\ub3c4\ub97c \uc774\uc5b4\uac04 \uc810\uc740 \uc218\uae09 \uce21\uba74\uc5d0\uc11c \ud655\uc778\ub418\ub294 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub0b4\uc77c \ud655\uc778\ud560 \uc810\\n\\n\ubbf8\uad6d \uc911\uac04\uc120\uac70 \uacb0\uacfc\uc640 \ubbf8\uad6d \uace0\uc6a9\uc9c0\ud45c \ubc1c\ud45c \uc77c\uc815\uc774 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778 \uc21c\ub9e4\ub3c4\uac00 \uc774\uc5b4\uc9c8\uc9c0, \uae30\uad00 \uc21c\ub9e4\uc218\uac00 \uc720\uc9c0\ub420\uc9c0 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\uac00 5,900\uc120 \uc548\ud30e\uc5d0\uc11c \uc5b4\ub5a4 \ud750\ub984\uc744 \ubcf4\uc77c\uc9c0 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ubbf8\uad6d \uae30\uc220\uc8fc \uc870\uc815 \uc6b0\ub824\uac00 \uad6d\ub0b4 \ub300\ud615\uc8fc\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\ub3c4 \ud568\uaed8 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc624\ub298 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \uc9c0\ub09c\uc8fc \ub9d0 \ud558\ub77d\uc744 \uc77c\ubd80 \ub418\ub3cc\ub9ac\uba70 \uc0c1\uc2b9 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \uc704\ud55c \uc218\uce58 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\ub294 \ub0b4\uc6a9\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-02-domestic-market-midday","metadata":{"permalink":"/blog/en/market/2026-11-02-domestic-market-midday","source":"@site/market/2026-11-02-domestic-market-midday/index.mdx","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ud558\ub77d \ucd9c\ubc1c \ub4a4 \uc0c1\uc2b9 \uc804\ud658\ud574 5,800\uc120 \ud68c\ubcf5","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-02T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":2.9,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-02-domestic-market-midday","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ud558\ub77d \ucd9c\ubc1c \ub4a4 \uc0c1\uc2b9 \uc804\ud658\ud574 5,800\uc120 \ud68c\ubcf5","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 11\uc6d4 2\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-02-domestic-market-close"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \uc57d\uc138 \ucd9c\ubc1c \ub4a4 \ub099\ud3ed \ucd95\uc18c","permalink":"/blog/en/market/2026-11-02-domestic-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 2\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uc7a5 \uc694\uc57d\\n\\n\uc9c0\ub09c \uc8fc\ub9d0 \ubbf8\uad6d \uc99d\uc2dc\uc5d0\uc11c\ub294 \uc778\ud154 \uc8fc\uac00 \uae09\ub77d\uacfc \uc2e0\uc6a9 \uc6b0\ub824\uac00 \uc5b8\uae09\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\ub828 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \uc778\ud154 \uc8fc\uac00\uac00 29% \ud558\ub77d\ud558\uace0 \ud544\ub77c\ub378\ud53c\uc544 \ubc18\ub3c4\uccb4\uc9c0\uc218\uac00 7.20% \ud558\ub77d\ud588\ub2e4\uace0 \uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub7ec\ud55c \ubc30\uacbd \uc18d\uc5d0\uc11c \ucf54\uc2a4\ud53c\ub294 1.62% \ud558\ub77d\ud55c 5,637\uc120\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uadf8\ub7ec\ub098 \uc7a5 \ucd08\ubc18 \ud68c\ubcf5\uc138\ub97c \ubcf4\uc774\uba70 \uc624\uc804 9\uc2dc 36\ubd84\uaed8 \uc0c1\uc2b9 \uc804\ud658\ud588\ub2e4\uace0 \uad00\ub828 \ubcf4\ub3c4\ub294 \uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc815\uc624 \ubb34\ub835\uc5d0\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \uc804\uc77c \ub300\ube44 \uc0c1\uc2b9\ud3ed\uc744 \ud0a4\uc6b0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,857.57 | +126.83 | +2.21% | 5,637.77 | 5,863.88 | 5,616.50 | 117,103\ucc9c\uc8fc | 8\uc870 5,146\uc5b5\uc6d0 | 2026-11-02 12:28 KST |\\n| \ucf54\uc2a4\ub2e5 | 735.87 | +11.49 | +1.59% | 716.44 | 737.34 | 716.21 | 217,840\ucc9c\uc8fc | 3\uc870 1,164\uc5b5\uc6d0 | 2026-11-02 12:28 KST |\\n\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,637.77\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,857.57\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 716.44\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 735.87\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,730.74, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 724.38\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-26 | 5,499.05 | 5,565.67 | 5,455.11 | 5,469.47 | 202,295 |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 228,294 |\\n| 2026-11-02 | 5,637.77 | 5,863.88 | 5,616.50 | 5,856.06 | 116,665 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-26 | 742.17 | 745.95 | 727.20 | 727.21 | 476,231 |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 470,174 |\\n| 2026-11-02 | 716.44 | 737.34 | 716.21 | 736.20 | 217,096 |\\n\\n2026\ub144 11\uc6d4 2\uc77c \ubd09\uc740 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc77c\ubd09 \ud45c\uc758 \ub2f9\uc77c \uc885\uac00\ub294 \ud45c \uc791\uc131 \uc2dc\uc810\uc758 \ud615\uc131 \uc911 \uc218\uce58\uc774\uba70 \uc2e4\uc2dc\uac04 \ud604\uc7ac\uac00\uc640 \uc2dc\ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c 5,730.74\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 5,850\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c 724.38\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 735\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984 \ubcc0\ud654\\n\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\ub825\uae30\uae30 \ud14c\ub9c8\uac00 7.21% \uc0c1\uc2b9\ud588\uace0, \uad00\uc774\uc74c\uc1e0 \ud14c\ub9c8\uac00 6.98% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc870\uc120 \ud14c\ub9c8\uac00 6.07%, \uc870\uc120\uae30\uc790\uc7ac \ud14c\ub9c8\uac00 5.57% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc774 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,637.77\ubcf4\ub2e4 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,857.57\uc774 \ub192\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 716.44\ubcf4\ub2e4 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 735.87\uc774 \ub192\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc7a5\uc911 \uc218\uae09 \ud655\uc815\uce58\ub294 \uc544\uc9c1 \uc9d1\uacc4\ub418\uc9c0 \uc54a\uc544 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ud6c4\uc5d0 \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 5,850\uc120 \ubd80\uadfc\uc758 \uc0c1\uc2b9\ud3ed\uc744 \uc720\uc9c0\ud558\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 735\uc120 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\uc758 \uc0c1\uc2b9\uc138\uac00 \uc624\ud6c4\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ub9c8\uac10 \ubb34\ub835 \uc218\uae09 \ud655\uc815\uce58\uac00 \uc5b4\ub5bb\uac8c \uc9d1\uacc4\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ud558\ub77d \ucd9c\ubc1c \ub4a4 \uc0c1\uc2b9 \uc804\ud658\ud574 \uc815\uc624 \ubb34\ub835 \ub450 \uc9c0\uc218 \ubaa8\ub450 \uc804\uc77c \ub300\ube44 \uc0c1\uc2b9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-02-domestic-market-open","metadata":{"permalink":"/blog/en/market/2026-11-02-domestic-market-open","source":"@site/market/2026-11-02-domestic-market-open/index.mdx","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \uc57d\uc138 \ucd9c\ubc1c \ub4a4 \ub099\ud3ed \ucd95\uc18c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-02T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":2.95,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-02-domestic-market-open","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \uc57d\uc138 \ucd9c\ubc1c \ub4a4 \ub099\ud3ed \ucd95\uc18c","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ud558\ub77d \ucd9c\ubc1c \ub4a4 \uc0c1\uc2b9 \uc804\ud658\ud574 5,800\uc120 \ud68c\ubcf5","permalink":"/blog/en/market/2026-11-02-domestic-market-midday"},"nextItem":{"title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-02-nasdaq-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 2\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ubc30\uacbd\\n\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 25,437.00\uc73c\ub85c \uc804\uc77c \ub300\ube44 747.72\ud3ec\uc778\ud2b8, 2.86% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,580.07\ub85c \uc804\uc77c \ub300\ube44 140.32\ud3ec\uc778\ud2b8, 1.82% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\ub828 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \uc778\uacf5\uc9c0\ub2a5 \uc218\uc775\uc131 \uc6b0\ub824\uac00 \ubbf8\uad6d \uc99d\uc2dc \ud558\ub77d\uc758 \ubc30\uacbd\uc73c\ub85c \uc5b8\uae09\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc6d0/\ub2ec\ub7ec \ud658\uc728\uc740 1,335.00\uc6d0\uc73c\ub85c \uc804\uc77c \ub300\ube44 0.70\uc6d0, 0.05% \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub7ec\ud55c \ud750\ub984 \uc18d\uc5d0\uc11c \uad6d\ub0b4 \uc99d\uc2dc\ub294 \uc57d\uc138\ub85c \ucd9c\ubc1c\ud55c \ub4a4 \ub099\ud3ed\uc744 \uc904\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uac1c\ubcc4 \uc885\ubaa9\uc758 \ud750\ub984\uc744 \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub824\uc6b0\uba70, \uc774\ub294 \ucc38\uace0\uc6a9 \ubc30\uacbd \uc815\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,725.35 | -5.39 | -0.09% | 5,637.77 | 5,725.35 | 5,616.50 | 39,590\ucc9c\uc8fc | 2\uc870 7,193\uc5b5\uc6d0 | 2026-11-02 09:29 KST |\\n| \ucf54\uc2a4\ub2e5 | 724.06 | -0.32 | -0.04% | 716.44 | 726.29 | 716.21 | 81,439\ucc9c\uc8fc | 1\uc870 2,124\uc5b5\uc6d0 | 2026-11-02 09:29 KST |\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc740 \ubaa8\ub450 \ud558\ub77d \ucd9c\ubc1c\ud55c \ub4a4 \ub099\ud3ed\uc744 \uc904\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,637.77\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,725.35\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 716.44\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 724.06\uc744 \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,730.74, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 724.38\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-26 | 5,499.05 | 5,565.67 | 5,455.11 | 5,469.47 | 202,295 |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 228,294 |\\n| 2026-11-02 | 5,637.77 | 5,717.94 | 5,616.50 | 5,717.94 | 38,950 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-26 | 742.17 | 745.95 | 727.20 | 727.21 | 476,231 |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 470,174 |\\n| 2026-11-02 | 716.44 | 726.29 | 716.21 | 724.58 | 80,277 |\\n\\n2026\ub144 11\uc6d4 2\uc77c \ubd09\uc740 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc77c\ubd09 \ud45c\uc758 \ub2f9\uc77c \uc885\uac00\ub294 \ud45c \uc791\uc131 \uc2dc\uc810\uc758 \ud615\uc131 \uc911 \uc218\uce58\uc774\uba70 \uc2e4\uc2dc\uac04 \ud604\uc7ac\uac00\uc640 \uc2dc\ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c 5,730.74\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 5,720\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c 724.38\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 724\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc804\uc77c \uc218\uae09\\n\\n\uc804\uc77c\uc778 2026\ub144 10\uc6d4 30\uc77c \uc218\uae09\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +6,027 |\\n| \uc678\uad6d\uc778 | -16,149 |\\n| \uae30\uad00 | +7,539 |\\n| \uae30\ud0c0\ubc95\uc778 | +2,580 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +1,648 |\\n| \uc678\uad6d\uc778 | -212 |\\n| \uae30\uad00 | -1,391 |\\n| \uae30\ud0c0\ubc95\uc778 | -47 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uac1c\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc678\uad6d\uc778 \uc21c\ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc774\ub0a0 \uc218\uae09\uc5d0\uc11c \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 5,720\uc120 \ubd80\uadfc\uc5d0\uc11c \ub099\ud3ed\uc744 \ub354 \uc904\uc774\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 724\uc120 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uacfc \uae30\uad00\uc758 \uc7a5 \ucd08\ubc18 \uc218\uae09 \ubc29\ud5a5\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc \ud558\ub77d \ubc30\uacbd\uacfc \uad00\ub828\ub41c \ud750\ub984\uc774 \uc7a5\uc911 \uc644\ud654\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uc7a5 \ucd08\ubc18 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ud558\ub77d \ucd9c\ubc1c \ub4a4 \ub099\ud3ed\uc744 \uc904\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-02-nasdaq-market-close","metadata":{"permalink":"/blog/en/market/2026-11-02-nasdaq-market-close","source":"@site/market/2026-11-02-nasdaq-market-close/index.mdx","title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-02T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":2.3,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-02-nasdaq-market-close","title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \uc57d\uc138 \ucd9c\ubc1c \ub4a4 \ub099\ud3ed \ucd95\uc18c","permalink":"/blog/en/market/2026-11-02-domestic-market-open"},"nextItem":{"title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-02-nasdaq-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc804\uc77c \ub300\ube44 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\ub960\uc740 1.07%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\ub3c4 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc73c\ub098 \ub099\ud3ed\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc0c1\uc2b9\uc73c\ub85c \ub9c8\uac10\ud574 \uc9c0\uc218 \uac04 \ubc29\ud5a5\uc774 \uac08\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \ub2f9\uc77c \uace0\uac00 | \ub2f9\uc77c \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,164.32 | -272.68 | -1.07% | 25,437.00 | 25,796.40 | 25,164.32 |\\n| S&P500 | 7,541.40 | -38.67 | -0.51% | 7,580.07 | 7,659.78 | 7,541.40 |\\n| \ub2e4\uc6b0\uc9c0\uc218 | 51,983.98 | +213.67 | +0.41% | 51,770.31 | 52,424.91 | 51,981.66 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 11\uc6d4 2\uc77c 16\uc2dc 20\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 11\uc6d4 3\uc77c 06\uc2dc 20\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc218\uce58\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \uc885\uac00\uc5d0\uc11c \uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc744 \ube7c\ub294 \ubc29\uc2dd\uc73c\ub85c \uc5ed\uc0b0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 \uc804 \uac70\ub798\uc77c \ub9c8\uac10 \uae00\uc758 \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 \ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4\uc758 \ucd5c\ub300\uac12\uacfc \ucd5c\uc18c\uac12\uc73c\ub85c \uc0b0\ucd9c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218 \uc218\uce58\ub294 Yahoo Finance \uc77c\ubd09\uc73c\ub85c \ud655\uc778\ud55c \uac12\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 \uc9c1\uc811 \uc870\ud68c\uc5d0\uc11c \uc218\uce58 \ucd94\ucd9c\uc774 \ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \ubcf8\ubb38 \uc2a4\ub0c5\uc0f7\uc740 \ub124\uc774\ubc84 \uac12\uc774 \uc544\ub2c8\ub77c \ud55c\ud22c MTS \uad50\ucc28\uac12\uc73c\ub85c \ucc44\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc640 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub9c8\uac10 \uc6d0\uc778\uc740 \ubcf8\ubb38\uc5d0 \uc4f0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ub9c8\uac10 \ud750\ub984\\n\\nS&P500\uc740 7,541.40\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 -38.67, \ub4f1\ub77d\ub960\uc740 -0.51%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,580.07\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \ub2f9\uc77c \uace0\uac00\ub294 7,659.78, \ub2f9\uc77c \uc800\uac00\ub294 7,541.40\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 51,983.98\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 +213.67, \ub4f1\ub77d\ub960\uc740 +0.41%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218 \ub2f9\uc77c \uace0\uac00\ub294 52,424.91, \ub2f9\uc77c \uc800\uac00\ub294 51,981.66\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\uace0 \ub2e4\uc6b0\uc9c0\uc218\ub294 \uc0c1\uc2b9\ud588\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \ub098\uc2a4\ub2e5 \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc74c \uac70\ub798\uc77c \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uc800\uac00 25,164.32 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \uc885\uac00 25,437.00 \ubd80\uadfc\uc73c\ub85c \ub418\ub3cc\ub9ac\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ub2e4\uc6b0\uc9c0\uc218\uc758 \uc0c1\uc2b9\uacfc \ub098\uc2a4\ub2e5\uc758 \ud558\ub77d\uc774\ub77c\ub294 \ubc29\ud5a5 \ucc28\uc774\uac00 \ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub3c4 \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, S&P500\uacfc \ub098\uc2a4\ub2e5\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub3c4 \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub9c8\uac10 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ub2e4\uc74c \uac70\ub798\uc77c\uc758 \uacb0\uacfc\ub97c \ubcf4\uc7a5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5\uc740 1.07% \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub294 \uc800\uac00 \uc9c0\uc9c0 \uc5ec\ubd80\uc640 \uc9c0\uc218 \uac04 \ubc29\ud5a5 \ucc28\uc774\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub418\uba70, \uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-11-02-nasdaq-market-midday","metadata":{"permalink":"/blog/en/market/2026-11-02-nasdaq-market-midday","source":"@site/market/2026-11-02-nasdaq-market-midday/index.mdx","title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-02T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":2.49,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-02-nasdaq-market-midday","title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-02-nasdaq-market-close"},"nextItem":{"title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-02-nasdaq-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5\uc911 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc7a5\uc911\uc5d0\ub3c4 \uc804\uc77c \ub300\ube44 \uc0c1\uc2b9 \ud750\ub984\uc744 \uc720\uc9c0\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc624\uc804\ubcf4\ub2e4 \uc0c1\uc2b9 \ud3ed\uc774 \uc904\uc5c8\uace0 \ud604\uc7ac\uac00\ub294 \uc2dc\uac00\ub97c \ubc11\ub3cc\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uc0c1\uc2b9\uc774 \uc7a5\uc911 \ub4e4\uc5b4 \ub418\ub3cc\ub824\uc9c4 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\nS&P500\ub3c4 \ub098\uc2a4\ub2e5\uacfc \ube44\uc2b7\ud55c \ud3ed\uc73c\ub85c \uc0c1\uc2b9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,513.85 | +76.85 | +0.30% | 25,437.00 | 25,799.46 | 25,456.59 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 11\uc6d4 2\uc77c 12\uc2dc 56\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 11\uc6d4 3\uc77c 02\uc2dc 56\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc774 \uc9c4\ud589 \uc911\uc774\ub77c \uacc4\uc18d \ubcc0\ud558\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc218\uce58\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud55c \uac12\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc640 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub3c4 25,437.00\uc73c\ub85c \ub124\uc774\ubc84 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc7a5\uc911 \uc2dc\uac00\ub294 25,600.17\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n\ucc28\ud2b8\uc758 \uc9c1\uc804 \uac70\ub798\uc77c\uc778 2026\ub144 10\uc6d4 30\uc77c \uc885\uac00\ub294 25,437.00\uc73c\ub85c \ub124\uc774\ubc84 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ud615\uc131 \uc911\uc778 \ub2f9\uc77c \ubd09\uc758 \uc2dc\uac00\uc640 \uc7a5\uc911 \uace0\uac00, \uc7a5\uc911 \uc800\uac00\ub3c4 \ub124\uc774\ubc84 \uc7a5\uc911 \uac12\uacfc \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\\n\\nS&P500\ub3c4 \ub098\uc2a4\ub2e5\uacfc \ud568\uaed8 \uc0c1\uc2b9\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 S&P500\uc740 7,602.85, \uc804\uc77c \ub300\ube44 +22.78, \ub4f1\ub77d\ub960 +0.30%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,580.07\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \uc7a5\uc911 \uace0\uac00\ub294 7,659.78, \uc7a5\uc911 \uc800\uac00\ub294 7,599.59\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \uc0c1\uc2b9\ub960\uc774 \ub098\uc2a4\ub2e5\uacfc \uac19\uc740 \uc218\uc900\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uc7a5\uc911 \uc0c1\uc2b9\uc740 \uae30\uc220\uc8fc\uc5d0\ub9cc \uad6d\ud55c\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uacfc \uc624\ud6c4 \ud750\ub984 \ubcc0\ud654\\n\\n\uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc774 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \ud604\uc7ac\uac00\ub294 \uc2dc\uac00 25,600.17\ubcf4\ub2e4 86.32 \ub0ae\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uc2a4\ub0c5\uc0f7\uc778 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 10\uc2dc 00\ubd84 \uae30\uc900 25,636.91\ubcf4\ub2e4\ub3c4 123.06 \ub0ae\uc544\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ub4f1\ub77d\ub960\ub3c4 \uc624\uc804 +0.79%\uc5d0\uc11c \uc7a5\uc911 +0.30%\ub85c \uc0c1\uc2b9 \ud3ed\uc774 \ucd95\uc18c\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00\ub294 25,799.46\uae4c\uc9c0 \uc62c\ub790\uc73c\ub098 \ud604\uc7ac\uac00\ub294 \uace0\uac00 \ubd80\uadfc\uc744 \uc9c0\ud0a4\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uc0c1\uc2b9\uc774 \uc624\ud6c4 \ub4e4\uc5b4 \ub418\ub3cc\ub824\uc9c4 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10\uae4c\uc9c0 \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \uc885\uac00 25,437.00 \uc704\ub97c \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc2dc\uac00 25,600.17\uc744 \ub2e4\uc2dc \ud68c\ubcf5\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uc804\uc77c \ub300\ube44 \uc0c1\uc2b9 \ud3ed\uc774 \ub9c8\uac10\uae4c\uc9c0 \ud655\ub300\ub418\ub294\uc9c0 \ucd95\uc18c\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, S&P500\uacfc \ub098\uc2a4\ub2e5\uc758 \uc0c1\uc2b9\ub960 \ucc28\uc774\uac00 \ub9c8\uac10\uae4c\uc9c0 \ubc8c\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ud655\uc815\ub41c \uacb0\uacfc\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc624\uc804 \uc0c1\uc2b9 \ud3ed\uc744 \uc77c\ubd80 \ub418\ub3cc\ub838\uc73c\ub098 \uc804\uc77c \ub300\ube44 \uc0c1\uc2b9 \ud750\ub984\uc740 \uc7a5\uc911\uc5d0\ub3c4 \uc720\uc9c0\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-11-02-nasdaq-market-open","metadata":{"permalink":"/blog/en/market/2026-11-02-nasdaq-market-open","source":"@site/market/2026-11-02-nasdaq-market-open/index.mdx","title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-11-02T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":2.27,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-11-02-nasdaq-market-open","title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-02-nasdaq-market-midday"},"nextItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-30-domestic-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uac1c\uc7a5 \ubc30\uacbd\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c\uc778 2026\ub144 10\uc6d4 30\uc77c \uc885\uac00\ub294 25,437.00\uc73c\ub85c, 2026\ub144 10\uc6d4 29\uc77c \uc885\uac00 26,184.72\ubcf4\ub2e4 747.72 \ub0ae\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804 \uac70\ub798\uc77c \ub4f1\ub77d\ub960\uc740 -2.86%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804\uc5d0\ub294 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uad00\ub828 \ubcf4\ub3c4\uac00 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc564\ud2b8\ub85c\ud53d\uc774 \ubbf8\uad6d \uae30\uc5c5\uacf5\uac1c \uacfc\uc815\uc5d0\uc11c \uc77c\ubcf8\uc5d0\uc11c \ucd5c\ub300 35\uc5b5 \ub2ec\ub7ec\ub97c \uc870\ub2ec\ud558\uae30\ub85c \ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \uc124\ube44\ud22c\uc790 \ud655\ub300\ub85c \ube45\ud14c\ud06c\uc758 \uc789\uc5ec\ud604\uae08\ud750\ub984\uc774 \uc545\ud654\ud560 \uc218 \uc788\ub2e4\ub294 \uc804\ub9dd \ubcf4\ub3c4\ub3c4 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\ub370\uc774\ud130\uc13c\ud130 \uaddc\uc81c\uc640 \uc911\uac04\uc120\uac70 \uad00\ub828 \ubcf4\ub3c4\ub3c4 \uac1c\uc7a5 \uc804 \uc7ac\ub8cc\ub85c \ud568\uaed8 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc8fc\uac00 \ud558\ub77d\uc774\ub098 \uae30\uc5c5 \ubd80\ub3c4\uc5d0 \ub300\ube44\ud55c \ud48b\uc635\uc158\uacfc \uc2e0\uc6a9\ubd80\ub3c4\uc2a4\uc651 \uc218\uc694\uac00 \ub298\uace0 \uc788\ub2e4\ub294 \ubcf4\ub3c4\ub3c4 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,636.91 | +199.92 | +0.79% | 25,437.00 | 25,668.77 | 25,567.38 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 11\uc6d4 2\uc77c 10\uc2dc 00\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 11\uc6d4 3\uc77c 00\uc2dc 00\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc774 \uc9c4\ud589 \uc911\uc774\ub77c \uacc4\uc18d \ubcc0\ud558\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\uc11c \ud655\uc778\ud55c \uc218\uce58\uc774\uba70, \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00 25,437.00\uacfc \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc640 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc2dc\uac00\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \uae30\uc900 25,600.17\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\\n\\nS&P500\ub3c4 \ub098\uc2a4\ub2e5\uacfc \ud568\uaed8 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 S&P500\uc740 7,627.86, \uc804\uc77c \ub300\ube44 +47.79, \ub4f1\ub77d\ub960 +0.63%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,580.07\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \uc7a5\uc911 \uace0\uac00\ub294 7,627.86, \uc7a5\uc911 \uc800\uac00\ub294 7,616.50\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \uc7a5 \uc624\ud508 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \uc0c1\uc2b9\ub960\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ucd08\ubc18 \ubc18\ub4f1\uc740 \uae30\uc220\uc8fc \ucabd\uc5d0\uc11c \uc0c1\ub300\uc801\uc73c\ub85c \uac15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uad00\ub828 \ubcf4\ub3c4 \ud3c9\uac00\uac00 \uc7a5\uc911\uc5d0 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uace0\uac00 25,668.77 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uc800\uac00 25,567.38 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, S&P500\uacfc \ub098\uc2a4\ub2e5\uc758 \uc0c1\uc2b9\ub960 \ucc28\uc774\uac00 \uc7a5\uc911\uc5d0 \uc881\ud600\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ud655\uc815\ub41c \uacb0\uacfc\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc804 \uac70\ub798\uc77c \ud558\ub77d \ub4a4 \uc0c1\uc2b9 \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-10-30-domestic-market-close","metadata":{"permalink":"/blog/en/market/2026-10-30-domestic-market-close","source":"@site/market/2026-10-30-domestic-market-close/index.mdx","title":"2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":2.51,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-domestic-market-close","title":"2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"2026\ub144 11\uc6d4 2\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","permalink":"/blog/en/market/2026-11-02-nasdaq-market-open"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \uc624\uc804 \ud750\ub984","permalink":"/blog/en/market/2026-10-30-domestic-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc774 \ubaa8\ub450 \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 3.48% \ud558\ub77d\ud55c 5,730.74\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \ub300\ube44 3.83% \ud558\ub77d\ud55c 724.38\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00\ubd80\ud130 \uc885\uac00\uae4c\uc9c0 \uc804\uc77c \uc885\uac00\ub97c \ud68c\ubcf5\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 5,599.42\uae4c\uc9c0 \ub0b4\ub824\uac14\ub2e4\uac00 5,730.74\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc7a5\uc911 717.27\uae4c\uc9c0 \ub0b4\ub824\uac14\ub2e4\uac00 724.38\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,730.74 | -206.92 | -3.48% | 5,760.35 | 5,784.98 | 5,599.42 | 213,759\ucc9c\uc8fc | 19\uc870 2,687\uc5b5\uc6d0 |\\n| \ucf54\uc2a4\ub2e5 | 724.38 | -28.85 | -3.83% | 737.76 | 739.79 | 717.27 | 434,190\ucc9c\uc8fc | 5\uc870 7,416\uc5b5\uc6d0 |\\n\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,937.66, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 753.23\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-26 | 5,499.05 | 5,565.67 | 5,455.11 | 5,469.47 | 202,295 |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 213,759 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-26 | 742.17 | 745.95 | 727.20 | 727.21 | 476,231 |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 434,190 |\\n\\n\ucf54\uc2a4\ud53c\ub294 10\uc6d4 28\uc77c 6,000\uc120\uc744 \ub118\uae34 \ub4a4 \uc774\ud2c0 \uc5f0\uc18d \ud558\ub77d\ud574 5,700\uc120 \ucd08\ubc18\uc73c\ub85c \ub0b4\ub824\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \ucd5c\uadfc 5\uac70\ub798\uc77c \uc911 \uac00\uc7a5 \ub0ae\uc740 \uc885\uac00\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2f9\uc77c \uc218\uae09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +6,197 |\\n| \uc678\uad6d\uc778 | -16,167 |\\n| \uae30\uad00 | +7,432 |\\n| \uae30\ud0c0\ubc95\uc778 | +2,538 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +1,688 |\\n| \uc678\uad6d\uc778 | -267 |\\n| \uae30\uad00 | -1,377 |\\n| \uae30\ud0c0\ubc95\uc778 | -44 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uac1c\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uc774 \ud070 \ud3ed\uc73c\ub85c \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ucf54\uc2a4\ud53c \uc218\uae09\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc758 \uc21c\ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984\\n\\n\uc9c0\uc218 \ud558\ub77d \uc18d\uc5d0\uc11c\ub3c4 \uc0c1\uc2b9\ud55c \ud14c\ub9c8\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub9c8\uac10 \ud14c\ub9c8 \uc0c1\uc2b9\ub960\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \ud14c\ub9c8 | \ub4f1\ub77d\ub960 |\\n| --- | --- |\\n| \ubc31\uc2e0\uc5ec\uad8c | +8.88% |\\n| \ube14\ub85d\uccb4\uc778 | +5.47% |\\n| \ubcf4\uc548(\uc815\ubcf4) | +3.38% |\\n| \uc8fc\ub958\ud310\ub9e4 | +2.69% |\\n| \ud574\uc6b4 | +1.69% |\\n\\n\uc0c1\uc2b9 \ud14c\ub9c8\uac00 \uc788\uc5c8\uc74c\uc5d0\ub3c4 \ub450 \uc9c0\uc218 \ubaa8\ub450 3% \ub118\uac8c \ud558\ub77d\ud55c \uc810\uc774 \uc774\ub0a0\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\uc758 \ubc30\uacbd\uc744 \ud2b9\uc815 \uc7ac\ub8cc \ud558\ub098\ub85c \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub824\uc6b0\uba70, \uc774\ub294 \ucc38\uace0\uc6a9 \ud750\ub984 \uc815\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub0b4\uc77c \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 5,700\uc120\uc5d0\uc11c \uc9c0\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 720\uc120 \ubd80\uadfc\uc5d0\uc11c \uc9c0\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc758 \ucf54\uc2a4\ud53c \uc21c\ub9e4\ub3c4 \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9 \ud14c\ub9c8\uc758 \uc0c1\ub300\uc801 \uac15\uc138\uac00 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-10-30-domestic-market-midday","metadata":{"permalink":"/blog/en/market/2026-10-30-domestic-market-midday","source":"@site/market/2026-10-30-domestic-market-midday/index.mdx","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \uc624\uc804 \ud750\ub984","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":3.48,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-domestic-market-midday","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \uc624\uc804 \ud750\ub984","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-30-domestic-market-close"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ucd9c\ubc1c","permalink":"/blog/en/market/2026-10-30-domestic-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc624\uc804\uc7a5 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uc7a5 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc740 \ubaa8\ub450 \ud070 \ud3ed\uc758 \ud558\ub77d\uc138\ub97c \ubcf4\uc774\uba70 \uc624\uc804\uc7a5\uc744 \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 5,600\uc120 \uc544\ub798\uae4c\uc9c0 \ubc00\ub838\ub2e4\uac00 \ub099\ud3ed\uc744 \uc77c\ubd80 \uc904\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 \uc7a5\uc911 \uc800\uc810 \uc774\ud6c4 \ub099\ud3ed\uc744 \ub2e4\uc18c \ucd95\uc18c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ub274\uc695 \uc99d\uc2dc\uc5d0\uc11c \uc778\uacf5\uc9c0\ub2a5 \uad00\ub828 \uae30\uc220\uc8fc\uac00 \uc57d\uc138\ub97c \ubcf4\uc778 \uc5ec\ud30c\uac00 \uad6d\ub0b4 \uc99d\uc2dc\uc5d0\ub3c4 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\ub828 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \uc54c\ud30c\ubcb3\uc758 \ubd80\uc9c4\ud55c \uc2e4\uc801 \uc774\ud6c4 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ube44\uc6a9\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \ud655\uc0b0\ud588\ub2e4\uace0 \uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ub9c8\uac10 \uc774\ud6c4 \uc2e4\uc801\uc744 \ubc1c\ud45c\ud55c \uc544\ub9c8\uc874\uacfc \uc778\ud154\uc774 \uc2dc\uac04 \uc678 \uac70\ub798\uc5d0\uc11c \ud558\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\ub3c4 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc99d\uc2dc\uc5d0\uc11c\ub294 \uc7a5 \ucd08\ubc18 \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub3c4\ud638\uac00 \uc77c\uc2dc\ud6a8\ub825\uc815\uc9c0, \uc774\ub978\ubc14 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ub410\ub2e4\ub294 \ubcf4\ub3c4\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub7ec\ud55c \ud750\ub984\uc740 \uc624\uc804\uc7a5 \ud558\ub77d\uc758 \ubc30\uacbd\uc73c\ub85c \uc5b8\uae09\ub418\uace0 \uc788\uc73c\uba70, \uac1c\ubcc4 \uc885\ubaa9\uc758 \ud750\ub984\uc744 \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,662.39 | -275.27 | -4.64% | 5,760.35 | 5,784.98 | 5,599.42 | 120,598\ucc9c\uc8fc | 9\uc870 9,954\uc5b5\uc6d0 | 2026-10-30 12:29 KST |\\n| \ucf54\uc2a4\ub2e5 | 723.09 | -30.14 | -4.00% | 737.76 | 739.79 | 717.27 | 296,616\ucc9c\uc8fc | 3\uc870 5,088\uc5b5\uc6d0 | 2026-10-30 12:29 KST |\\n\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70, \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \uc774\ud6c4\uc5d0\ub3c4 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,937.66, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 753.23\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 5,403.17 | 5,550.30 | 5,305.98 | 5,550.30 | 249,517 |\\n| 2026-10-26 | 5,499.05 | 5,565.67 | 5,455.11 | 5,469.47 | 202,295 |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,657.20 | 119,727 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 748.32 | 753.02 | 732.87 | 751.69 | 505,474 |\\n| 2026-10-26 | 742.17 | 745.95 | 727.20 | 727.21 | 476,231 |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 721.85 | 295,045 |\\n\\n2026\ub144 10\uc6d4 30\uc77c \ubd09\uc740 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc77c\ubd09 \ud45c\uc758 \ub2f9\uc77c \uc885\uac00\ub294 \ud45c \uc791\uc131 \uc2dc\uc810\uc758 \ud615\uc131 \uc911 \uc218\uce58\uc774\uba70 \uc2e4\uc2dc\uac04 \ud604\uc7ac\uac00\uc640 \uc2dc\ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c 6,000\uc120\uc744 \ub118\uacbc\ub358 \ud750\ub984\uc5d0\uc11c \ud558\ub8e8 \ub9cc\uc5d0 \ud070 \ud3ed\uc73c\ub85c \ub418\ub3cc\ub9bc\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c 753.23\uc5d0\uc11c \ud558\ub77d\ud574 720\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984 \ubcc0\ud654\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,760.35\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 \uc800\uc810 5,599.42\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc800\uc810 \ub300\ube44\ub85c\ub294 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,662.39\uae4c\uc9c0 \ub099\ud3ed\uc744 \uc77c\ubd80 \uc904\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 737.76\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 \uc800\uc810 717.27\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc800\uc810 \ub300\ube44\ub85c\ub294 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 723.09\uae4c\uc9c0 \ub099\ud3ed\uc744 \ub2e4\uc18c \ucd95\uc18c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00 \ub300\ube44 \ud558\ub77d \ubc29\ud5a5\uc774 \uc720\uc9c0\ub41c \uac00\uc6b4\ub370, \uc800\uc810\uc5d0\uc11c\uc758 \ubc18\ub4f1 \uc2dc\ub3c4\uac00 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ub300\uc2dc\ubcf4\ub4dc \uc870\ud68c \uc2dc\uc810\uc758 \ud14c\ub9c8 \ud56d\ubaa9\uc740 \ube44\uc5b4 \uc788\uc5b4, \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc0c1\uc2b9\ub960 \uc0c1\uc704\uc5d0\ub294 \uac1c\ubcc4 \uc885\ubaa9 \uc911\uc2ec\uc758 \uc6c0\uc9c1\uc784\uc774 \uc788\uc5c8\uc73c\ub098, \uc9c0\uc218 \uc804\uccb4\uc758 \ud558\ub77d \ud750\ub984\uacfc\ub294 \ubcc4\uac1c\ub85c \ud574\uc11d\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc804\uc77c \uc218\uae09\\n\\n\uc804\uc77c\uc778 2026\ub144 10\uc6d4 29\uc77c \uc218\uae09\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc218\uae09 \ud655\uc815\uce58\ub294 \uc544\uc9c1 \uc9d1\uacc4 \uc911\uc774\ubbc0\ub85c \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | -429 |\\n| \uc678\uad6d\uc778 | +1,221 |\\n| \uae30\uad00 | -4,132 |\\n| \uae30\ud0c0\ubc95\uc778 | +3,340 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +2,058 |\\n| \uc678\uad6d\uc778 | -1,210 |\\n| \uae30\uad00 | -740 |\\n| \uae30\ud0c0\ubc95\uc778 | -108 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uac1c\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uae30\uad00 \uc21c\ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc774\ub0a0 \uc218\uae09\uc5d0\uc11c \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ud6c4\uc5d0 \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 5,600\uc120 \ubd80\uadfc\uc5d0\uc11c \ub099\ud3ed\uc744 \ucd94\uac00\ub85c \uc904\uc774\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 720\uc120 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uc800\uc810 \uc774\ud6c4\uc758 \ubc18\ub4f1 \uc2dc\ub3c4\uac00 \uc624\ud6c4\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uae30\uc220\uc8fc \uc6b0\ub824\uc640 \uad00\ub828\ub41c \ud750\ub984\uc774 \uc624\ud6c4\uc5d0 \uc644\ud654\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc218\uae09 \ud655\uc815\uce58\uac00 \uc9d1\uacc4\ub418\ub294 \ub300\ub85c \uc678\uad6d\uc778\xb7\uae30\uad00\uc758 \ubc29\ud5a5\uc744 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc624\uc804\uc7a5 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-10-30-domestic-market-open","metadata":{"permalink":"/blog/en/market/2026-10-30-domestic-market-open","source":"@site/market/2026-10-30-domestic-market-open/index.mdx","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ucd9c\ubc1c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":2.88,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-domestic-market-open","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ucd9c\ubc1c","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \uc624\uc804 \ud750\ub984","permalink":"/blog/en/market/2026-10-30-domestic-market-midday"},"nextItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-30-nasdaq-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ubc30\uacbd\\n\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 26,184.72\ub85c \uc804\uc77c \ub300\ube44 365.13\ud3ec\uc778\ud2b8, 1.38% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,720.39\ub85c \uc804\uc77c \ub300\ube44 23.59\ud3ec\uc778\ud2b8, 0.30% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\ub828 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \uc54c\ud30c\ubcb3\uc758 \ubd80\uc9c4\ud55c \uc2e4\uc801\uc774 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ube44\uc6a9 \uc6b0\ub824\ub97c \uc790\uadf9\ud558\uba70 \ub274\uc695 \uc99d\uc2dc \uae30\uc220\uc8fc \ud22c\uc790 \uc2ec\ub9ac\ub97c \uc704\ucd95\uc2dc\ucf30\ub2e4\uace0 \uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub7ec\ud55c \ud750\ub984\uc774 \uad6d\ub0b4 \uc99d\uc2dc \uac1c\uc7a5 \ucd08\ubc18 \uc57d\uc138 \ucd9c\ubc1c\uc758 \ubc30\uacbd\uc73c\ub85c \uc5b8\uae09\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uac1c\ubcc4 \uc885\ubaa9\uc758 \ud750\ub984\uc744 \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub824\uc6b0\uba70, \uc774\ub294 \ucc38\uace0\uc6a9 \ubc30\uacbd \uc815\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,719.05 | -218.61 | -3.68% | 5,760.35 | 5,784.98 | 5,679.80 | 37,046\ucc9c\uc8fc | 3\uc870 4,429\uc5b5\uc6d0 | 2026-10-30 09:29 KST |\\n| \ucf54\uc2a4\ub2e5 | 737.55 | -15.68 | -2.08% | 737.76 | 739.32 | 726.68 | 113,072\ucc9c\uc8fc | 1\uc870 2,259\uc5b5\uc6d0 | 2026-10-30 09:29 KST |\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc740 \ubaa8\ub450 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,760.35\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,719.05\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 737.76\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 737.55\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,937.66, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 753.23\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 5,403.17 | 5,550.30 | 5,305.98 | 5,550.30 | 249,517 |\\n| 2026-10-26 | 5,499.05 | 5,565.67 | 5,455.11 | 5,469.47 | 202,295 |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,679.80 | 5,728.65 | 36,366 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 748.32 | 753.02 | 732.87 | 751.69 | 505,474 |\\n| 2026-10-26 | 742.17 | 745.95 | 727.20 | 727.21 | 476,231 |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.32 | 726.68 | 739.05 | 111,266 |\\n\\n2026\ub144 10\uc6d4 30\uc77c \ubd09\uc740 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc77c\ubd09 \ud45c\uc758 \ub2f9\uc77c \uc885\uac00\ub294 \ud45c \uc791\uc131 \uc2dc\uc810\uc758 \ud615\uc131 \uc911 \uc218\uce58\uc774\uba70 \uc2e4\uc2dc\uac04 \ud604\uc7ac\uac00\uc640 \uc2dc\ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c 5,937.66\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 5,700\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c 753.23\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 740\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc804\uc77c \uc218\uae09\\n\\n\uc804\uc77c\uc778 2026\ub144 10\uc6d4 29\uc77c \uc218\uae09\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | -429 |\\n| \uc678\uad6d\uc778 | +1,221 |\\n| \uae30\uad00 | -4,132 |\\n| \uae30\ud0c0\ubc95\uc778 | +3,340 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +2,058 |\\n| \uc678\uad6d\uc778 | -1,210 |\\n| \uae30\uad00 | -740 |\\n| \uae30\ud0c0\ubc95\uc778 | -108 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uac1c\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uae30\uad00 \uc21c\ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc774\ub0a0 \uc218\uae09\uc5d0\uc11c \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 5,700\uc120 \ubd80\uadfc\uc5d0\uc11c \ub099\ud3ed\uc744 \uc904\uc774\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 740\uc120 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uacfc \uae30\uad00\uc758 \uc7a5 \ucd08\ubc18 \uc218\uae09 \ubc29\ud5a5\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uae30\uc220\uc8fc \uc6b0\ub824\uc640 \uad00\ub828\ub41c \ud750\ub984\uc774 \uc7a5\uc911 \uc644\ud654\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uc7a5 \ucd08\ubc18 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-10-30-nasdaq-market-close","metadata":{"permalink":"/blog/en/market/2026-10-30-nasdaq-market-close","source":"@site/market/2026-10-30-nasdaq-market-close/index.mdx","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":2.22,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-nasdaq-market-close","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ucd9c\ubc1c","permalink":"/blog/en/market/2026-10-30-domestic-market-open"},"nextItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-30-nasdaq-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc804\uc77c \ub300\ube44 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\ub960\uc740 2.86%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\ub3c4 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc73c\ub098 \ub099\ud3ed\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \uc54c\ud30c\ubcb3\uacfc \uc544\ub9c8\uc874 \ub4f1 \ub300\ud615 \uae30\uc220\uc8fc\uc758 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4 \uc6b0\ub824\uac00 \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \ub2f9\uc77c \uace0\uac00 | \ub2f9\uc77c \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,437.00 | -747.72 | -2.86% | 26,184.72 | 25,657.97 | 25,191.32 |\\n| S&P500 | 7,580.07 | -140.32 | -1.82% | 7,720.39 | 7,635.77 | 7,529.84 |\\n| \ub2e4\uc6b0\uc9c0\uc218 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 16\uc2dc 20\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 31\uc77c 05\uc2dc 20\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc218\uce58\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \uc885\uac00\uc5d0\uc11c \uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc744 \ube7c\ub294 \ubc29\uc2dd\uc73c\ub85c \uc5ed\uc0b0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 \uc804\uc77c \ub9c8\uac10 \uae00\uc758 \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 \ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4\uc758 \ucd5c\ub300\uac12\uacfc \ucd5c\uc18c\uac12\uc73c\ub85c \uc0b0\ucd9c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 \uc9c1\uc811 \uc870\ud68c\uc5d0\uc11c \uc218\uce58 \ucd94\ucd9c\uc774 \ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \ubcf8\ubb38 \uc2a4\ub0c5\uc0f7\uc740 \ub124\uc774\ubc84 \uac12\uc774 \uc544\ub2c8\ub77c \ud55c\ud22c MTS \uad50\ucc28\uac12\uc73c\ub85c \ucc44\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc640 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub9c8\uac10 \uc6d0\uc778\uc740 \ubcf8\ubb38\uc5d0 \uc4f0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ub9c8\uac10 \ud750\ub984\\n\\nS&P500\uc740 7,580.07\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 -140.32, \ub4f1\ub77d\ub960\uc740 -1.82%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,720.39\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \ub2f9\uc77c \uace0\uac00\ub294 7,635.77, \ub2f9\uc77c \uc800\uac00\ub294 7,529.84\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \ub9c8\uac10 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \ub098\uc2a4\ub2e5 \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc74c \uac70\ub798\uc77c \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uc800\uac00 25,191.32 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uacfc S&P500\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub3c4 \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \uc885\uac00 26,184.72 \ubd80\uadfc\uc73c\ub85c \ub418\ub3cc\ub9ac\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \ub2e4\uc6b0\uc9c0\uc218 \ub9c8\uac10 \uc218\uce58\uac00 \ud655\uc778\ub418\ub294 \ub300\ub85c \uc138 \uc9c0\uc218\uc758 \ubc29\ud5a5\uc774 \uc77c\uce58\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub9c8\uac10 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ub2e4\uc74c \uac70\ub798\uc77c\uc758 \uacb0\uacfc\ub97c \ubcf4\uc7a5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5\uc740 2.86% \ud558\ub77d\uc73c\ub85c \ud55c \uc8fc\ub97c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub294 \uc800\uac00 \uc9c0\uc9c0 \uc5ec\ubd80\uc640 \uc9c0\uc218 \uac04 \ub099\ud3ed \ucc28\uc774\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>"},{"id":"2026-10-30-nasdaq-market-midday","metadata":{"permalink":"/blog/en/market/2026-10-30-nasdaq-market-midday","source":"@site/market/2026-10-30-nasdaq-market-midday/index.mdx","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":2.51,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-nasdaq-market-midday","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-30-nasdaq-market-close"},"nextItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-30-nasdaq-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5\uc911 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc7a5\uc911\uc5d0\ub3c4 \ud558\ub77d \ud750\ub984\uc744 \uc774\uc5b4\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uc2a4\ub0c5\uc0f7\ubcf4\ub2e4 \ub099\ud3ed\uc774 \ucee4\uc84c\uc73c\uba70 \uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc740 \ub098\ud0c0\ub098\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d \uc555\ub825\uc740 \ub098\uc2a4\ub2e5\uc774 S&P500\ubcf4\ub2e4 \ud06c\uac8c \ubc1b\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\uacbd\uc73c\ub85c\ub294 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uc7a5\uc911\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,412.36 | -772.36 | -2.95% | 26,184.72 | 25,673.00 | 25,397.52 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 12\uc2dc 56\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 31\uc77c 01\uc2dc 56\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc774 \uc9c4\ud589 \uc911\uc774\ub77c \uacc4\uc18d \ubcc0\ud558\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc218\uce58\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud55c \uac12\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc640 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub3c4 26,184.72\ub85c \ub124\uc774\ubc84 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc7a5\uc911 \uc2dc\uac00\ub294 25,592.49\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n\ucc28\ud2b8\uc758 \uc9c1\uc804 \uac70\ub798\uc77c\uc778 2026\ub144 10\uc6d4 29\uc77c \uc885\uac00\ub294 26,184.72\ub85c \ub124\uc774\ubc84 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ud615\uc131 \uc911\uc778 \ub2f9\uc77c \ubd09\uc758 \uc2dc\uac00\uc640 \uc7a5\uc911 \uace0\uac00, \uc7a5\uc911 \uc800\uac00\ub3c4 \ub124\uc774\ubc84 \uc7a5\uc911 \uac12\uacfc \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\\n\\nS&P500\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub099\ud3ed\uc774 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 S&P500\uc740 7,580.70, \uc804\uc77c \ub300\ube44 -139.69, \ub4f1\ub77d\ub960 -1.81%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,720.39\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \uc7a5\uc911 \uace0\uac00\ub294 7,635.77, \uc7a5\uc911 \uc800\uac00\ub294 7,579.27\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \uae30\uc220\uc8fc \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uacfc \uc624\ud6c4 \ud750\ub984 \ubcc0\ud654\\n\\n\uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc740 \ub098\ud0c0\ub098\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \ud604\uc7ac\uac00\ub294 \uc2dc\uac00 25,592.49\ubcf4\ub2e4 180.13 \ub0ae\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uc2a4\ub0c5\uc0f7\uc778 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 10\uc2dc 02\ubd84 \uae30\uc900 25,643.49\ubcf4\ub2e4\ub3c4 231.13 \ub0ae\uc544\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ub4f1\ub77d\ub960\ub3c4 \uc624\uc804 -2.07%\uc5d0\uc11c \uc7a5\uc911 -2.95%\ub85c \ub099\ud3ed\uc774 \ud655\ub300\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00\ub294 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc558\uc73c\ub098 \ud604\uc7ac\uac00\ub294 \uace0\uac00 \ubd80\uadfc\uc744 \uc9c0\ud0a4\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \ud558\ub77d\uc774 \uc624\ud6c4 \ub4e4\uc5b4 \ub418\ub3cc\ub824\uc9c0\uc9c0 \uc54a\uace0 \uc774\uc5b4\uc9c4 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10\uae4c\uc9c0 \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uc800\uac00 25,397.52 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc804\uc77c \ub300\ube44 \ub099\ud3ed\uc774 \ub9c8\uac10\uae4c\uc9c0 \ucd95\uc18c\ub418\ub294\uc9c0 \ud655\ub300\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, S&P500\uacfc \ub098\uc2a4\ub2e5\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \ub9c8\uac10\uae4c\uc9c0 \uc881\ud600\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4\uc5d0 \ub300\ud55c \ud3c9\uac00\uac00 \uc7a5 \ud6c4\ubc18\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ud655\uc815\ub41c \uacb0\uacfc\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4\uc5d0 \ub300\ud55c \uc6b0\ub824 \uc18d\uc5d0 \uc7a5\uc911\uc5d0\ub3c4 \ud558\ub77d \ud750\ub984\uc744 \uc774\uc5b4\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-10-30-nasdaq-market-open","metadata":{"permalink":"/blog/en/market/2026-10-30-nasdaq-market-open","source":"@site/market/2026-10-30-nasdaq-market-open/index.mdx","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":2.35,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-nasdaq-market-open","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-30-nasdaq-market-midday"},"nextItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-29-domestic-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uac1c\uc7a5 \ubc30\uacbd\\n\\n\ub098\uc2a4\ub2e5\uc740 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804 \uc7ac\ub8cc\ub85c\ub294 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc54c\ud30c\ubcb3\uc740 3\ubd84\uae30 \uc790\ubcf8\uc9c0\ucd9c\uc774 \uc804\ub144 \ub300\ube44 114% \uae09\uc99d\ud588\ub2e4\ub294 \ubcf4\ub3c4\uc640 \ud568\uaed8 \uc2e4\uc801 \uc1fc\ud06c\ub85c \uc8fc\uac00\uac00 13% \uae09\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc544\ub9c8\uc874\uc740 2,200\uc5b5 \ub2ec\ub7ec \uaddc\ubaa8 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \uacc4\ud68d\uc744 \uc720\uc9c0\ud558\uba74\uc11c \ud604\uae08\ud750\ub984 \uc545\ud654 \uc6b0\ub824\uac00 \uc81c\uae30\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\ud154\uc740 \uc2e4\uc801\uc804\ub9dd \uc545\ud654\uac00 \ud568\uaed8 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ud68c\uc758\ub860\uc774 \ub2e4\uc2dc \ubd80\uac01\ub418\uba74\uc11c \uae30\uc220\uc8fc \uc911\uc2ec\uc758 \ub098\uc2a4\ub2e5 \ucd08\ubc18 \ud750\ub984\uc744 \uc555\ubc15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,643.49 | -541.23 | -2.07% | 26,184.72 | 25,657.97 | 25,537.64 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 10\uc2dc 02\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 23\uc2dc 02\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc774 \uc9c4\ud589 \uc911\uc774\ub77c \uacc4\uc18d \ubcc0\ud558\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 \uc9c1\uc811 \uc870\ud68c\uc5d0\uc11c \uac00\uaca9 \ub370\uc774\ud130\ub97c \ub2f4\uc740 \ubcf8\ubb38\uc774 \ubc18\ud658\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\uc5d0 \ub530\ub77c \uc2a4\ub0c5\uc0f7 \uc218\uce58\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uc73c\ub85c \ucc44\uc6e0\uc73c\uba70 \ub124\uc774\ubc84 \uac12\uc778 \uac83\ucc98\ub7fc \ud45c\uae30\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc640 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 26,184.72\ub85c \uc77c\ubd09 \uae30\uc900 2026\ub144 10\uc6d4 29\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 \uc7a5\uc911 \uace0\uac00\ub294 25,657.97, \uc7a5\uc911 \uc800\uac00\ub294 25,537.64\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\\n\\nS&P500\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub099\ud3ed\uc774 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 S&P500\uc740 7,628.20, \uc804\uc77c \ub300\ube44 -92.19, \ub4f1\ub77d\ub960 -1.19%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,720.39\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \uc7a5\uc911 \uace0\uac00\ub294 7,635.77, \uc7a5\uc911 \uc800\uac00\ub294 7,622.27\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \uc7a5 \uc624\ud508 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \uae30\uc220\uc8fc \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \uc54c\ud30c\ubcb3\uacfc \uc544\ub9c8\uc874, \uc778\ud154 \uad00\ub828 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4 \ud3c9\uac00\uac00 \uc7a5\uc911\uc5d0 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uc800\uac00 25,537.64 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, S&P500\uacfc \ub098\uc2a4\ub2e5\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \uc7a5\uc911\uc5d0 \uc881\ud600\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \uc7a5 \ub9c8\uac10 \ub54c\uae4c\uc9c0 \uace0\uac00\uc640 \uc800\uac00\uc758 \ubc94\uc704\uac00 \uc5b4\ub5bb\uac8c \ubcc0\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ud655\uc815\ub41c \uacb0\uacfc\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4\uc5d0 \ub300\ud55c \uc6b0\ub824 \uc18d\uc5d0 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-10-29-domestic-market-close","metadata":{"permalink":"/blog/en/market/2026-10-29-domestic-market-close","source":"@site/market/2026-10-29-domestic-market-close/index.mdx","title":"2026\ub144 10\uc6d4 29\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/en/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":2.58,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-29-domestic-market-close","title":"2026\ub144 10\uc6d4 29\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-30-nasdaq-market-open"},"nextItem":{"title":"\uc2dc\ud669 \uc139\uc158 \uc2dc\uc791 \uc548\ub0b4","permalink":"/blog/en/market/market-section-opening"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 29\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc774 \ubaa8\ub450 \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 1.24% \ud558\ub77d\ud55c 5,937.66\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \ub300\ube44 2.34% \ud558\ub77d\ud55c 753.23\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uc810 \ub300\ube44\ub85c\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \uc544\ub798\uc5d0\uc11c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 6,100.11\uae4c\uc9c0 \uc62c\ub790\uc73c\ub098 \uc885\uac00\ub294 5,937.66\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc7a5\uc911 768.75\uae4c\uc9c0 \uc62c\ub790\uc73c\ub098 \uc885\uac00\ub294 753.23\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,937.66 | -74.78 | -1.24% | 6,017.22 | 6,100.11 | 5,817.92 | 279,659\ucc9c\uc8fc | 24\uc870 9,071\uc5b5\uc6d0 |\\n| \ucf54\uc2a4\ub2e5 | 753.23 | -18.05 | -2.34% | 767.78 | 768.75 | 741.96 | 468,753\ucc9c\uc8fc | 5\uc870 8,154\uc5b5\uc6d0 |\\n\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 6,012.44, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 771.28\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 5,403.17 | 5,550.30 | 5,305.98 | 5,550.30 | 249,517 |\\n| 2026-10-26 | 5,499.05 | 5,565.67 | 5,455.11 | 5,469.47 | 202,295 |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 279,659 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 748.32 | 753.02 | 732.87 | 751.69 | 505,474 |\\n| 2026-10-26 | 742.17 | 745.95 | 727.20 | 727.21 | 476,231 |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 468,753 |\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c 6,000\uc120\uc744 \ub118\uae34 \ub4a4 \ud558\ub8e8 \ub9cc\uc5d0 \ub2e4\uc2dc \uc544\ub798\ub85c \ub0b4\ub824\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 5\uac70\ub798\uc77c \uc911 \uac00\uc7a5 \ub0ae\uc740 \uc885\uac00\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2f9\uc77c \uc218\uae09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +327 |\\n| \uc678\uad6d\uc778 | +763 |\\n| \uae30\uad00 | -4,472 |\\n| \uae30\ud0c0\ubc95\uc778 | +3,383 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +2,173 |\\n| \uc678\uad6d\uc778 | -1,303 |\\n| \uae30\uad00 | -759 |\\n| \uae30\ud0c0\ubc95\uc778 | -1,105 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uacfc \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uc758 \ucf54\uc2a4\ud53c \uc21c\ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc774\ub0a0 \uc218\uae09\uc5d0\uc11c \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984\\n\\n\uc9c0\uc218 \ud558\ub77d \uc18d\uc5d0\uc11c\ub3c4 \uc0c1\uc2b9\ud55c \ud14c\ub9c8\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub9c8\uac10 \ud14c\ub9c8 \uc0c1\uc2b9\ub960\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \ud14c\ub9c8 | \ub4f1\ub77d\ub960 |\\n| --- | --- |\\n| \ub9c8\ub9ac\ud654\ub098(\ub300\ub9c8) \uad00\ub828\uc8fc | +14.58% |\\n| \ub9c8\uc774\ud06c\ub85cLED | +6.08% |\\n| \ud648\ub124\ud2b8\uc6cc\ud06c | +3.31% |\\n| \uc740\ud589 | +1.75% |\\n| \ubcf4\ud5d8 | +1.66% |\\n\\n\uae08\uc735 \ud14c\ub9c8\uc778 \uc740\ud589\uacfc \ubcf4\ud5d8\uc774 \uc9c0\uc218 \ud558\ub77d \uc18d\uc5d0\uc11c\ub3c4 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc2dc\uc7a5 \ube0c\ub9ac\ud551\uc5d0\uc11c\ub294 \uae09\ub77d\uc7a5 \uc18d HBM \ub300\ud615\uc8fc \uc0c1\uc2b9 \ub9c8\uac10\uacfc \uae08\uc735\xb7\uad11\ud1b5\uc2e0 \uc21c\ud658\ub9e4, \ubc30\ud130\ub9ac \uc57d\uc138\ub97c \uc5b8\uae09\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\ub828 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \uc5ed\ub300 \ucd5c\uace0 \uc2e4\uc801\uc5d0\ub3c4 \ub300\ud615 \ubc18\ub3c4\uccb4\uc8fc\uc758 \uc8fc\uac00\uac00 5%\ub300 \ud558\ub77d\ud588\ub2e4\uace0 \uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ud558\ub77d\uc758 \ubc30\uacbd\uc73c\ub85c \ud2b9\uc815 \uc885\ubaa9\uc758 \ud750\ub984\uc744 \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub824\uc6b0\uba70, \uc774\ub294 \ucc38\uace0\uc6a9 \ud750\ub984 \uc815\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub0b4\uc77c \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 6,000\uc120\uc744 \ud68c\ubcf5\ud558\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 750\uc120 \ubd80\uadfc\uc5d0\uc11c \uc9c0\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uc758 \ucf54\uc2a4\ud53c \uc21c\ub9e4\ub3c4 \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\uc735 \ud14c\ub9c8\uc758 \uc0c1\ub300\uc801 \uac15\uc138\uac00 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"market-section-opening","metadata":{"permalink":"/blog/en/market/market-section-opening","source":"@site/market/2026-10-29-market-section-opening/index.mdx","title":"\uc2dc\ud669 \uc139\uc158 \uc2dc\uc791 \uc548\ub0b4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uc548\ub0b4","permalink":"/blog/en/market/tags/\uc548\ub0b4"}],"readingTime":1.1,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"market-section-opening","title":"\uc2dc\ud669 \uc139\uc158 \uc2dc\uc791 \uc548\ub0b4","authors":["way"],"tags":["market","\uc2dc\ud669","\uc548\ub0b4"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-29-domestic-market-close"},"nextItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-29-nasdaq-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\ube14\ub85c\uadf8\uc5d0 \uc2dc\ud669 \uc139\uc158\uc744 \uc0c8\ub85c \uc5f4\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc774 \uc139\uc158\uc5d0\uc11c \ub2e4\ub8e8\ub294 \uae00\\n\\n\uad6d\ub0b4 \uc2dc\uc7a5\uacfc \ub098\uc2a4\ub2e5 \uc2dc\uc7a5\uc744 \uac01\uac01 \uc7a5 \uc624\ud508, \uc7a5\uc911, \uc7a5 \ub9c8\uac10 \uae30\uc900\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uae00\uc740 \ud3c9\uc77c \uc624\uc804 9\uc2dc 30\ubd84, \uc624\ud6c4 12\uc2dc 30\ubd84, \uc624\ud6c4 4\uc2dc\uc5d0 \uc62c\ub77c\uac11\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uae00\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 \uae30\uc900 \uc624\uc804 10\uc2dc, \uc624\ud6c4 1\uc2dc, \uc624\ud6c4 4\uc2dc 20\ubd84\uc5d0 \uc62c\ub77c\uac11\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d \uacf5\ud734\uc77c\uc774\ub098 \ubbf8\uad6d \ud734\uc7a5\uc77c\uc5d0\ub294 \ud574\ub2f9 \uc2dc\uc7a5 \uae00\uc774 \uc62c\ub77c\uac00\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uae00\uc5d0 \ud3ec\ud568\ub418\ub294 \ub370\uc774\ud130\\n\\n\uac01 \uae00\uc5d0\ub294 \ud574\ub2f9 \uc2dc\uc810\uc758 \ub124\uc774\ubc84 \ucc28\ud2b8 \ub370\uc774\ud130 \uc2a4\ub0c5\uc0f7\uc774 \ud3ec\ud568\ub429\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uc640 \uc804\uc77c \ub300\ube44, \ub4f1\ub77d\ub960, \uc2dc\uac00\uc640 \uace0\uac00, \uc800\uac00, \uac70\ub798\ub7c9\uacfc \uac70\ub798\ub300\uae08\uc744 \ud45c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uae00\uc5d0\ub294 \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09 \uc885\uac00\ub3c4 \ud568\uaed8 \uc2e3\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uae00\uc5d0\ub294 \ub098\uc2a4\ub2e5 \uc885\ud569\uc744 \uc911\uc2ec\uc73c\ub85c \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\ub3c4 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc218\uce58\ub294 \uc870\ud68c \uc2dc\uc810\uc758 \uc2a4\ub0c5\uc0f7\uc774\uba70, \ucd9c\ucc98 \ub9c1\ud06c\ub97c \ud568\uaed8 \ub0a8\uae41\ub2c8\ub2e4.<br/>\\n\\n#### \ud655\uc778\ud560 \uc810\\n\\n\uc774 \uc139\uc158\uc758 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub429\ub2c8\ub2e4.<br/>\\n\ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc73c\uba70, \ubaa9\ud45c\uc8fc\uac00\ub97c \uc81c\uc2dc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc2a4\ub0c5\uc0f7\uc740 \ud655\uc815\uce58\uac00 \uc544\ub2c8\ub77c \ud574\ub2f9 \uc2dc\uc810\uae4c\uc9c0\uc758 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5 \ub9c8\uac10 \uae00\uc758 \uc218\uce58\uc640 \uc7a5\uc911 \uae00\uc758 \uc218\uce58\uac00 \ub2e4\ub97c \uc218 \uc788\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\uc55e\uc73c\ub85c\ub294 \uac1c\uc7a5 \uc9c1\ud6c4\uc758 \ubc29\ud5a5\uacfc \uc7a5\uc911 \ud750\ub984, \ub9c8\uac10 \uacb0\uacfc\ub97c \uac19\uc740 \uae30\uc900\uc73c\ub85c \uc774\uc5b4\uc11c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-10-29-nasdaq-market-close","metadata":{"permalink":"/blog/en/market/2026-10-29-nasdaq-market-close","source":"@site/market/2026-10-29-nasdaq-market-close/index.mdx","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/en/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":2.14,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-29-nasdaq-market-close","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\uc2dc\ud669 \uc139\uc158 \uc2dc\uc791 \uc548\ub0b4","permalink":"/blog/en/market/market-section-opening"},"nextItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-29-nasdaq-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc804\uc77c \ub300\ube44 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\ub960\uc740 1.38%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\ub3c4 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc73c\ub098 \ub099\ud3ed\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \ub2f9\uc77c \uace0\uac00 | \ub2f9\uc77c \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 26,184.72 | -365.13 | -1.38% | 26,549.85 | 26,273.73 | 26,076.80 |\\n| S&P500 | 7,720.39 | -23.59 | -0.30% | 7,743.98 | 7,729.59 | 7,692.26 |\\n| \ub2e4\uc6b0\uc9c0\uc218 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 29\uc77c 16\uc2dc 20\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 05\uc2dc 20\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc218\uce58\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \uc885\uac00\uc5d0\uc11c \uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc744 \ube7c\ub294 \ubc29\uc2dd\uc73c\ub85c \uc5ed\uc0b0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 \ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4\uc758 \ucd5c\ub300\uac12\uacfc \ucd5c\uc18c\uac12\uc73c\ub85c \uc0b0\ucd9c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 \uc9c1\uc811 \uc870\ud68c\uc5d0\uc11c \uc218\uce58 \ucd94\ucd9c\uc774 \ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \ubcf8\ubb38 \uc2a4\ub0c5\uc0f7\uc740 \ub124\uc774\ubc84 \uac12\uc774 \uc544\ub2c8\ub77c \ud55c\ud22c MTS \uad50\ucc28\uac12\uc73c\ub85c \ucc44\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc640 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub525\uc11c\uce58 \uad50\ucc28\uac80\uc99d\uc740 \uc11c\ubc84 \uc624\ub958\ub85c \uc2e4\ud328\ud574 \ub9c8\uac10 \uc774\uc288 \ubcf4\uac15\uc740 \uc0dd\ub7b5\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub9c8\uac10 \uc6d0\uc778\uc740 \ubcf8\ubb38\uc5d0 \uc4f0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ub9c8\uac10 \ud750\ub984\\n\\nS&P500\uc740 7,720.39\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 -23.59, \ub4f1\ub77d\ub960\uc740 -0.30%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,743.98\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \ub2f9\uc77c \uace0\uac00\ub294 7,729.59, \ub2f9\uc77c \uc800\uac00\ub294 7,692.26\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \ub9c8\uac10 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \ub098\uc2a4\ub2e5 \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc74c \uac70\ub798\uc77c \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uc800\uac00 26,076.80 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uacfc S&P500\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub3c4 \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \uc885\uac00 26,549.85 \ubd80\uadfc\uc73c\ub85c \ub418\ub3cc\ub9ac\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \ub2e4\uc6b0\uc9c0\uc218 \ub9c8\uac10 \uc218\uce58\uac00 \ud655\uc778\ub418\ub294 \ub300\ub85c \uc138 \uc9c0\uc218\uc758 \ubc29\ud5a5\uc774 \uc77c\uce58\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub9c8\uac10 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ub2e4\uc74c \uac70\ub798\uc77c\uc758 \uacb0\uacfc\ub97c \ubcf4\uc7a5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 1% \ub118\ub294 \ud558\ub77d\uc73c\ub85c 10\uc6d4 29\uc77c \uac70\ub798\ub97c \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-10-29-nasdaq-market-midday","metadata":{"permalink":"/blog/en/market/2026-10-29-nasdaq-market-midday","source":"@site/market/2026-10-29-nasdaq-market-midday/index.mdx","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/en/market/tags/\uc7a5\uc911"}],"readingTime":3.07,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-29-nasdaq-market-midday","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-29-nasdaq-market-close"},"nextItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-29-nasdaq-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5\uc911 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5\uc740 \ud558\ub77d \ud750\ub984\uc744 \uc774\uc5b4\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \uc624\ud508 \uc774\ud6c4 \uc18c\ud3ed \ubc18\ub4f1\ud588\uc73c\ub098 \uc804\uc77c \ub300\ube44 \ud558\ub77d \uc0c1\ud0dc\ub294 \uc720\uc9c0\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ud558\ub77d\uc758 \uc911\uc2ec\uc5d0\ub294 \ub300\ud615 \uae30\uc220\uae30\uc5c5 \uc2e4\uc801\uc5d0 \ub300\ud55c \uc2e4\ub9dd\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc54c\ud30c\ubcb3\uc758 3\ubd84\uae30 \uc2e4\uc801\uc774 \uc2dc\uc7a5 \uc608\uc0c1\uce58\ub97c \ubc11\ub3cc\uc558\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc7a5 \ucd08\ubc18\ubd80\ud130 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790\uc5d0 \ub300\ud55c \uc218\uc775\uc131 \uc6b0\ub824\ub3c4 \uae30\uc220\uc8fc \uc804\ubc18\uc758 \uc2ec\ub9ac\ub97c \uc555\ubc15\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 9\uc6d4 \uac1c\uc778\uc18c\ube44\uc9c0\ucd9c \ubb3c\uac00\uc9c0\uc218\ub294 \ucee8\uc13c\uc11c\uc2a4\uc5d0 \ubd80\ud569\ud588\uace0 \uad6d\ub0b4\ucd1d\uc0dd\uc0b0\uc740 \ucee8\uc13c\uc11c\uc2a4\ub97c \uc18c\ud3ed \uc0c1\ud68c\ud588\ub2e4\ub294 \uc18c\uc2dd\uc774 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc2dc\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 26,210.96 | -338.89 | -1.28% | 26,549.85 | 26,201.82 | 26,286.46 | 26,053.16 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 29\uc77c 12\uc2dc 57\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 01\uc2dc 57\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc774 \uc9c4\ud589 \uc911\uc774\ub77c \uacc4\uc18d \ubcc0\ud558\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569 \uc218\uce58\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc640 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc5d0\uc11c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uad50\ucc28\uac12\ub3c4 \uac19\uc740 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 26,197.14, \uc804\uc77c \ub300\ube44 -352.71, \ub4f1\ub77d\ub960 -1.33%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 26,549.85\ub85c \ub124\uc774\ubc84 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 \uc7a5\uc911 \uace0\uac00\ub294 26,273.73, \uc7a5\uc911 \uc800\uac00\ub294 26,076.80\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \ucd9c\ucc98\uc758 \ud604\uc7ac\uac00 \ucc28\uc774\ub294 \uc870\ud68c \uc2dc\uac01 \ucc28\uc774\ub85c \uc124\uba85\ub429\ub2c8\ub2e4.<br/>\\n\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\\n\\nS&P500\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub099\ud3ed\uc774 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 S&P500\uc740 7,715.09, \uc804\uc77c \ub300\ube44 -28.89, \ub4f1\ub77d\ub960 -0.37%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,743.98\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \uc7a5\uc911 \uace0\uac00\ub294 7,729.59, \uc7a5\uc911 \uc800\uac00\ub294 7,699.80\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \uae30\uc220\uc8fc \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uacfc \uc624\ud6c4 \ud750\ub984 \ubcc0\ud654\\n\\n\uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc740 \ub098\ud0c0\ub098\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 \uc2dc\uac00 26,201.82\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 \ud604\uc7ac\uac00 26,210.96\uc73c\ub85c \uc2dc\uac00 \uc704\uc5d0\uc11c \uac70\ub798\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc804\uc77c \uc885\uac00 \ub300\ube44\ub85c\ub294 \uc5ec\uc804\ud788 1% \ub118\ub294 \ud558\ub77d \uc0c1\ud0dc\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5 \uc624\ud508 \uc2a4\ub0c5\uc0f7(\ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 09\uc2dc 59\ubd84)\uc758 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 26,170.19\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ud604\uc7ac\uac00\ub294 \uc624\ud508 \uc2a4\ub0c5\uc0f7\ubcf4\ub2e4 \uc62c\ub790\uc73c\ub098 \ud558\ub77d \ubc29\ud5a5 \uc790\uccb4\ub294 \ubc14\ub00c\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc800\uac00 26,053.16\uc5d0\uc11c \ubc18\ub4f1\ud574 \uace0\uac00 26,286.46\uae4c\uc9c0 \uc62c\ub790\uc73c\ub098 \uc0c1\uc2b9 \uc804\ud658\uc73c\ub85c \ubcf4\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900\uc73c\ub85c\ub3c4 \uac19\uc740 \ud750\ub984\uc774 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc7a5 \uc624\ud508 \ub2f9\uc2dc 26,154.79\uc5d0\uc11c \uc7a5\uc911 26,197.14\ub85c \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 \uc7a5\uc911 \uace0\uac00\ub294 26,200.39\uc5d0\uc11c 26,273.73\uc73c\ub85c \ud655\ub300\ub410\uace0 \uc7a5\uc911 \uc800\uac00\ub294 26,076.80\uc744 \uc720\uc9c0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\ub3c4 \uc7a5 \uc624\ud508 \ub2f9\uc2dc 7,709.43\uc5d0\uc11c \uc7a5\uc911 7,715.09\ub85c \uc18c\ud3ed \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804\uc758 \ud558\ub77d\uc774 \uc624\ud6c4 \ub4e4\uc5b4 \uc644\ub9cc\ud574\uc84c\uc73c\ub098 \ubc29\ud5a5\uc774 \ubc14\ub010 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10\uae4c\uc9c0 \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \uc54c\ud30c\ubcb3 \uc2e4\uc801 \uc2e4\ub9dd\uc5d0 \ub530\ub978 \ud558\ub77d \uc555\ub825\uc774 \ub9c8\uac10\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uc800\uac00 26,053.16 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uac1c\uc778\uc18c\ube44\uc9c0\ucd9c \ubb3c\uac00\uc9c0\uc218\uc640 \uad6d\ub0b4\ucd1d\uc0dd\uc0b0 \uc9c0\ud45c\uac00 \uc7a5 \ud6c4\ubc18 \uc2ec\ub9ac\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, S&P500\uacfc \ub098\uc2a4\ub2e5\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \ub9c8\uac10\uae4c\uc9c0 \uc881\ud600\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\uc12f\uc9f8, \uc7a5 \ub9c8\uac10 \ub54c\uae4c\uc9c0 \uac70\ub798\ub7c9\uacfc \uace0\uac00\uc640 \uc800\uac00\uc758 \ubc94\uc704\uac00 \uc5b4\ub5bb\uac8c \ubcc0\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ud655\uc815\ub41c \uacb0\uacfc\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc2e4\uc801 \uc2e4\ub9dd\uacfc \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc218\uc775\uc131 \uc6b0\ub824 \uc18d\uc5d0 \ud558\ub77d \ud750\ub984\uc744 \uc774\uc5b4\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-10-29-nasdaq-market-open","metadata":{"permalink":"/blog/en/market/2026-10-29-nasdaq-market-open","source":"@site/market/2026-10-29-nasdaq-market-open/index.mdx","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/en/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/en/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/en/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/en/market/tags/\uc7a5\uc624\ud508"}],"readingTime":2.53,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/en/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-29-nasdaq-market-open","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","permalink":"/blog/en/market/2026-10-29-nasdaq-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uac1c\uc7a5 \ubc30\uacbd\\n\\n\ub098\uc2a4\ub2e5\uc740 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804 \uc7ac\ub8cc\ub85c\ub294 \ub300\ud615 \uae30\uc220\uae30\uc5c5 \uc2e4\uc801\uc5d0 \ub300\ud55c \ud3c9\uac00\uac00 \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc54c\ud30c\ubcb3\uc740 3\ubd84\uae30 \ub9e4\ucd9c\uacfc \uc870\uc815 \uc8fc\ub2f9\uc21c\uc774\uc775\uc774 \uc2dc\uc7a5 \uc608\uc0c1\uce58\ub97c \ubc11\ub3cc\uc558\ub2e4\ub294 \ubcf4\ub3c4\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac04\uc678 \uac70\ub798\uc5d0\uc11c \uc54c\ud30c\ubcb3\uc774 \uae09\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\ub3c4 \ud568\uaed8 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790\uc5d0 \ub300\ud55c \uc218\uc775\uc131 \uc6b0\ub824\uac00 \uae30\uc220\uc8fc \uc911\uc2ec\uc758 \ub098\uc2a4\ub2e5 \uc120\ubb3c\uacfc \ucd08\ubc18 \ud750\ub984\uc744 \uc555\ubc15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 9\uc6d4 \uac1c\uc778\uc18c\ube44\uc9c0\ucd9c \ubb3c\uac00\uc9c0\uc218\ub294 \ucee8\uc13c\uc11c\uc2a4\uc5d0 \ubd80\ud569\ud588\uace0 \uad6d\ub0b4\ucd1d\uc0dd\uc0b0\uc740 \ucee8\uc13c\uc11c\uc2a4\ub97c \uc18c\ud3ed \uc0c1\ud68c\ud588\ub2e4\ub294 \uc18c\uc2dd\uc774 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc77c\ub77c\uc774\ub9b4\ub9ac\ub294 \ube44\ub9cc\uacfc \ub2f9\ub1e8\ubcd1 \uce58\ub8cc\uc81c \uc218\uc694 \uc99d\uac00\uc5d0 \ud798\uc785\uc5b4 \ud638\uc2e4\uc801\uc744 \uae30\ub85d\ud588\ub2e4\ub294 \uc18c\uc2dd\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc2dc\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 | \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 26,170.19 | -379.66 | -1.43% | 26,549.85 | 26,201.82 | 26,209.84 | 26,053.16 | 191,612\ucc9c\uc8fc |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 29\uc77c 09\uc2dc 59\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 29\uc77c 22\uc2dc 59\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc774 \uc9c4\ud589 \uc911\uc774\ub77c \uacc4\uc18d \ubcc0\ud558\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569 \uc218\uce58\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc640 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc5d0\uc11c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 28\uc77c \uc885\uac00 26,549.85\ub294 \ub124\uc774\ubc84 \uc77c\ubcc4 \uc2dc\uc138\uc640 \uc704 \uc804\uc77c \uc885\uac00 \uac12\uc774 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uad50\ucc28\uac12\ub3c4 \uac19\uc740 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 26,154.79, \uc804\uc77c \ub300\ube44 -395.06, \ub4f1\ub77d\ub960 -1.49%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 26,549.85\ub85c \ub124\uc774\ubc84 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 \uc7a5\uc911 \uace0\uac00\ub294 26,200.39, \uc7a5\uc911 \uc800\uac00\ub294 26,076.80\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \ucd9c\ucc98\uc758 \ud604\uc7ac\uac00 \ucc28\uc774\ub294 \uc870\ud68c \uc2dc\uac01 \ucc28\uc774\ub85c \uc124\uba85\ub429\ub2c8\ub2e4.<br/>\\n\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\\n\\nS&P500\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub099\ud3ed\uc774 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 S&P500\uc740 7,709.43, \uc804\uc77c \ub300\ube44 -34.55, \ub4f1\ub77d\ub960 -0.45%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,743.98\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \uc7a5\uc911 \uace0\uac00\ub294 7,712.89, \uc7a5\uc911 \uc800\uac00\ub294 7,699.80\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \uc7a5 \uc624\ud508 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \uae30\uc220\uc8fc \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \uc54c\ud30c\ubcb3 \uc2e4\uc801\uc5d0 \ub300\ud55c \uc2dc\uc7a5\uc758 \ud3c9\uac00\uac00 \uc7a5\uc911\uc5d0 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uac1c\uc778\uc18c\ube44\uc9c0\ucd9c \ubb3c\uac00\uc9c0\uc218\uc640 \uad6d\ub0b4\ucd1d\uc0dd\uc0b0 \uc9c0\ud45c\uac00 \uc7a5\uc911 \uc2ec\ub9ac\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uc800\uac00 26,053.16 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, S&P500\uacfc \ub098\uc2a4\ub2e5\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \uc7a5\uc911\uc5d0 \uc881\ud600\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\uc12f\uc9f8, \uc7a5 \ub9c8\uac10 \ub54c\uae4c\uc9c0 \uac70\ub798\ub7c9\uacfc \uace0\uac00\uc640 \uc800\uac00\uc758 \ubc94\uc704\uac00 \uc5b4\ub5bb\uac8c \ubcc0\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ud655\uc815\ub41c \uacb0\uacfc\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc2e4\uc801 \uc2e4\ub9dd\uacfc \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc218\uc775\uc131 \uc6b0\ub824 \uc18d\uc5d0 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"}]}}')}}]);